// =====================================================================
// Evangelhos cronológicos — textos dos tópicos da harmonia
// Formato: {p:"Passagem"} abre uma perícope; {v,t,n} é versículo.
// =====================================================================

const EV = window.TEXTOS_SEED["evangelhos"];

EV[1] = [
{p:"Lucas 1:1-4"},
{v:1,t:"Visto que muitos empreenderam compor uma narração dos fatos que entre nós se cumpriram,"},
{v:2,t:"conforme nos transmitiram os que desde o princípio foram testemunhas oculares e ministros da palavra,"},
{v:3,t:"pareceu bem também a mim, depois de investigar tudo cuidadosamente desde a origem, escrever para ti, excelentíssimo Teófilo, uma exposição ordenada,"},
{v:4,t:"para que reconheças a solidez dos ensinamentos que recebeste.",n:"Solidez traduz asphaleia, a firmeza que não deixa lugar a dúvida; ensinamentos verte o verbo katechein, de onde vem catequese."}
];

EV[2] = [
{p:"João 1:1-18"},
{v:1,t:"No princípio era o Verbo, e o Verbo estava junto de Deus, e o Verbo era Deus.",n:"Verbo traduz Logos, a Palavra subsistente de Deus; junto de Deus verte pros ton Theon, que indica não só proximidade, mas orientação viva de pessoa a pessoa."},
{v:2,t:"Ele estava no princípio junto de Deus."},
{v:3,t:"Todas as coisas foram feitas por meio dele, e sem ele nada se fez do que foi feito."},
{v:4,t:"Nele estava a vida, e a vida era a luz dos homens;"},
{v:5,t:"e a luz brilha nas trevas, e as trevas não a apreenderam.",n:"O verbo katalambanein significa ao mesmo tempo compreender e dominar: as trevas nem entenderam a luz nem conseguiram vencê-la."},
{v:6,t:"Houve um homem enviado por Deus, cujo nome era João."},
{v:7,t:"Este veio como testemunha, para dar testemunho da luz, a fim de que todos cressem por meio dele."},
{v:8,t:"Ele não era a luz, mas veio para dar testemunho da luz."},
{v:9,t:"O Verbo era a luz verdadeira, que ilumina todo homem, vindo a este mundo."},
{v:10,t:"Estava no mundo, e o mundo foi feito por meio dele, e o mundo não o conheceu."},
{v:11,t:"Veio para o que era seu, e os seus não o receberam."},
{v:12,t:"Mas a todos os que o receberam deu o poder de se tornarem filhos de Deus: aos que creem no seu nome,"},
{v:13,t:"os quais não nasceram do sangue, nem da vontade da carne, nem da vontade do homem, mas de Deus."},
{v:14,t:"E o Verbo se fez carne e habitou entre nós; e vimos a sua glória, glória como do Unigênito do Pai, cheio de graça e de verdade.",n:"Habitou verte eskenosen, literalmente armou a sua tenda, evocando a tenda do encontro em que Deus habitava no meio de Israel."},
{v:15,t:"João dá testemunho dele e clama: Este era aquele de quem eu disse: o que vem depois de mim passou adiante de mim, porque existia antes de mim."},
{v:16,t:"Da sua plenitude todos nós recebemos, e graça sobre graça."},
{v:17,t:"Porque a Lei foi dada por meio de Moisés; a graça e a verdade vieram por meio de Jesus Cristo."},
{v:18,t:"A Deus, ninguém jamais o viu; o Deus Unigênito, que está no seio do Pai, esse o deu a conhecer."}
];

EV[3] = [
{p:"Mateus 1:1-17"},
{v:1,t:"Livro da origem de Jesus Cristo, filho de Davi, filho de Abraão."},
{v:2,t:"Abraão gerou Isaac; Isaac gerou Jacó; Jacó gerou Judá e seus irmãos;"},
{v:3,t:"Judá gerou de Tamar Farés e Zara; Farés gerou Esrom; Esrom gerou Aram;"},
{v:4,t:"Aram gerou Aminadab; Aminadab gerou Naasson; Naasson gerou Salmon;"},
{v:5,t:"Salmon gerou de Raab Booz; Booz gerou de Rute Obed; Obed gerou Jessé;"},
{v:6,t:"Jessé gerou o rei Davi. Davi gerou Salomão da que fora mulher de Urias;"},
{v:7,t:"Salomão gerou Roboão; Roboão gerou Abias; Abias gerou Asaf;",n:"Os manuscritos gregos mais antigos trazem Asaf aqui e Amós no v. 10, formas que designam os reis Asa e Amon."},
{v:8,t:"Asaf gerou Josafá; Josafá gerou Jorão; Jorão gerou Ozias;"},
{v:9,t:"Ozias gerou Joatão; Joatão gerou Acaz; Acaz gerou Ezequias;"},
{v:10,t:"Ezequias gerou Manassés; Manassés gerou Amós; Amós gerou Josias;"},
{v:11,t:"Josias gerou Jeconias e seus irmãos, no tempo da deportação para a Babilônia."},
{v:12,t:"Depois da deportação para a Babilônia, Jeconias gerou Salatiel; Salatiel gerou Zorobabel;"},
{v:13,t:"Zorobabel gerou Abiud; Abiud gerou Eliacim; Eliacim gerou Azor;"},
{v:14,t:"Azor gerou Sadoc; Sadoc gerou Aquim; Aquim gerou Eliud;"},
{v:15,t:"Eliud gerou Eleazar; Eleazar gerou Matã; Matã gerou Jacó;"},
{v:16,t:"Jacó gerou José, o esposo de Maria, da qual nasceu Jesus, que é chamado Cristo."},
{v:17,t:"Assim, todas as gerações desde Abraão até Davi são catorze gerações; desde Davi até a deportação para a Babilônia, catorze gerações; e desde a deportação para a Babilônia até Cristo, catorze gerações."},
{p:"Lucas 3:23-38"},
{v:23,t:"Jesus, ao começar, tinha cerca de trinta anos, e era, como se julgava, filho de José, filho de Heli,"},
{v:24,t:"filho de Matat, filho de Levi, filho de Melqui, filho de Janai, filho de José,"},
{v:25,t:"filho de Matatias, filho de Amós, filho de Naum, filho de Esli, filho de Nagai,"},
{v:26,t:"filho de Maat, filho de Matatias, filho de Semei, filho de Josec, filho de Jodá,"},
{v:27,t:"filho de Joanã, filho de Resa, filho de Zorobabel, filho de Salatiel, filho de Neri,"},
{v:28,t:"filho de Melqui, filho de Adi, filho de Cosã, filho de Elmadã, filho de Er,"},
{v:29,t:"filho de Jesus, filho de Eliézer, filho de Jorim, filho de Matat, filho de Levi,"},
{v:30,t:"filho de Simeão, filho de Judá, filho de José, filho de Jonã, filho de Eliacim,"},
{v:31,t:"filho de Meleá, filho de Mená, filho de Matatá, filho de Natã, filho de Davi,"},
{v:32,t:"filho de Jessé, filho de Obed, filho de Booz, filho de Sala, filho de Naasson,"},
{v:33,t:"filho de Aminadab, filho de Admin, filho de Arni, filho de Esrom, filho de Farés, filho de Judá,"},
{v:34,t:"filho de Jacó, filho de Isaac, filho de Abraão, filho de Taré, filho de Nacor,"},
{v:35,t:"filho de Seruc, filho de Ragau, filho de Faleg, filho de Éber, filho de Sala,"},
{v:36,t:"filho de Cainã, filho de Arfaxad, filho de Sem, filho de Noé, filho de Lamec,"},
{v:37,t:"filho de Matusalém, filho de Enoc, filho de Jared, filho de Malaleel, filho de Cainã,"},
{v:38,t:"filho de Enós, filho de Set, filho de Adão, filho de Deus."}
];

EV[4] = [
{p:"Lucas 1:5-25"},
{v:5,t:"Houve, nos dias de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da classe de Abias; sua mulher era das filhas de Aarão e chamava-se Isabel."},
{v:6,t:"Ambos eram justos diante de Deus, caminhando irrepreensíveis em todos os mandamentos e preceitos do Senhor."},
{v:7,t:"Não tinham filhos, porque Isabel era estéril, e ambos eram avançados em idade."},
{v:8,t:"Ora, enquanto ele exercia as funções sacerdotais diante de Deus, na ordem da sua classe,"},
{v:9,t:"coube a ele por sorte, segundo o costume do sacerdócio, entrar no santuário do Senhor para oferecer o incenso."},
{v:10,t:"E toda a multidão do povo estava fora, orando, à hora do incenso."},
{v:11,t:"Apareceu a ele um anjo do Senhor, de pé, à direita do altar do incenso."},
{v:12,t:"Ao vê-lo, Zacarias turbou-se, e o temor caiu sobre ele."},
{v:13,t:"Mas o anjo disse a ele: Não temas, Zacarias, porque a tua súplica foi ouvida: Isabel, tua mulher, dará a ti um filho, e tu o chamarás João."},
{v:14,t:"Ele será para ti alegria e júbilo, e muitos se alegrarão com o seu nascimento,"},
{v:15,t:"porque será grande diante do Senhor; não beberá vinho nem bebida fermentada e será cheio do Espírito Santo já desde o ventre de sua mãe;"},
{v:16,t:"e converterá muitos dos filhos de Israel ao Senhor, seu Deus."},
{v:17,t:"Ele caminhará à frente do Senhor com o espírito e o poder de Elias, para converter os corações dos pais aos filhos e os rebeldes à prudência dos justos, a fim de preparar para o Senhor um povo bem disposto."},
{v:18,t:"Zacarias disse ao anjo: Como saberei isso? Pois eu sou velho, e minha mulher é avançada em idade."},
{v:19,t:"O anjo respondeu a ele: Eu sou Gabriel, que assisto diante de Deus, e fui enviado para falar contigo e anunciar a ti esta boa nova."},
{v:20,t:"Eis que ficarás mudo e não poderás falar até o dia em que essas coisas acontecerem, porque não creste nas minhas palavras, que se cumprirão a seu tempo."},
{v:21,t:"O povo estava esperando Zacarias e admirava-se da sua demora no santuário."},
{v:22,t:"Ao sair, não podia falar com eles, e compreenderam que tivera uma visão no santuário; ele fazia sinais para eles e permanecia mudo."},
{v:23,t:"Quando se completaram os dias do seu serviço, voltou para casa."},
{v:24,t:"Depois desses dias, Isabel, sua mulher, concebeu e ocultou-se durante cinco meses, dizendo:"},
{v:25,t:"Assim fez comigo o Senhor, nos dias em que olhou para mim, a fim de tirar a minha vergonha entre os homens."}
];

EV[5] = [
{p:"Lucas 1:26-38"},
{v:26,t:"No sexto mês, o anjo Gabriel foi enviado por Deus a uma cidade da Galileia chamada Nazaré,"},
{v:27,t:"a uma virgem desposada com um homem chamado José, da casa de Davi; e o nome da virgem era Maria."},
{v:28,t:"Entrando onde ela estava, disse: Alegra-te, cheia de graça, o Senhor está contigo.",n:"Cheia de graça verte kecharitomene, particípio perfeito que exprime a plenitude estável da graça já recebida; a Vulgata traduziu gratia plena. A saudação chaire, alegra-te, ecoa os anúncios messiânicos de alegria à filha de Sião."},
{v:29,t:"Ela turbou-se com essas palavras e refletia que saudação seria essa."},
{v:30,t:"O anjo disse a ela: Não temas, Maria, porque encontraste graça diante de Deus."},
{v:31,t:"Eis que conceberás no ventre e darás à luz um filho, e o chamarás Jesus."},
{v:32,t:"Ele será grande, será chamado Filho do Altíssimo, e o Senhor Deus dará a ele o trono de Davi, seu pai;"},
{v:33,t:"reinará para sempre sobre a casa de Jacó, e o seu reino não terá fim."},
{v:34,t:"Maria disse ao anjo: Como será isso, se eu não conheço homem?",n:"Conhecer, no uso bíblico, designa a relação conjugal; o presente do verbo sugere um propósito permanente de virgindade."},
{v:35,t:"O anjo respondeu a ela: O Espírito Santo virá sobre ti, e o poder do Altíssimo te cobrirá com a sua sombra; por isso, o que nascer será santo e será chamado Filho de Deus."},
{v:36,t:"Eis que Isabel, tua parenta, também concebeu um filho na velhice, e este é o sexto mês daquela que chamavam estéril,"},
{v:37,t:"porque para Deus nada é impossível."},
{v:38,t:"Disse então Maria: Eis a serva do Senhor; faça-se em mim segundo a tua palavra. E o anjo retirou-se dela."}
];

EV[6] = [
{p:"Lucas 1:39-56"},
{v:39,t:"Naqueles dias, Maria levantou-se e foi apressadamente para a região montanhosa, a uma cidade de Judá."},
{v:40,t:"Entrou na casa de Zacarias e saudou Isabel."},
{v:41,t:"Quando Isabel ouviu a saudação de Maria, a criança saltou no seu ventre, e Isabel ficou cheia do Espírito Santo."},
{v:42,t:"Com um grande grito, exclamou: Bendita és tu entre as mulheres, e bendito é o fruto do teu ventre!"},
{v:43,t:"Donde me vem que a mãe do meu Senhor venha a mim?"},
{v:44,t:"Pois, quando a voz da tua saudação chegou aos meus ouvidos, a criança saltou de alegria no meu ventre."},
{v:45,t:"Bem-aventurada a que creu, porque se cumprirá o que da parte do Senhor foi dito a ela."},
{v:46,t:"Maria então disse: A minha alma engrandece o Senhor,"},
{v:47,t:"e o meu espírito exulta em Deus, meu Salvador,"},
{v:48,t:"porque olhou para a humildade da sua serva. Eis que, desde agora, todas as gerações me chamarão bem-aventurada,",n:"Humildade verte tapeinosis, que designa antes a condição humilde, a pequenez, do que a virtude da humildade."},
{v:49,t:"porque o Poderoso fez em mim grandes coisas, e santo é o seu nome;"},
{v:50,t:"a sua misericórdia se estende de geração em geração sobre os que o temem."},
{v:51,t:"Manifestou o poder do seu braço, dispersou os soberbos nos pensamentos do seu coração;"},
{v:52,t:"depôs os poderosos dos tronos e exaltou os humildes;"},
{v:53,t:"encheu de bens os famintos e despediu vazios os ricos."},
{v:54,t:"Socorreu Israel, seu servo, recordando a sua misericórdia,"},
{v:55,t:"conforme falara a nossos pais, em favor de Abraão e da sua descendência para sempre."},
{v:56,t:"Maria permaneceu com ela cerca de três meses e voltou para sua casa."}
];

EV[7] = [
{p:"Lucas 1:57-80"},
{v:57,t:"Completou-se para Isabel o tempo de dar à luz, e ela teve um filho."},
{v:58,t:"Os vizinhos e parentes ouviram que o Senhor usara com ela de grande misericórdia e alegravam-se com ela."},
{v:59,t:"No oitavo dia, vieram circuncidar o menino e queriam chamá-lo Zacarias, com o nome de seu pai."},
{v:60,t:"Mas sua mãe respondeu: Não; ele será chamado João."},
{v:61,t:"Disseram a ela: Não há ninguém na tua parentela que tenha esse nome."},
{v:62,t:"E perguntavam por sinais ao pai como queria que ele se chamasse."},
{v:63,t:"Ele pediu uma tabuinha e escreveu: João é o seu nome. E todos se admiraram."},
{v:64,t:"No mesmo instante, abriu-se a sua boca e soltou-se a sua língua, e falava, bendizendo a Deus."},
{v:65,t:"O temor apoderou-se de todos os seus vizinhos, e por toda a região montanhosa da Judeia se comentavam todas essas coisas;"},
{v:66,t:"todos os que as ouviam guardavam-nas no coração, dizendo: Que virá a ser este menino? Pois a mão do Senhor estava com ele."},
{v:67,t:"Zacarias, seu pai, ficou cheio do Espírito Santo e profetizou, dizendo:"},
{v:68,t:"Bendito o Senhor, Deus de Israel, porque visitou e redimiu o seu povo,"},
{v:69,t:"e suscitou para nós uma força de salvação na casa de Davi, seu servo,",n:"Literalmente, um chifre de salvação: imagem hebraica do poder invencível."},
{v:70,t:"como falara pela boca dos seus santos profetas desde a antiguidade:"},
{v:71,t:"salvação dos nossos inimigos e da mão de todos os que nos odeiam;"},
{v:72,t:"para fazer misericórdia com os nossos pais e recordar a sua santa aliança,"},
{v:73,t:"o juramento que jurou a Abraão, nosso pai, de conceder a nós"},
{v:74,t:"que, libertados da mão dos inimigos, o sirvamos sem temor,"},
{v:75,t:"em santidade e justiça, diante dele, todos os nossos dias."},
{v:76,t:"E tu, menino, serás chamado profeta do Altíssimo, porque irás à frente do Senhor para preparar os seus caminhos,"},
{v:77,t:"para dar ao seu povo o conhecimento da salvação, no perdão dos seus pecados,"},
{v:78,t:"pelas entranhas de misericórdia do nosso Deus, com que nos visitará o Sol nascente do alto,",n:"Sol nascente traduz anatole, termo que na versão grega do Antigo Testamento verte também o Germe messiânico anunciado pelos profetas."},
{v:79,t:"para iluminar os que jazem nas trevas e na sombra da morte e dirigir os nossos passos no caminho da paz."},
{v:80,t:"O menino crescia e fortalecia-se em espírito, e viveu nos desertos até o dia da sua manifestação a Israel."}
];

EV[8] = [
{p:"Mateus 1:18-25"},
{v:18,t:"A origem de Jesus Cristo foi assim: Maria, sua mãe, estava desposada com José; antes de coabitarem, achou-se grávida por obra do Espírito Santo.",n:"O desposório judaico já constituía vínculo matrimonial verdadeiro, embora a esposa ainda não vivesse na casa do esposo."},
{v:19,t:"José, seu esposo, sendo justo e não querendo expô-la publicamente, resolveu deixá-la em segredo."},
{v:20,t:"Enquanto pensava nisso, eis que um anjo do Senhor apareceu a ele em sonho, dizendo: José, filho de Davi, não temas receber Maria, tua esposa, pois o que nela foi gerado vem do Espírito Santo."},
{v:21,t:"Ela dará à luz um filho, e tu o chamarás Jesus, porque ele salvará o seu povo dos seus pecados.",n:"Jesus, em hebraico Yeshua, significa o Senhor salva."},
{v:22,t:"Tudo isso aconteceu para que se cumprisse o que o Senhor dissera pelo profeta:"},
{v:23,t:"Eis que a virgem conceberá e dará à luz um filho, e o chamarão Emanuel, que significa: Deus conosco."},
{v:24,t:"Despertando do sono, José fez como o anjo do Senhor ordenara e recebeu a sua esposa."},
{v:25,t:"E não a conhecia, até que ela deu à luz um filho; e ele o chamou Jesus.",n:"A expressão semítica até que afirma apenas o que houve antes do parto, sem nada dizer sobre o que se seguiu; não contradiz a virgindade perpétua de Maria."}
];

EV[9] = [
{p:"Lucas 2:1-7"},
{v:1,t:"Naqueles dias, saiu um decreto de César Augusto para que se recenseasse toda a terra."},
{v:2,t:"Este primeiro recenseamento foi feito quando Quirino era governador da Síria."},
{v:3,t:"E todos iam recensear-se, cada um à sua cidade."},
{v:4,t:"José também subiu da Galileia, da cidade de Nazaré, para a Judeia, à cidade de Davi, chamada Belém, por ser da casa e da família de Davi,"},
{v:5,t:"para recensear-se com Maria, sua esposa, que estava grávida."},
{v:6,t:"Enquanto estavam ali, completaram-se os dias de ela dar à luz,"},
{v:7,t:"e deu à luz o seu filho primogênito; envolveu-o em faixas e reclinou-o numa manjedoura, porque não havia lugar para eles na hospedaria.",n:"Primogênito é título legal do primeiro nascido, com os direitos e deveres previstos na Lei, e não implica que tenham nascido outros filhos depois."}
];

EV[10] = [
{p:"Lucas 2:8-20"},
{v:8,t:"Havia naquela região pastores que viviam nos campos e guardavam de noite os turnos de vigília junto ao seu rebanho."},
{v:9,t:"Um anjo do Senhor apareceu junto deles, e a glória do Senhor os envolveu de luz, e temeram com grande temor."},
{v:10,t:"O anjo disse a eles: Não temais; eis que eu vos anuncio uma grande alegria, que será para todo o povo:"},
{v:11,t:"nasceu para vós hoje, na cidade de Davi, um Salvador, que é Cristo, o Senhor."},
{v:12,t:"E isto vos servirá de sinal: encontrareis um recém-nascido envolto em faixas e deitado numa manjedoura."},
{v:13,t:"De repente, juntou-se ao anjo uma multidão do exército celeste, que louvava a Deus, dizendo:"},
{v:14,t:"Glória a Deus nas alturas, e paz na terra aos homens do seu agrado.",n:"Do seu agrado verte eudokias: os homens que são objeto da benevolência divina, e não os homens de boa vontade da antiga versão latina."},
{v:15,t:"Quando os anjos se retiraram deles para o céu, os pastores diziam uns aos outros: Vamos até Belém e vejamos o que aconteceu, o que o Senhor nos deu a conhecer."},
{v:16,t:"Foram apressadamente e encontraram Maria, José e o recém-nascido deitado na manjedoura."},
{v:17,t:"Ao verem, contaram o que se dissera a eles a respeito daquele menino."},
{v:18,t:"E todos os que ouviram admiraram-se do que os pastores diziam."},
{v:19,t:"Maria, porém, conservava todas essas coisas, meditando-as no seu coração."},
{v:20,t:"Os pastores voltaram, glorificando e louvando a Deus por tudo o que tinham ouvido e visto, conforme se dissera a eles."}
];

EV[11] = [
{p:"Lucas 2:21"},
{v:21,t:"Quando se completaram os oito dias para a circuncisão do menino, foi chamado Jesus, nome que o anjo dissera antes de ele ser concebido no ventre."}
];

EV[12] = [
{p:"Lucas 2:22-38"},
{v:22,t:"Quando se completaram os dias da purificação deles, segundo a Lei de Moisés, levaram-no a Jerusalém para apresentá-lo ao Senhor,"},
{v:23,t:"como está escrito na Lei do Senhor: Todo primogênito varão será consagrado ao Senhor,"},
{v:24,t:"e para oferecer em sacrifício, segundo o que se diz na Lei do Senhor, um par de rolas ou dois pombinhos.",n:"Era a oferta dos pobres, prevista para quem não podia apresentar um cordeiro."},
{v:25,t:"Havia em Jerusalém um homem chamado Simeão; era justo e piedoso, esperava a consolação de Israel, e o Espírito Santo estava sobre ele."},
{v:26,t:"Fora revelado a ele pelo Espírito Santo que não veria a morte antes de ver o Cristo do Senhor."},
{v:27,t:"Movido pelo Espírito, foi ao Templo; e, quando os pais trouxeram o menino Jesus para cumprirem a seu respeito o costume da Lei,"},
{v:28,t:"ele o tomou nos braços e bendisse a Deus, dizendo:"},
{v:29,t:"Agora, Senhor, deixas ir em paz o teu servo, segundo a tua palavra,"},
{v:30,t:"porque os meus olhos viram a tua salvação,"},
{v:31,t:"que preparaste diante de todos os povos:"},
{v:32,t:"luz para iluminar as nações e glória do teu povo Israel."},
{v:33,t:"Seu pai e sua mãe admiravam-se do que se dizia a respeito dele."},
{v:34,t:"Simeão os abençoou e disse a Maria, sua mãe: Eis que este menino está posto para queda e reerguimento de muitos em Israel e como sinal de contradição"},
{v:35,t:"— e uma espada traspassará a tua própria alma —, para que se revelem os pensamentos de muitos corações."},
{v:36,t:"Havia também uma profetisa, Ana, filha de Fanuel, da tribo de Aser; era de idade muito avançada: vivera com o marido sete anos desde a sua virgindade"},
{v:37,t:"e era viúva de oitenta e quatro anos; não se afastava do Templo, servindo a Deus noite e dia com jejuns e orações."},
{v:38,t:"Chegando naquela mesma hora, louvava a Deus e falava do menino a todos os que esperavam a redenção de Jerusalém."}
];

EV[13] = [
{p:"Mateus 2:1-12"},
{v:1,t:"Tendo Jesus nascido em Belém da Judeia, nos dias do rei Herodes, eis que magos vindos do oriente chegaram a Jerusalém,",n:"Magos designava sábios orientais dedicados à observação dos astros; o número três é dedução posterior, a partir dos três presentes."},
{v:2,t:"dizendo: Onde está o rei dos judeus que acaba de nascer? Vimos a sua estrela no oriente e viemos adorá-lo.",n:"No oriente pode também traduzir-se no seu surgir: viram a estrela levantar-se."},
{v:3,t:"Ao ouvir isso, o rei Herodes perturbou-se, e toda Jerusalém com ele;"},
{v:4,t:"e, reunindo todos os príncipes dos sacerdotes e os escribas do povo, perguntava a eles onde havia de nascer o Cristo."},
{v:5,t:"Eles responderam: Em Belém da Judeia, pois assim está escrito pelo profeta:"},
{v:6,t:"E tu, Belém, terra de Judá, de modo algum és a menor entre as principais cidades de Judá, porque de ti sairá o chefe que apascentará Israel, meu povo."},
{v:7,t:"Então Herodes chamou os magos em segredo e averiguou com eles o tempo em que a estrela aparecera;"},
{v:8,t:"e, enviando-os a Belém, disse: Ide e informai-vos com exatidão sobre o menino; quando o encontrardes, avisai-me, para que eu também vá adorá-lo."},
{v:9,t:"Depois de ouvirem o rei, partiram; e eis que a estrela que tinham visto no oriente ia adiante deles, até parar sobre o lugar onde estava o menino."},
{v:10,t:"Ao verem a estrela, alegraram-se com grandíssima alegria."},
{v:11,t:"Entrando na casa, viram o menino com Maria, sua mãe; prostrando-se, adoraram-no; e, abrindo os seus tesouros, ofereceram a ele presentes: ouro, incenso e mirra."},
{v:12,t:"Avisados em sonho para não voltarem a Herodes, retiraram-se por outro caminho para a sua região."}
];

EV[14] = [
{p:"Mateus 2:13-18"},
{v:13,t:"Depois que eles partiram, eis que um anjo do Senhor apareceu em sonho a José, dizendo: Levanta-te, toma o menino e sua mãe, foge para o Egito e fica lá até que eu te avise, porque Herodes vai procurar o menino para matá-lo."},
{v:14,t:"Ele levantou-se, tomou de noite o menino e sua mãe e retirou-se para o Egito,"},
{v:15,t:"onde ficou até a morte de Herodes, para que se cumprisse o que o Senhor dissera pelo profeta: Do Egito chamei o meu filho."},
{v:16,t:"Então Herodes, vendo que fora enganado pelos magos, irritou-se profundamente e mandou matar todos os meninos de Belém e de todo o seu território, de dois anos para baixo, conforme o tempo que averiguara com os magos."},
{v:17,t:"Cumpriu-se então o que fora dito pelo profeta Jeremias:"},
{v:18,t:"Uma voz se ouviu em Ramá, pranto e grande lamento: é Raquel que chora os seus filhos e não quer ser consolada, porque já não existem."}
];

EV[15] = [
{p:"Mateus 2:19-23"},
{v:19,t:"Morto Herodes, eis que um anjo do Senhor apareceu em sonho a José, no Egito,"},
{v:20,t:"dizendo: Levanta-te, toma o menino e sua mãe e vai para a terra de Israel, pois morreram os que atentavam contra a vida do menino."},
{v:21,t:"Ele levantou-se, tomou o menino e sua mãe e entrou na terra de Israel."},
{v:22,t:"Mas, ouvindo que Arquelau reinava na Judeia em lugar de Herodes, seu pai, teve medo de ir para lá; avisado em sonho, retirou-se para a região da Galileia"},
{v:23,t:"e foi morar numa cidade chamada Nazaré, para que se cumprisse o que fora dito pelos profetas: Será chamado Nazareno.",n:"Nenhum profeta traz literalmente essa frase; o evangelista resume um tema profético, talvez com alusão a netser, o rebento do tronco de Jessé."},
{p:"Lucas 2:39-40"},
{v:39,t:"Quando cumpriram tudo segundo a Lei do Senhor, voltaram para a Galileia, para a sua cidade de Nazaré."},
{v:40,t:"O menino crescia e fortalecia-se, cheio de sabedoria, e a graça de Deus estava sobre ele."}
];

EV[16] = [
{p:"Lucas 2:41-50"},
{v:41,t:"Seus pais iam todos os anos a Jerusalém, para a festa da Páscoa."},
{v:42,t:"Quando ele completou doze anos, subiram, segundo o costume da festa;"},
{v:43,t:"terminados aqueles dias, ao voltarem, o menino Jesus ficou em Jerusalém, sem que os seus pais o soubessem."},
{v:44,t:"Pensando que ele estava na caravana, caminharam um dia e procuravam-no entre os parentes e conhecidos;"},
{v:45,t:"não o encontrando, voltaram a Jerusalém à sua procura."},
{v:46,t:"Depois de três dias, encontraram-no no Templo, sentado no meio dos doutores, ouvindo-os e interrogando-os;"},
{v:47,t:"e todos os que o ouviam pasmavam da sua inteligência e das suas respostas."},
{v:48,t:"Ao vê-lo, ficaram atônitos, e sua mãe disse a ele: Filho, por que agiste assim conosco? Eis que teu pai e eu, aflitos, te procurávamos."},
{v:49,t:"Ele respondeu: Por que me procuráveis? Não sabíeis que devo estar nas coisas de meu Pai?",n:"A expressão grega admite dois sentidos, ambos verdadeiros: nas coisas de meu Pai ou na casa de meu Pai."},
{v:50,t:"Mas eles não compreenderam a palavra que dissera a eles."}
];

EV[17] = [
{p:"Lucas 2:51-52"},
{v:51,t:"Desceu com eles, foi para Nazaré e era submisso a eles. Sua mãe conservava todas essas coisas no coração."},
{v:52,t:"E Jesus crescia em sabedoria, em estatura e em graça, diante de Deus e dos homens."}
];

EV[18] = [
{p:"Mateus 3:1-12"},
{v:1,t:"Naqueles dias, apareceu João Batista, pregando no deserto da Judeia"},
{v:2,t:"e dizendo: Convertei-vos, porque está próximo o Reino dos Céus.",n:"Convertei-vos verte metanoeite: mudança profunda da mente e do coração, e não apenas penitência exterior."},
{v:3,t:"Este é aquele de quem falou o profeta Isaías: Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."},
{v:4,t:"João usava uma veste de pelos de camelo e um cinto de couro à volta dos rins; o seu alimento eram gafanhotos e mel silvestre."},
{v:5,t:"Então saíam ao seu encontro Jerusalém, toda a Judeia e toda a região do Jordão,"},
{v:6,t:"e eram batizados por ele no rio Jordão, confessando os seus pecados."},
{v:7,t:"Vendo que muitos fariseus e saduceus vinham ao seu batismo, disse a eles: Raça de víboras, quem vos ensinou a fugir da ira que está para vir?"},
{v:8,t:"Produzi, pois, fruto digno da conversão"},
{v:9,t:"e não penseis que basta dizer dentro de vós: Temos Abraão por pai. Pois eu vos digo que Deus pode suscitar destas pedras filhos a Abraão."},
{v:10,t:"O machado já está posto à raiz das árvores; toda árvore que não produz bom fruto será cortada e lançada ao fogo."},
{v:11,t:"Eu vos batizo com água para a conversão; mas aquele que vem depois de mim é mais forte do que eu, e eu não sou digno de levar as suas sandálias: ele vos batizará no Espírito Santo e no fogo."},
{v:12,t:"Tem na mão a pá de joeirar e limpará a sua eira: recolherá o seu trigo no celeiro, mas queimará a palha em fogo inextinguível."},
{p:"Marcos 1:1-8"},
{v:1,t:"Princípio do Evangelho de Jesus Cristo, Filho de Deus."},
{v:2,t:"Como está escrito no profeta Isaías: Eis que envio o meu mensageiro diante da tua face; ele preparará o teu caminho.",n:"A citação combina Malaquias e Êxodo com Isaías; Marcos a atribui em bloco ao profeta maior."},
{v:3,t:"Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."},
{v:4,t:"Apareceu João no deserto, batizando e pregando um batismo de conversão para o perdão dos pecados."},
{v:5,t:"Saía ao seu encontro toda a região da Judeia e todos os habitantes de Jerusalém, e eram batizados por ele no rio Jordão, confessando os seus pecados."},
{v:6,t:"João vestia-se de pelos de camelo, com um cinto de couro à volta dos rins, e comia gafanhotos e mel silvestre."},
{v:7,t:"E pregava, dizendo: Depois de mim vem o que é mais forte do que eu, diante de quem não sou digno de me inclinar para desatar a correia das suas sandálias."},
{v:8,t:"Eu vos batizei com água, mas ele vos batizará no Espírito Santo."},
{p:"Lucas 3:1-18"},
{v:1,t:"No décimo quinto ano do governo de Tibério César, sendo Pôncio Pilatos governador da Judeia, Herodes tetrarca da Galileia, Filipe, seu irmão, tetrarca da região da Itureia e da Traconítide, e Lisânias tetrarca da Abilene,"},
{v:2,t:"sob os sumos sacerdotes Anás e Caifás, a palavra de Deus veio a João, filho de Zacarias, no deserto."},
{v:3,t:"Ele percorreu toda a região do Jordão, pregando um batismo de conversão para o perdão dos pecados,"},
{v:4,t:"como está escrito no livro das palavras do profeta Isaías: Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."},
{v:5,t:"Todo vale será aterrado, todo monte e colina serão abaixados; os caminhos tortuosos se tornarão retos, e os escabrosos, planos;"},
{v:6,t:"e toda carne verá a salvação de Deus."},
{v:7,t:"Dizia então às multidões que saíam para ser batizadas por ele: Raça de víboras, quem vos ensinou a fugir da ira que está para vir?"},
{v:8,t:"Produzi, pois, frutos dignos da conversão e não comeceis a dizer dentro de vós: Temos Abraão por pai. Pois eu vos digo que Deus pode suscitar destas pedras filhos a Abraão."},
{v:9,t:"O machado já está posto à raiz das árvores; toda árvore que não produz bom fruto será cortada e lançada ao fogo."},
{v:10,t:"As multidões perguntavam a ele: Que devemos fazer?"},
{v:11,t:"Ele respondia: Quem tem duas túnicas reparta com quem não tem, e quem tem o que comer faça o mesmo."},
{v:12,t:"Vieram também publicanos para ser batizados e disseram a ele: Mestre, que devemos fazer?"},
{v:13,t:"Ele respondeu: Não exijais nada além do que vos foi fixado."},
{v:14,t:"Também soldados perguntavam: E nós, que devemos fazer? Disse a eles: Não pratiqueis extorsão contra ninguém, não denuncieis falsamente e contentai-vos com o vosso soldo."},
{v:15,t:"Como o povo estava na expectativa e todos se perguntavam no coração se João não seria o Cristo,"},
{v:16,t:"João respondeu a todos: Eu vos batizo com água, mas vem aquele que é mais forte do que eu, e eu não sou digno de desatar a correia das suas sandálias: ele vos batizará no Espírito Santo e no fogo."},
{v:17,t:"Tem na mão a pá de joeirar para limpar a sua eira e recolher o trigo no seu celeiro; a palha, porém, ele a queimará em fogo inextinguível."},
{v:18,t:"Assim, com muitas outras exortações, anunciava ao povo a boa nova."}
];

EV[19] = [
{p:"Mateus 3:13-17"},
{v:13,t:"Então Jesus veio da Galileia ao Jordão, ao encontro de João, para ser batizado por ele."},
{v:14,t:"João procurava impedi-lo, dizendo: Eu é que preciso ser batizado por ti, e tu vens a mim?"},
{v:15,t:"Jesus respondeu: Deixa por agora, pois assim nos convém cumprir toda a justiça. Então João o deixou."},
{v:16,t:"Batizado, Jesus saiu logo da água; e eis que os céus se abriram, e ele viu o Espírito de Deus descer como pomba e vir sobre ele."},
{v:17,t:"E uma voz dos céus dizia: Este é o meu Filho amado, em quem me comprazo."},
{p:"Marcos 1:9-11"},
{v:9,t:"Naqueles dias, Jesus veio de Nazaré da Galileia e foi batizado por João no Jordão."},
{v:10,t:"Logo ao sair da água, viu os céus rasgarem-se e o Espírito descer sobre ele como pomba."},
{v:11,t:"E dos céus veio uma voz: Tu és o meu Filho amado, em ti me comprazo."},
{p:"Lucas 3:21-22"},
{v:21,t:"Quando todo o povo era batizado, também Jesus foi batizado; e, enquanto orava, o céu se abriu,"},
{v:22,t:"e o Espírito Santo desceu sobre ele em forma corpórea, como pomba; e veio do céu uma voz: Tu és o meu Filho amado, em ti me comprazo."}
];

EV[20] = [
{p:"Mateus 4:1-11"},
{v:1,t:"Então Jesus foi conduzido pelo Espírito ao deserto, para ser tentado pelo diabo."},
{v:2,t:"Depois de jejuar quarenta dias e quarenta noites, teve fome."},
{v:3,t:"O tentador aproximou-se e disse a ele: Se és Filho de Deus, manda que estas pedras se tornem pães."},
{v:4,t:"Ele respondeu: Está escrito: Não só de pão viverá o homem, mas de toda palavra que sai da boca de Deus."},
{v:5,t:"Então o diabo o levou à Cidade Santa, colocou-o sobre o pináculo do Templo"},
{v:6,t:"e disse a ele: Se és Filho de Deus, lança-te daqui abaixo, pois está escrito: Aos seus anjos dará ordens a teu respeito, e eles te sustentarão nas mãos, para que não tropeces em alguma pedra."},
{v:7,t:"Jesus respondeu: Também está escrito: Não tentarás o Senhor, teu Deus."},
{v:8,t:"De novo o diabo o levou a um monte muito alto, mostrou a ele todos os reinos do mundo e a sua glória"},
{v:9,t:"e disse: Tudo isto darei a ti, se, prostrado, me adorares."},
{v:10,t:"Então Jesus disse a ele: Vai-te, Satanás, pois está escrito: Adorarás o Senhor, teu Deus, e só a ele prestarás culto."},
{v:11,t:"Então o diabo o deixou; e eis que os anjos se aproximaram e o serviam."},
{p:"Marcos 1:12-13"},
{v:12,t:"Logo depois, o Espírito o impeliu para o deserto."},
{v:13,t:"E esteve no deserto quarenta dias, tentado por Satanás; vivia entre as feras, e os anjos o serviam."},
{p:"Lucas 4:1-13"},
{v:1,t:"Jesus, cheio do Espírito Santo, voltou do Jordão e era conduzido pelo Espírito no deserto,"},
{v:2,t:"durante quarenta dias, sendo tentado pelo diabo. Não comeu nada naqueles dias e, terminados eles, teve fome."},
{v:3,t:"O diabo disse a ele: Se és Filho de Deus, manda que esta pedra se torne pão."},
{v:4,t:"Jesus respondeu: Está escrito: Não só de pão viverá o homem."},
{v:5,t:"Levando-o ao alto, o diabo mostrou a ele, num instante, todos os reinos da terra"},
{v:6,t:"e disse: Darei a ti todo este poder e a glória destes reinos, porque foram entregues a mim e eu os dou a quem quero."},
{v:7,t:"Portanto, se te prostrares diante de mim, tudo será teu."},
{v:8,t:"Jesus respondeu: Está escrito: Adorarás o Senhor, teu Deus, e só a ele prestarás culto."},
{v:9,t:"Então o levou a Jerusalém, colocou-o sobre o pináculo do Templo e disse: Se és Filho de Deus, lança-te daqui abaixo,"},
{v:10,t:"pois está escrito: Aos seus anjos dará ordens a teu respeito, para que te guardem;"},
{v:11,t:"e: Eles te sustentarão nas mãos, para que não tropeces em alguma pedra."},
{v:12,t:"Jesus respondeu: Está dito: Não tentarás o Senhor, teu Deus."},
{v:13,t:"Terminada toda tentação, o diabo afastou-se dele até o tempo oportuno."}
];

EV[21] = [
{p:"João 1:19-34"},
{v:19,t:"Este é o testemunho de João, quando os judeus enviaram de Jerusalém sacerdotes e levitas para perguntarem a ele: Quem és tu?"},
{v:20,t:"Ele confessou e não negou; confessou: Eu não sou o Cristo."},
{v:21,t:"Perguntaram: Então quem és? És Elias? Disse: Não sou. És o Profeta? Respondeu: Não.",n:"O Profeta é a figura anunciada por Moisés no Deuteronômio, esperada para os tempos messiânicos."},
{v:22,t:"Disseram então: Quem és? Para darmos resposta aos que nos enviaram, que dizes de ti mesmo?"},
{v:23,t:"Declarou: Eu sou a voz do que clama no deserto: Endireitai o caminho do Senhor, como disse o profeta Isaías."},
{v:24,t:"Os enviados eram dos fariseus"},
{v:25,t:"e perguntaram: Por que batizas, então, se não és o Cristo, nem Elias, nem o Profeta?"},
{v:26,t:"João respondeu: Eu batizo com água; no meio de vós está quem vós não conheceis,"},
{v:27,t:"aquele que vem depois de mim, de quem não sou digno de desatar a correia da sandália."},
{v:28,t:"Isso aconteceu em Betânia, além do Jordão, onde João estava batizando."},
{v:29,t:"No dia seguinte, viu Jesus vir ao seu encontro e disse: Eis o Cordeiro de Deus, que tira o pecado do mundo.",n:"O verbo airein significa tirar e carregar: o Cordeiro remove o pecado tomando-o sobre si, como o Servo de Isaías."},
{v:30,t:"Este é aquele de quem eu disse: Depois de mim vem um homem que passou adiante de mim, porque existia antes de mim."},
{v:31,t:"Eu não o conhecia, mas foi para que ele fosse manifestado a Israel que eu vim batizar com água."},
{v:32,t:"E João deu testemunho, dizendo: Vi o Espírito descer do céu como pomba e permanecer sobre ele."},
{v:33,t:"Eu não o conhecia, mas quem me enviou a batizar com água disse a mim: Aquele sobre quem vires o Espírito descer e permanecer, esse é o que batiza no Espírito Santo."},
{v:34,t:"E eu vi e dou testemunho: este é o Filho de Deus."}
];

EV[22] = [
{p:"João 1:35-51"},
{v:35,t:"No dia seguinte, João estava de novo ali com dois dos seus discípulos"},
{v:36,t:"e, fixando o olhar em Jesus, que passava, disse: Eis o Cordeiro de Deus."},
{v:37,t:"Os dois discípulos ouviram-no falar e seguiram Jesus."},
{v:38,t:"Jesus voltou-se e, vendo que o seguiam, perguntou: Que procurais? Disseram: Rabi — que quer dizer Mestre —, onde moras?"},
{v:39,t:"Respondeu: Vinde e vede. Foram, viram onde morava e permaneceram com ele aquele dia; era por volta da hora décima.",n:"Cerca de quatro horas da tarde."},
{v:40,t:"André, irmão de Simão Pedro, era um dos dois que tinham ouvido João e seguido Jesus."},
{v:41,t:"Ele encontrou primeiro o seu irmão Simão e disse: Encontramos o Messias — que quer dizer Cristo —"},
{v:42,t:"e o levou a Jesus. Fixando nele o olhar, Jesus disse: Tu és Simão, filho de João; tu te chamarás Cefas — que quer dizer Pedra."},
{v:43,t:"No dia seguinte, Jesus resolveu partir para a Galileia. Encontrou Filipe e disse a ele: Segue-me."},
{v:44,t:"Filipe era de Betsaida, a cidade de André e de Pedro."},
{v:45,t:"Filipe encontrou Natanael e disse: Encontramos aquele de quem escreveram Moisés, na Lei, e os profetas: Jesus, filho de José, de Nazaré."},
{v:46,t:"Natanael disse: De Nazaré pode sair algo de bom? Filipe respondeu: Vem e vê."},
{v:47,t:"Jesus viu Natanael vir ao seu encontro e disse dele: Eis um verdadeiro israelita, em quem não há falsidade."},
{v:48,t:"Natanael perguntou: Donde me conheces? Jesus respondeu: Antes de Filipe te chamar, eu te vi, quando estavas debaixo da figueira."},
{v:49,t:"Natanael respondeu: Rabi, tu és o Filho de Deus, tu és o Rei de Israel!"},
{v:50,t:"Jesus disse: Crês porque eu disse que te vi debaixo da figueira? Verás coisas maiores do que estas."},
{v:51,t:"E acrescentou: Em verdade, em verdade vos digo: vereis o céu aberto e os anjos de Deus subirem e descerem sobre o Filho do Homem.",n:"Alusão à escada de Jacó: Cristo é o novo lugar do encontro entre o céu e a terra."}
];

EV[23] = [
{p:"João 2:1-12"},
{v:1,t:"Três dias depois, houve umas bodas em Caná da Galileia, e a mãe de Jesus estava ali."},
{v:2,t:"Também Jesus foi convidado para as bodas, com os seus discípulos."},
{v:3,t:"Faltando o vinho, a mãe de Jesus disse a ele: Não têm vinho."},
{v:4,t:"Jesus respondeu: Que há entre mim e ti, mulher? Ainda não chegou a minha hora.",n:"A expressão semítica que há entre mim e ti marca distância entre planos, sem aspereza; mulher, no uso de João, é tratamento solene, que reaparecerá junto à cruz."},
{v:5,t:"Sua mãe disse aos que serviam: Fazei tudo o que ele vos disser."},
{v:6,t:"Havia ali seis talhas de pedra, destinadas à purificação dos judeus, cada uma com capacidade de duas ou três medidas.",n:"Cada medida, o metretes, equivalia a cerca de quarenta litros."},
{v:7,t:"Jesus disse a eles: Enchei as talhas de água. E encheram-nas até em cima."},
{v:8,t:"Então disse: Tirai agora e levai ao mestre-sala. E levaram."},
{v:9,t:"Quando o mestre-sala provou a água transformada em vinho — e não sabia donde vinha, mas sabiam os que serviam, que tinham tirado a água —, chamou o esposo"},
{v:10,t:"e disse: Todo homem serve primeiro o vinho bom e, quando já beberam bastante, o inferior; tu guardaste o vinho bom até agora."},
{v:11,t:"Este princípio dos sinais, Jesus o fez em Caná da Galileia; manifestou a sua glória, e os seus discípulos creram nele."},
{v:12,t:"Depois disso, desceu a Cafarnaum com sua mãe, seus irmãos e seus discípulos, e permaneceram ali poucos dias.",n:"Irmãos, no uso semítico, abrange os parentes próximos, como primos; nada diz de outros filhos de Maria."}
];

EV[24] = [
{p:"João 2:13-25"},
{v:13,t:"Estava próxima a Páscoa dos judeus, e Jesus subiu a Jerusalém."},
{v:14,t:"Encontrou no Templo os vendedores de bois, ovelhas e pombas, e os cambistas sentados;"},
{v:15,t:"e, fazendo um chicote de cordas, expulsou todos do Templo, com as ovelhas e os bois; espalhou o dinheiro dos cambistas e derrubou as mesas;"},
{v:16,t:"e aos que vendiam pombas disse: Tirai isto daqui; não façais da casa de meu Pai uma casa de comércio."},
{v:17,t:"Os seus discípulos lembraram-se de que está escrito: O zelo da tua casa me devorará."},
{v:18,t:"Os judeus então disseram a ele: Que sinal nos mostras, para fazeres essas coisas?"},
{v:19,t:"Jesus respondeu: Destruí este templo, e em três dias eu o levantarei."},
{v:20,t:"Os judeus disseram: Em quarenta e seis anos foi construído este templo, e tu o levantarás em três dias?"},
{v:21,t:"Mas ele falava do templo do seu corpo."},
{v:22,t:"Por isso, quando ressuscitou dos mortos, os seus discípulos lembraram-se de que ele dissera isso e creram na Escritura e na palavra que Jesus dissera."},
{v:23,t:"Enquanto estava em Jerusalém, na festa da Páscoa, muitos creram no seu nome, vendo os sinais que fazia."},
{v:24,t:"Mas Jesus não se confiava a eles, porque os conhecia a todos"},
{v:25,t:"e não precisava de que alguém desse testemunho sobre o homem, pois ele sabia o que há no homem."}
];

EV[25] = [
{p:"João 3:1-21"},
{v:1,t:"Havia entre os fariseus um homem chamado Nicodemos, um dos chefes dos judeus."},
{v:2,t:"Ele foi ter com Jesus de noite e disse: Rabi, sabemos que vieste de Deus como mestre, pois ninguém pode fazer os sinais que tu fazes, se Deus não estiver com ele."},
{v:3,t:"Jesus respondeu: Em verdade, em verdade te digo: quem não nascer do alto não pode ver o Reino de Deus.",n:"O advérbio anothen significa ao mesmo tempo do alto e de novo; o duplo sentido sustenta todo o diálogo."},
{v:4,t:"Nicodemos perguntou: Como pode um homem nascer, sendo velho? Pode entrar segunda vez no ventre de sua mãe e nascer?"},
{v:5,t:"Jesus respondeu: Em verdade, em verdade te digo: quem não nascer da água e do Espírito não pode entrar no Reino de Deus."},
{v:6,t:"O que nasceu da carne é carne, e o que nasceu do Espírito é espírito."},
{v:7,t:"Não te admires de eu te dizer: é necessário nascerdes do alto."},
{v:8,t:"O vento sopra onde quer, e ouves a sua voz, mas não sabes donde vem nem para onde vai; assim é todo aquele que nasceu do Espírito.",n:"Em grego, pneuma designa tanto o vento quanto o Espírito: a frase joga com os dois sentidos."},
{v:9,t:"Nicodemos perguntou: Como pode ser isso?"},
{v:10,t:"Jesus respondeu: Tu és mestre em Israel e não sabes isso?"},
{v:11,t:"Em verdade, em verdade te digo: nós falamos do que sabemos e damos testemunho do que vimos, mas vós não recebeis o nosso testemunho."},
{v:12,t:"Se vos falei das coisas terrenas e não credes, como crereis, se eu vos falar das celestes?"},
{v:13,t:"Ninguém subiu ao céu senão aquele que desceu do céu, o Filho do Homem."},
{v:14,t:"E, como Moisés levantou a serpente no deserto, assim é necessário que o Filho do Homem seja levantado,"},
{v:15,t:"para que todo o que crê tenha nele a vida eterna."},
{v:16,t:"Pois Deus amou tanto o mundo, que deu o seu Filho unigênito, para que todo o que crê nele não pereça, mas tenha a vida eterna."},
{v:17,t:"Porque Deus não enviou o seu Filho ao mundo para julgar o mundo, mas para que o mundo seja salvo por ele."},
{v:18,t:"Quem crê nele não é julgado; quem não crê já está julgado, porque não creu no nome do Filho unigênito de Deus."},
{v:19,t:"O julgamento é este: a luz veio ao mundo, e os homens amaram mais as trevas do que a luz, porque as suas obras eram más."},
{v:20,t:"Pois todo o que pratica o mal odeia a luz e não vem para a luz, para que as suas obras não sejam reprovadas;"},
{v:21,t:"mas quem pratica a verdade vem para a luz, para que se manifeste que as suas obras são feitas em Deus."}
];

EV[26] = [
{p:"João 3:22-36"},
{v:22,t:"Depois disso, Jesus foi com os seus discípulos para a terra da Judeia; permanecia ali com eles e batizava."},
{v:23,t:"João também batizava em Enon, perto de Salim, porque havia ali muitas águas, e as pessoas iam e eram batizadas;"},
{v:24,t:"pois João ainda não tinha sido lançado na prisão."},
{v:25,t:"Surgiu então uma discussão entre os discípulos de João e um judeu, a respeito da purificação."},
{v:26,t:"Foram a João e disseram: Rabi, aquele que estava contigo além do Jordão, de quem deste testemunho, ei-lo batizando, e todos vão a ele."},
{v:27,t:"João respondeu: Ninguém pode receber coisa alguma, se não for dada a ele do céu."},
{v:28,t:"Vós mesmos sois testemunhas de que eu disse: Eu não sou o Cristo, mas fui enviado adiante dele."},
{v:29,t:"Quem tem a esposa é o esposo; mas o amigo do esposo, que está presente e o ouve, alegra-se muito com a voz do esposo. Esta minha alegria está completa."},
{v:30,t:"É necessário que ele cresça e que eu diminua."},
{v:31,t:"Quem vem do alto está acima de todos; quem é da terra pertence à terra e fala da terra. Quem vem do céu está acima de todos:"},
{v:32,t:"dá testemunho do que viu e ouviu, e ninguém recebe o seu testemunho."},
{v:33,t:"Quem recebe o seu testemunho atesta que Deus é verdadeiro."},
{v:34,t:"Pois aquele que Deus enviou fala as palavras de Deus, porque ele dá o Espírito sem medida."},
{v:35,t:"O Pai ama o Filho e entregou tudo na sua mão."},
{v:36,t:"Quem crê no Filho tem a vida eterna; quem não obedece ao Filho não verá a vida, mas a ira de Deus permanece sobre ele."}
];

EV[27] = [
{p:"João 4:1-42"},
{v:1,t:"Quando Jesus soube que os fariseus tinham ouvido dizer que ele fazia mais discípulos e batizava mais do que João"},
{v:2,t:"— embora Jesus mesmo não batizasse, mas os seus discípulos —,"},
{v:3,t:"deixou a Judeia e partiu de novo para a Galileia."},
{v:4,t:"Devia passar pela Samaria."},
{v:5,t:"Chegou então a uma cidade da Samaria chamada Sicar, perto do terreno que Jacó dera a seu filho José."},
{v:6,t:"Ficava ali o poço de Jacó. Jesus, cansado da caminhada, sentou-se junto ao poço; era por volta da hora sexta.",n:"Por volta do meio-dia."},
{v:7,t:"Veio uma mulher da Samaria tirar água. Jesus disse a ela: Dá-me de beber."},
{v:8,t:"Os seus discípulos tinham ido à cidade comprar alimento."},
{v:9,t:"A mulher samaritana disse a ele: Como tu, sendo judeu, pedes de beber a mim, que sou samaritana? Pois os judeus não se dão com os samaritanos."},
{v:10,t:"Jesus respondeu: Se conhecesses o dom de Deus e quem é o que te diz: Dá-me de beber, tu é que pedirias a ele, e ele daria a ti água viva.",n:"Água viva designa, no uso comum, a água corrente de fonte; nos lábios de Jesus, o dom do Espírito."},
{v:11,t:"A mulher disse: Senhor, não tens com que tirar a água, e o poço é fundo; donde tens, pois, a água viva?"},
{v:12,t:"És maior do que o nosso pai Jacó, que nos deu o poço e dele bebeu, com os seus filhos e o seu gado?"},
{v:13,t:"Jesus respondeu: Todo o que bebe desta água terá sede de novo,"},
{v:14,t:"mas quem beber da água que eu darei a ele nunca mais terá sede: a água que eu darei se tornará nele uma fonte de água que jorra para a vida eterna."},
{v:15,t:"A mulher disse: Senhor, dá-me dessa água, para que eu não tenha mais sede nem venha aqui tirá-la."},
{v:16,t:"Ele disse: Vai, chama o teu marido e volta aqui."},
{v:17,t:"A mulher respondeu: Não tenho marido. Jesus disse: Disseste bem: não tenho marido;"},
{v:18,t:"pois tiveste cinco maridos, e o que agora tens não é teu marido; nisso falaste a verdade."},
{v:19,t:"A mulher disse: Senhor, vejo que és profeta."},
{v:20,t:"Os nossos pais adoraram neste monte, e vós dizeis que em Jerusalém está o lugar onde se deve adorar.",n:"O monte é o Garizim, onde os samaritanos tinham erguido o seu templo."},
{v:21,t:"Jesus disse: Mulher, crê em mim: vem a hora em que nem neste monte nem em Jerusalém adorareis o Pai."},
{v:22,t:"Vós adorais o que não conheceis; nós adoramos o que conhecemos, porque a salvação vem dos judeus."},
{v:23,t:"Mas vem a hora, e é agora, em que os verdadeiros adoradores adorarão o Pai em espírito e verdade, pois são esses os adoradores que o Pai procura."},
{v:24,t:"Deus é espírito, e os que o adoram devem adorar em espírito e verdade."},
{v:25,t:"A mulher disse: Sei que vem o Messias, chamado Cristo; quando ele vier, anunciará a nós todas as coisas."},
{v:26,t:"Jesus disse a ela: Sou eu, que falo contigo."},
{v:27,t:"Nisso chegaram os seus discípulos e admiravam-se de que falasse com uma mulher; contudo, ninguém perguntou: Que procuras? ou: Por que falas com ela?"},
{v:28,t:"A mulher deixou o seu cântaro, foi à cidade e disse às pessoas:"},
{v:29,t:"Vinde ver um homem que me disse tudo o que fiz. Não será ele o Cristo?"},
{v:30,t:"Saíram da cidade e foram ao seu encontro."},
{v:31,t:"Entretanto, os discípulos pediam a ele: Rabi, come."},
{v:32,t:"Mas ele disse: Eu tenho um alimento para comer que vós não conheceis."},
{v:33,t:"Os discípulos diziam entre si: Alguém trouxe de comer para ele?"},
{v:34,t:"Jesus disse a eles: O meu alimento é fazer a vontade daquele que me enviou e consumar a sua obra."},
{v:35,t:"Não dizeis vós que ainda faltam quatro meses para a colheita? Eis que eu vos digo: levantai os olhos e vede os campos, que já estão dourados para a colheita."},
{v:36,t:"O que colhe recebe salário e recolhe fruto para a vida eterna, para que se alegrem juntos o que semeia e o que colhe."},
{v:37,t:"Nisto é verdadeiro o provérbio: um é o que semeia, outro o que colhe."},
{v:38,t:"Eu vos enviei a colher o que não trabalhastes; outros trabalharam, e vós entrastes no seu trabalho."},
{v:39,t:"Muitos samaritanos daquela cidade creram nele por causa da palavra da mulher, que testemunhava: Ele me disse tudo o que fiz."},
{v:40,t:"Por isso, quando os samaritanos foram ao seu encontro, pediram a ele que permanecesse com eles; e permaneceu ali dois dias."},
{v:41,t:"E muitos mais creram por causa da sua palavra"},
{v:42,t:"e diziam à mulher: Já não é por causa do que disseste que cremos; nós mesmos ouvimos e sabemos que este é verdadeiramente o Salvador do mundo."}
];

EV[28] = [
{p:"João 4:43-54"},
{v:43,t:"Passados os dois dias, partiu dali para a Galileia."},
{v:44,t:"O próprio Jesus testemunhara que um profeta não tem honra na sua pátria."},
{v:45,t:"Quando chegou à Galileia, os galileus o acolheram, porque tinham visto tudo o que fizera em Jerusalém durante a festa; pois também eles tinham ido à festa."},
{v:46,t:"Foi então de novo a Caná da Galileia, onde transformara a água em vinho. Havia um funcionário real cujo filho estava doente em Cafarnaum."},
{v:47,t:"Ao ouvir que Jesus chegara da Judeia à Galileia, foi ao seu encontro e pedia a ele que descesse e curasse o seu filho, que estava à morte."},
{v:48,t:"Jesus disse a ele: Se não virdes sinais e prodígios, não credes."},
{v:49,t:"O funcionário disse: Senhor, desce, antes que o meu menino morra."},
{v:50,t:"Jesus respondeu: Vai, o teu filho vive. O homem creu na palavra que Jesus dissera a ele e partiu."},
{v:51,t:"Quando já descia, os seus servos vieram ao seu encontro, dizendo que o seu menino vivia."},
{v:52,t:"Perguntou a eles a hora em que melhorara; responderam: Ontem, à hora sétima, a febre o deixou.",n:"Cerca de uma hora da tarde."},
{v:53,t:"O pai reconheceu que era aquela a hora em que Jesus dissera: O teu filho vive; e creu ele e toda a sua casa."},
{v:54,t:"Este segundo sinal fez Jesus, ao voltar da Judeia para a Galileia."}
];

EV[29] = [
{p:"Mateus 14:3-5"},
{v:3,t:"Pois Herodes prendera João, acorrentara-o e o metera no cárcere por causa de Herodíades, mulher de Filipe, seu irmão,"},
{v:4,t:"porque João dizia a ele: Não é lícito a ti possuí-la."},
{v:5,t:"E, querendo matá-lo, temia o povo, porque o tinham por profeta."},
{p:"Lucas 3:19-20"},
{v:19,t:"Mas Herodes, o tetrarca, repreendido por ele por causa de Herodíades, mulher do seu irmão, e por todos os males que praticara,"},
{v:20,t:"acrescentou a todos eles ainda este: encerrou João no cárcere."}
];

EV[30] = [
{p:"João 5:1-15"},
{v:1,t:"Depois disso, havia uma festa dos judeus, e Jesus subiu a Jerusalém."},
{v:2,t:"Há em Jerusalém, junto à porta das Ovelhas, uma piscina chamada em hebraico Betesda, que tem cinco pórticos."},
{v:3,t:"Neles jazia uma multidão de enfermos: cegos, coxos, paralíticos.",n:"A parte final do v. 3 e o v. 4, sobre o anjo que descia a agitar a água, faltam nos manuscritos mais antigos; a Nova Vulgata os omite, e a numeração salta do v. 3 ao v. 5."},
{v:5,t:"Estava ali um homem enfermo havia trinta e oito anos."},
{v:6,t:"Jesus, vendo-o deitado e sabendo que estava assim havia muito tempo, disse a ele: Queres ficar são?"},
{v:7,t:"O enfermo respondeu: Senhor, não tenho ninguém que me ponha na piscina quando a água é agitada; enquanto eu vou, outro desce antes de mim."},
{v:8,t:"Jesus disse a ele: Levanta-te, toma o teu leito e anda."},
{v:9,t:"No mesmo instante, o homem ficou são, tomou o seu leito e andava. Aquele dia era sábado."},
{v:10,t:"Os judeus diziam então ao que fora curado: É sábado; não é lícito a ti carregar o teu leito."},
{v:11,t:"Ele respondeu: Aquele que me fez são disse a mim: Toma o teu leito e anda."},
{v:12,t:"Perguntaram: Quem é o homem que te disse: Toma e anda?"},
{v:13,t:"Mas o que fora curado não sabia quem era, pois Jesus se afastara da multidão que estava naquele lugar."},
{v:14,t:"Depois disso, Jesus o encontrou no Templo e disse a ele: Eis que ficaste são; não peques mais, para que não te aconteça coisa pior."},
{v:15,t:"O homem foi anunciar aos judeus que fora Jesus quem o fizera são."}
];

EV[31] = [
{p:"João 5:16-47"},
{v:16,t:"Por isso os judeus perseguiam Jesus, porque fazia essas coisas no sábado."},
{v:17,t:"Mas ele respondeu a eles: Meu Pai trabalha até agora, e eu também trabalho.",n:"O descanso do sétimo dia não interrompe a obra pela qual Deus conserva o mundo; ao dizer que trabalha com o Pai, Jesus reivindica a mesma obra, e é isso que os ouvintes entendem no versículo seguinte."},
{v:18,t:"Por isso os judeus procuravam ainda mais matá-lo, porque não só violava o sábado, mas também dizia que Deus era seu próprio Pai, fazendo-se igual a Deus."},
{v:19,t:"Jesus respondeu e disse a eles: Em verdade, em verdade vos digo: o Filho não pode fazer nada de si mesmo, senão o que vê o Pai fazer; pois o que este faz, o Filho o faz igualmente."},
{v:20,t:"Porque o Pai ama o Filho e mostra a ele tudo o que faz; e obras maiores do que estas mostrará a ele, para que vos admireis."},
{v:21,t:"Pois, como o Pai ressuscita os mortos e lhes dá a vida, assim também o Filho dá a vida a quem quer."},
{v:22,t:"Porque o Pai não julga ninguém, mas entregou todo o julgamento ao Filho,"},
{v:23,t:"para que todos honrem o Filho como honram o Pai. Quem não honra o Filho não honra o Pai que o enviou."},
{v:24,t:"Em verdade, em verdade vos digo: quem ouve a minha palavra e crê naquele que me enviou tem a vida eterna e não vem a julgamento, mas passou da morte para a vida."},
{v:25,t:"Em verdade, em verdade vos digo: vem a hora, e é agora, em que os mortos ouvirão a voz do Filho de Deus, e os que a ouvirem viverão.",n:"E é agora: a ressurreição final já começou a agir no presente, nos que passam da morte do pecado para a vida pela fé. Nos vv. 28-29 o mesmo anúncio se volta para a ressurreição dos corpos."},
{v:26,t:"Pois, como o Pai tem a vida em si mesmo, assim também deu ao Filho ter a vida em si mesmo;"},
{v:27,t:"e deu a ele o poder de exercer o julgamento, porque é Filho do Homem.",n:"Aqui a expressão vem sem artigo em grego, aproximando-se da visão de Daniel 7, em que um como filho de homem recebe o poder de julgar."},
{v:28,t:"Não vos admireis disso, porque vem a hora em que todos os que estão nos sepulcros ouvirão a sua voz"},
{v:29,t:"e sairão: os que fizeram o bem, para a ressurreição da vida; os que praticaram o mal, para a ressurreição do julgamento."},
{v:30,t:"Eu não posso fazer nada de mim mesmo. Julgo conforme ouço, e o meu julgamento é justo, porque não busco a minha vontade, mas a vontade daquele que me enviou."},
{v:31,t:"Se eu dou testemunho de mim mesmo, o meu testemunho não é válido.",n:"A Lei não aceitava a palavra de uma só testemunha; Jesus assume a exigência e passa a enumerar as testemunhas que o abonam: João, as obras, o Pai, as Escrituras."},
{v:32,t:"Outro é o que dá testemunho de mim, e sei que é verdadeiro o testemunho que ele dá de mim."},
{v:33,t:"Vós enviastes mensageiros a João, e ele deu testemunho da verdade."},
{v:34,t:"Eu, porém, não recebo testemunho de homem; digo isso para que sejais salvos."},
{v:35,t:"Ele era a lâmpada que arde e ilumina, e vós quisestes alegrar-vos por um momento na sua luz."},
{v:36,t:"Mas eu tenho um testemunho maior que o de João: as obras que o Pai me deu para realizar, essas mesmas obras que faço dão testemunho de mim, de que o Pai me enviou."},
{v:37,t:"E o Pai que me enviou, ele mesmo deu testemunho de mim. Nunca ouvistes a sua voz, nem vistes a sua face,"},
{v:38,t:"e não tendes a sua palavra permanecendo em vós, porque não credes naquele que ele enviou."},
{v:39,t:"Examinais as Escrituras, porque julgais ter nelas a vida eterna; e são elas que dão testemunho de mim.",n:"A forma grega tanto pode ser afirmação como ordem: examinais as Escrituras ou examinai as Escrituras. O sentido não muda muito, pois a censura recai sobre parar no livro sem chegar àquele de quem o livro fala."},
{v:40,t:"E não quereis vir a mim para terdes a vida."},
{v:41,t:"Não recebo glória dos homens."},
{v:42,t:"Mas eu vos conheço: não tendes em vós o amor de Deus."},
{v:43,t:"Eu vim em nome de meu Pai, e não me recebeis; se outro vier em seu próprio nome, a esse recebereis."},
{v:44,t:"Como podeis crer, vós que recebeis glória uns dos outros e não buscais a glória que vem do Deus único?"},
{v:45,t:"Não penseis que eu vos acusarei diante do Pai; há quem vos acuse: Moisés, em quem esperais."},
{v:46,t:"Pois, se crêsseis em Moisés, creríeis também em mim, porque ele escreveu a meu respeito."},
{v:47,t:"Mas, se não credes nos seus escritos, como crereis nas minhas palavras?"}
];

EV[32] = [
{p:"Mateus 4:12"},
{v:12,t:"Ouvindo que João fora entregue, retirou-se para a Galileia.",n:"Entregue verte paradothenai, o mesmo verbo que os Evangelhos usarão para a entrega de Jesus: a sorte do precursor prefigura a do Senhor."},
{p:"Marcos 1:14-15"},
{v:14,t:"Depois que João foi entregue, Jesus foi para a Galileia, pregando o Evangelho de Deus"},
{v:15,t:"e dizendo: O tempo está cumprido e o Reino de Deus está próximo; convertei-vos e crede no Evangelho.",n:"Convertei-vos traduz metanoeite, que pede uma mudança do modo de pensar e de julgar, e não apenas o pesar pelo que se fez."},
{p:"Lucas 4:14-15"},
{v:14,t:"E Jesus voltou, no poder do Espírito, para a Galileia, e a sua fama correu por toda a região vizinha."},
{v:15,t:"Ele ensinava nas suas sinagogas, glorificado por todos."}
];

EV[33] = [
{p:"Lucas 4:16-30"},
{v:16,t:"Foi a Nazaré, onde fora criado, e entrou, segundo o seu costume, no dia de sábado, na sinagoga, e levantou-se para ler."},
{v:17,t:"Foi dado a ele o livro do profeta Isaías; e, desenrolando o livro, encontrou o lugar onde estava escrito:"},
{v:18,t:"O Espírito do Senhor está sobre mim, pelo que me ungiu para anunciar a Boa Nova aos pobres; enviou-me a proclamar aos cativos a libertação e aos cegos a recuperação da vista, a pôr em liberdade os oprimidos,",n:"Ungiu verte echrisen, do mesmo radical de Cristo: ao ler Isaías, Jesus diz que a unção anunciada recai sobre ele."},
{v:19,t:"a proclamar um ano de graça do Senhor.",n:"O ano de graça é o jubileu de Levítico 25, em que se perdoavam as dívidas e se devolviam as terras; Jesus o toma como figura do que vem realizar."},
{v:20,t:"Enrolando o livro, devolveu-o ao servente e sentou-se; e os olhos de todos na sinagoga estavam fixos nele."},
{v:21,t:"Começou a dizer a eles: Hoje se cumpriu esta Escritura aos vossos ouvidos."},
{v:22,t:"E todos davam testemunho dele e admiravam-se das palavras de graça que saíam da sua boca, e diziam: Não é este o filho de José?"},
{v:23,t:"Ele disse a eles: Sem dúvida me direis este provérbio: Médico, cura-te a ti mesmo. Tudo o que ouvimos ter acontecido em Cafarnaum, faze-o também aqui, na tua pátria."},
{v:24,t:"E acrescentou: Em verdade vos digo que nenhum profeta é bem recebido na sua pátria."},
{v:25,t:"Na verdade vos digo: muitas viúvas havia em Israel nos dias de Elias, quando o céu se fechou por três anos e seis meses, de modo que houve grande fome por toda a terra;"},
{v:26,t:"e a nenhuma delas foi enviado Elias, senão a uma mulher viúva de Sarepta, na Sidônia."},
{v:27,t:"E muitos leprosos havia em Israel no tempo do profeta Eliseu; e nenhum deles foi purificado, senão Naamã, o sírio.",n:"Os dois exemplos são de estrangeiros socorridos enquanto Israel era passado adiante; é essa universalidade, e não a pretensão messiânica, o que acende a ira dos ouvintes."},
{v:28,t:"Ouvindo isso, todos na sinagoga se encheram de ira;"},
{v:29,t:"e, levantando-se, lançaram-no fora da cidade e o levaram até ao alto do monte sobre o qual a sua cidade estava edificada, para o precipitarem."},
{v:30,t:"Ele, porém, passando pelo meio deles, seguia o seu caminho."}
];

EV[34] = [
{p:"Mateus 4:13-17"},
{v:13,t:"E, deixando Nazaré, foi habitar em Cafarnaum, à beira-mar, nos confins de Zabulon e Neftali,"},
{v:14,t:"para que se cumprisse o que foi dito pelo profeta Isaías:"},
{v:15,t:"Terra de Zabulon e terra de Neftali, caminho do mar, além do Jordão, Galileia dos gentios:"},
{v:16,t:"o povo que jazia nas trevas viu uma grande luz; e sobre os que jaziam na região e sombra da morte, uma luz se levantou."},
{v:17,t:"Desde então começou Jesus a pregar e a dizer: Convertei-vos, porque o Reino dos céus está próximo.",n:"Reino dos céus é a forma preferida por São Mateus, que evita pronunciar o nome de Deus; equivale ao Reino de Deus dos outros evangelistas."},
{p:"Lucas 4:31"},
{v:31,t:"Desceu a Cafarnaum, cidade da Galileia, e ali os ensinava nos sábados."}
];

EV[35] = [
{p:"Mateus 4:18-22"},
{v:18,t:"Caminhando junto ao mar da Galileia, viu dois irmãos, Simão, chamado Pedro, e André, seu irmão, lançando a rede ao mar, pois eram pescadores."},
{v:19,t:"E disse a eles: Vinde após mim, e eu vos farei pescadores de homens."},
{v:20,t:"Eles, deixando imediatamente as redes, seguiram-no."},
{v:21,t:"Passando adiante, viu outros dois irmãos, Tiago, filho de Zebedeu, e João, seu irmão, na barca com Zebedeu, seu pai, consertando as suas redes; e os chamou."},
{v:22,t:"Eles, deixando imediatamente a barca e seu pai, seguiram-no."},
{p:"Marcos 1:16-20"},
{v:16,t:"Passando junto ao mar da Galileia, viu Simão e André, irmão de Simão, lançando as redes ao mar, pois eram pescadores."},
{v:17,t:"E disse a eles Jesus: Vinde após mim, e farei que vos torneis pescadores de homens."},
{v:18,t:"E logo, deixando as redes, seguiram-no."},
{v:19,t:"Adiantando-se um pouco, viu Tiago, filho de Zebedeu, e João, seu irmão, também eles na barca, consertando as redes;"},
{v:20,t:"e logo os chamou. Deixando na barca seu pai Zebedeu com os assalariados, foram após ele."},
{p:"Lucas 5:1-11"},
{v:1,t:"Ora, apertando-o a multidão para ouvir a palavra de Deus, ele estava junto ao lago de Genesaré,"},
{v:2,t:"e viu duas barcas paradas à beira do lago; os pescadores tinham descido delas e lavavam as redes."},
{v:3,t:"Subindo a uma das barcas, que era de Simão, pediu a ele que se afastasse um pouco da terra; e, sentado, ensinava as multidões desde a barca."},
{v:4,t:"Quando acabou de falar, disse a Simão: Faze-te ao largo e lançai as vossas redes para a pesca.",n:"A ordem passa do singular ao plural: faze-te tu ao largo, lançai vós as redes. O gesto é de Pedro, mas o trabalho é de todos."},
{v:5,t:"Simão respondeu: Mestre, trabalhamos a noite toda e nada apanhamos; mas, sobre a tua palavra, lançarei as redes."},
{v:6,t:"Feito isso, apanharam grande quantidade de peixes, e as suas redes rompiam-se."},
{v:7,t:"Fizeram sinal aos companheiros da outra barca, para que viessem ajudá-los; e vieram, e encheram ambas as barcas, a ponto de quase se afundarem."},
{v:8,t:"Vendo isso, Simão Pedro caiu aos joelhos de Jesus, dizendo: Afasta-te de mim, Senhor, porque sou um homem pecador."},
{v:9,t:"Pois o espanto o tomara, e a todos os que estavam com ele, pela pesca que tinham feito;"},
{v:10,t:"e igualmente a Tiago e a João, filhos de Zebedeu, que eram companheiros de Simão. E Jesus disse a Simão: Não temas; de agora em diante serás pescador de homens.",n:"O verbo grego zogrein significa apanhar vivo, poupar da morte; a pesca de que se fala não tira a vida, dá-a."},
{v:11,t:"E, levando as barcas para a terra, deixaram tudo e seguiram-no."}
];

EV[36] = [
{p:"Marcos 1:21-28"},
{v:21,t:"Entraram em Cafarnaum; e logo, no sábado, entrando na sinagoga, ensinava."},
{v:22,t:"E admiravam-se do seu ensino, porque os ensinava como quem tem autoridade, e não como os escribas.",n:"Os escribas ensinavam apoiando-se na cadeia dos mestres antigos; Jesus fala por si, e é essa exousia, autoridade que não se recebeu de outro, o que espanta."},
{v:23,t:"Havia logo na sinagoga deles um homem com espírito impuro, e ele gritou:"},
{v:24,t:"Que temos nós contigo, Jesus Nazareno? Vieste perder-nos? Sei quem tu és: o Santo de Deus.",n:"Que temos nós contigo traduz ao pé da letra um modo de dizer hebraico que recusa qualquer trato: não te metas conosco."},
{v:25,t:"Jesus o repreendeu, dizendo: Cala-te e sai dele."},
{v:26,t:"E o espírito impuro, agitando-o com violência e gritando com grande voz, saiu dele."},
{v:27,t:"Todos ficaram tão espantados que perguntavam entre si: Que é isto? Um ensino novo, com autoridade! Ele manda até nos espíritos impuros, e obedecem a ele."},
{v:28,t:"E logo a sua fama se espalhou por toda parte, em toda a região da Galileia."},
{p:"Lucas 4:32-37"},
{v:32,t:"E admiravam-se do seu ensino, porque a sua palavra era com autoridade."},
{v:33,t:"Havia na sinagoga um homem que tinha um espírito de demônio impuro, e gritou com grande voz:"},
{v:34,t:"Ah! Que temos nós contigo, Jesus Nazareno? Vieste perder-nos? Sei quem tu és: o Santo de Deus."},
{v:35,t:"Jesus o repreendeu, dizendo: Cala-te e sai dele. E o demônio, lançando-o por terra no meio, saiu dele sem lhe fazer mal algum."},
{v:36,t:"O espanto tomou a todos, e diziam uns aos outros: Que palavra é esta, que com autoridade e poder manda nos espíritos impuros, e eles saem?"},
{v:37,t:"E a sua fama se difundia por todos os lugares da região."}
];

EV[37] = [
{p:"Mateus 8:14-17"},
{v:14,t:"Chegando Jesus à casa de Pedro, viu a sogra dele deitada e com febre."},
{v:15,t:"Tocou-lhe a mão, e a febre a deixou; ela se levantou e o servia."},
{v:16,t:"Caída a tarde, trouxeram a ele muitos endemoninhados; e ele expulsava os espíritos com uma palavra, e curou todos os que estavam mal,"},
{v:17,t:"para que se cumprisse o que foi dito pelo profeta Isaías: Ele tomou as nossas enfermidades e carregou as nossas doenças."},
{p:"Marcos 1:29-34"},
{v:29,t:"E logo, saindo da sinagoga, foram à casa de Simão e André, com Tiago e João."},
{v:30,t:"A sogra de Simão estava de cama, com febre; e logo falaram a ele dela."},
{v:31,t:"Aproximando-se, ele a levantou, tomando-a pela mão; a febre a deixou, e ela os servia."},
{v:32,t:"Caída a tarde, quando o sol se pôs, traziam a ele todos os que estavam mal e os endemoninhados;",n:"Esperam o pôr do sol porque com ele acaba o sábado e volta a ser lícito carregar os doentes."},
{v:33,t:"e a cidade inteira estava reunida à porta."},
{v:34,t:"Curou muitos que estavam mal de diversas doenças e expulsou muitos demônios; e não deixava falar os demônios, porque o conheciam."},
{p:"Lucas 4:38-41"},
{v:38,t:"Levantando-se da sinagoga, entrou na casa de Simão. A sogra de Simão estava tomada de grande febre, e rogaram a ele por ela."},
{v:39,t:"Inclinando-se sobre ela, repreendeu a febre, e a febre a deixou; e ela, levantando-se imediatamente, os servia."},
{v:40,t:"Ao pôr do sol, todos os que tinham enfermos de várias doenças os traziam a ele; e ele, impondo as mãos sobre cada um, os curava."},
{v:41,t:"Também saíam demônios de muitos, gritando: Tu és o Filho de Deus. Mas ele os repreendia e não os deixava falar, porque sabiam que ele era o Cristo."}
];

EV[38] = [
{p:"Mateus 4:23-25"},
{v:23,t:"E percorria toda a Galileia, ensinando nas suas sinagogas, pregando o Evangelho do Reino e curando toda doença e toda enfermidade no povo."},
{v:24,t:"A sua fama correu por toda a Síria; e traziam a ele todos os que estavam mal, atormentados por várias doenças e sofrimentos, endemoninhados, lunáticos e paralíticos; e ele os curou."},
{v:25,t:"E seguiram-no numerosas multidões da Galileia, da Decápole, de Jerusalém, da Judeia e de além do Jordão."},
{p:"Marcos 1:35-39"},
{v:35,t:"De madrugada, ainda muito escuro, levantou-se, saiu e foi a um lugar deserto, e ali orava."},
{v:36,t:"Simão e os que estavam com ele foram à sua procura;"},
{v:37,t:"e, encontrando-o, disseram a ele: Todos te buscam."},
{v:38,t:"Ele respondeu: Vamos a outra parte, às povoações vizinhas, para que também ali eu pregue; pois para isso saí."},
{v:39,t:"E foi pregar nas sinagogas deles, por toda a Galileia, e expulsava os demônios."},
{p:"Lucas 4:42-44"},
{v:42,t:"Sendo já dia, saiu e foi a um lugar deserto; as multidões o procuravam e chegaram até ele, e o retinham, para que não se afastasse delas."},
{v:43,t:"Ele disse a eles: É necessário que eu anuncie o Reino de Deus também às outras cidades, pois para isso fui enviado."},
{v:44,t:"E pregava nas sinagogas da Judeia.",n:"Judeia está aqui no sentido largo de terra dos judeus, abrangendo a Galileia; parte dos manuscritos traz justamente Galileia."}
];

EV[39] = [
{p:"Mateus 8:1-4"},
{v:1,t:"Quando desceu do monte, seguiram-no numerosas multidões."},
{v:2,t:"E eis que um leproso, aproximando-se, prostrava-se diante dele, dizendo: Senhor, se queres, podes purificar-me."},
{v:3,t:"Estendendo a mão, ele o tocou, dizendo: Quero, sê purificado. E logo a sua lepra foi purificada.",n:"Tocar um leproso tornava impuro quem o tocasse; aqui dá-se o contrário, e é a impureza que cede ao contato."},
{v:4,t:"Jesus disse a ele: Olha, não digas a ninguém; mas vai, mostra-te ao sacerdote e apresenta a oferta que Moisés ordenou, em testemunho para eles."},
{p:"Marcos 1:40-45"},
{v:40,t:"Veio a ele um leproso, suplicando e pondo-se de joelhos, e disse: Se queres, podes purificar-me."},
{v:41,t:"Compadecido, estendeu a mão, tocou-o e disse: Quero, sê purificado.",n:"Alguns manuscritos antigos trazem irado em lugar de compadecido; a lição mais difícil apontaria para a cólera de Jesus diante do mal que desfigura o homem."},
{v:42,t:"E logo a lepra o deixou, e ficou purificado."},
{v:43,t:"Ele o despediu imediatamente, advertindo-o com severidade,"},
{v:44,t:"e disse a ele: Vê, não digas nada a ninguém; mas vai, mostra-te ao sacerdote e oferece pela tua purificação o que Moisés ordenou, em testemunho para eles."},
{v:45,t:"Mas ele, saindo, começou a apregoar muito e a divulgar o acontecido, de modo que Jesus já não podia entrar publicamente numa cidade, mas ficava fora, em lugares desertos; e vinham a ele de toda parte."},
{p:"Lucas 5:12-16"},
{v:12,t:"Estando ele numa das cidades, eis um homem cheio de lepra; vendo Jesus, caiu de rosto por terra e rogou a ele: Senhor, se queres, podes purificar-me."},
{v:13,t:"Estendendo a mão, tocou-o, dizendo: Quero, sê purificado. E logo a lepra o deixou."},
{v:14,t:"E ele lhe ordenou que não dissesse a ninguém: Mas vai, mostra-te ao sacerdote e oferece pela tua purificação o que Moisés ordenou, em testemunho para eles."},
{v:15,t:"A sua fama, porém, se difundia ainda mais, e grandes multidões acorriam para o ouvir e para serem curadas das suas enfermidades."},
{v:16,t:"Ele, porém, retirava-se para lugares desertos e orava."}
];

EV[40] = [
{p:"Mateus 9:2-8"},
{v:2,t:"E eis que traziam a ele um paralítico, deitado num leito. Vendo Jesus a fé deles, disse ao paralítico: Confia, filho; os teus pecados são perdoados.",n:"A fé deles é a dos que carregam o doente: em toda a cena, quem crê são os amigos, e é a essa fé que o perdão responde."},
{v:3,t:"E eis que alguns escribas disseram entre si: Este blasfema."},
{v:4,t:"Vendo Jesus os pensamentos deles, disse: Por que pensais o mal nos vossos corações?"},
{v:5,t:"Que é mais fácil dizer: Os teus pecados são perdoados; ou dizer: Levanta-te e anda?"},
{v:6,t:"Ora, para que saibais que o Filho do Homem tem sobre a terra o poder de perdoar pecados — disse então ao paralítico: Levanta-te, toma o teu leito e vai para tua casa.",n:"A frase fica suspensa: Jesus interrompe o que dizia aos escribas para se voltar ao doente, e a cura termina o que a palavra começara."},
{v:7,t:"E ele, levantando-se, foi para sua casa."},
{v:8,t:"Vendo isso, as multidões temeram e glorificaram a Deus, que deu tal poder aos homens."},
{p:"Marcos 2:1-12"},
{v:1,t:"Entrou de novo em Cafarnaum, passados alguns dias, e ouviu-se que estava em casa."},
{v:2,t:"Reuniram-se muitos, de modo que já não havia lugar nem junto à porta; e ele lhes anunciava a palavra."},
{v:3,t:"Vieram, trazendo a ele um paralítico, carregado por quatro."},
{v:4,t:"E, não podendo apresentá-lo diante dele por causa da multidão, descobriram o teto onde ele estava e, abrindo uma passagem, baixaram o leito em que jazia o paralítico."},
{v:5,t:"Vendo Jesus a fé deles, disse ao paralítico: Filho, os teus pecados são perdoados."},
{v:6,t:"Estavam ali sentados alguns escribas, que pensavam nos seus corações:"},
{v:7,t:"Por que este fala assim? Ele blasfema. Quem pode perdoar pecados, senão um só, que é Deus?"},
{v:8,t:"Conhecendo logo Jesus, no seu espírito, que assim pensavam entre si, disse a eles: Por que pensais essas coisas nos vossos corações?"},
{v:9,t:"Que é mais fácil dizer ao paralítico: Os teus pecados são perdoados; ou dizer: Levanta-te, toma o teu leito e anda?"},
{v:10,t:"Ora, para que saibais que o Filho do Homem tem sobre a terra o poder de perdoar pecados — disse ao paralítico:"},
{v:11,t:"A ti eu digo: Levanta-te, toma o teu leito e vai para tua casa."},
{v:12,t:"E ele se levantou e, tomando logo o leito, saiu à vista de todos, de modo que todos se admiravam e glorificavam a Deus, dizendo: Nunca vimos coisa assim."},
{p:"Lucas 5:17-26"},
{v:17,t:"Num dos dias, estava ele ensinando; e estavam sentados fariseus e doutores da Lei, vindos de todas as aldeias da Galileia, da Judeia e de Jerusalém; e o poder do Senhor estava com ele para curar."},
{v:18,t:"E eis uns homens que traziam num leito um homem paralítico, e procuravam introduzi-lo e pô-lo diante dele."},
{v:19,t:"Não achando por onde introduzi-lo, por causa da multidão, subiram ao terraço e, pelas telhas, baixaram-no com o leito para o meio, diante de Jesus."},
{v:20,t:"Vendo ele a fé deles, disse: Homem, os teus pecados são perdoados."},
{v:21,t:"Os escribas e fariseus começaram a pensar: Quem é este, que fala blasfêmias? Quem pode perdoar pecados, senão só Deus?"},
{v:22,t:"Conhecendo Jesus os pensamentos deles, respondeu: Que pensais nos vossos corações?"},
{v:23,t:"Que é mais fácil dizer: Os teus pecados são perdoados; ou dizer: Levanta-te e anda?"},
{v:24,t:"Ora, para que saibais que o Filho do Homem tem sobre a terra o poder de perdoar pecados — disse ao paralítico: A ti eu digo: Levanta-te, toma o teu leito e vai para tua casa."},
{v:25,t:"E logo, levantando-se diante deles, tomou o leito em que jazia e foi para sua casa, glorificando a Deus."},
{v:26,t:"O assombro tomou a todos, e glorificavam a Deus; e, cheios de temor, diziam: Vimos hoje coisas admiráveis."}
];

EV[41] = [
{p:"Mateus 9:9"},
{v:9,t:"Passando dali, Jesus viu um homem sentado na coletoria, chamado Mateus, e disse a ele: Segue-me. Ele se levantou e o seguiu.",n:"O mesmo homem é chamado Levi por São Marcos e São Lucas; a tradição vê nos dois nomes uma só pessoa, o publicano que se tornou evangelista."},
{p:"Marcos 2:13-14"},
{v:13,t:"Saiu de novo para a beira-mar; toda a multidão vinha a ele, e ele os ensinava."},
{v:14,t:"Ao passar, viu Levi, filho de Alfeu, sentado na coletoria, e disse a ele: Segue-me. Ele se levantou e o seguiu."},
{p:"Lucas 5:27-28"},
{v:27,t:"Depois disso, saiu e viu um publicano chamado Levi, sentado na coletoria, e disse a ele: Segue-me."},
{v:28,t:"Ele, deixando tudo, levantou-se e o seguiu."}
];

EV[42] = [
{p:"Mateus 12:1-8"},
{v:1,t:"Naquele tempo, Jesus passou pelas searas no sábado; os seus discípulos, tendo fome, começaram a arrancar espigas e a comer."},
{v:2,t:"Vendo isso, os fariseus disseram a ele: Eis que os teus discípulos fazem o que não é lícito fazer no sábado.",n:"O que se censura não é apanhar espigas alheias, que a Lei permitia ao faminto, mas fazê-lo no sábado: arrancar e esfregar contavam como colher e debulhar."},
{v:3,t:"Ele disse a eles: Não lestes o que fez Davi, quando teve fome, ele e os que estavam com ele?"},
{v:4,t:"Como entrou na casa de Deus e comeram os pães da proposição, que não lhe era lícito comer, nem aos que estavam com ele, mas só aos sacerdotes?"},
{v:5,t:"Ou não lestes na Lei que, nos sábados, os sacerdotes no Templo violam o sábado e ficam sem culpa?"},
{v:6,t:"Ora, eu vos digo que aqui está algo maior que o Templo."},
{v:7,t:"Se soubésseis o que significa: Misericórdia quero, e não sacrifício, não teríeis condenado os inocentes."},
{v:8,t:"Porque o Filho do Homem é senhor do sábado."},
{p:"Marcos 2:23-28"},
{v:23,t:"E aconteceu que ele passava, no sábado, pelas searas, e os seus discípulos começaram a abrir caminho, arrancando as espigas."},
{v:24,t:"Os fariseus diziam a ele: Vê, por que fazem no sábado o que não é lícito?"},
{v:25,t:"Ele disse a eles: Nunca lestes o que fez Davi, quando teve necessidade e sentiu fome, ele e os que estavam com ele?"},
{v:26,t:"Como entrou na casa de Deus, no tempo do sumo sacerdote Abiatar, e comeu os pães da proposição, que não é lícito comer senão aos sacerdotes, e deu também aos que estavam com ele?",n:"Em 1 Samuel 21 o sacerdote é Aquimelec, pai de Abiatar; a menção do filho, mais conhecido por acompanhar Davi, é modo antigo de indicar a passagem pelo nome da figura principal."},
{v:27,t:"E dizia a eles: O sábado foi feito por causa do homem, e não o homem por causa do sábado."},
{v:28,t:"Assim, o Filho do Homem é senhor até do sábado."},
{p:"Lucas 6:1-5"},
{v:1,t:"Aconteceu que, num sábado, passava ele pelas searas, e os seus discípulos arrancavam espigas e comiam, esfregando-as com as mãos."},
{v:2,t:"Alguns dos fariseus disseram: Por que fazeis o que não é lícito nos sábados?"},
{v:3,t:"Jesus respondeu: Não lestes o que fez Davi, quando teve fome, ele e os que estavam com ele?"},
{v:4,t:"Como entrou na casa de Deus, tomou os pães da proposição, comeu e deu aos que estavam com ele, embora não seja lícito comê-los senão só aos sacerdotes?"},
{v:5,t:"E dizia a eles: O Filho do Homem é senhor do sábado."}
];

EV[43] = [
{p:"Mateus 12:9-14"},
{v:9,t:"Partindo dali, foi à sinagoga deles."},
{v:10,t:"E eis um homem que tinha a mão seca; e perguntaram a ele: É lícito curar nos sábados? — para o acusarem."},
{v:11,t:"Ele disse a eles: Qual de vós, tendo uma só ovelha, se ela cair num poço no sábado, não a segurará e levantará?"},
{v:12,t:"Ora, quanto mais vale um homem do que uma ovelha! Portanto, é lícito fazer o bem nos sábados."},
{v:13,t:"Então disse ao homem: Estende a tua mão. Ele a estendeu, e ficou restituída, sã como a outra."},
{v:14,t:"Saindo, os fariseus fizeram conselho contra ele, sobre como o matariam."},
{p:"Marcos 3:1-6"},
{v:1,t:"Entrou de novo na sinagoga. Havia ali um homem que tinha a mão seca."},
{v:2,t:"E o observavam, para ver se o curaria no sábado, a fim de o acusarem."},
{v:3,t:"Ele disse ao homem que tinha a mão seca: Levanta-te para o meio."},
{v:4,t:"E disse a eles: É lícito, nos sábados, fazer o bem ou fazer o mal? Salvar uma vida ou matá-la? Eles, porém, calavam-se.",n:"A pergunta não deixa saída: quem se recusa a fazer o bem no dia santo já escolheu o outro termo. Enquanto calam, tramam a morte de Jesus, e é o que o v. 6 dirá."},
{v:5,t:"Olhando-os em redor com ira, contristado pela dureza do coração deles, disse ao homem: Estende a mão. Ele a estendeu, e a sua mão foi restituída."},
{v:6,t:"Saindo, os fariseus logo tomaram conselho com os herodianos contra ele, sobre como o matariam."},
{p:"Lucas 6:6-11"},
{v:6,t:"Aconteceu que, noutro sábado, entrou na sinagoga e ensinava. Havia ali um homem cuja mão direita estava seca."},
{v:7,t:"Os escribas e fariseus o observavam, para ver se curaria no sábado, a fim de acharem de que o acusar."},
{v:8,t:"Ele, porém, conhecia os pensamentos deles, e disse ao homem que tinha a mão seca: Levanta-te e fica de pé no meio. Ele se levantou e ficou de pé."},
{v:9,t:"Jesus disse a eles: Pergunto-vos: é lícito, no sábado, fazer o bem ou fazer o mal? Salvar uma vida ou perdê-la?"},
{v:10,t:"E, olhando a todos em redor, disse ao homem: Estende a tua mão. Ele o fez, e a sua mão foi restituída."},
{v:11,t:"Eles, porém, encheram-se de furor e discutiam entre si o que fariam a Jesus."}
];

EV[44] = [
{p:"Mateus 12:15-21"},
{v:15,t:"Sabendo disso, Jesus retirou-se dali. Muitos o seguiram, e ele curou a todos,"},
{v:16,t:"e ordenou a eles que não o tornassem manifesto,"},
{v:17,t:"para que se cumprisse o que foi dito pelo profeta Isaías:"},
{v:18,t:"Eis o meu servo, a quem escolhi; o meu amado, em quem a minha alma se comprazeu. Porei sobre ele o meu Espírito, e ele anunciará o julgamento às nações."},
{v:19,t:"Não contenderá nem gritará, nem alguém ouvirá a sua voz nas praças."},
{v:20,t:"Não quebrará a cana rachada, nem apagará o pavio que fumega, até que leve o julgamento à vitória;",n:"A cana rachada e o pavio que ainda fumega são figuras do que está quase a acabar: o Servo não remata o que se rompe, sustenta-o."},
{v:21,t:"e no seu nome esperarão as nações."},
{p:"Marcos 3:7-12"},
{v:7,t:"Jesus retirou-se com os seus discípulos para o mar, e uma grande multidão da Galileia o seguiu; também da Judeia,"},
{v:8,t:"de Jerusalém, da Idumeia, de além do Jordão e dos arredores de Tiro e Sidônia, uma grande multidão, ouvindo quanto fazia, veio a ele."},
{v:9,t:"E disse aos seus discípulos que lhe preparassem uma barquinha, por causa da multidão, para que não o comprimissem."},
{v:10,t:"Pois curou a muitos, de modo que se lançavam sobre ele, quantos tinham males, para o tocarem."},
{v:11,t:"E os espíritos impuros, quando o viam, prostravam-se diante dele e gritavam: Tu és o Filho de Deus."},
{v:12,t:"Mas ele os repreendia com severidade, para que não o tornassem manifesto."}
];

EV[45] = [
{p:"Marcos 3:13-19"},
{v:13,t:"Subiu ao monte e chamou a si os que ele quis; e foram a ele."},
{v:14,t:"Constituiu doze, aos quais deu o nome de apóstolos, para que estivessem com ele e para os enviar a pregar,",n:"Apóstolo quer dizer enviado. A ordem das duas finalidades não é indiferente: primeiro estar com ele, depois ser enviado."},
{v:15,t:"com poder de expulsar os demônios."},
{v:16,t:"Constituiu os doze: Simão, a quem pôs o nome de Pedro;"},
{v:17,t:"Tiago, filho de Zebedeu, e João, irmão de Tiago, aos quais pôs o nome de Boanerges, isto é, filhos do trovão;"},
{v:18,t:"André, Filipe, Bartolomeu, Mateus, Tomé, Tiago, filho de Alfeu, Tadeu, Simão, o Cananeu,",n:"Cananeu não indica aqui a terra de Canaã, mas verte o aramaico qanana, o zeloso; São Lucas traduz o mesmo epíteto por Zelote."},
{v:19,t:"e Judas Iscariotes, que o entregou."},
{p:"Lucas 6:12-16"},
{v:12,t:"Naqueles dias, saiu ao monte para orar, e passou a noite em oração a Deus."},
{v:13,t:"Sendo dia, chamou a si os seus discípulos e escolheu doze deles, aos quais também deu o nome de apóstolos:"},
{v:14,t:"Simão, a quem pôs o nome de Pedro, e André, seu irmão; Tiago e João; Filipe e Bartolomeu;"},
{v:15,t:"Mateus e Tomé; Tiago, filho de Alfeu, e Simão, chamado Zelote;"},
{v:16,t:"Judas, filho de Tiago, e Judas Iscariotes, que veio a ser o traidor."}
];

EV[46] = [
{p:"Mateus 5:1-12"},
{v:1,t:"Vendo as multidões, subiu ao monte; e, tendo-se sentado, os seus discípulos aproximaram-se dele.",n:"Sentar-se era a postura do mestre que ensina com autoridade; o monte evoca o Sinai, e quem ali fala não recebe a Lei, mas dá-lhe cumprimento."},
{v:2,t:"E, abrindo a boca, ensinava-os, dizendo:"},
{v:3,t:"Bem-aventurados os pobres em espírito, porque deles é o Reino dos céus.",n:"Pobres em espírito são os que nada têm de seu diante de Deus e disso não fazem queixa; a pobreza de que se fala é primeiro uma condição da alma, embora não dispense a outra."},
{v:4,t:"Bem-aventurados os que choram, porque serão consolados."},
{v:5,t:"Bem-aventurados os mansos, porque possuirão a terra.",n:"Retoma o Salmo 37: a terra prometida aos que não a arrancam pela força."},
{v:6,t:"Bem-aventurados os que têm fome e sede da justiça, porque serão saciados."},
{v:7,t:"Bem-aventurados os misericordiosos, porque alcançarão misericórdia."},
{v:8,t:"Bem-aventurados os puros de coração, porque verão a Deus."},
{v:9,t:"Bem-aventurados os pacíficos, porque serão chamados filhos de Deus.",n:"O grego eirenopoioi diz mais que viver em paz: designa quem a faz, quem a produz entre os que estavam desavindos."},
{v:10,t:"Bem-aventurados os que sofrem perseguição por causa da justiça, porque deles é o Reino dos céus."},
{v:11,t:"Bem-aventurados sois quando vos injuriarem e perseguirem e, mentindo, disserem todo mal contra vós por minha causa.",n:"Aqui o discurso passa da terceira à segunda pessoa: as bem-aventuranças deixam de descrever e voltam-se para quem escuta."},
{v:12,t:"Alegrai-vos e exultai, porque é grande a vossa recompensa nos céus; pois assim perseguiram os profetas que vieram antes de vós."},
{p:"Lucas 6:17-26"},
{v:17,t:"Descendo com eles, parou num lugar plano, com grande multidão dos seus discípulos e grande número de povo de toda a Judeia, de Jerusalém e da região litorânea de Tiro e Sidônia,",n:"Por este lugar plano se costuma chamar sermão da planície ao discurso de São Lucas, mais breve que o de São Mateus e dirigido de modo mais direto aos que escutam."},
{v:18,t:"que tinham vindo para o ouvir e para serem curados das suas doenças; e os atormentados por espíritos impuros eram curados."},
{v:19,t:"E toda a multidão procurava tocá-lo, porque saía dele uma força que curava a todos."},
{v:20,t:"Ele, levantando os olhos para os seus discípulos, dizia: Bem-aventurados vós, os pobres, porque vosso é o Reino de Deus.",n:"São Lucas diz os pobres, sem acrescentar em espírito: nele a bem-aventurança recai sobre a pobreza real, e a ela correspondem os ais dirigidos aos ricos."},
{v:21,t:"Bem-aventurados vós, que agora tendes fome, porque sereis saciados. Bem-aventurados vós, que agora chorais, porque haveis de rir."},
{v:22,t:"Bem-aventurados sereis quando os homens vos odiarem, e quando vos excluírem, insultarem e proscreverem o vosso nome como mau, por causa do Filho do Homem."},
{v:23,t:"Alegrai-vos naquele dia e exultai, porque é grande a vossa recompensa no céu; pois assim faziam os seus pais aos profetas."},
{v:24,t:"Mas ai de vós, ricos, porque já tendes a vossa consolação.",n:"O ai não é maldição, mas lamento: chora-se por quem já gastou em vida o que lhe cabia receber."},
{v:25,t:"Ai de vós, que agora estais fartos, porque haveis de ter fome. Ai de vós, que agora rides, porque haveis de lamentar e chorar."},
{v:26,t:"Ai de vós, quando todos os homens vos louvarem; pois assim faziam os seus pais aos falsos profetas."}
];

EV[47] = [
{p:"Mateus 5:13-16"},
{v:13,t:"Vós sois o sal da terra. Se o sal perder o sabor, com que se há de salgar? Para nada mais presta, senão para ser lançado fora e pisado pelos homens."},
{v:14,t:"Vós sois a luz do mundo. Não se pode esconder uma cidade situada sobre um monte."},
{v:15,t:"Nem se acende uma lâmpada para a pôr debaixo do alqueire, mas sobre o velador, e ela ilumina todos os que estão em casa.",n:"O alqueire era a vasilha de medir grão, que virada cobria a chama; o velador, o suporte alto em que a lâmpada alcançava toda a casa."},
{v:16,t:"Assim brilhe a vossa luz diante dos homens, para que vejam as vossas boas obras e glorifiquem o vosso Pai que está nos céus."}
];

EV[48] = [
{p:"Mateus 5:17-20"},
{v:17,t:"Não penseis que vim revogar a Lei ou os Profetas; não vim revogar, mas dar cumprimento.",n:"Dar cumprimento verte plerosai, encher até à medida: não anular o que a Lei pedia, mas levá-lo ao termo que ela mesma anunciava."},
{v:18,t:"Pois em verdade vos digo: até que passem o céu e a terra, não passará da Lei um só i nem um só til, sem que tudo se cumpra.",n:"O iota era a menor letra do alfabeto grego, como o yod do hebraico; o til é o traço miúdo que distingue letras semelhantes. Diz-se assim: nem o menor sinal da escrita."},
{v:19,t:"Portanto, quem violar um destes mandamentos, mesmo o menor, e assim ensinar aos homens, será chamado o menor no Reino dos céus; mas quem os praticar e ensinar, esse será chamado grande no Reino dos céus."},
{v:20,t:"Pois eu vos digo: se a vossa justiça não exceder a dos escribas e fariseus, não entrareis no Reino dos céus."}
];

EV[49] = [
{p:"Mateus 5:21-26"},
{v:21,t:"Ouvistes que foi dito aos antigos: Não matarás; e quem matar será réu de julgamento."},
{v:22,t:"Eu, porém, vos digo: todo o que se irar contra o seu irmão será réu de julgamento; quem disser ao seu irmão: Raca, será réu diante do Sinédrio; e quem lhe disser: Louco, será réu da geena do fogo.",n:"Raca é injúria aramaica, algo como cabeça oca. A geena é o vale de Hinom, junto a Jerusalém, onde outrora se queimavam crianças a Moloc e depois se queimava o lixo: tornou-se nome do castigo final."},
{v:23,t:"Portanto, se estiveres apresentando a tua oferta ao altar e ali te lembrares de que o teu irmão tem alguma coisa contra ti,"},
{v:24,t:"deixa ali a tua oferta diante do altar e vai primeiro reconciliar-te com o teu irmão; depois vem e apresenta a tua oferta.",n:"Note-se que não se trata do que tu tens contra ele, mas do que ele tem contra ti: a iniciativa cabe ao ofensor, e interrompe até o culto."},
{v:25,t:"Entra em acordo depressa com o teu adversário, enquanto estás com ele no caminho, para que o adversário não te entregue ao juiz, e o juiz ao guarda, e sejas lançado na prisão."},
{v:26,t:"Em verdade te digo: não sairás dali enquanto não pagares o último centavo."}
];

EV[50] = [
{p:"Mateus 5:27-30"},
{v:27,t:"Ouvistes que foi dito: Não cometerás adultério."},
{v:28,t:"Eu, porém, vos digo: todo o que olha para uma mulher desejando-a já cometeu adultério com ela no seu coração."},
{v:29,t:"Se o teu olho direito te escandaliza, arranca-o e lança-o fora de ti; pois te convém que se perca um dos teus membros, e não que todo o teu corpo seja lançado na geena.",n:"Escandalizar traduz skandalizein, fazer tropeçar: a imagem é a da armadilha posta no caminho, não a do mero desgosto."},
{v:30,t:"E, se a tua mão direita te escandaliza, corta-a e lança-a fora de ti; pois te convém que se perca um dos teus membros, e não que todo o teu corpo vá para a geena."}
];

EV[51] = [
{p:"Mateus 5:31-32"},
{v:31,t:"Foi dito também: Quem repudiar a sua mulher, dê-lhe carta de divórcio."},
{v:32,t:"Eu, porém, vos digo: todo o que repudia a sua mulher, exceto no caso de união ilegítima, a expõe ao adultério; e quem casar com a repudiada comete adultério.",n:"O termo grego porneia não designa aqui o adultério, que tem outro nome no mesmo versículo, mas uma união que nunca foi legítima; daí a tradução."}
];

EV[52] = [
{p:"Mateus 5:33-37"},
{v:33,t:"Ouvistes ainda que foi dito aos antigos: Não jurarás falso, mas cumprirás ao Senhor os teus juramentos."},
{v:34,t:"Eu, porém, vos digo: não jureis de modo algum: nem pelo céu, porque é o trono de Deus;"},
{v:35,t:"nem pela terra, porque é o escabelo dos seus pés; nem por Jerusalém, porque é a cidade do grande Rei."},
{v:36,t:"Nem jurarás pela tua cabeça, porque não podes tornar um só cabelo branco ou preto."},
{v:37,t:"Seja o vosso falar: Sim, sim; não, não. O que passa disso vem do Maligno."}
];

EV[53] = [
{p:"Mateus 5:38-42"},
{v:38,t:"Ouvistes que foi dito: Olho por olho e dente por dente.",n:"A lei antiga do talião já era um freio: media a vingança pelo dano, proibindo exceder-lhe. Jesus não a corrige por excessiva, mas leva além do que ela podia pedir."},
{v:39,t:"Eu, porém, vos digo: não resistais ao mau; mas, se alguém te bater na face direita, oferece-lhe também a outra."},
{v:40,t:"E ao que quiser demandar contigo para te tirar a túnica, deixa-lhe também o manto."},
{v:41,t:"E, se alguém te obrigar a caminhar mil passos, vai com ele dois mil.",n:"O verbo angareuein designa a requisição forçada que os soldados romanos podiam impor aos habitantes; a medida é a milha romana, mil passos."},
{v:42,t:"Dá a quem te pede, e não voltes as costas ao que deseja de ti um empréstimo."},
{p:"Lucas 6:29-30"},
{v:29,t:"Ao que te bater numa face, oferece também a outra; e ao que te tirar o manto, não recuses também a túnica."},
{v:30,t:"Dá a todo o que te pede; e ao que toma o que é teu, não o reclames."}
];

EV[54] = [
{p:"Mateus 5:43-48"},
{v:43,t:"Ouvistes que foi dito: Amarás o teu próximo e odiarás o teu inimigo.",n:"A primeira metade está em Levítico 19; a segunda não se lê em parte alguma da Lei, e é a leitura corrente que Jesus recusa."},
{v:44,t:"Eu, porém, vos digo: amai os vossos inimigos e orai pelos que vos perseguem,"},
{v:45,t:"para que sejais filhos do vosso Pai que está nos céus; pois ele faz nascer o seu sol sobre maus e bons, e faz chover sobre justos e injustos."},
{v:46,t:"Se amardes os que vos amam, que recompensa tereis? Não fazem os publicanos também o mesmo?"},
{v:47,t:"E, se saudardes apenas os vossos irmãos, que fazeis de mais? Não fazem os gentios também o mesmo?"},
{v:48,t:"Sede, pois, perfeitos, como perfeito é o vosso Pai celeste.",n:"Perfeito traduz teleios, o que chegou ao seu fim e medida; não a impecabilidade, mas a inteireza de quem ama sem descontar ninguém, à maneira do Pai que faz nascer o sol sobre todos."},
{p:"Lucas 6:27-28.32-36"},
{v:27,t:"Mas a vós que me ouvis eu digo: amai os vossos inimigos, fazei o bem aos que vos odeiam;"},
{v:28,t:"bendizei os que vos amaldiçoam, orai pelos que vos difamam."},
{v:32,t:"Se amais os que vos amam, que agradecimento tereis? Pois também os pecadores amam os que os amam.",n:"Agradecimento verte charis, a mesma palavra que noutros lugares se traduz por graça: pergunta-se que favor há nisso, que mérito gratuito."},
{v:33,t:"E, se fizerdes o bem aos que vos fazem o bem, que agradecimento tereis? Também os pecadores fazem o mesmo."},
{v:34,t:"E, se emprestardes àqueles de quem esperais receber, que agradecimento tereis? Também os pecadores emprestam aos pecadores, para receberem outro tanto."},
{v:35,t:"Amai, porém, os vossos inimigos; fazei o bem e emprestai sem nada esperar; e será grande a vossa recompensa, e sereis filhos do Altíssimo, porque ele é bom para com os ingratos e maus."},
{v:36,t:"Sede misericordiosos, como o vosso Pai é misericordioso.",n:"Onde São Mateus conclui pedindo que sejamos perfeitos como o Pai, São Lucas diz misericordiosos: é a mesma exigência, dita pelo que nela há de mais próprio a Deus."}
];

EV[55] = [
{p:"Mateus 6:1-4"},
{v:1,t:"Guardai-vos de praticar a vossa justiça diante dos homens para serdes vistos por eles; do contrário, não tereis recompensa junto do vosso Pai que está nos céus.",n:"Justiça abrange aqui as três obras de piedade que o capítulo vai percorrer: a esmola, a oração e o jejum."},
{v:2,t:"Portanto, quando deres esmola, não toques trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem honrados pelos homens. Em verdade vos digo: já receberam a sua recompensa.",n:"Hipócrita era, no teatro grego, o ator que falava por trás de uma máscara; a palavra guarda essa imagem de quem representa um papel diante do público."},
{v:3,t:"Tu, porém, ao dares esmola, não saiba a tua mão esquerda o que faz a tua direita,"},
{v:4,t:"para que a tua esmola fique em segredo; e o teu Pai, que vê no segredo, te retribuirá."}
];

EV[56] = [
{p:"Mateus 6:5-15"},
{v:5,t:"E, quando orardes, não sejais como os hipócritas, que gostam de orar de pé nas sinagogas e nas esquinas das praças, para serem vistos pelos homens. Em verdade vos digo: já receberam a sua recompensa."},
{v:6,t:"Tu, porém, quando orares, entra no teu quarto e, fechada a porta, ora ao teu Pai que está no segredo; e o teu Pai, que vê no segredo, te retribuirá."},
{v:7,t:"Orando, não useis de muitas palavras, como os gentios, que julgam ser ouvidos por muito falarem."},
{v:8,t:"Não sejais como eles, pois o vosso Pai sabe do que tendes necessidade antes que lho peçais."},
{v:9,t:"Vós, portanto, orai assim: Pai nosso, que estás nos céus, santificado seja o teu nome;"},
{v:10,t:"venha o teu Reino; seja feita a tua vontade, assim na terra como no céu."},
{v:11,t:"O pão nosso de cada dia dá-nos hoje;",n:"O adjetivo epiousios não aparece em nenhum outro texto grego conhecido antes deste. Pode entender-se como o pão necessário à subsistência, o pão de hoje ou o pão do dia que vem; a tradução corrente guarda a primeira leitura sem excluir as outras."},
{v:12,t:"e perdoa-nos as nossas dívidas, assim como nós perdoamos aos nossos devedores;",n:"São Mateus fala de dívidas, imagem semita do pecado como débito; São Lucas, ao referir a mesma oração, diz pecados."},
{v:13,t:"e não nos deixes cair em tentação, mas livra-nos do Maligno.",n:"O verbo grego é levar para dentro, e o pedido não supõe que Deus induza ao mal: pede-se que não nos abandone à prova quando ela chegar."},
{v:14,t:"Pois, se perdoardes aos homens as suas ofensas, também o vosso Pai celeste vos perdoará;"},
{v:15,t:"mas, se não perdoardes aos homens, tampouco o vosso Pai vos perdoará as vossas ofensas."}
];

EV[57] = [
{p:"Mateus 6:16-18"},
{v:16,t:"Quando jejuardes, não vos mostreis tristes como os hipócritas, que desfiguram o rosto para parecer aos homens que jejuam. Em verdade vos digo: já receberam a sua recompensa."},
{v:17,t:"Tu, porém, quando jejuares, unge a tua cabeça e lava o teu rosto,"},
{v:18,t:"para não parecer aos homens que jejuas, mas ao teu Pai que está no segredo; e o teu Pai, que vê no segredo, te retribuirá."}
];

EV[58] = [
{p:"Mateus 6:19-21"},
{v:19,t:"Não ajunteis para vós tesouros na terra, onde a traça e a ferrugem corroem, e onde os ladrões arrombam e roubam."},
{v:20,t:"Ajuntai para vós tesouros no céu, onde nem a traça nem a ferrugem corroem, e onde os ladrões não arrombam nem roubam."},
{v:21,t:"Pois onde está o teu tesouro, ali estará também o teu coração."}
];

EV[59] = [
{p:"Mateus 6:22-23"},
{v:22,t:"A lâmpada do corpo é o olho. Se o teu olho for simples, todo o teu corpo será luminoso;",n:"Simples verte haplous, o que é de uma só peça, sem dobra nem segunda intenção; no falar da época dizia-se também do olhar generoso, que não cobiça."},
{v:23,t:"mas, se o teu olho for mau, todo o teu corpo será tenebroso. Se, pois, a luz que há em ti é trevas, quão grandes serão as trevas!"}
];

EV[60] = [
{p:"Mateus 6:24"},
{v:24,t:"Ninguém pode servir a dois senhores; pois ou odiará um e amará o outro, ou se apegará a um e desprezará o outro. Não podeis servir a Deus e ao dinheiro.",n:"O texto conserva a palavra aramaica mamona, o bem acumulado em que se põe a segurança; ao pô-la em frente de Deus, Jesus trata-a como um senhor rival, quase um nome próprio."}
];

EV[61] = [
{p:"Mateus 6:25-34"},
{v:25,t:"Por isso vos digo: não andeis ansiosos pela vossa vida, sobre o que haveis de comer; nem pelo vosso corpo, sobre o que haveis de vestir. Não é a vida mais do que o alimento, e o corpo mais do que a veste?",n:"Ansiosos traduz merimnan, o cuidado que divide e dilacera; não se condena a previdência, mas a inquietação que rouba a confiança."},
{v:26,t:"Olhai as aves do céu: não semeiam, nem ceifam, nem ajuntam em celeiros; e o vosso Pai celeste as alimenta. Não valeis vós muito mais do que elas?"},
{v:27,t:"Qual de vós, por mais que se inquiete, pode acrescentar um só côvado à sua estatura?",n:"As duas palavras são ambíguas: pode ler-se acrescentar um côvado à altura ou acrescentar um instante à duração da vida. A segunda leitura ajusta-se melhor ao contexto, mas a imagem material é a que o grego diz primeiro."},
{v:28,t:"E por que andais ansiosos com a veste? Considerai os lírios do campo, como crescem: não trabalham nem fiam."},
{v:29,t:"E eu vos digo que nem Salomão, em toda a sua glória, se vestiu como um deles."},
{v:30,t:"Ora, se Deus veste assim a erva do campo, que hoje existe e amanhã é lançada no forno, quanto mais a vós, homens de pouca fé!"},
{v:31,t:"Não andeis, pois, ansiosos, dizendo: Que comeremos? ou: Que beberemos? ou: Com que nos vestiremos?"},
{v:32,t:"Por todas essas coisas se afadigam os gentios; ora, o vosso Pai celeste sabe que de tudo isso tendes necessidade."},
{v:33,t:"Buscai primeiro o Reino de Deus e a sua justiça, e todas essas coisas vos serão acrescentadas."},
{v:34,t:"Não vos inquieteis, pois, pelo dia de amanhã; o dia de amanhã cuidará de si mesmo. Basta a cada dia o seu próprio mal."}
];

EV[62] = [
{p:"Mateus 7:1-5"},
{v:1,t:"Não julgueis, para que não sejais julgados."},
{v:2,t:"Pois com o julgamento com que julgardes sereis julgados, e com a medida com que medirdes vos medirão."},
{v:3,t:"Por que vês o argueiro no olho do teu irmão e não reparas na trave que está no teu?",n:"Argueiro é o fragmento miúdo de palha ou serradura; a trave é a viga que sustenta o telhado. O exagero é deliberado, e nele está o riso da parábola."},
{v:4,t:"Ou como dirás ao teu irmão: Deixa-me tirar o argueiro do teu olho, quando há uma trave no teu?"},
{v:5,t:"Hipócrita, tira primeiro a trave do teu olho, e então verás claro para tirar o argueiro do olho do teu irmão.",n:"A ordem não proíbe corrigir o irmão: manda começar por si, para enxergar o bastante e poder fazê-lo."},
{p:"Lucas 6:37-42"},
{v:37,t:"Não julgueis, e não sereis julgados; não condeneis, e não sereis condenados; perdoai, e sereis perdoados."},
{v:38,t:"Dai, e será dado a vós: uma boa medida, calcada, sacudida, transbordante, será posta no vosso regaço; pois com a medida com que medirdes vos medirão.",n:"A imagem vem do mercado de grão: enchia-se a medida, calcava-se e sacudia-se para assentar, e ainda se deixava transbordar. O regaço é a dobra larga do manto, usada como bolsa."},
{v:39,t:"Disse-lhes também uma parábola: Pode um cego guiar outro cego? Não cairão ambos numa cova?"},
{v:40,t:"O discípulo não está acima do mestre; mas todo o que estiver bem formado será como o seu mestre."},
{v:41,t:"Por que vês o argueiro no olho do teu irmão e não reparas na trave que está no teu próprio olho?"},
{v:42,t:"Como podes dizer ao teu irmão: Irmão, deixa-me tirar o argueiro do teu olho, tu que não vês a trave no teu? Hipócrita, tira primeiro a trave do teu olho, e então verás claro para tirar o argueiro do olho do teu irmão."}
];

EV[63] = [
{p:"Mateus 7:6"},
{v:6,t:"Não deis aos cães o que é santo, nem lanceis as vossas pérolas diante dos porcos, para que não as pisem com os pés e, voltando-se, vos despedacem.",n:"O que é santo designa a carne oferecida em sacrifício, que não se atirava aos animais. Cão e porco eram, para o ouvinte judeu, os bichos impuros por excelência."}
];

EV[64] = [
{p:"Mateus 7:7-11"},
{v:7,t:"Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto."},
{v:8,t:"Pois todo o que pede recebe; quem busca acha; e ao que bate se abrirá."},
{v:9,t:"Ou qual de vós é o homem que, se o filho lhe pedir pão, lhe dará uma pedra?"},
{v:10,t:"Ou, se lhe pedir um peixe, lhe dará uma serpente?"},
{v:11,t:"Se vós, pois, sendo maus, sabeis dar boas coisas aos vossos filhos, quanto mais o vosso Pai que está nos céus dará coisas boas aos que lhas pedirem!"}
];

EV[65] = [
{p:"Mateus 7:12"},
{v:12,t:"Portanto, tudo quanto quereis que os homens vos façam, fazei-o também vós a eles; nisto está a Lei e os Profetas.",n:"A regra corria entre os antigos na forma negativa, não faças a outro o que não queres para ti; aqui vem em forma positiva, e pede iniciativa em lugar de abstenção."},
{p:"Lucas 6:31"},
{v:31,t:"E, como quereis que os homens vos façam, fazei-lhes também vós do mesmo modo."}
];

EV[66] = [
{p:"Mateus 7:13-14"},
{v:13,t:"Entrai pela porta estreita; porque larga é a porta e espaçoso o caminho que leva à perdição, e muitos são os que entram por ela."},
{v:14,t:"Quão estreita é a porta e apertado o caminho que leva à vida, e poucos são os que o encontram!"}
];

EV[67] = [
{p:"Mateus 7:15-20"},
{v:15,t:"Guardai-vos dos falsos profetas, que vêm a vós com vestes de ovelhas, mas por dentro são lobos vorazes."},
{v:16,t:"Pelos seus frutos os conhecereis. Colhem-se, porventura, uvas dos espinheiros, ou figos dos abrolhos?"},
{v:17,t:"Assim, toda árvore boa produz frutos bons, e a árvore má produz frutos maus."},
{v:18,t:"Não pode a árvore boa dar frutos maus, nem a árvore má dar frutos bons."},
{v:19,t:"Toda árvore que não dá bom fruto é cortada e lançada ao fogo."},
{v:20,t:"Portanto, pelos seus frutos os conhecereis."},
{p:"Lucas 6:43-45"},
{v:43,t:"Não há árvore boa que dê fruto mau, nem árvore má que dê fruto bom."},
{v:44,t:"Cada árvore se conhece pelo seu próprio fruto; pois não se colhem figos dos espinheiros, nem se vindimam uvas da sarça."},
{v:45,t:"O homem bom, do bom tesouro do seu coração, tira o bem; e o mau, do mau, tira o mal; pois a boca fala do que transborda do coração."}
];

EV[68] = [
{p:"Mateus 7:21-23"},
{v:21,t:"Nem todo o que me diz: Senhor, Senhor, entrará no Reino dos céus, mas aquele que faz a vontade de meu Pai que está nos céus."},
{v:22,t:"Muitos me dirão naquele dia: Senhor, Senhor, não profetizamos nós em teu nome, e em teu nome não expulsamos demônios, e em teu nome não fizemos muitos milagres?"},
{v:23,t:"E então lhes declararei: Nunca vos conheci; apartai-vos de mim, vós que praticais a iniquidade."},
{p:"Lucas 6:46"},
{v:46,t:"Por que me chamais: Senhor, Senhor, e não fazeis o que eu digo?"}
];

EV[69] = [
{p:"Mateus 7:24-29"},
{v:24,t:"Todo aquele, pois, que ouve estas minhas palavras e as põe em prática será comparado ao homem prudente que edificou a sua casa sobre a rocha."},
{v:25,t:"Caiu a chuva, vieram as torrentes, sopraram os ventos e investiram contra aquela casa; e ela não caiu, porque estava fundada sobre a rocha."},
{v:26,t:"E todo o que ouve estas minhas palavras e não as põe em prática será comparado ao homem insensato que edificou a sua casa sobre a areia."},
{v:27,t:"Caiu a chuva, vieram as torrentes, sopraram os ventos e arremeteram contra aquela casa; e ela caiu, e grande foi a sua ruína.",n:"As duas casas recebem a mesma tempestade: não se prometeu ao que ouve que a chuva o poupe, mas que o alicerce aguente."},
{v:28,t:"Quando Jesus acabou estas palavras, as multidões admiravam-se do seu ensino;"},
{v:29,t:"pois as ensinava como quem tem autoridade, e não como os seus escribas."},
{p:"Lucas 6:47-49"},
{v:47,t:"Todo o que vem a mim, ouve as minhas palavras e as põe em prática, eu vos mostrarei a quem é semelhante:"},
{v:48,t:"é semelhante ao homem que, edificando uma casa, cavou fundo e pôs o alicerce sobre a rocha. Vindo a enchente, a torrente arremeteu contra aquela casa e não conseguiu abalá-la, porque estava bem edificada.",n:"São Lucas insiste no cavar fundo, trabalho oculto e demorado; São Mateus opõe simplesmente a rocha à areia."},
{v:49,t:"Mas o que ouve e não põe em prática é semelhante ao homem que edificou a sua casa sobre a terra, sem alicerce; a torrente arremeteu contra ela, e logo caiu, e grande foi a ruína daquela casa."}
];

EV[70] = [
{p:"Mateus 8:5-13"},
{v:5,t:"Tendo ele entrado em Cafarnaum, aproximou-se dele um centurião, rogando-lhe"},
{v:6,t:"e dizendo: Senhor, o meu servo jaz em casa, paralítico, atrozmente atormentado."},
{v:7,t:"Disse a ele: Eu irei curá-lo."},
{v:8,t:"Mas o centurião respondeu: Senhor, não sou digno de que entres sob o meu teto; mas dize somente uma palavra, e o meu servo será curado.",n:"São estas as palavras que a Igreja repete antes da comunhão, mudando apenas o servo pela alma de quem as diz."},
{v:9,t:"Pois também eu sou homem sujeito a autoridade, e tenho soldados sob as minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz.",n:"O centurião raciocina pelo que conhece: se a sua palavra, que é de homem sujeito a outros, basta para mover soldados à distância, quanto mais a de Jesus sobre a doença."},
{v:10,t:"Ouvindo isso, Jesus admirou-se e disse aos que o seguiam: Em verdade vos digo: em ninguém, em Israel, encontrei tamanha fé."},
{v:11,t:"E eu vos digo que muitos virão do oriente e do ocidente e se sentarão à mesa com Abraão, Isaac e Jacó no Reino dos céus;"},
{v:12,t:"mas os filhos do Reino serão lançados nas trevas exteriores; ali haverá pranto e ranger de dentes."},
{v:13,t:"E disse Jesus ao centurião: Vai; faça-se conforme creste. E naquela hora o servo ficou curado."},
{p:"Lucas 7:1-10"},
{v:1,t:"Quando acabou de dizer todas essas palavras aos ouvidos do povo, entrou em Cafarnaum."},
{v:2,t:"O servo de um centurião, que lhe era caro, estava mal e à morte."},
{v:3,t:"Tendo ouvido falar de Jesus, enviou a ele alguns anciãos dos judeus, rogando-lhe que viesse curar o seu servo.",n:"Em São Lucas o centurião não fala em pessoa: manda primeiro os anciãos, depois os amigos. A distância que guarda é a mesma que as suas palavras confessam."},
{v:4,t:"Chegando eles a Jesus, suplicavam com insistência, dizendo: Ele merece que lhe concedas isso,"},
{v:5,t:"pois ama a nossa nação, e ele mesmo nos edificou a sinagoga."},
{v:6,t:"Jesus foi com eles. E, quando já não estava longe da casa, o centurião enviou amigos a dizer a ele: Senhor, não te incomodes, pois não sou digno de que entres sob o meu teto;"},
{v:7,t:"por isso nem me julguei digno de ir ter contigo; mas dize uma palavra, e seja curado o meu servo."},
{v:8,t:"Pois também eu sou homem posto sob autoridade, e tenho soldados sob as minhas ordens; e digo a este: Vai, e ele vai; e a outro: Vem, e ele vem; e ao meu servo: Faze isto, e ele o faz."},
{v:9,t:"Ouvindo isso, Jesus admirou-se dele e, voltando-se para a multidão que o seguia, disse: Eu vos digo que nem em Israel encontrei tamanha fé."},
{v:10,t:"E, voltando a casa, os enviados encontraram o servo com saúde."}
];

EV[71] = [
{p:"Mateus 9:27-31"},
{v:27,t:"Partindo Jesus dali, seguiram-no dois cegos, gritando: Tem piedade de nós, Filho de Davi.",n:"Filho de Davi é título messiânico; são os cegos que primeiro o dão a Jesus em São Mateus, enquanto os que veem hesitam."},
{v:28,t:"Chegado a casa, os cegos vieram a ele; e Jesus disse a eles: Credes que posso fazer isso? Responderam: Sim, Senhor."},
{v:29,t:"Então tocou os olhos deles, dizendo: Faça-se convosco segundo a vossa fé."},
{v:30,t:"E os seus olhos se abriram. Jesus advertiu-os com severidade: Vede que ninguém o saiba."},
{v:31,t:"Eles, porém, saindo, divulgaram a sua fama por toda aquela terra."}
];

EV[72] = [
{p:"Mateus 9:32-34"},
{v:32,t:"Ao saírem eles, eis que trouxeram a ele um homem mudo, endemoninhado."},
{v:33,t:"Expulso o demônio, o mudo falou; e as multidões admiraram-se, dizendo: Nunca se viu tal coisa em Israel."},
{v:34,t:"Mas os fariseus diziam: É pelo príncipe dos demônios que ele expulsa os demônios.",n:"Diante do mesmo sinal, a multidão admira-se e os fariseus acusam; esta é a primeira formulação da calúnia que voltará no episódio de Belzebu."}
];

EV[73] = [
{p:"Mateus 9:35"},
{v:35,t:"E percorria Jesus todas as cidades e aldeias, ensinando nas suas sinagogas, pregando o Evangelho do Reino e curando toda doença e toda enfermidade."},
{p:"Lucas 8:1-3"},
{v:1,t:"Aconteceu depois que ele percorria cidades e aldeias, pregando e anunciando a Boa Nova do Reino de Deus; e com ele iam os Doze"},
{v:2,t:"e algumas mulheres que tinham sido curadas de espíritos maus e de enfermidades: Maria, chamada Madalena, da qual tinham saído sete demônios;"},
{v:3,t:"Joana, mulher de Cusa, procurador de Herodes; Susana e muitas outras, que os serviam com os seus bens.",n:"Que um mestre daquele tempo se fizesse acompanhar de mulheres era coisa sem exemplo; São Lucas guarda-lhes os nomes e diz que sustentavam o grupo com o que tinham."}
];

EV[74] = [
{p:"Lucas 7:11-17"},
{v:11,t:"Aconteceu depois que ele foi a uma cidade chamada Naim; e iam com ele os seus discípulos e uma grande multidão."},
{v:12,t:"Quando se aproximou da porta da cidade, eis que levavam um morto, filho único de sua mãe, e ela era viúva; e grande multidão da cidade ia com ela.",n:"Viúva e sem filho, a mulher ficava sem quem a sustentasse ou representasse; a perda não era só do afeto, mas de todo o amparo."},
{v:13,t:"Vendo-a, o Senhor compadeceu-se dela e disse a ela: Não chores.",n:"Ninguém pediu nada: é o único caso em que Jesus ressuscita alguém sem que a fé de outro o solicite. O motivo dado é apenas a compaixão."},
{v:14,t:"E, aproximando-se, tocou o esquife; os que o levavam pararam. E disse: Jovem, eu te digo, levanta-te."},
{v:15,t:"O morto sentou-se e começou a falar; e Jesus o entregou à sua mãe."},
{v:16,t:"O temor tomou a todos, e glorificavam a Deus, dizendo: Um grande profeta surgiu entre nós, e Deus visitou o seu povo."},
{v:17,t:"E essa palavra a seu respeito correu por toda a Judeia e por toda a região vizinha."}
];

EV[75] = [
{p:"Mateus 12:22-45"},
{v:22,t:"Então lhe trouxeram um endemoninhado, cego e mudo; e ele o curou, de modo que o mudo falava e via."},
{v:23,t:"E todas as multidões se admiravam e diziam: Será este o Filho de Davi?",n:"Filho de Davi é título messiânico. A pergunta vem na forma grega que espera resposta negativa — algo como: não será este, por acaso…? —, e é justamente a hesitação da multidão que os fariseus se apressam a fechar."},
{v:24,t:"Mas os fariseus, ouvindo isso, disseram: Este não expulsa os demônios senão por Belzebu, príncipe dos demônios.",n:"Belzebu é deformação de Baal-Zebul, o Baal príncipe, deus de Ecrom mencionado no segundo livro dos Reis; a tradição judaica trocara o nome para Baal-Zebub, senhor das moscas, por escárnio."},
{v:25,t:"Conhecendo os seus pensamentos, disse-lhes: Todo reino dividido contra si mesmo fica devastado, e toda cidade ou casa dividida contra si mesma não subsistirá."},
{v:26,t:"Se Satanás expulsa Satanás, está dividido contra si mesmo: como, então, subsistirá o seu reino?"},
{v:27,t:"E, se eu expulso os demônios por Belzebu, por quem os expulsam os vossos filhos? Por isso eles mesmos serão os vossos juízes.",n:"Os vossos filhos são os exorcistas judeus, cuja prática os fariseus não contestavam. O argumento é um dilema: se o mesmo ato é santo neles e diabólico nele, a acusação não julga a obra, mas a pessoa."},
{v:28,t:"Mas, se é pelo Espírito de Deus que eu expulso os demônios, então chegou a vós o Reino de Deus."},
{v:29,t:"Ou como pode alguém entrar na casa do forte e roubar os seus bens, se primeiro não amarrar o forte? Só então saqueará a sua casa."},
{v:30,t:"Quem não está comigo está contra mim; e quem comigo não ajunta, espalha."},
{v:31,t:"Por isso vos digo: todo pecado e blasfêmia será perdoado aos homens; mas a blasfêmia contra o Espírito não será perdoada."},
{v:32,t:"E a quem disser uma palavra contra o Filho do Homem, será perdoado; mas a quem falar contra o Espírito Santo não será perdoado, nem neste século nem no futuro.",n:"O pecado que não se perdoa não é uma palavra pronunciada por engano, mas a disposição que descreve o bem como mal e chama diabólica a obra de Deus. Não se perdoa porque quem a tem já não pede perdão: a única coisa que o perdão exige é ser querido."},
{v:33,t:"Ou fazei a árvore boa e o seu fruto bom, ou fazei a árvore má e o seu fruto mau; porque pelo fruto se conhece a árvore."},
{v:34,t:"Raça de víboras, como podeis falar coisas boas, sendo maus? Porque da abundância do coração fala a boca."},
{v:35,t:"O homem bom, do bom tesouro, tira coisas boas; e o homem mau, do mau tesouro, tira coisas más."},
{v:36,t:"Digo-vos que de toda palavra vã que os homens disserem hão de prestar contas no dia do juízo."},
{v:37,t:"Porque pelas tuas palavras serás justificado, e pelas tuas palavras serás condenado."},
{v:38,t:"Então alguns dos escribas e fariseus lhe responderam: Mestre, queremos ver um sinal da tua parte."},
{v:39,t:"Mas ele lhes respondeu: Uma geração má e adúltera pede um sinal, e nenhum sinal lhe será dado, senão o sinal do profeta Jonas.",n:"Adúltera, no vocabulário dos profetas, diz infidelidade a Deus, e não o pecado de que trata o sexto mandamento."},
{v:40,t:"Porque, assim como Jonas esteve três dias e três noites no ventre do grande peixe, assim estará o Filho do Homem três dias e três noites no coração da terra.",n:"Três dias e três noites é expressão hebraica para um período que abrange partes de três dias, e não setenta e duas horas; conta-se do enterro na tarde de sexta à manhã de domingo."},
{v:41,t:"Os ninivitas se levantarão no juízo com esta geração e a condenarão, porque se converteram com a pregação de Jonas; e eis aqui quem é mais do que Jonas."},
{v:42,t:"A rainha do Sul se levantará no juízo com esta geração e a condenará, porque veio dos confins da terra para ouvir a sabedoria de Salomão; e eis aqui quem é mais do que Salomão.",n:"A rainha do Sul é a de Sabá, do primeiro livro dos Reis. Os dois exemplos são estrangeiros: uma cidade pagã que se converteu e uma rainha que veio de longe, ambas postas como juízes de quem tinha a promessa em casa."},
{v:43,t:"Quando o espírito imundo sai do homem, anda por lugares áridos buscando repouso, e não o encontra."},
{v:44,t:"Então diz: Voltarei para a minha casa, donde saí. E, chegando, encontra-a desocupada, varrida e adornada."},
{v:45,t:"Então vai e leva consigo outros sete espíritos piores do que ele; e entram e habitam ali; e o último estado daquele homem torna-se pior do que o primeiro. Assim será também com esta geração má.",n:"A casa está limpa, mas vazia: varrer não basta, é preciso que outro a habite. A parábola avisa contra a reforma que só remove, sem pôr nada no lugar."},
{p:"Marcos 3:20-30"},
{v:20,t:"Foram para casa, e de novo afluiu a multidão, de modo que nem podiam comer."},
{v:21,t:"Ao ouvirem isso, os seus foram para o prender, pois diziam: Está fora de si.",n:"Os seus traduz hoi par' autou, literalmente os do lado dele: a parentela. São Marcos é o único a conservar esta cena, das mais ásperas dos evangelhos."},
{v:22,t:"E os escribas que tinham descido de Jerusalém diziam: Está possuído por Belzebu, e é pelo príncipe dos demônios que expulsa os demônios."},
{v:23,t:"Tendo-os chamado, dizia-lhes em parábolas: Como pode Satanás expulsar Satanás?"},
{v:24,t:"Se um reino estiver dividido contra si mesmo, tal reino não pode subsistir."},
{v:25,t:"E, se uma casa estiver dividida contra si mesma, tal casa não poderá subsistir."},
{v:26,t:"E, se Satanás se levantou contra si mesmo e está dividido, não pode subsistir, mas está no fim."},
{v:27,t:"Ninguém pode entrar na casa do forte e saquear os seus bens, se primeiro não amarrar o forte; só então saqueará a sua casa."},
{v:28,t:"Em verdade vos digo: tudo será perdoado aos filhos dos homens, os pecados e as blasfêmias que proferirem;"},
{v:29,t:"mas quem blasfemar contra o Espírito Santo jamais terá perdão: é réu de pecado eterno."},
{v:30,t:"Isso porque diziam: Está possuído por um espírito imundo.",n:"São Marcos explica em que consistia a blasfêmia, e a explicação fecha a questão: era chamar imundo ao Espírito Santo."},
{p:"Lucas 11:14-32"},
{v:14,t:"Estava expulsando um demônio, e este era mudo; e, saído o demônio, o mudo falou; e as multidões admiraram-se."},
{v:15,t:"Mas alguns deles disseram: É por Belzebu, príncipe dos demônios, que ele expulsa os demônios."},
{v:16,t:"Outros, tentando-o, pediam-lhe um sinal do céu."},
{v:17,t:"Conhecendo ele os seus pensamentos, disse-lhes: Todo reino dividido contra si mesmo fica devastado, e casa sobre casa cai."},
{v:18,t:"Se também Satanás está dividido contra si mesmo, como subsistirá o seu reino? Pois dizeis que é por Belzebu que eu expulso os demônios."},
{v:19,t:"Se eu expulso os demônios por Belzebu, por quem os expulsam os vossos filhos? Por isso eles mesmos serão os vossos juízes."},
{v:20,t:"Mas, se é pelo dedo de Deus que eu expulso os demônios, então chegou a vós o Reino de Deus.",n:"Onde São Mateus diz Espírito de Deus, São Lucas diz dedo de Deus, expressão do Êxodo: é o que os magos do faraó reconheceram nas pragas. A troca é deliberada e remete o leitor ao primeiro êxodo."},
{v:21,t:"Quando o forte, bem armado, guarda o seu pátio, em segurança estão os seus bens."},
{v:22,t:"Mas, se sobrevier um mais forte do que ele e o vencer, tira-lhe todas as armas em que confiava e reparte os seus despojos."},
{v:23,t:"Quem não está comigo está contra mim; e quem comigo não ajunta, espalha."},
{v:24,t:"Quando o espírito imundo sai do homem, anda por lugares áridos buscando repouso; e, não o encontrando, diz: Voltarei para a minha casa, donde saí."},
{v:25,t:"E, chegando, encontra-a varrida e adornada."},
{v:26,t:"Então vai e leva consigo outros sete espíritos piores do que ele; e entram e habitam ali; e o último estado daquele homem torna-se pior do que o primeiro."},
{v:27,t:"Ora, enquanto ele dizia essas coisas, certa mulher do meio da multidão levantou a voz e lhe disse: Bem-aventurado o ventre que te trouxe e os peitos que te amamentaram!"},
{v:28,t:"Mas ele disse: Antes, bem-aventurados os que ouvem a palavra de Deus e a guardam!",n:"A resposta não nega o elogio a sua mãe: desloca-lhe o fundamento. O que a faz bem-aventurada não é o parentesco, mas ter ouvido e guardado a palavra — e é o que dela diz o próprio São Lucas, no primeiro capítulo."},
{v:29,t:"Afluindo as multidões, começou a dizer: Esta geração é uma geração má; pede um sinal, e nenhum sinal lhe será dado, senão o sinal de Jonas."},
{v:30,t:"Porque, assim como Jonas foi um sinal para os ninivitas, assim o será o Filho do Homem para esta geração."},
{v:31,t:"A rainha do Sul se levantará no juízo com os homens desta geração e os condenará, porque veio dos confins da terra para ouvir a sabedoria de Salomão; e eis aqui quem é mais do que Salomão."},
{v:32,t:"Os homens de Nínive se levantarão no juízo com esta geração e a condenarão, porque se converteram com a pregação de Jonas; e eis aqui quem é mais do que Jonas."}
];

EV[76] = [
{p:"Mateus 12:46-50"},
{v:46,t:"Enquanto ele ainda falava às multidões, eis que sua mãe e seus irmãos estavam fora, procurando falar com ele.",n:"Irmãos verte adelphoi, que no grego dos judeus da época recobre a parentela ampla — o hebraico e o aramaico não tinham palavra própria para primo. É por isso que a tradição da Igreja nunca leu aqui outros filhos de Maria."},
{v:47,t:"Alguém lhe disse: Eis que tua mãe e teus irmãos estão fora, procurando falar contigo."},
{v:48,t:"Mas ele respondeu ao que lhe falava: Quem é minha mãe e quem são meus irmãos?"},
{v:49,t:"E, estendendo a mão para os seus discípulos, disse: Eis minha mãe e meus irmãos."},
{v:50,t:"Porque todo o que fizer a vontade de meu Pai, que está nos céus, esse é meu irmão, minha irmã e minha mãe."},
{p:"Marcos 3:31-35"},
{v:31,t:"Chegaram sua mãe e seus irmãos e, ficando de fora, mandaram chamá-lo."},
{v:32,t:"A multidão estava sentada ao redor dele; e disseram-lhe: Eis que tua mãe e teus irmãos estão lá fora à tua procura."},
{v:33,t:"Ele lhes respondeu: Quem é minha mãe e meus irmãos?"},
{v:34,t:"E, olhando ao redor para os que estavam sentados em volta dele, disse: Eis minha mãe e meus irmãos.",n:"O gesto e a palavra formam um só sinal: os de fora são a parentela, os de dentro são os que escutam. A resposta não afasta a família; alarga-a até onde alcance a obediência."},
{v:35,t:"Porque quem fizer a vontade de Deus, esse é meu irmão, minha irmã e minha mãe."},
{p:"Lucas 8:19-21"},
{v:19,t:"Vieram a ele sua mãe e seus irmãos, e não podiam aproximar-se dele por causa da multidão."},
{v:20,t:"Foi-lhe anunciado: Tua mãe e teus irmãos estão lá fora e querem ver-te."},
{v:21,t:"Mas ele lhes respondeu: Minha mãe e meus irmãos são estes que ouvem a palavra de Deus e a põem em prática."}
];

EV[77] = [
{p:"Mateus 13:1-52"},
{v:1,t:"Naquele dia, tendo Jesus saído de casa, sentou-se à beira do mar."},
{v:2,t:"E reuniram-se junto dele tão grandes multidões, que entrou numa barca e se sentou; e toda a multidão estava de pé na praia."},
{v:3,t:"E falou-lhes muitas coisas em parábolas, dizendo: Eis que o semeador saiu a semear.",n:"Parábola verte parabolé, que no grego dos Setenta traduz o hebraico mashal: abrange a comparação, o provérbio e o enigma. Não é uma história com moral anexa, mas uma imagem que obriga quem ouve a decidir de que lado está."},
{v:4,t:"E, ao semear, uma parte caiu à beira do caminho; vieram as aves e a comeram."},
{v:5,t:"Outra caiu em lugar pedregoso, onde não havia muita terra; e logo nasceu, porque a terra não era profunda."},
{v:6,t:"Mas, saindo o sol, queimou-se; e, porque não tinha raiz, secou."},
{v:7,t:"Outra caiu entre os espinhos; e os espinhos cresceram e a sufocaram."},
{v:8,t:"Outra caiu em terra boa e deu fruto: uma cem, outra sessenta, outra trinta.",n:"Na Palestina, uma colheita de dez por um já era boa. Cem por um não é exagero retórico: é a medida do extraordinário, e é aí que está o assombro da parábola."},
{v:9,t:"Quem tem ouvidos, ouça."},
{v:10,t:"Aproximando-se os discípulos, disseram-lhe: Por que lhes falas em parábolas?"},
{v:11,t:"Ele respondeu: Porque a vós foi dado conhecer os mistérios do Reino dos céus, mas a eles não foi dado."},
{v:12,t:"Pois ao que tem será dado, e terá em abundância; mas ao que não tem, até o que tem lhe será tirado."},
{v:13,t:"Por isso lhes falo em parábolas: porque, vendo, não veem; e, ouvindo, não ouvem nem entendem."},
{v:14,t:"Cumpre-se neles a profecia de Isaías, que diz: Ouvindo, ouvireis e não entendereis; e, vendo, vereis e não percebereis."},
{v:15,t:"Porque o coração deste povo endureceu-se, e com os ouvidos ouviram mal, e fecharam os olhos; para que não vejam com os olhos, nem ouçam com os ouvidos, nem entendam com o coração, e se convertam, e eu os cure.",n:"A citação é de Isaías 6, e a dificuldade é antiga: parece que se fala em parábolas para que não se entenda. São Mateus atenua-a ao escrever porque, onde São Marcos escreve para que; o sentido é que a parábola não cria a cegueira, revela-a — e deixa aberta a porta a quem quiser perguntar, como fizeram os discípulos."},
{v:16,t:"Mas bem-aventurados os vossos olhos, porque veem, e os vossos ouvidos, porque ouvem."},
{v:17,t:"Pois em verdade vos digo que muitos profetas e justos desejaram ver o que vedes, e não viram; e ouvir o que ouvis, e não ouviram."},
{v:18,t:"Ouvi, pois, vós a parábola do semeador."},
{v:19,t:"A todo o que ouve a palavra do Reino e não a entende, vem o maligno e arrebata o que foi semeado no seu coração: este é o que foi semeado à beira do caminho."},
{v:20,t:"O que foi semeado em lugar pedregoso é o que ouve a palavra e logo a recebe com alegria;"},
{v:21,t:"mas não tem raiz em si, e é de pouca duração; sobrevindo tribulação ou perseguição por causa da palavra, logo tropeça."},
{v:22,t:"O que foi semeado entre os espinhos é o que ouve a palavra; mas as preocupações do mundo e a sedução da riqueza sufocam a palavra, e fica sem fruto."},
{v:23,t:"O que foi semeado em terra boa é o que ouve a palavra e a entende; esse dá fruto e produz: um cem, outro sessenta, outro trinta."},
{v:24,t:"Propôs-lhes outra parábola, dizendo: O Reino dos céus é semelhante a um homem que semeou boa semente no seu campo."},
{v:25,t:"Mas, enquanto os homens dormiam, veio o seu inimigo, semeou joio no meio do trigo e foi-se embora.",n:"O joio é o zizânio, erva que nos primeiros meses é indistinguível do trigo; só na espiga se revela. Semeá-lo no campo alheio era crime previsto no direito romano, o que mostra que a cena não é fantasia."},
{v:26,t:"Quando a erva cresceu e deu fruto, apareceu também o joio."},
{v:27,t:"Os servos do dono da casa vieram dizer-lhe: Senhor, não semeaste boa semente no teu campo? Donde vem, então, o joio?"},
{v:28,t:"Ele lhes respondeu: Um inimigo fez isso. E os servos lhe disseram: Queres que vamos arrancá-lo?"},
{v:29,t:"Mas ele disse: Não, para que, ao arrancar o joio, não arranqueis com ele o trigo.",n:"A razão da paciência não é indiferença ao mal, mas o risco de arrancar o trigo junto: quem separa cedo demais julga por aparências que ainda não se firmaram."},
{v:30,t:"Deixai crescer ambos juntos até à colheita; e, no tempo da colheita, direi aos ceifeiros: Recolhei primeiro o joio e atai-o em feixes para queimá-lo; o trigo, porém, recolhei no meu celeiro."},
{v:31,t:"Propôs-lhes outra parábola, dizendo: O Reino dos céus é semelhante a um grão de mostarda que um homem tomou e semeou no seu campo."},
{v:32,t:"É, de fato, a menor de todas as sementes; mas, quando cresce, é maior do que as hortaliças e torna-se árvore, de modo que as aves do céu vêm e fazem ninho nos seus ramos.",n:"A menor de todas as sementes era dito proverbial entre os rabinos, e não afirmação de botânica. As aves que fazem ninho vêm de Daniel e de Ezequiel, onde são as nações que se abrigam no reino."},
{v:33,t:"Disse-lhes outra parábola: O Reino dos céus é semelhante ao fermento que uma mulher tomou e escondeu em três medidas de farinha, até ficar tudo levedado.",n:"Três medidas são perto de quarenta litros de farinha, pão para mais de cem pessoas. E o fermento, que na Escritura costuma ser figura da corrupção, é aqui figura do Reino: escondido, pequeno e capaz de transformar toda a massa."},
{v:34,t:"Tudo isso disse Jesus às multidões em parábolas; e nada lhes falava sem parábolas,"},
{v:35,t:"para que se cumprisse o que foi dito pelo profeta: Abrirei em parábolas a minha boca; proclamarei coisas escondidas desde a fundação do mundo.",n:"A citação é do Salmo 78, versículo 2 — o salmo que também começa dizendo que vai abrir a boca em parábolas para contar a história do povo."},
{v:36,t:"Então, despedindo as multidões, foi para casa. E os seus discípulos aproximaram-se dele, dizendo: Explica-nos a parábola do joio do campo."},
{v:37,t:"Ele respondeu: O que semeia a boa semente é o Filho do Homem;"},
{v:38,t:"o campo é o mundo; a boa semente são os filhos do Reino; o joio são os filhos do maligno;"},
{v:39,t:"o inimigo que o semeou é o diabo; a colheita é o fim do mundo; e os ceifeiros são os anjos."},
{v:40,t:"Assim como se recolhe o joio e se queima no fogo, assim será no fim do mundo."},
{v:41,t:"O Filho do Homem enviará os seus anjos, e eles recolherão do seu Reino todos os escândalos e os que praticam a iniquidade,"},
{v:42,t:"e os lançarão na fornalha ardente; ali haverá pranto e ranger de dentes."},
{v:43,t:"Então os justos resplandecerão como o sol no Reino de seu Pai. Quem tem ouvidos, ouça."},
{v:44,t:"O Reino dos céus é semelhante a um tesouro escondido no campo, que um homem encontrou e escondeu; e, na sua alegria, vai, vende tudo quanto tem e compra aquele campo.",n:"Nas duas parábolas que se seguem, o que move a venda de tudo não é o dever, mas a alegria: quem encontrou não faz um sacrifício, faz um bom negócio."},
{v:45,t:"Ainda o Reino dos céus é semelhante a um negociante que busca boas pérolas."},
{v:46,t:"Tendo encontrado uma pérola de grande valor, foi, vendeu tudo quanto tinha e a comprou."},
{v:47,t:"Ainda o Reino dos céus é semelhante a uma rede lançada ao mar, que recolhe peixes de toda espécie."},
{v:48,t:"Quando está cheia, os pescadores a tiram para a praia e, sentados, recolhem os bons em cestos, mas lançam fora os maus."},
{v:49,t:"Assim será no fim do mundo: sairão os anjos e separarão os maus do meio dos justos,"},
{v:50,t:"e os lançarão na fornalha ardente; ali haverá pranto e ranger de dentes."},
{v:51,t:"Entendestes tudo isso? Disseram-lhe: Sim."},
{v:52,t:"E ele lhes disse: Por isso, todo escriba que se tornou discípulo do Reino dos céus é semelhante a um pai de família que tira do seu tesouro coisas novas e velhas.",n:"O versículo fecha o discurso e descreve quem o transmite: não um homem que troca o velho pelo novo, mas um que sabe tirar os dois do mesmo tesouro. É, provavelmente, o retrato que o evangelista faz de si mesmo."},
{p:"Marcos 4:1-34"},
{v:1,t:"De novo começou a ensinar à beira do mar. E reuniu-se junto dele uma multidão tão numerosa, que entrou numa barca e nela se sentou, no mar; e toda a multidão estava em terra, à beira do mar."},
{v:2,t:"Ensinava-lhes muitas coisas em parábolas e dizia-lhes na sua doutrina:"},
{v:3,t:"Ouvi: Eis que o semeador saiu a semear."},
{v:4,t:"E, ao semear, uma parte caiu à beira do caminho; vieram as aves e a comeram."},
{v:5,t:"Outra caiu em lugar pedregoso, onde não havia muita terra; e logo nasceu, porque a terra não era profunda."},
{v:6,t:"E, quando saiu o sol, queimou-se; e, porque não tinha raiz, secou."},
{v:7,t:"Outra caiu entre os espinhos; e os espinhos cresceram e a sufocaram, e não deu fruto."},
{v:8,t:"Outras caíram em terra boa e deram fruto, que cresceu e se desenvolveu: uma produziu trinta, outra sessenta, outra cem."},
{v:9,t:"E dizia: Quem tem ouvidos para ouvir, ouça."},
{v:10,t:"Quando ficou a sós, os que estavam ao redor dele com os Doze perguntavam-lhe sobre as parábolas."},
{v:11,t:"Ele lhes dizia: A vós foi dado o mistério do Reino de Deus; mas aos que estão fora, tudo se faz em parábolas,"},
{v:12,t:"para que, vendo, vejam e não percebam; e, ouvindo, ouçam e não entendam; para que não se convertam e lhes seja perdoado."},
{v:13,t:"E disse-lhes: Não entendeis esta parábola? Como, então, compreendereis todas as parábolas?"},
{v:14,t:"O semeador semeia a palavra."},
{v:15,t:"Os que estão à beira do caminho são aqueles em que se semeia a palavra; e, quando a ouvem, logo vem Satanás e tira a palavra que neles foi semeada."},
{v:16,t:"Do mesmo modo, os semeados em lugar pedregoso são os que, ouvindo a palavra, logo a recebem com alegria;"},
{v:17,t:"mas não têm raiz em si e são de pouca duração; sobrevindo depois tribulação ou perseguição por causa da palavra, logo tropeçam."},
{v:18,t:"Outros são os semeados entre os espinhos: são os que ouvem a palavra,"},
{v:19,t:"mas as preocupações do mundo, a sedução da riqueza e as demais cobiças entram e sufocam a palavra, e fica sem fruto."},
{v:20,t:"E os semeados em terra boa são os que ouvem a palavra, a acolhem e dão fruto: um trinta, outro sessenta, outro cem."},
{v:21,t:"E dizia-lhes: Acaso vem a lâmpada para ser posta debaixo do alqueire ou debaixo da cama? Não é antes para ser posta no candelabro?"},
{v:22,t:"Porque nada há oculto que não deva ser manifestado, nem nada foi escondido senão para vir à luz."},
{v:23,t:"Se alguém tem ouvidos para ouvir, ouça."},
{v:24,t:"E dizia-lhes: Atentai no que ouvis. Com a medida com que medirdes, sereis medidos, e ainda se vos acrescentará."},
{v:25,t:"Porque ao que tem será dado; e ao que não tem, até o que tem lhe será tirado."},
{v:26,t:"E dizia: O Reino de Deus é assim como um homem que lança a semente à terra:",n:"A parábola da semente que cresce sozinha só aparece em São Marcos, e é das mais discretas: o lavrador dorme, e o Reino cresce sem ele. Nada do que faz explica o que acontece."},
{v:27,t:"dorme e levanta-se, de noite e de dia, e a semente germina e cresce, sem que ele saiba como."},
{v:28,t:"Por si mesma a terra dá fruto: primeiro a erva, depois a espiga, depois o grão cheio na espiga."},
{v:29,t:"E, quando o fruto está pronto, logo ele mete a foice, porque chegou a colheita."},
{v:30,t:"E dizia: A que assemelharemos o Reino de Deus, ou com que parábola o representaremos?"},
{v:31,t:"É como um grão de mostarda, que, quando é semeado na terra, é a menor de todas as sementes que há na terra;"},
{v:32,t:"mas, quando é semeado, cresce e torna-se maior do que todas as hortaliças, e cria ramos tão grandes, que as aves do céu podem abrigar-se à sua sombra."},
{v:33,t:"E com muitas parábolas semelhantes lhes anunciava a palavra, conforme podiam ouvir.",n:"Conforme podiam ouvir: o ensino mede-se pela capacidade de quem escuta, e não pela do que fala. É a nota que São Marcos acrescenta ao tema das parábolas, e corrige o que o versículo 12 parecia dizer."},
{v:34,t:"E não lhes falava sem parábolas; mas, em particular, explicava tudo aos seus discípulos."},
{p:"Lucas 8:4-18"},
{v:4,t:"Reunindo-se uma grande multidão, e vindo a ele gente de todas as cidades, disse por parábola:"},
{v:5,t:"Saiu o semeador a semear a sua semente. E, ao semear, uma parte caiu à beira do caminho e foi pisada; e as aves do céu a comeram."},
{v:6,t:"Outra caiu sobre a rocha e, tendo nascido, secou, porque não tinha umidade."},
{v:7,t:"Outra caiu no meio dos espinhos; e os espinhos, crescendo com ela, a sufocaram."},
{v:8,t:"Outra caiu em terra boa e, tendo nascido, produziu fruto a cem por um. Dizendo isso, exclamava: Quem tem ouvidos para ouvir, ouça."},
{v:9,t:"Os seus discípulos perguntavam-lhe o que significava essa parábola."},
{v:10,t:"Ele disse: A vós foi dado conhecer os mistérios do Reino de Deus; aos demais, em parábolas, para que, vendo, não vejam, e, ouvindo, não entendam."},
{v:11,t:"Esta é a parábola: a semente é a palavra de Deus."},
{v:12,t:"Os que estão à beira do caminho são os que ouvem; depois vem o diabo e tira-lhes do coração a palavra, para que não creiam e se salvem."},
{v:13,t:"Os que estão sobre a rocha são os que, ao ouvirem, recebem a palavra com alegria; mas não têm raiz, creem por algum tempo e, na hora da provação, desistem."},
{v:14,t:"O que caiu entre os espinhos são os que ouviram, mas, ao seguirem o caminho, são sufocados pelas preocupações, pelas riquezas e pelos prazeres da vida, e não chegam a dar fruto maduro."},
{v:15,t:"O que caiu em terra boa são os que, ouvindo a palavra com coração reto e bom, a retêm e dão fruto pela perseverança.",n:"Só São Lucas acrescenta a perseverança, hypomoné — a virtude de permanecer debaixo do peso. Nos outros dois evangelhos a terra boa dá fruto; aqui, dá-o com o tempo."},
{v:16,t:"Ninguém acende uma lâmpada e a cobre com um vaso ou a põe debaixo da cama; mas põe-na no candelabro, para que os que entram vejam a luz."},
{v:17,t:"Porque nada há oculto que não venha a manifestar-se, nem escondido que não venha a ser conhecido e a vir à luz."},
{v:18,t:"Vede, pois, como ouvis; porque ao que tem será dado, e ao que não tem, até o que julga ter lhe será tirado."}
];

EV[78] = [
{p:"Mateus 8:19-22"},
{v:19,t:"E, aproximando-se um escriba, disse-lhe: Mestre, hei de seguir-te para onde quer que fores."},
{v:20,t:"E disse-lhe Jesus: As raposas têm covis, e as aves do céu, ninhos; mas o Filho do Homem não tem onde reclinar a cabeça.",n:"Filho do Homem verte a expressão aramaica bar enash, que tanto pode dizer simplesmente um homem como remeter à figura de Daniel 7, a quem é dado o domínio eterno. Jesus usa-a quase sempre que fala de si, e o duplo sentido é deliberado."},
{v:21,t:"Outro dos discípulos lhe disse: Senhor, permite-me ir primeiro enterrar meu pai."},
{v:22,t:"Mas Jesus lhe disse: Segue-me e deixa que os mortos enterrem os seus mortos.",n:"A dureza da frase é real e não se atenua. Enterrar o pai era, na lei judaica, dever que precedia quase todos os outros; a resposta põe o seguimento acima do mais sagrado dos deveres. Há quem entenda que o pai ainda não morrera, e que o pedido era o de esperar anos até que morresse — leitura provável, que explica a pressa, mas não abranda a exigência."}
];

EV[79] = [
{p:"Mateus 8:18"},
{v:18,t:"Vendo Jesus a multidão ao seu redor, mandou passar para a outra margem."},
{p:"Mateus 8:23-27"},
{v:23,t:"E, entrando ele na barca, os seus discípulos o seguiram."},
{v:24,t:"E eis que se levantou no mar uma grande tempestade, de modo que a barca era coberta pelas ondas; ele, porém, dormia.",n:"Tempestade traduz seismos, a mesma palavra que noutros lugares diz terremoto: São Mateus escolhe o termo do abalo cósmico, e não o do mau tempo."},
{v:25,t:"Aproximaram-se e o despertaram, dizendo: Senhor, salva-nos, que perecemos!"},
{v:26,t:"E ele lhes disse: Por que sois medrosos, homens de pouca fé? Então, levantando-se, repreendeu os ventos e o mar, e fez-se grande bonança."},
{v:27,t:"E os homens admiraram-se, dizendo: Quem é este, que até os ventos e o mar lhe obedecem?",n:"A pergunta tem resposta no saltério: é o Salmo 107 que diz que o Senhor muda a tempestade em brisa e cala as ondas do mar. Quem conhecia o salmo sabia de quem se estava falando."},
{p:"Marcos 4:35-41"},
{v:35,t:"Naquele dia, chegada a tarde, disse-lhes: Passemos para a outra margem."},
{v:36,t:"E, deixando a multidão, levaram-no consigo, assim como estava, na barca; e outras barcas o acompanhavam."},
{v:37,t:"Levantou-se então grande vendaval, e as ondas se lançavam contra a barca, de modo que já se enchia."},
{v:38,t:"Ele estava na popa, dormindo sobre a almofada. Despertaram-no e disseram-lhe: Mestre, não te importa que pereçamos?",n:"A almofada é o pormenor que só São Marcos conserva — o coxim de couro que servia de assento ao remador de popa. São estes detalhes que a antiga tradição atribuía à memória de Pedro."},
{v:39,t:"E ele, despertando, repreendeu o vento e disse ao mar: Cala-te, aquieta-te. O vento cessou, e fez-se grande bonança.",n:"Repreender e mandar calar são os verbos dos exorcismos: o mar é tratado como a potência hostil que o Antigo Testamento nele via."},
{v:40,t:"E disse-lhes: Por que sois medrosos? Ainda não tendes fé?"},
{v:41,t:"E temeram com grande temor e diziam uns aos outros: Quem é este, que até o vento e o mar lhe obedecem?"},
{p:"Lucas 8:22-25"},
{v:22,t:"Aconteceu que, num daqueles dias, entrou numa barca com os seus discípulos e lhes disse: Passemos à outra margem do lago. E partiram."},
{v:23,t:"Enquanto navegavam, ele adormeceu. E desceu sobre o lago um vendaval; a barca enchia-se de água, e corriam perigo."},
{v:24,t:"Aproximando-se, despertaram-no, dizendo: Mestre, Mestre, perecemos! Ele, despertando, repreendeu o vento e a fúria da água; cessaram, e fez-se bonança."},
{v:25,t:"E disse-lhes: Onde está a vossa fé? Eles, atemorizados, admiraram-se, dizendo uns aos outros: Quem é este, que até aos ventos e à água dá ordens, e lhe obedecem?"}
];

EV[80] = [
{p:"Mateus 8:28-34"},
{v:28,t:"Tendo chegado à outra margem, à região dos gadarenos, vieram ao seu encontro dois endemoninhados, saídos dos sepulcros, tão furiosos que ninguém podia passar por aquele caminho.",n:"Os manuscritos hesitam entre gadarenos, gerasenos e gergesenos; a Nova Vulgata lê gadarenos em São Mateus e gerasenos nos outros dois. Gadara e Gerasa ficavam ambas a leste do lago, em território pagão — o que explica a manada de porcos, animal impuro que nenhum judeu criaria."},
{v:29,t:"E eis que gritaram, dizendo: Que temos nós contigo, Filho de Deus? Vieste aqui atormentar-nos antes do tempo?"},
{v:30,t:"Havia, longe deles, uma grande manada de porcos pastando."},
{v:31,t:"E os demônios lhe suplicavam, dizendo: Se nos expulsas, manda-nos para a manada de porcos."},
{v:32,t:"E ele lhes disse: Ide. E eles, saindo, foram para os porcos; e eis que toda a manada se precipitou pelo despenhadeiro no mar, e morreram nas águas."},
{v:33,t:"Os que os apascentavam fugiram e, indo à cidade, contaram tudo, e o que acontecera aos endemoninhados."},
{v:34,t:"E eis que toda a cidade saiu ao encontro de Jesus e, ao vê-lo, rogaram-lhe que se retirasse do seu território.",n:"Ninguém pede a cura de mais ninguém: pedem que ele vá embora. A cidade prefere os porcos ao homem restituído, e o evangelho anota-o sem comentário."},
{p:"Mateus 9:1"},
{v:1,t:"E, entrando numa barca, passou para a outra margem e veio à sua cidade."},
{p:"Marcos 5:1-20"},
{v:1,t:"Chegaram à outra margem do mar, à região dos gerasenos."},
{v:2,t:"E, saindo ele da barca, logo veio ao seu encontro, dos sepulcros, um homem com espírito imundo,"},
{v:3,t:"que tinha morada nos sepulcros; e nem com cadeias alguém o podia prender,"},
{v:4,t:"pois muitas vezes fora preso com grilhões e cadeias, mas quebrara as cadeias e despedaçara os grilhões, e ninguém conseguia dominá-lo."},
{v:5,t:"E continuamente, de noite e de dia, andava pelos sepulcros e pelos montes, gritando e ferindo-se com pedras."},
{v:6,t:"Vendo Jesus de longe, correu e prostrou-se diante dele."},
{v:7,t:"E, gritando com grande voz, disse: Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? Conjuro-te por Deus que não me atormentes."},
{v:8,t:"Porque lhe dizia: Sai desse homem, espírito imundo."},
{v:9,t:"E perguntou-lhe: Qual é o teu nome? Respondeu-lhe: Legião é o meu nome, porque somos muitos.",n:"A legião romana contava perto de seis mil homens. O nome que o espírito se dá é o da força de ocupação, e é a única vez em que um demônio, interrogado, responde com um número."},
{v:10,t:"E suplicava-lhe muito que não os expulsasse daquela região."},
{v:11,t:"Ora, havia ali, junto ao monte, uma grande manada de porcos pastando."},
{v:12,t:"E suplicaram-lhe, dizendo: Manda-nos para os porcos, para que entremos neles."},
{v:13,t:"E ele o permitiu. E os espíritos imundos, saindo, entraram nos porcos; e a manada, de uns dois mil, precipitou-se pelo despenhadeiro no mar, e afogaram-se no mar."},
{v:14,t:"Os que os apascentavam fugiram e contaram na cidade e pelos campos; e foram ver o que acontecera."},
{v:15,t:"Chegaram a Jesus e viram o endemoninhado, o que tivera a legião, sentado, vestido e em seu juízo perfeito; e tiveram medo.",n:"Sentado, vestido e em seu juízo: três palavras que desfazem exatamente os três traços com que o homem fora descrito — o que corria pelos montes, o que andava nu, o que gritava. A cura é dita pela devolução do que se perdera."},
{v:16,t:"Os que tinham visto contaram-lhes o que acontecera ao endemoninhado e o dos porcos."},
{v:17,t:"E começaram a rogar-lhe que se retirasse do seu território."},
{v:18,t:"Ao entrar ele na barca, o que fora endemoninhado suplicava-lhe que o deixasse ficar com ele."},
{v:19,t:"Não o permitiu, mas disse-lhe: Vai para tua casa, para os teus, e anuncia-lhes quanto o Senhor te fez e como teve misericórdia de ti.",n:"Na Galileia, Jesus manda calar os que cura; aqui, em terra pagã, manda anunciar. Onde não havia expectativa messiânica a ser mal entendida, não havia razão para o silêncio."},
{v:20,t:"Ele foi e começou a proclamar na Decápole quanto Jesus lhe fizera; e todos se admiravam.",n:"A Decápole era a liga das dez cidades gregas a leste do Jordão. O primeiro pregador em território pagão é, assim, um homem que ninguém enviou e que Jesus mandou apenas voltar para casa."},
{p:"Lucas 8:26-39"},
{v:26,t:"E navegaram para a região dos gerasenos, que fica defronte da Galileia."},
{v:27,t:"Quando desembarcou em terra, veio ao seu encontro um homem da cidade, possuído por demônios; havia muito tempo não vestia roupa nem morava em casa, mas nos sepulcros."},
{v:28,t:"Vendo Jesus, gritou, prostrou-se diante dele e disse com grande voz: Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? Peço-te que não me atormentes."},
{v:29,t:"Pois ordenava ao espírito imundo que saísse daquele homem; muitas vezes se apoderara dele, e era guardado preso com cadeias e grilhões; mas, quebrando as prisões, era impelido pelo demônio para os desertos."},
{v:30,t:"Perguntou-lhe Jesus: Qual é o teu nome? Ele disse: Legião — porque muitos demônios tinham entrado nele."},
{v:31,t:"E suplicavam-lhe que não os mandasse para o abismo.",n:"O abismo, abyssos, é nos escritos do tempo o lugar onde os espíritos rebeldes ficam encerrados até ao juízo. Onde Marcos diz apenas fora da região, Lucas nomeia a prisão que temem."},
{v:32,t:"Havia ali uma grande manada de porcos, pastando no monte; e suplicaram-lhe que lhes permitisse entrar neles. E ele o permitiu."},
{v:33,t:"Saindo os demônios do homem, entraram nos porcos; e a manada precipitou-se pelo despenhadeiro no lago, e afogou-se."},
{v:34,t:"Vendo os pastores o que acontecera, fugiram e contaram na cidade e pelos campos."},
{v:35,t:"Saíram para ver o que acontecera; vieram a Jesus e encontraram o homem, de quem tinham saído os demônios, sentado aos pés de Jesus, vestido e em seu juízo perfeito; e tiveram medo."},
{v:36,t:"Os que tinham visto contaram-lhes como fora salvo o endemoninhado."},
{v:37,t:"E toda a multidão da região dos gerasenos lhe rogou que se retirasse deles, porque grande temor os tomara. Ele entrou na barca e voltou."},
{v:38,t:"O homem, de quem tinham saído os demônios, pedia-lhe para ficar com ele; mas Jesus o despediu, dizendo:"},
{v:39,t:"Volta para tua casa e conta quanto Deus te fez. E ele foi, proclamando por toda a cidade quanto Jesus lhe fizera.",n:"Jesus manda contar o que Deus fez; o homem conta o que Jesus fez. São Lucas deixa a passagem de um nome ao outro sem nenhum comentário."}
];

EV[81] = [
{p:"Mateus 9:10-13"},
{v:10,t:"E aconteceu que, estando ele à mesa em casa, vieram muitos publicanos e pecadores e sentaram-se à mesa com Jesus e os seus discípulos.",n:"Publicanos eram os cobradores de impostos para Roma; a sua profissão tornava-os impuros e traidores ao mesmo tempo. Comer à mesa de alguém era, no Oriente, declarar-se seu, e é isso que escandaliza — não a conversa, mas a mesa."},
{v:11,t:"Vendo isso, os fariseus diziam aos seus discípulos: Por que come o vosso Mestre com publicanos e pecadores?"},
{v:12,t:"Ele, ouvindo, disse: Não são os sãos que precisam de médico, mas os doentes."},
{v:13,t:"Ide aprender o que significa: Misericórdia quero, e não sacrifício. Porque não vim chamar justos, mas pecadores.",n:"A citação é de Oseias 6,6. Ide aprender era fórmula rabínica de repreensão dirigida a quem se julgava mestre: manda estudar os doutores da lei."},
{p:"Marcos 2:15-17"},
{v:15,t:"E aconteceu que, estando ele à mesa em casa de Levi, muitos publicanos e pecadores sentaram-se à mesa com Jesus e os seus discípulos, pois eram muitos e o seguiam."},
{v:16,t:"Os escribas dos fariseus, vendo que ele comia com pecadores e publicanos, diziam aos seus discípulos: Por que come com publicanos e pecadores?"},
{v:17,t:"Ouvindo isso, Jesus lhes disse: Não são os sãos que precisam de médico, mas os doentes; não vim chamar justos, mas pecadores."},
{p:"Lucas 5:29-32"},
{v:29,t:"Levi ofereceu-lhe um grande banquete em sua casa; e havia grande número de publicanos e de outros que estavam à mesa com eles."},
{v:30,t:"Os fariseus e os seus escribas murmuravam contra os discípulos dele, dizendo: Por que comeis e bebeis com publicanos e pecadores?"},
{v:31,t:"Jesus lhes respondeu: Não são os sãos que precisam de médico, mas os doentes."},
{v:32,t:"Não vim chamar justos, mas pecadores, ao arrependimento.",n:"Só São Lucas acrescenta ao arrependimento. Os três evangelhos dizem que Jesus veio chamar pecadores; Lucas precisa para quê — não para os deixar como estão, mas para os fazer voltar."}
];

EV[82] = [
{p:"Mateus 9:14-17"},
{v:14,t:"Então aproximaram-se dele os discípulos de João, dizendo: Por que nós e os fariseus jejuamos muitas vezes, mas os teus discípulos não jejuam?"},
{v:15,t:"E Jesus lhes disse: Podem acaso os convidados da boda estar de luto enquanto o esposo está com eles? Dias virão em que o esposo lhes será tirado, e então jejuarão.",n:"O esposo é, nos profetas, o próprio Deus em relação a Israel. A resposta não discute a disciplina do jejum: muda a questão, dizendo que a festa já começou — e anuncia, na mesma frase, que o esposo será tirado."},
{v:16,t:"Ninguém põe remendo de pano novo em roupa velha, porque o remendo repuxa a roupa, e o rasgão fica pior."},
{v:17,t:"Nem se põe vinho novo em odres velhos; do contrário, os odres se rompem, o vinho se derrama e os odres se perdem. Mas põe-se vinho novo em odres novos, e ambos se conservam.",n:"O odre de pele, já esticado por uma fermentação, rebenta com a seguinte. A imagem não diz que o velho é mau, mas que não aguenta: o que é novo exige forma nova."},
{p:"Marcos 2:18-22"},
{v:18,t:"Os discípulos de João e os fariseus estavam jejuando. Vieram e lhe disseram: Por que os discípulos de João e os discípulos dos fariseus jejuam, mas os teus discípulos não jejuam?"},
{v:19,t:"Jesus lhes respondeu: Podem acaso jejuar os convidados da boda enquanto o esposo está com eles? Enquanto têm consigo o esposo, não podem jejuar."},
{v:20,t:"Dias virão em que o esposo lhes será tirado, e então jejuarão, naquele dia."},
{v:21,t:"Ninguém costura remendo de pano novo em roupa velha; do contrário, o remendo novo repuxa o velho, e o rasgão fica pior."},
{v:22,t:"E ninguém põe vinho novo em odres velhos; do contrário, o vinho rompe os odres, e perdem-se o vinho e os odres. Mas vinho novo em odres novos."},
{p:"Lucas 5:33-39"},
{v:33,t:"Disseram-lhe eles: Os discípulos de João jejuam muitas vezes e fazem orações, e do mesmo modo os dos fariseus; mas os teus comem e bebem."},
{v:34,t:"Jesus lhes disse: Podeis fazer jejuar os convidados da boda enquanto o esposo está com eles?"},
{v:35,t:"Dias virão em que o esposo lhes será tirado; então, naqueles dias, jejuarão."},
{v:36,t:"Disse-lhes também uma parábola: Ninguém rasga um pedaço de roupa nova para remendar roupa velha; do contrário, rasga a nova, e o pedaço tirado da nova não combina com a velha."},
{v:37,t:"E ninguém põe vinho novo em odres velhos; do contrário, o vinho novo romperá os odres, e há de derramar-se, e os odres se perderão."},
{v:38,t:"Mas vinho novo deve ser posto em odres novos."},
{v:39,t:"E ninguém que bebe do velho quer o novo, pois diz: O velho é bom.",n:"Só São Lucas acrescenta este verso, e ele soa contra tudo o que vem antes. É observação irônica sobre o hábito: quem se acostumou ao velho nem chega a provar o novo — e, portanto, nunca saberá."}
];

EV[83] = [
{p:"Mateus 9:18-26"},
{v:18,t:"Enquanto lhes dizia essas coisas, eis que um chefe se aproximou e se prostrou diante dele, dizendo: Minha filha acaba de morrer; mas vem, impõe a tua mão sobre ela, e viverá."},
{v:19,t:"E Jesus, levantando-se, o seguiu com os seus discípulos."},
{v:20,t:"E eis que uma mulher, que havia doze anos sofria de hemorragia, aproximou-se por trás e tocou a orla do seu manto,",n:"A hemorragia tornava-a permanentemente impura segundo o Levítico, e impuro tudo o que tocasse; por isso vem por trás. A orla é o tsitsit, a franja com um fio de púrpura que a lei mandava coser nos quatro cantos do manto."},
{v:21,t:"pois dizia consigo: Se eu apenas tocar o seu manto, ficarei curada."},
{v:22,t:"Jesus, voltando-se e vendo-a, disse: Tem confiança, filha; a tua fé te salvou. E desde aquela hora a mulher ficou curada.",n:"Salvou traduz sozo, que diz ao mesmo tempo curar e salvar. O evangelho não separa as duas coisas, e a tradução conserva a palavra que as une."},
{v:23,t:"Tendo Jesus chegado à casa do chefe e vendo os flautistas e a multidão em alvoroço, disse:",n:"Os flautistas eram carpideiros profissionais; a Mixná registra que mesmo o mais pobre em Israel devia contratar ao menos duas flautas e uma carpideira para o enterro da mulher."},
{v:24,t:"Retirai-vos, porque a menina não está morta, mas dorme. E riam-se dele."},
{v:25,t:"Mas, expulsa a multidão, ele entrou, tomou-lhe a mão, e a menina levantou-se."},
{v:26,t:"E a notícia disso correu por toda aquela região."},
{p:"Marcos 5:21-43"},
{v:21,t:"Tendo Jesus passado de novo, na barca, para a outra margem, reuniu-se junto dele grande multidão; e ele estava à beira do mar."},
{v:22,t:"E veio um dos chefes da sinagoga, chamado Jairo; e, ao vê-lo, prostrou-se a seus pés"},
{v:23,t:"e suplicava-lhe com insistência, dizendo: Minha filhinha está nas últimas; vem, impõe-lhe as mãos, para que seja salva e viva."},
{v:24,t:"E ele foi com ele; e grande multidão o seguia e o apertava.",n:"São Marcos encaixa uma história dentro da outra: o pai fica à espera enquanto a mulher é atendida, e é nessa demora que a filha morre. O modo de contar é ele mesmo o argumento sobre a fé que espera."},
{v:25,t:"Ora, uma mulher que havia doze anos sofria de hemorragia,"},
{v:26,t:"e muito padecera às mãos de muitos médicos, gastando tudo o que tinha, sem proveito algum, mas antes piorando,"},
{v:27,t:"tendo ouvido falar de Jesus, veio por trás, no meio da multidão, e tocou o seu manto."},
{v:28,t:"Porque dizia: Se eu tocar ao menos as suas vestes, ficarei curada."},
{v:29,t:"E logo se estancou a fonte do seu sangue, e sentiu no corpo que estava curada do seu mal."},
{v:30,t:"E logo Jesus, reconhecendo em si mesmo que saíra dele uma força, voltando-se no meio da multidão, dizia: Quem tocou nas minhas vestes?"},
{v:31,t:"Os seus discípulos lhe diziam: Vês que a multidão te aperta, e dizes: Quem me tocou?"},
{v:32,t:"E olhava ao redor para ver quem fizera isso."},
{v:33,t:"A mulher, temendo e tremendo, sabendo o que lhe acontecera, veio, prostrou-se diante dele e disse-lhe toda a verdade."},
{v:34,t:"E ele lhe disse: Filha, a tua fé te salvou; vai em paz e fica curada do teu mal.",n:"Filha é a única vez em que Jesus chama assim a alguém. A mulher tocara às escondidas e podia ter ido embora curada e anônima; ele detém tudo para lhe dar um nome."},
{v:35,t:"Ainda ele falava, quando vieram da casa do chefe da sinagoga, dizendo: Tua filha morreu; por que ainda incomodas o Mestre?"},
{v:36,t:"Mas Jesus, ouvindo o que se dizia, disse ao chefe da sinagoga: Não temas, crê somente."},
{v:37,t:"E não permitiu que ninguém o acompanhasse, senão Pedro, Tiago e João, irmão de Tiago."},
{v:38,t:"Chegaram à casa do chefe da sinagoga, e ele viu o alvoroço e os que choravam e gritavam muito."},
{v:39,t:"E, entrando, disse-lhes: Por que vos alvoroçais e chorais? A menina não está morta, mas dorme."},
{v:40,t:"E riam-se dele. Mas ele, tendo mandado sair a todos, tomou consigo o pai e a mãe da menina e os que estavam com ele, e entrou onde estava a menina."},
{v:41,t:"E, tomando a mão da menina, disse-lhe: Talitá kum — que quer dizer: Menina, eu te digo, levanta-te.",n:"São Marcos conserva as palavras em aramaico, a língua em que foram ditas, e traduz em seguida para os seus leitores de Roma. Talitá é o feminino de cordeirinho, termo de carinho para uma menina."},
{v:42,t:"E logo a menina se levantou e andava, pois tinha doze anos. E ficaram atônitos, com grande espanto.",n:"Doze anos: os mesmos da doença da mulher. Uma vivia havia doze anos o que a outra tinha de idade, e as duas histórias, encaixadas uma na outra, fecham-se por esse número."},
{v:43,t:"E ordenou-lhes com insistência que ninguém o soubesse; e mandou dar-lhe de comer."},
{p:"Lucas 8:40-56"},
{v:40,t:"Ao voltar Jesus, a multidão o recebeu, pois todos o esperavam."},
{v:41,t:"E eis que veio um homem chamado Jairo, que era chefe da sinagoga; e, prostrando-se aos pés de Jesus, suplicava-lhe que fosse à sua casa,"},
{v:42,t:"porque tinha uma filha única, de cerca de doze anos, que estava morrendo. Enquanto ia, as multidões o apertavam."},
{v:43,t:"E uma mulher, que havia doze anos sofria de hemorragia e a ninguém pudera ser curada,",n:"São Lucas, que a tradição diz médico, é o único que não escreve que a mulher gastara tudo com médicos sem proveito, como faz São Marcos."},
{v:44,t:"aproximou-se por trás e tocou a orla do seu manto; e logo se estancou a sua hemorragia."},
{v:45,t:"E disse Jesus: Quem me tocou? Como todos negassem, disse Pedro: Mestre, as multidões te cercam e te apertam."},
{v:46,t:"Mas Jesus disse: Alguém me tocou, pois senti que de mim saiu uma força."},
{v:47,t:"A mulher, vendo que não passara despercebida, veio tremendo e, prostrando-se diante dele, declarou diante de todo o povo por que motivo o tocara e como logo ficara curada."},
{v:48,t:"E ele lhe disse: Filha, a tua fé te salvou; vai em paz."},
{v:49,t:"Ainda ele falava, quando veio alguém da casa do chefe da sinagoga, dizendo: Tua filha morreu; não incomodes mais o Mestre."},
{v:50,t:"Mas Jesus, ouvindo, respondeu-lhe: Não temas; crê somente, e ela será salva."},
{v:51,t:"Chegando à casa, não permitiu que ninguém entrasse com ele, senão Pedro, João e Tiago, e o pai e a mãe da menina."},
{v:52,t:"Todos choravam e se lamentavam por ela. Mas ele disse: Não choreis; não está morta, mas dorme."},
{v:53,t:"E riam-se dele, sabendo que estava morta."},
{v:54,t:"Ele, porém, tomando-lhe a mão, exclamou: Menina, levanta-te."},
{v:55,t:"E o seu espírito voltou, e ela se levantou imediatamente; e ele mandou que lhe dessem de comer."},
{v:56,t:"Os seus pais ficaram atônitos; mas ele ordenou-lhes que a ninguém dissessem o que acontecera."}
];

EV[84] = [
{p:"Mateus 11:2-6"},
{v:2,t:"João, tendo ouvido no cárcere falar das obras de Cristo, enviou pelos seus discípulos"},
{v:3,t:"a perguntar-lhe: És tu o que há de vir, ou esperamos outro?",n:"A pergunta vem de quem o apontara no Jordão, e é das passagens que mais garantem a honestidade dos evangelhos: nada obrigava a conservá-la. João anunciara um juízo com o machado posto à raiz das árvores, e o que ouve contar são curas."},
{v:4,t:"E Jesus lhes respondeu: Ide e anunciai a João o que ouvis e vedes:"},
{v:5,t:"os cegos veem e os coxos andam, os leprosos são purificados e os surdos ouvem, os mortos ressuscitam e aos pobres é anunciado o Evangelho.",n:"A resposta é tecida com versos de Isaías 29, 35 e 61 — e deixa de fora, do último deles, justamente o dia da vingança do nosso Deus. A omissão é a resposta: o machado não veio, e não é engano nenhum."},
{v:6,t:"E bem-aventurado aquele que não se escandalizar em mim."},
{p:"Lucas 7:18-23"},
{v:18,t:"Os discípulos de João contaram-lhe todas essas coisas. E João, chamando dois dos seus discípulos,"},
{v:19,t:"enviou-os ao Senhor, a perguntar: És tu o que há de vir, ou esperamos outro?"},
{v:20,t:"Chegando a ele, os homens disseram: João Batista enviou-nos a ti, a perguntar: És tu o que há de vir, ou esperamos outro?"},
{v:21,t:"Naquela hora curou muitos de doenças, de males e de espíritos malignos, e a muitos cegos deu a vista.",n:"São Lucas acrescenta este versículo: antes de responder com palavras, Jesus faz diante dos enviados aquilo de que vai falar. A resposta é para ser vista, não ouvida."},
{v:22,t:"E, respondendo, disse-lhes: Ide e anunciai a João o que vistes e ouvistes: os cegos veem, os coxos andam, os leprosos são purificados e os surdos ouvem, os mortos ressuscitam e aos pobres é anunciado o Evangelho."},
{v:23,t:"E bem-aventurado aquele que não se escandalizar em mim."}
];

EV[85] = [
{p:"Mateus 11:7-30"},
{v:7,t:"Ao partirem eles, começou Jesus a falar de João às multidões: Que saístes a ver no deserto? Uma cana agitada pelo vento?"},
{v:8,t:"Então, que saístes a ver? Um homem vestido com roupas delicadas? Eis que os que vestem roupas delicadas estão nas casas dos reis.",n:"A alusão é mordaz: quem está no palácio é Herodes, e é ele que tem João preso. A cana agitada pelo vento era, além disso, o emblema cunhado nas moedas de Herodes Antipas."},
{v:9,t:"Então, que saístes a ver? Um profeta? Sim, eu vos digo, e mais do que profeta."},
{v:10,t:"Este é aquele de quem está escrito: Eis que envio o meu mensageiro diante da tua face, o qual preparará o teu caminho diante de ti."},
{v:11,t:"Em verdade vos digo: entre os nascidos de mulher não surgiu ninguém maior do que João Batista; mas o menor no Reino dos céus é maior do que ele.",n:"O elogio e o limite vêm na mesma frase. João é o maior do que veio antes, e o último dessa ordem; a que começa agora não se mede pela grandeza de quem a recebe."},
{v:12,t:"Desde os dias de João Batista até agora, o Reino dos céus sofre violência, e os violentos o arrebatam.",n:"Dos versículos mais discutidos dos evangelhos. O verbo biazetai tanto pode ser passivo — o Reino é violentado — como médio — o Reino irrompe com força. A primeira leitura faz dos violentos os perseguidores; a segunda, os que se esforçam por entrar. A Nova Vulgata conserva a ambiguidade, e a tradução também."},
{v:13,t:"Porque todos os profetas e a lei profetizaram até João."},
{v:14,t:"E, se quiserdes aceitá-lo, ele é Elias, que há de vir."},
{v:15,t:"Quem tem ouvidos, ouça."},
{v:16,t:"A que compararei esta geração? É semelhante a meninos sentados nas praças, que gritam aos companheiros:"},
{v:17,t:"Tocamos flauta para vós, e não dançastes; entoamos lamentações, e não vos batestes no peito.",n:"As duas brincadeiras de rua eram o casamento e o enterro. A geração recusa os dois jogos: não dança com um nem chora com o outro, e acha defeito em ambos os que vieram."},
{v:18,t:"Porque veio João, que não come nem bebe, e dizem: Está possesso."},
{v:19,t:"Veio o Filho do Homem, que come e bebe, e dizem: Eis um comilão e bebedor de vinho, amigo de publicanos e pecadores. Mas a sabedoria foi justificada pelas suas obras."},
{v:20,t:"Então começou a censurar as cidades em que se fizeram a maior parte dos seus milagres, porque não se converteram:"},
{v:21,t:"Ai de ti, Corazin! Ai de ti, Betsaida! Porque, se em Tiro e Sidônia se tivessem feito os milagres que em vós se fizeram, há muito teriam feito penitência em cilício e cinza.",n:"Tiro e Sidônia eram, nos profetas, as cidades pagãs por excelência; Sodoma, o caso extremo. A comparação inverte todas as expectativas: as cidades da Galileia que o viram são julgadas com mais rigor do que aquelas que nunca ouviram."},
{v:22,t:"Por isso vos digo: no dia do juízo haverá menos rigor para Tiro e Sidônia do que para vós."},
{v:23,t:"E tu, Cafarnaum, acaso serás elevada até ao céu? Até ao abismo descerás. Porque, se em Sodoma se tivessem feito os milagres que em ti se fizeram, ela permaneceria até ao dia de hoje."},
{v:24,t:"Por isso vos digo: no dia do juízo haverá menos rigor para a terra de Sodoma do que para ti."},
{v:25,t:"Naquele tempo, disse Jesus: Eu te louvo, Pai, Senhor do céu e da terra, porque escondeste estas coisas aos sábios e prudentes e as revelaste aos pequeninos.",n:"Os versículos 25 a 27 são chamados, desde o século XIX, o relâmpago joanino: falam como o quarto evangelho, embora estejam em Mateus e em Lucas. São a passagem mais explícita dos evangelhos sinóticos sobre o conhecimento mútuo entre o Pai e o Filho."},
{v:26,t:"Sim, Pai, porque assim foi do teu agrado."},
{v:27,t:"Tudo me foi entregue por meu Pai; e ninguém conhece o Filho senão o Pai, nem ninguém conhece o Pai senão o Filho, e aquele a quem o Filho o quiser revelar."},
{v:28,t:"Vinde a mim, todos vós que estais cansados e sobrecarregados, e eu vos aliviarei."},
{v:29,t:"Tomai sobre vós o meu jugo e aprendei de mim, porque sou manso e humilde de coração, e encontrareis descanso para as vossas almas.",n:"Jugo era, no vocabulário dos rabinos, o conjunto dos preceitos: falava-se do jugo da lei e do jugo do Reino. Não se promete aqui a ausência de jugo, mas outro — e o único mestre da Escritura que se apresenta dizendo o que ele próprio é."},
{v:30,t:"Porque o meu jugo é suave, e o meu fardo é leve."},
{p:"Lucas 7:24-35"},
{v:24,t:"Tendo partido os mensageiros de João, começou a falar de João às multidões: Que saístes a ver no deserto? Uma cana agitada pelo vento?"},
{v:25,t:"Então, que saístes a ver? Um homem vestido com roupas delicadas? Eis que os que vestem com esplendor e vivem nas delícias estão nos palácios dos reis."},
{v:26,t:"Então, que saístes a ver? Um profeta? Sim, eu vos digo, e mais do que profeta."},
{v:27,t:"Este é aquele de quem está escrito: Eis que envio o meu mensageiro diante da tua face, o qual preparará o teu caminho diante de ti."},
{v:28,t:"Eu vos digo: entre os nascidos de mulher, ninguém é maior do que João; mas o menor no Reino de Deus é maior do que ele."},
{v:29,t:"E todo o povo que o ouviu, e também os publicanos, reconheceram a justiça de Deus, tendo recebido o batismo de João;"},
{v:30,t:"mas os fariseus e os doutores da lei frustraram em si mesmos o desígnio de Deus, não se deixando batizar por ele.",n:"Frustrar em si mesmos o desígnio de Deus: a expressão é forte e única. Não se diz que o plano de Deus falhou, mas que o tornaram sem efeito quanto a si — o que Deus queria dar continuou oferecido, e não foi recebido."},
{v:31,t:"A que, pois, compararei os homens desta geração? E a que são semelhantes?"},
{v:32,t:"São semelhantes a meninos sentados na praça, que gritam uns aos outros: Tocamos flauta para vós, e não dançastes; entoamos lamentações, e não chorastes."},
{v:33,t:"Porque veio João Batista, que não come pão nem bebe vinho, e dizeis: Está possesso."},
{v:34,t:"Veio o Filho do Homem, que come e bebe, e dizeis: Eis um comilão e bebedor de vinho, amigo de publicanos e pecadores."},
{v:35,t:"Mas a sabedoria foi justificada por todos os seus filhos.",n:"Onde São Mateus diz pelas suas obras, São Lucas diz pelos seus filhos. A sabedoria de Deus prova-se pelo que gera: no primeiro caso, pelo que faz; no segundo, por aqueles que a acolhem."}
];

EV[86] = [
{p:"Mateus 9:36-38"},
{v:36,t:"Vendo as multidões, compadeceu-se delas, porque estavam cansadas e abatidas, como ovelhas que não têm pastor.",n:"Compadeceu-se verte splanchnizomai, verbo formado sobre as entranhas: diz a comoção que se sente no corpo. Nos evangelhos, quem assim se compadece é quase sempre o próprio Jesus."},
{v:37,t:"Então disse aos seus discípulos: A messe é grande, mas os trabalhadores são poucos."},
{v:38,t:"Rogai, pois, ao Senhor da messe que envie trabalhadores para a sua messe."},
{p:"Mateus 10:1-42"},
{v:1,t:"E, chamando os seus doze discípulos, deu-lhes poder sobre os espíritos imundos, para os expulsarem e para curarem toda doença e toda enfermidade."},
{v:2,t:"Os nomes dos doze apóstolos são estes: primeiro, Simão, chamado Pedro, e André, seu irmão; Tiago, filho de Zebedeu, e João, seu irmão;",n:"Apóstolo significa enviado, e é a única vez que São Mateus usa a palavra. O número doze não é casual: corresponde às tribos de Israel, e diz que o povo está sendo refundado."},
{v:3,t:"Filipe e Bartolomeu; Tomé e Mateus, o publicano; Tiago, filho de Alfeu, e Tadeu;"},
{v:4,t:"Simão, o cananeu, e Judas Iscariotes, o mesmo que o entregou.",n:"Cananeu não diz aqui a terra de Canaã, mas verte o aramaico qananaya, o zeloso — o mesmo que São Lucas traduz por zelota. Na mesma lista estão um cobrador de impostos de Roma e um homem do partido que queria expulsá-la."},
{v:5,t:"A estes doze enviou Jesus, dando-lhes as seguintes instruções: Não sigais pelo caminho dos gentios nem entreis em cidade de samaritanos;"},
{v:6,t:"ide antes às ovelhas perdidas da casa de Israel."},
{v:7,t:"Em vosso caminho, pregai, dizendo: Está próximo o Reino dos céus."},
{v:8,t:"Curai os doentes, ressuscitai os mortos, purificai os leprosos, expulsai os demônios. De graça recebestes, de graça dai."},
{v:9,t:"Não leveis ouro, nem prata, nem cobre nos vossos cintos;"},
{v:10,t:"nem alforje para o caminho, nem duas túnicas, nem sandálias, nem bastão; porque o trabalhador é digno do seu sustento.",n:"São Mateus e São Lucas proíbem o bastão; São Marcos permite-o, e permite também as sandálias. A divergência é antiga e ninguém a harmonizou: o sentido comum é o da desprovisão total, e cada evangelista a mede pelo que era o mínimo entre os seus."},
{v:11,t:"Em qualquer cidade ou aldeia em que entrardes, informai-vos de quem nela é digno, e ficai ali até vos retirardes."},
{v:12,t:"Ao entrardes na casa, saudai-a."},
{v:13,t:"E, se a casa for digna, venha sobre ela a vossa paz; mas, se não for digna, volte para vós a vossa paz."},
{v:14,t:"E, se alguém não vos receber nem ouvir as vossas palavras, ao sairdes daquela casa ou cidade, sacudi o pó dos vossos pés.",n:"Sacudir o pó era gesto que os judeus faziam ao voltar de terra pagã, para não trazer nada dela consigo. Aplicado a uma cidade de Israel, é de uma dureza calculada."},
{v:15,t:"Em verdade vos digo: no dia do juízo haverá menos rigor para a terra de Sodoma e Gomorra do que para aquela cidade."},
{v:16,t:"Eis que eu vos envio como ovelhas no meio de lobos; sede, pois, prudentes como as serpentes e simples como as pombas."},
{v:17,t:"Acautelai-vos dos homens, porque vos entregarão aos tribunais e vos açoitarão nas suas sinagogas;"},
{v:18,t:"e sereis levados por minha causa diante de governadores e reis, para servir de testemunho a eles e aos gentios."},
{v:19,t:"Quando vos entregarem, não vos preocupeis com o modo de falar nem com o que haveis de dizer, porque naquela hora vos será dado o que haveis de falar;"},
{v:20,t:"pois não sois vós que falais, mas o Espírito de vosso Pai é que fala em vós."},
{v:21,t:"O irmão entregará à morte o irmão, e o pai, o filho; os filhos se levantarão contra os pais e os matarão."},
{v:22,t:"E sereis odiados por todos por causa do meu nome; mas quem perseverar até ao fim, esse será salvo."},
{v:23,t:"Quando vos perseguirem numa cidade, fugi para outra. Em verdade vos digo: não acabareis de percorrer as cidades de Israel antes que venha o Filho do Homem."},
{v:24,t:"O discípulo não está acima do mestre, nem o servo acima do seu senhor."},
{v:25,t:"Basta ao discípulo ser como o seu mestre, e ao servo, como o seu senhor. Se ao dono da casa chamaram Belzebu, quanto mais aos seus familiares!"},
{v:26,t:"Não os temais, pois; nada há encoberto que não venha a ser descoberto, nem oculto que não venha a ser conhecido."},
{v:27,t:"O que vos digo nas trevas, dizei-o à luz; e o que ouvis ao ouvido, proclamai-o sobre os telhados."},
{v:28,t:"Não temais os que matam o corpo e não podem matar a alma; temei antes aquele que pode fazer perecer no inferno a alma e o corpo."},
{v:29,t:"Não se vendem dois passarinhos por um asse? E nenhum deles cai por terra sem o vosso Pai.",n:"O asse era a menor moeda de cobre romana, um décimo sexto do salário de um dia. O argumento vai do preço mais baixo que se podia nomear até aos cabelos da cabeça: nada é pequeno o bastante para escapar."},
{v:30,t:"Quanto a vós, até os cabelos da vossa cabeça estão todos contados."},
{v:31,t:"Não temais, pois; mais valeis vós do que muitos passarinhos."},
{v:32,t:"Todo aquele, pois, que me confessar diante dos homens, também eu o confessarei diante de meu Pai, que está nos céus;"},
{v:33,t:"mas quem me negar diante dos homens, também eu o negarei diante de meu Pai, que está nos céus."},
{v:34,t:"Não penseis que vim trazer paz à terra; não vim trazer paz, mas espada.",n:"Não se anuncia uma guerra, mas a divisão que a fidelidade provoca — e os versos seguintes dizem onde: dentro de casa. A espada é a que separa, e a imagem vem do profeta Miqueias, citado quase palavra por palavra no versículo 36."},
{v:35,t:"Porque vim separar o homem de seu pai, a filha de sua mãe, e a nora de sua sogra;"},
{v:36,t:"e os inimigos do homem serão os da sua própria casa."},
{v:37,t:"Quem ama o pai ou a mãe mais do que a mim não é digno de mim; e quem ama o filho ou a filha mais do que a mim não é digno de mim."},
{v:38,t:"E quem não toma a sua cruz e não segue após mim não é digno de mim.",n:"Primeira menção da cruz nos evangelhos, muito antes da Paixão. Quem ouvia sabia o que era: o condenado carregava a viga até ao lugar do suplício, atravessando a cidade."},
{v:39,t:"Quem encontrar a sua vida a perderá; e quem perder a sua vida por causa de mim a encontrará."},
{v:40,t:"Quem vos recebe, a mim me recebe; e quem me recebe, recebe aquele que me enviou."},
{v:41,t:"Quem recebe um profeta na qualidade de profeta receberá recompensa de profeta; e quem recebe um justo na qualidade de justo receberá recompensa de justo."},
{v:42,t:"E quem der a um destes pequeninos ainda que seja um copo de água fresca, na qualidade de discípulo, em verdade vos digo: não perderá a sua recompensa."},
{p:"Mateus 11:1"},
{v:1,t:"E aconteceu que, tendo Jesus acabado de dar instruções aos seus doze discípulos, partiu dali para ensinar e pregar nas suas cidades."},
{p:"Marcos 6:7-13"},
{v:7,t:"E chamou os Doze e começou a enviá-los dois a dois, e deu-lhes poder sobre os espíritos imundos.",n:"Dois a dois: a lei exigia duas testemunhas para que um depoimento valesse. O envio aos pares não é companhia, é forma jurídica do testemunho."},
{v:8,t:"E ordenou-lhes que nada levassem para o caminho, senão apenas um bastão: nem pão, nem alforje, nem dinheiro no cinto;"},
{v:9,t:"mas que calçassem sandálias e não vestissem duas túnicas."},
{v:10,t:"E dizia-lhes: Em qualquer casa em que entrardes, ficai ali até partirdes daquele lugar."},
{v:11,t:"E, se algum lugar não vos receber nem vos ouvir, ao sairdes dali, sacudi o pó dos vossos pés, em testemunho contra eles."},
{v:12,t:"E, tendo partido, pregavam que se convertessem."},
{v:13,t:"Expulsavam muitos demônios, ungiam com óleo muitos doentes e os curavam.",n:"A unção dos doentes com óleo só aparece aqui e na Carta de São Tiago. É o gesto de que a Igreja fará um dos sacramentos."},
{p:"Lucas 9:1-6"},
{v:1,t:"Tendo convocado os Doze, deu-lhes poder e autoridade sobre todos os demônios e para curar doenças."},
{v:2,t:"E enviou-os a pregar o Reino de Deus e a curar os enfermos."},
{v:3,t:"E disse-lhes: Nada leveis para o caminho: nem bastão, nem alforje, nem pão, nem dinheiro; nem tenhais duas túnicas."},
{v:4,t:"Em qualquer casa em que entrardes, ficai ali e de lá parti."},
{v:5,t:"E, onde não vos receberem, ao sairdes daquela cidade, sacudi o pó dos vossos pés, em testemunho contra eles."},
{v:6,t:"Partindo, percorriam as aldeias, anunciando o Evangelho e curando por toda parte."}
];

EV[87] = [
{p:"Mateus 13:53-58"},
{v:53,t:"E aconteceu que, tendo Jesus acabado estas parábolas, retirou-se dali."},
{v:54,t:"E, vindo à sua pátria, ensinava-os na sinagoga deles, de tal modo que se admiravam e diziam: Donde lhe vêm esta sabedoria e estes prodígios?"},
{v:55,t:"Não é este o filho do carpinteiro? Não se chama sua mãe Maria, e seus irmãos Tiago, José, Simão e Judas?",n:"Carpinteiro traduz tekton, o artesão que trabalha a madeira e também a pedra — numa aldeia de casas de pedra, o ofício abrangia as duas coisas."},
{v:56,t:"E não estão entre nós todas as suas irmãs? Donde lhe vem, então, tudo isso?"},
{v:57,t:"E escandalizavam-se nele. Mas Jesus lhes disse: Um profeta não fica sem honra senão na sua pátria e na sua casa.",n:"O escândalo nasce do que sabem, e não do que ignoram: conhecem a família, a casa, o ofício. A familiaridade, aqui, é o obstáculo."},
{v:58,t:"E não fez ali muitos milagres, por causa da incredulidade deles."},
{p:"Marcos 6:1-6"},
{v:1,t:"Saindo dali, foi para a sua pátria; e os seus discípulos o seguiam."},
{v:2,t:"Chegado o sábado, começou a ensinar na sinagoga; e muitos, ao ouvi-lo, admiravam-se e diziam: Donde lhe vem tudo isso? E que sabedoria é esta que lhe foi dada, e os prodígios que se fazem por suas mãos?"},
{v:3,t:"Não é este o carpinteiro, filho de Maria, e irmão de Tiago, José, Judas e Simão? E não estão aqui entre nós as suas irmãs? E escandalizavam-se nele.",n:"São Marcos escreve o carpinteiro, filho de Maria; São Mateus, o filho do carpinteiro. Chamar alguém pelo nome da mãe, e não pelo do pai, era incomum e podia ser injurioso — o que combina com o tom da cena."},
{v:4,t:"E Jesus lhes dizia: Um profeta não fica sem honra senão na sua pátria, entre os seus parentes e em sua casa."},
{v:5,t:"E não podia fazer ali nenhum milagre; apenas curou uns poucos doentes, impondo-lhes as mãos.",n:"Não podia é a formulação mais ousada dos evangelhos, e São Mateus abranda-a para não fez. Marcos deixa-a como está: a incredulidade não limita o poder de Deus, mas fecha a porta por onde ele entrava."},
{v:6,t:"E admirava-se da incredulidade deles. E percorria as aldeias em redor, ensinando."}
];

EV[88] = [
{p:"Mateus 14:1-12"},
{v:1,t:"Naquele tempo, Herodes, o tetrarca, ouviu a fama de Jesus"},
{v:2,t:"e disse aos seus servos: Este é João Batista; ele ressuscitou dos mortos, e por isso operam nele os poderes miraculosos.",n:"Herodes Antipas, filho de Herodes o Grande, governava a Galileia e a Pereia. Tetrarca quer dizer, à letra, senhor de uma quarta parte: o reino do pai fora repartido entre os filhos, e nenhum deles teve o título de rei, embora o povo lhes desse esse nome."},
{v:3,t:"Porque Herodes tinha mandado prender João, e o tinha atado e posto na prisão, por causa de Herodíades, mulher de seu irmão Filipe."},
{v:4,t:"Pois João lhe dizia: Não te é lícito tê-la.",n:"A lei do Levítico proibia casar com a mulher do irmão vivo. João não acusa de adultério: invoca a lei, e é por isso que o caso é público."},
{v:5,t:"E, querendo matá-lo, temeu o povo, porque o tinham por profeta."},
{v:6,t:"Ora, celebrando-se o aniversário de Herodes, a filha de Herodíades dançou no meio dos convidados e agradou a Herodes."},
{v:7,t:"Por isso prometeu, com juramento, dar-lhe o que ela pedisse."},
{v:8,t:"E ela, instigada por sua mãe, disse: Dá-me aqui, num prato, a cabeça de João Batista."},
{v:9,t:"O rei entristeceu-se; mas, por causa do juramento e dos que estavam à mesa, mandou que a dessem.",n:"O motivo dado é a vergonha diante dos convidados. Um juramento para cometer um crime não obriga, e Herodes sabia-o; mata para não desdizer-se em público."},
{v:10,t:"E mandou decapitar João no cárcere."},
{v:11,t:"E a sua cabeça foi trazida num prato e dada à jovem, e ela a levou a sua mãe."},
{v:12,t:"Vieram os seus discípulos, levaram o corpo e o sepultaram; e foram anunciá-lo a Jesus."},
{p:"Marcos 6:14-29"},
{v:14,t:"O rei Herodes ouviu falar dele, porque o seu nome se tornara célebre, e diziam: João Batista ressuscitou dos mortos, e por isso operam nele os poderes miraculosos."},
{v:15,t:"Outros diziam: É Elias. E outros: É um profeta, como um dos profetas."},
{v:16,t:"Herodes, ouvindo isso, dizia: É João, a quem mandei decapitar: ele ressuscitou."},
{v:17,t:"Pois o próprio Herodes mandara prender João e o atara no cárcere, por causa de Herodíades, mulher de seu irmão Filipe, com quem se casara."},
{v:18,t:"Porque João dizia a Herodes: Não te é lícito ter a mulher de teu irmão."},
{v:19,t:"Herodíades odiava-o e queria matá-lo, mas não podia,"},
{v:20,t:"porque Herodes temia João, sabendo que era homem justo e santo, e o protegia; e, ao ouvi-lo, ficava muito perplexo, mas o ouvia de boa vontade.",n:"O retrato é dos mais finos dos evangelhos: um homem que sabe de que lado está a verdade, gosta de a ouvir, protege quem a diz — e acaba por mandar matá-lo, por não suportar o constrangimento de uma sala."},
{v:21,t:"Chegou, porém, um dia favorável, quando Herodes, no seu aniversário, ofereceu um banquete aos seus grandes, aos tribunos e aos principais da Galileia."},
{v:22,t:"Tendo entrado a filha da mesma Herodíades e tendo dançado, agradou a Herodes e aos convidados. Disse o rei à jovem: Pede-me o que quiseres, e eu te darei."},
{v:23,t:"E jurou-lhe: Tudo o que me pedires te darei, ainda que seja metade do meu reino.",n:"A promessa é a de Assuero a Ester, no livro daquele nome. Herodes fala como um rei de história antiga — e nem sequer tinha o título de rei nem poder para dispor de metade de coisa alguma."},
{v:24,t:"Ela saiu e disse a sua mãe: Que hei de pedir? E esta respondeu: A cabeça de João Batista."},
{v:25,t:"Entrando logo, apressada, junto ao rei, pediu, dizendo: Quero que me dês agora, num prato, a cabeça de João Batista."},
{v:26,t:"O rei entristeceu-se muito; mas, por causa do juramento e dos convidados, não quis desagradá-la."},
{v:27,t:"E logo o rei enviou um guarda, ordenando que trouxesse a cabeça de João. Ele foi, decapitou-o no cárcere,"},
{v:28,t:"trouxe a sua cabeça num prato e a deu à jovem; e a jovem a deu a sua mãe."},
{v:29,t:"Ouvindo isso, os seus discípulos vieram, levaram o seu corpo e o puseram num sepulcro.",n:"São Marcos conta a morte de João com as palavras com que há de contar a de Jesus: um poderoso que não queria matar, cede à pressão dos presentes; discípulos que vêm, levam o corpo e o põem num sepulcro."},
{p:"Lucas 9:7-9"},
{v:7,t:"Ora, Herodes, o tetrarca, ouviu falar de tudo o que se fazia, e estava perplexo, porque alguns diziam que João ressuscitara dos mortos;"},
{v:8,t:"outros, que Elias aparecera; e outros, que um dos antigos profetas ressuscitara."},
{v:9,t:"E disse Herodes: A João eu mandei decapitar; quem é, pois, este, de quem ouço tais coisas? E procurava vê-lo.",n:"São Lucas guarda esta curiosidade para o dia da Paixão, quando Pilatos lhe envia Jesus e Herodes finalmente o vê — e não obtém dele uma palavra."}
];

EV[89] = [
{p:"Mateus 14:13-21"},
{v:13,t:"Ouvindo isso, Jesus retirou-se dali de barco, para um lugar deserto, à parte; e as multidões, sabendo-o, seguiram-no a pé, saindo das cidades.",n:"É o único milagre contado pelos quatro evangelhos, e São Marcos e São Mateus contam-no duas vezes, com números diferentes. Nenhum outro episódio da vida pública recebeu tanta atenção."},
{v:14,t:"Ao desembarcar, viu uma grande multidão, compadeceu-se deles e curou os seus enfermos."},
{v:15,t:"Chegada a tarde, aproximaram-se dele os discípulos, dizendo: O lugar é deserto e a hora já passou; despede as multidões, para que vão às aldeias comprar comida."},
{v:16,t:"Mas Jesus lhes disse: Não precisam de ir; dai-lhes vós de comer."},
{v:17,t:"Eles responderam: Não temos aqui senão cinco pães e dois peixes."},
{v:18,t:"E ele disse: Trazei-os aqui a mim."},
{v:19,t:"E, tendo mandado que as multidões se sentassem sobre a relva, tomou os cinco pães e os dois peixes e, levantando os olhos ao céu, abençoou, partiu os pães e deu-os aos discípulos; e os discípulos, às multidões.",n:"Tomar, levantar os olhos, abençoar, partir e dar: os cinco gestos vão repetir-se, palavra por palavra, na última ceia. Os evangelistas escrevem a cena do deserto com o vocabulário da Eucaristia."},
{v:20,t:"E todos comeram e se fartaram; e recolheram os pedaços que sobraram, doze cestos cheios.",n:"Doze cestos, como as doze tribos: o que sobra não é desperdício, é medida. O milagre não dá o suficiente, dá em excesso."},
{v:21,t:"Ora, os que comeram eram cerca de cinco mil homens, sem contar mulheres e crianças."},
{p:"Marcos 6:30-44"},
{v:30,t:"Os apóstolos reuniram-se com Jesus e contaram-lhe tudo o que tinham feito e ensinado."},
{v:31,t:"E ele lhes disse: Vinde vós, à parte, para um lugar deserto, e descansai um pouco. Porque eram muitos os que vinham e iam, e nem tinham tempo de comer."},
{v:32,t:"E partiram de barco para um lugar deserto, à parte."},
{v:33,t:"Muitos os viram partir e reconheceram-nos; e de todas as cidades correram a pé para lá e chegaram antes deles."},
{v:34,t:"Ao desembarcar, viu uma grande multidão e compadeceu-se deles, porque eram como ovelhas que não têm pastor; e começou a ensinar-lhes muitas coisas.",n:"Ovelhas sem pastor é a frase com que Moisés pede a Deus um sucessor, no livro dos Números, e com que Ezequiel acusa os chefes de Israel. E o primeiro remédio que se dá à fome da multidão é o ensino."},
{v:35,t:"Como já fosse tarde, aproximaram-se dele os seus discípulos, dizendo: O lugar é deserto e a hora já passou;"},
{v:36,t:"despede-os, para que vão aos campos e aldeias em redor comprar de comer."},
{v:37,t:"Mas ele lhes respondeu: Dai-lhes vós de comer. E disseram-lhe: Iremos comprar duzentos denários de pães e lhes daremos de comer?",n:"O denário era o salário de um dia. Duzentos denários equivaliam a mais de meio ano de trabalho, e a pergunta é irônica: mandar comprar é o mesmo que mandar não fazer nada."},
{v:38,t:"E ele lhes disse: Quantos pães tendes? Ide ver. Tendo-se informado, disseram: Cinco, e dois peixes."},
{v:39,t:"E ordenou-lhes que todos se sentassem em grupos sobre a relva verde."},
{v:40,t:"E sentaram-se em grupos de cem e de cinquenta.",n:"Cem e cinquenta são as divisões do povo no deserto, segundo o Êxodo e os Números. A multidão sentada na relva verde fica disposta como Israel no acampamento."},
{v:41,t:"E, tomando os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou e partiu os pães, e dava-os aos seus discípulos para que os pusessem diante deles; e repartiu entre todos os dois peixes."},
{v:42,t:"E todos comeram e se fartaram."},
{v:43,t:"E recolheram dos pedaços doze cestos cheios, e também dos peixes."},
{v:44,t:"Ora, os que comeram os pães eram cinco mil homens."},
{p:"Lucas 9:10-17"},
{v:10,t:"Ao voltarem, os apóstolos contaram-lhe tudo o que tinham feito. E, tomando-os consigo, retirou-se à parte para uma cidade chamada Betsaida."},
{v:11,t:"As multidões, sabendo-o, seguiram-no; e ele as recebeu, falava-lhes do Reino de Deus e curava os que precisavam de cura."},
{v:12,t:"O dia começava a declinar, e os Doze, aproximando-se, disseram-lhe: Despede a multidão, para que vão às aldeias e aos campos em redor buscar pousada e comida, porque aqui estamos num lugar deserto."},
{v:13,t:"Mas ele lhes disse: Dai-lhes vós de comer. E eles responderam: Não temos mais do que cinco pães e dois peixes, a não ser que vamos nós comprar comida para todo este povo."},
{v:14,t:"Pois eram cerca de cinco mil homens. E disse aos seus discípulos: Fazei-os sentar-se em grupos de cerca de cinquenta."},
{v:15,t:"Assim fizeram, e fizeram sentar-se a todos."},
{v:16,t:"E, tomando os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou-os, partiu-os e deu-os aos discípulos para que os pusessem diante da multidão."},
{v:17,t:"E todos comeram e se fartaram; e recolheram o que lhes sobrou: doze cestos de pedaços."},
{p:"João 6:1-14"},
{v:1,t:"Depois disso, Jesus passou para a outra margem do mar da Galileia, que é o de Tiberíades."},
{v:2,t:"E grande multidão o seguia, porque via os sinais que fazia sobre os enfermos."},
{v:3,t:"Jesus subiu ao monte e ali se sentou com os seus discípulos."},
{v:4,t:"Estava próxima a Páscoa, a festa dos judeus.",n:"São João é o único que situa o episódio às portas da Páscoa, e é essa nota que prepara todo o discurso do capítulo: fala-se de pão sem fermento, de êxodo e de cordeiro antes de se dizer uma palavra."},
{v:5,t:"Tendo Jesus levantado os olhos e visto que grande multidão vinha a ele, disse a Filipe: Onde compraremos pães para que estes comam?"},
{v:6,t:"Dizia isso para o pôr à prova, pois ele bem sabia o que ia fazer."},
{v:7,t:"Respondeu-lhe Filipe: Duzentos denários de pães não lhes bastam, para que cada um receba um pouco."},
{v:8,t:"Disse-lhe um dos seus discípulos, André, irmão de Simão Pedro:"},
{v:9,t:"Está aqui um menino que tem cinco pães de cevada e dois peixes; mas que é isso para tantos?",n:"Pão de cevada era o pão dos pobres, de metade do preço do de trigo. Só São João o diz — e só ele conta que os pães eram de um menino."},
{v:10,t:"Disse Jesus: Fazei sentar-se os homens. Havia muita relva naquele lugar. Sentaram-se, pois, os homens, em número de cerca de cinco mil."},
{v:11,t:"Jesus tomou os pães e, tendo dado graças, distribuiu-os aos que estavam sentados; e igualmente dos peixes, quanto queriam.",n:"Tendo dado graças verte eucharistesas. É a palavra donde vem Eucaristia, e São João emprega-a aqui, onde os outros escrevem abençoou."},
{v:12,t:"Quando ficaram saciados, disse aos seus discípulos: Recolhei os pedaços que sobraram, para que nada se perca."},
{v:13,t:"Recolheram-nos, pois, e encheram doze cestos com os pedaços dos cinco pães de cevada que sobraram aos que tinham comido."},
{v:14,t:"Vendo os homens o sinal que fizera, diziam: Este é verdadeiramente o profeta que há de vir ao mundo.",n:"O profeta que há de vir é o do Deuteronômio 18, semelhante a Moisés. Quem acabara de receber pão no deserto reconhece naturalmente o novo Moisés — e é justamente esse reconhecimento que o verso seguinte mostra ser perigoso."}
];

EV[90] = [
{p:"Mateus 14:22-36"},
{v:22,t:"E logo obrigou os discípulos a entrar no barco e a passar antes dele para a outra margem, enquanto despedia as multidões."},
{v:23,t:"Tendo despedido as multidões, subiu ao monte, à parte, para orar. Chegada a noite, estava ali sozinho."},
{v:24,t:"O barco já estava a muitos estádios da terra, açoitado pelas ondas, porque o vento era contrário."},
{v:25,t:"Na quarta vigília da noite, veio ter com eles, caminhando sobre o mar.",n:"A quarta vigília vai das três da madrugada às seis: a hora mais escura, imediatamente antes do amanhecer. Os romanos dividiam a noite em quatro vigílias; os judeus, em três."},
{v:26,t:"Os discípulos, vendo-o caminhar sobre o mar, perturbaram-se e diziam: É um fantasma. E de medo gritaram."},
{v:27,t:"Mas logo Jesus lhes falou, dizendo: Tende confiança; sou eu, não temais.",n:"Sou eu traduz ego eimi — as mesmas palavras com que Deus se nomeia a Moisés na sarça e com que fala em Isaías. Em grego servem também para dizer simplesmente sou eu; os evangelhos usam a coincidência, e não a explicam."},
{v:28,t:"Pedro respondeu-lhe: Senhor, se és tu, manda-me ir ter contigo sobre as águas."},
{v:29,t:"E ele disse: Vem. E Pedro, descendo do barco, caminhou sobre as águas e foi ter com Jesus."},
{v:30,t:"Mas, vendo a força do vento, teve medo e, começando a afundar, gritou: Senhor, salva-me!"},
{v:31,t:"E logo Jesus, estendendo a mão, segurou-o e lhe disse: Homem de pouca fé, por que duvidaste?",n:"O episódio de Pedro sobre as águas só existe em São Mateus. A censura não é por ter descido do barco, mas por ter olhado para o vento depois de descer."},
{v:32,t:"E, tendo subido ao barco, o vento cessou."},
{v:33,t:"Os que estavam no barco prostraram-se diante dele, dizendo: Verdadeiramente tu és o Filho de Deus."},
{v:34,t:"E, tendo feito a travessia, chegaram à terra de Genesaré."},
{v:35,t:"Reconhecendo-o os homens daquele lugar, mandaram avisar toda aquela região e trouxeram-lhe todos os doentes;"},
{v:36,t:"e suplicavam-lhe que pudessem tocar ao menos a orla do seu manto; e todos os que tocaram ficaram curados."},
{p:"Marcos 6:45-56"},
{v:45,t:"E logo obrigou os seus discípulos a entrar no barco e a passar adiante para a outra margem, rumo a Betsaida, enquanto ele despedia a multidão."},
{v:46,t:"E, tendo-se despedido deles, foi ao monte orar."},
{v:47,t:"Chegada a tarde, o barco estava no meio do mar, e ele, sozinho, em terra."},
{v:48,t:"Vendo-os em dificuldade ao remar, pois o vento lhes era contrário, veio ter com eles, pela quarta vigília da noite, caminhando sobre o mar; e queria passar adiante deles.",n:"Queria passar adiante deles desconcerta quem lê, mas é linguagem do Êxodo e dos Reis: é o que Deus faz diante de Moisés na fenda da rocha e diante de Elias no Horeb. Passar adiante é o modo de se mostrar, não de se afastar."},
{v:49,t:"Eles, porém, vendo-o caminhar sobre o mar, pensaram que era um fantasma e gritaram."},
{v:50,t:"Pois todos o viram e ficaram perturbados. Mas ele logo lhes falou e disse: Tende confiança; sou eu, não temais."},
{v:51,t:"E subiu com eles para o barco, e o vento cessou; e ficaram sobremaneira atônitos entre si,"},
{v:52,t:"porque não tinham compreendido o dos pães: o seu coração estava endurecido.",n:"Coração endurecido é, no Êxodo, o que se diz do faraó. São Marcos aplica-o aos discípulos — e é ele quem menos os poupa de todos os evangelistas."},
{v:53,t:"E, tendo feito a travessia, chegaram à terra de Genesaré e atracaram."},
{v:54,t:"Ao saírem do barco, logo o reconheceram;"},
{v:55,t:"e, percorrendo toda aquela região, começaram a trazer em macas os doentes, para onde ouviam dizer que ele estava."},
{v:56,t:"E, onde quer que entrasse — aldeias, cidades ou campos —, punham os enfermos nas praças e suplicavam-lhe que tocassem ao menos a orla do seu manto; e todos os que tocavam ficavam curados."},
{p:"João 6:15-24"},
{v:15,t:"Sabendo Jesus que estavam para vir arrebatá-lo, a fim de o fazer rei, retirou-se de novo, sozinho, para o monte.",n:"É a única vez que os evangelhos dizem que quiseram fazê-lo rei, e a resposta é a fuga. O que a multidão concluiu do pão é exatamente o que ele recusa."},
{v:16,t:"Chegada a tarde, os seus discípulos desceram ao mar"},
{v:17,t:"e, tendo entrado num barco, atravessavam o mar rumo a Cafarnaum. Já se fizera escuro, e Jesus ainda não viera a eles."},
{v:18,t:"E o mar levantava-se, porque soprava um vento forte."},
{v:19,t:"Tendo remado uns vinte e cinco ou trinta estádios, veem Jesus caminhando sobre o mar e aproximando-se do barco; e tiveram medo."},
{v:20,t:"Mas ele lhes disse: Sou eu, não temais."},
{v:21,t:"Quiseram então recebê-lo no barco, e logo o barco chegou à terra para onde iam."},
{v:22,t:"No dia seguinte, a multidão que ficara do outro lado do mar viu que ali não havia senão um barco, e que Jesus não entrara nele com os seus discípulos, mas que só os discípulos tinham partido."},
{v:23,t:"Vieram, porém, outros barcos de Tiberíades para perto do lugar onde tinham comido o pão, depois de o Senhor ter dado graças."},
{v:24,t:"Quando, pois, a multidão viu que Jesus não estava ali, nem os seus discípulos, entraram nos barcos e foram a Cafarnaum, à procura de Jesus."}
];

EV[91] = [
{p:"João 6:25-71"},
{v:25,t:"E, tendo-o encontrado na outra margem do mar, disseram-lhe: Rabi, quando chegaste aqui?",n:"Começa aqui o discurso do Pão da Vida, construído como uma homilia de sinagoga sobre o texto citado no versículo 31: primeiro explica-se pão do céu, depois dar a comer. É o mais longo discurso de São João fora da última ceia, e o que custou mais discípulos."},
{v:26,t:"Jesus lhes respondeu: Em verdade, em verdade vos digo: buscais-me não porque vistes sinais, mas porque comestes dos pães e ficastes saciados."},
{v:27,t:"Trabalhai, não pela comida que perece, mas pela que permanece para a vida eterna, a qual o Filho do Homem vos dará; porque a este o Pai, Deus, marcou com o seu selo."},
{v:28,t:"Disseram-lhe então: Que havemos de fazer para realizar as obras de Deus?"},
{v:29,t:"Jesus lhes respondeu: A obra de Deus é esta: que creiais naquele que ele enviou.",n:"Perguntam por obras, no plural, e a resposta vem no singular: uma só obra, e ela não é fazer, é crer. São Paulo dirá a mesma coisa com outras palavras."},
{v:30,t:"Disseram-lhe então: Que sinal fazes tu, para que o vejamos e creiamos em ti? Que obra realizas?"},
{v:31,t:"Nossos pais comeram o maná no deserto, conforme está escrito: Deu-lhes a comer pão do céu.",n:"Pedem um sinal no dia seguinte ao de terem comido de cinco pães. A citação é do Salmo 78, e a tradição judaica esperava que o Messias repetisse o maná — o que explica a exigência: um pão só não basta, seria preciso quarenta anos."},
{v:32,t:"Jesus lhes disse: Em verdade, em verdade vos digo: não foi Moisés que vos deu o pão do céu, mas é meu Pai que vos dá o verdadeiro pão do céu."},
{v:33,t:"Porque o pão de Deus é aquele que desce do céu e dá vida ao mundo."},
{v:34,t:"Disseram-lhe então: Senhor, dá-nos sempre desse pão."},
{v:35,t:"Jesus lhes disse: Eu sou o pão da vida; quem vem a mim não terá fome, e quem crê em mim jamais terá sede.",n:"Primeira das sete declarações eu sou com predicado no quarto evangelho. O pedido do versículo anterior repete o da samaritana — dá-me sempre dessa água —, e a resposta é a mesma: o dom não é uma coisa, é ele."},
{v:36,t:"Mas eu vos disse: vistes-me, e não credes."},
{v:37,t:"Tudo o que o Pai me dá virá a mim; e o que vem a mim eu não lançarei fora,"},
{v:38,t:"porque desci do céu não para fazer a minha vontade, mas a vontade daquele que me enviou."},
{v:39,t:"E esta é a vontade daquele que me enviou: que eu não perca nada de tudo o que me deu, mas que o ressuscite no último dia."},
{v:40,t:"Porque esta é a vontade de meu Pai: que todo aquele que vê o Filho e nele crê tenha a vida eterna; e eu o ressuscitarei no último dia."},
{v:41,t:"Murmuravam, pois, dele os judeus, porque dissera: Eu sou o pão que desceu do céu.",n:"Murmuravam é o verbo que o Êxodo usa para o povo no deserto, diante do próprio maná. A geração que come o pão do céu murmura das duas vezes."},
{v:42,t:"E diziam: Não é este Jesus, o filho de José, cujo pai e mãe conhecemos? Como diz ele agora: Desci do céu?"},
{v:43,t:"Jesus lhes respondeu: Não murmureis entre vós."},
{v:44,t:"Ninguém pode vir a mim se o Pai, que me enviou, não o atrair; e eu o ressuscitarei no último dia.",n:"Atrair verte helkyo, verbo que se usa para puxar uma rede ou uma espada da bainha: diz força, não persuasão. E o mesmo verbo volta no capítulo 12, quando diz que, levantado da terra, atrairá todos a si."},
{v:45,t:"Está escrito nos profetas: E serão todos ensinados por Deus. Todo aquele que ouviu o Pai e aprendeu vem a mim."},
{v:46,t:"Não que alguém tenha visto o Pai, senão aquele que vem de Deus: esse viu o Pai."},
{v:47,t:"Em verdade, em verdade vos digo: quem crê tem a vida eterna."},
{v:48,t:"Eu sou o pão da vida."},
{v:49,t:"Vossos pais comeram o maná no deserto, e morreram."},
{v:50,t:"Este é o pão que desce do céu, para que quem dele comer não morra."},
{v:51,t:"Eu sou o pão vivo que desceu do céu; se alguém comer deste pão, viverá para sempre; e o pão que eu darei é a minha carne, pela vida do mundo.",n:"Aqui o discurso vira. Até agora o pão era ele enquanto se crê nele; a partir deste versículo é a sua carne, e falará em comer e beber. Muitos intérpretes distinguem as duas partes, mas o texto não as separa, e a leitura da Igreja sempre as leu juntas."},
{v:52,t:"Discutiam, pois, os judeus entre si, dizendo: Como pode este dar-nos a comer a sua carne?"},
{v:53,t:"Jesus lhes disse: Em verdade, em verdade vos digo: se não comerdes a carne do Filho do Homem e não beberdes o seu sangue, não tereis a vida em vós.",n:"Para um judeu, a frase era duplamente intolerável: a lei proibia comer sangue sob pena de exclusão do povo. Jesus não abranda diante do escândalo — endurece, e é o que faz partir os discípulos."},
{v:54,t:"Quem come a minha carne e bebe o meu sangue tem a vida eterna, e eu o ressuscitarei no último dia.",n:"Do versículo 54 em diante, o verbo muda: já não é phago, comer, mas trogo, que diz mastigar, roer, e se usava dos animais. A escolha é deliberada e afasta qualquer leitura só figurada."},
{v:55,t:"Porque a minha carne é verdadeira comida, e o meu sangue é verdadeira bebida."},
{v:56,t:"Quem come a minha carne e bebe o meu sangue permanece em mim, e eu nele."},
{v:57,t:"Assim como o Pai que vive me enviou, e eu vivo pelo Pai, assim também quem me come viverá por mim."},
{v:58,t:"Este é o pão que desceu do céu; não como os pais comeram e morreram: quem come este pão viverá para sempre."},
{v:59,t:"Isto disse ele na sinagoga, ensinando em Cafarnaum."},
{v:60,t:"Muitos, pois, dos seus discípulos, ao ouvirem, disseram: Dura é esta palavra; quem a pode ouvir?",n:"Dura não quer dizer difícil de entender: quer dizer dura de aceitar. Tinham entendido bem, e é por isso que se vão embora."},
{v:61,t:"Sabendo Jesus em si mesmo que os seus discípulos murmuravam disso, disse-lhes: Isto vos escandaliza?"},
{v:62,t:"E se virdes o Filho do Homem subir para onde antes estava?"},
{v:63,t:"O espírito é que vivifica; a carne de nada aproveita. As palavras que eu vos disse são espírito e são vida.",n:"A carne de nada aproveita não desdiz o que ficou dito da sua carne: carne, aqui, é a condição humana deixada a si mesma, como em todo o quarto evangelho. Sem o Espírito, comer aquela carne não aproveitaria — é o que se diz, e não o contrário."},
{v:64,t:"Mas há entre vós alguns que não creem. Porque Jesus sabia desde o princípio quais eram os que não criam e quem havia de entregá-lo."},
{v:65,t:"E dizia: Por isso vos disse que ninguém pode vir a mim se não lhe for concedido pelo Pai."},
{v:66,t:"Desde então, muitos dos seus discípulos voltaram atrás e já não andavam com ele.",n:"É a única defecção em massa que os evangelhos registram, e não vem de uma exigência moral nem de uma perseguição: vem de uma doutrina. Jesus deixa-os ir sem corrigir uma palavra."},
{v:67,t:"Disse, pois, Jesus aos Doze: Quereis vós também retirar-vos?"},
{v:68,t:"Respondeu-lhe Simão Pedro: Senhor, a quem iremos? Tu tens palavras de vida eterna;",n:"A resposta não é entendi: é não há para onde ir. A fé de Pedro afirma-se aqui sem compreender, e é a primeira confissão do quarto evangelho."},
{v:69,t:"e nós cremos e conhecemos que tu és o Santo de Deus."},
{v:70,t:"Jesus lhes respondeu: Não vos escolhi eu, os Doze? E um de vós é um diabo."},
{v:71,t:"Falava de Judas, filho de Simão Iscariotes; pois era este que o havia de entregar, sendo um dos Doze."},
{p:"João 7:1"},
{v:1,t:"Depois disso, Jesus andava pela Galileia; não queria andar pela Judeia, porque os judeus procuravam matá-lo."}
];

EV[92] = [
{p:"Mateus 15:1-20"},
{v:1,t:"Então aproximaram-se de Jesus escribas e fariseus vindos de Jerusalém, dizendo:"},
{v:2,t:"Por que os teus discípulos transgridem a tradição dos antigos? Pois não lavam as mãos quando comem pão.",n:"A lavagem antes de comer não era preceito da lei escrita, mas da tradição oral dos mestres. A discussão não é de higiene: é sobre o que obriga em consciência."},
{v:3,t:"Ele lhes respondeu: E vós, por que transgredis o mandamento de Deus por causa da vossa tradição?"},
{v:4,t:"Porque Deus disse: Honra o pai e a mãe; e: Quem amaldiçoar o pai ou a mãe seja punido de morte."},
{v:5,t:"Vós, porém, dizeis: Quem disser ao pai ou à mãe: É oferta ao templo aquilo com que eu te poderia socorrer,"},
{v:6,t:"esse não precisa honrar o seu pai. E assim anulastes a palavra de Deus por causa da vossa tradição.",n:"O caso é concreto e devastador: declarando consagrado ao templo o que devia ao sustento dos pais, o filho ficava dispensado de os socorrer — e cumpria a letra de um voto para quebrar um mandamento."},
{v:7,t:"Hipócritas! Bem profetizou de vós Isaías, dizendo:"},
{v:8,t:"Este povo honra-me com os lábios, mas o seu coração está longe de mim."},
{v:9,t:"Em vão me prestam culto, ensinando doutrinas que são preceitos de homens."},
{v:10,t:"E, tendo chamado a si a multidão, disse-lhes: Ouvi e entendei."},
{v:11,t:"Não é o que entra pela boca que torna o homem impuro; mas o que sai da boca, isso é que torna o homem impuro."},
{v:12,t:"Então, aproximando-se os discípulos, disseram-lhe: Sabes que os fariseus se escandalizaram ao ouvir essa palavra?"},
{v:13,t:"Ele respondeu: Toda planta que meu Pai celeste não plantou será arrancada."},
{v:14,t:"Deixai-os: são cegos que guiam cegos. E, se um cego guiar outro cego, ambos cairão na cova."},
{v:15,t:"Pedro lhe disse: Explica-nos essa parábola."},
{v:16,t:"Ele disse: Também vós estais ainda sem entendimento?"},
{v:17,t:"Não compreendeis que tudo o que entra pela boca desce ao ventre e é lançado fora?"},
{v:18,t:"Mas o que sai da boca vem do coração, e isso é que torna o homem impuro."},
{v:19,t:"Porque do coração saem os maus pensamentos, homicídios, adultérios, fornicações, furtos, falsos testemunhos, blasfêmias."},
{v:20,t:"São estas as coisas que tornam o homem impuro; mas comer sem lavar as mãos não torna o homem impuro."},
{p:"Marcos 7:1-23"},
{v:1,t:"Reuniram-se junto dele os fariseus e alguns dos escribas, vindos de Jerusalém."},
{v:2,t:"E, vendo que alguns dos seus discípulos comiam pão com as mãos impuras, isto é, não lavadas —"},
{v:3,t:"pois os fariseus e todos os judeus não comem sem lavar cuidadosamente as mãos, guardando a tradição dos antigos;",n:"Os versículos 3 e 4 são um parêntese explicativo para leitores que não eram judeus e não conheciam o costume. São Marcos escreve para Roma, e é por isso que precisa de o explicar."},
{v:4,t:"e, ao voltarem da praça, não comem sem se aspergirem; e há muitas outras coisas que receberam para guardar: lavagens de copos, jarros e vasilhas de bronze —"},
{v:5,t:"perguntaram-lhe, pois, os fariseus e os escribas: Por que os teus discípulos não andam segundo a tradição dos antigos, mas comem pão com as mãos impuras?"},
{v:6,t:"Ele lhes disse: Bem profetizou Isaías a vosso respeito, hipócritas, como está escrito: Este povo honra-me com os lábios, mas o seu coração está longe de mim."},
{v:7,t:"Em vão me prestam culto, ensinando doutrinas que são preceitos de homens."},
{v:8,t:"Abandonando o mandamento de Deus, guardais a tradição dos homens."},
{v:9,t:"E dizia-lhes: Bem sabeis anular o mandamento de Deus para guardardes a vossa tradição."},
{v:10,t:"Pois Moisés disse: Honra o teu pai e a tua mãe; e: Quem amaldiçoar o pai ou a mãe seja punido de morte."},
{v:11,t:"Vós, porém, dizeis: Se alguém disser ao pai ou à mãe: É corbã, isto é, oferta, aquilo com que eu te poderia socorrer,",n:"Corbã é palavra hebraica que o próprio texto traduz, como faz sempre São Marcos. Designava o que se consagrava ao templo e ficava, por isso, fora do uso comum."},
{v:12,t:"já não o deixais fazer nada pelo pai ou pela mãe,"},
{v:13,t:"anulando a palavra de Deus pela vossa tradição, que vós transmitistes; e fazeis muitas outras coisas semelhantes."},
{v:14,t:"E, tendo chamado de novo a multidão, dizia-lhes: Ouvi-me todos e entendei."},
{v:15,t:"Nada há fora do homem que, entrando nele, o possa tornar impuro; mas o que sai do homem, isso é que torna o homem impuro.",n:"Alguns manuscritos acrescentam aqui um versículo 16 — se alguém tem ouvidos para ouvir, ouça —, que falta nos mais antigos. A Nova Vulgata omite-o, e a numeração salta do 15 ao 17."},
{v:17,t:"Quando entrou em casa, longe da multidão, os seus discípulos o interrogavam sobre a parábola."},
{v:18,t:"E disse-lhes: Também vós estais assim sem entendimento? Não compreendeis que tudo o que de fora entra no homem não o pode tornar impuro,"},
{v:19,t:"porque não entra no seu coração, mas no ventre, e sai para a latrina? Assim declarava puros todos os alimentos.",n:"A última frase é comentário do evangelista, não palavra de Jesus, e é das mais consequentes do Novo Testamento: nela se apoia a decisão de não impor as leis alimentares aos convertidos vindos do paganismo. São Marcos tira a conclusão que os Atos dos Apóstolos e São Paulo haviam de discutir durante anos."},
{v:20,t:"E dizia: O que sai do homem, isso é que torna o homem impuro."},
{v:21,t:"Porque de dentro, do coração dos homens, saem os maus pensamentos, fornicações, furtos, homicídios,"},
{v:22,t:"adultérios, cobiças, maldades, dolo, libertinagem, inveja, blasfêmia, soberba, insensatez."},
{v:23,t:"Todos esses males saem de dentro e tornam o homem impuro."}
];

EV[93] = [
{p:"Mateus 15:21-28"},
{v:21,t:"E, saindo dali, Jesus retirou-se para as regiões de Tiro e Sidônia.",n:"É a única vez que Jesus sai de território judaico. Tiro e Sidônia são as cidades que ele próprio nomeara, no tópico 85, como exemplo de povos pagãos que se teriam convertido."},
{v:22,t:"E eis que uma mulher cananeia, vinda daquelas regiões, gritava, dizendo: Tem piedade de mim, Senhor, Filho de Davi! Minha filha está gravemente atormentada por um demônio.",n:"Cananeia é nome arcaico, tirado do Antigo Testamento: designa o povo que Israel devia expulsar da terra. São Mateus escolhe-o de propósito, para que o leitor sinta toda a distância que o episódio vai atravessar."},
{v:23,t:"Mas ele não lhe respondeu palavra. E, aproximando-se, os seus discípulos lhe rogavam, dizendo: Despede-a, porque vem gritando atrás de nós."},
{v:24,t:"Ele respondeu: Não fui enviado senão às ovelhas perdidas da casa de Israel."},
{v:25,t:"Ela, porém, veio, prostrou-se diante dele e disse: Senhor, socorre-me!"},
{v:26,t:"Ele respondeu: Não é bom tomar o pão dos filhos e lançá-lo aos cachorrinhos.",n:"Cachorrinhos verte kynaria, diminutivo: não é o cão de rua, é o que vive dentro de casa. O diminutivo abranda a dureza da frase e é justamente o que dá à mulher a brecha por onde há de responder."},
{v:27,t:"E ela disse: Sim, Senhor; mas também os cachorrinhos comem das migalhas que caem da mesa dos seus donos."},
{v:28,t:"Então Jesus lhe respondeu: Ó mulher, grande é a tua fé; faça-se contigo como queres. E desde aquela hora a sua filha ficou curada.",n:"É a única pessoa nos evangelhos que ganha uma discussão com Jesus — e ganha-a aceitando o lugar que lhe foi dado e tirando dele a consequência. Só a ela e ao centurião se elogia a fé com a palavra grande."},
{p:"Marcos 7:24-30"},
{v:24,t:"Levantando-se dali, foi para as regiões de Tiro. E, entrando numa casa, não queria que ninguém o soubesse; mas não pôde ficar escondido."},
{v:25,t:"Pelo contrário, logo que ouviu falar dele uma mulher cuja filhinha tinha um espírito imundo, veio e prostrou-se a seus pés."},
{v:26,t:"A mulher era grega, siro-fenícia de nascimento; e rogava-lhe que expulsasse o demônio da sua filha.",n:"Onde São Mateus escreve cananeia, com o nome antigo do adversário, São Marcos dá a identidade civil da época: grega de cultura, siro-fenícia de origem. Os dois dizem a mesma distância por vocabulários diferentes."},
{v:27,t:"E ele lhe dizia: Deixa primeiro que se fartem os filhos, pois não é bom tomar o pão dos filhos e lançá-lo aos cachorrinhos.",n:"Primeiro: a palavra que São Marcos acrescenta muda tudo. Não se diz que os cachorrinhos não comerão, mas que os filhos comem antes — e é uma ordem, não uma exclusão."},
{v:28,t:"Ela respondeu: Senhor, também os cachorrinhos, debaixo da mesa, comem das migalhas dos filhos."},
{v:29,t:"E ele lhe disse: Por causa desta palavra, vai; o demônio saiu da tua filha.",n:"Por causa desta palavra: em São Marcos, o que obtém a cura é o argumento, e não a fé — que ele nem chega a nomear. É o único milagre do segundo evangelho feito à distância."},
{v:30,t:"E, voltando para casa, encontrou a menina deitada na cama, e o demônio saído."}
];

EV[94] = [
{p:"Mateus 15:29-31"},
{v:29,t:"Partindo dali, Jesus veio para junto do mar da Galileia e, subindo ao monte, ali se sentou."},
{v:30,t:"E vieram a ele grandes multidões, trazendo consigo coxos, cegos, aleijados, mudos e muitos outros; e os puseram a seus pés, e ele os curou,"},
{v:31,t:"de modo que a multidão se admirava, ao ver os mudos falando, os aleijados sãos, os coxos andando e os cegos vendo; e glorificavam o Deus de Israel.",n:"Glorificavam o Deus de Israel: a fórmula é a que se usaria na boca de pagãos, e a cena passa-se ainda em território da Decápole. São Mateus assinala assim, sem o dizer, quem era aquela multidão."},
{p:"Marcos 7:31-37"},
{v:31,t:"E, deixando de novo as regiões de Tiro, veio por Sidônia ao mar da Galileia, atravessando a região da Decápole."},
{v:32,t:"E trouxeram-lhe um surdo que falava com dificuldade, e suplicavam-lhe que lhe impusesse a mão."},
{v:33,t:"E, tomando-o à parte, longe da multidão, pôs-lhe os dedos nos ouvidos e, cuspindo, tocou-lhe a língua.",n:"São Marcos é o único que conserva estes gestos, e não os explica. A saliva era tida como remédio na medicina antiga; o que o evangelho sublinha é que o surdo, que não podia ouvir palavra alguma, recebe tudo pelo tato."},
{v:34,t:"E, levantando os olhos ao céu, suspirou e disse: Éfeta — que quer dizer: Abre-te.",n:"Éfeta é aramaico, conservado como o talitá kum. A liturgia do batismo guardou-o durante séculos: o sacerdote tocava os ouvidos e a boca do batizando e dizia a mesma palavra."},
{v:35,t:"E logo se abriram os seus ouvidos, soltou-se o laço da sua língua e falava corretamente."},
{v:36,t:"E ordenou-lhes que a ninguém o dissessem; mas, quanto mais lhes ordenava, tanto mais o proclamavam."},
{v:37,t:"E, sobremaneira admirados, diziam: Tudo fez bem: faz ouvir os surdos e falar os mudos.",n:"Tudo fez bem é a frase do primeiro capítulo do Gênesis, no fim de cada dia da criação. E faz ouvir os surdos e falar os mudos é a promessa de Isaías 35. As duas juntas dizem, numa linha, quem a multidão pressente estar diante de si."}
];

EV[95] = [
{p:"Mateus 15:32-39"},
{v:32,t:"Jesus, tendo chamado os seus discípulos, disse: Tenho compaixão desta multidão, porque há já três dias que permanecem comigo e não têm o que comer; e não quero despedi-los em jejum, para que não desfaleçam no caminho.",n:"Segunda multiplicação, e esta em território pagão, do lado oriental do lago. Os números mudam: sete pães, sete cestos, quatro mil — onde a primeira tinha cinco, doze e cinco mil. Sete e quatro são, na simbólica bíblica, números da totalidade dos povos, como doze o é das tribos."},
{v:33,t:"Disseram-lhe os discípulos: Onde havemos de arranjar, num deserto, pães suficientes para saciar tão grande multidão?",n:"A pergunta é desconcertante, vindo de quem assistiu à primeira multiplicação. É também o motivo de muitos verem nas duas narrativas duas versões do mesmo episódio; os evangelistas, porém, conservam-nas separadas e fazem Jesus referir-se expressamente às duas, no tópico seguinte."},
{v:34,t:"E Jesus lhes disse: Quantos pães tendes? Eles responderam: Sete, e alguns peixinhos."},
{v:35,t:"Então mandou que a multidão se sentasse no chão."},
{v:36,t:"E, tomando os sete pães e os peixes, tendo dado graças, partiu-os e deu-os aos discípulos; e os discípulos, às multidões."},
{v:37,t:"E todos comeram e se fartaram; e do que sobrou dos pedaços recolheram sete cestos cheios."},
{v:38,t:"Ora, os que comeram eram quatro mil homens, sem contar mulheres e crianças."},
{v:39,t:"E, tendo despedido as multidões, entrou no barco e foi para as regiões de Magadã."},
{p:"Marcos 8:1-10"},
{v:1,t:"Naqueles dias, havendo de novo grande multidão, e não tendo o que comer, chamou os seus discípulos e disse-lhes:"},
{v:2,t:"Tenho compaixão desta multidão, porque há já três dias que permanecem comigo e não têm o que comer;"},
{v:3,t:"e, se os despedir em jejum para suas casas, desfalecerão no caminho; e alguns deles vieram de longe.",n:"Vieram de longe é, na linguagem dos profetas e de São Paulo, o modo de designar os que estão fora da aliança. A nota geográfica é também teológica."},
{v:4,t:"Os seus discípulos lhe responderam: Como poderá alguém saciá-los de pão, aqui, num deserto?"},
{v:5,t:"E perguntou-lhes: Quantos pães tendes? Eles disseram: Sete."},
{v:6,t:"E ordenou à multidão que se sentasse no chão. E, tomando os sete pães, tendo dado graças, partiu-os e dava-os aos seus discípulos para que os distribuíssem; e eles os distribuíram à multidão."},
{v:7,t:"Tinham também alguns peixinhos; e, tendo-os abençoado, mandou distribuí-los também."},
{v:8,t:"E comeram e se fartaram; e recolheram dos pedaços que sobraram sete cestos."},
{v:9,t:"Eram cerca de quatro mil; e os despediu."},
{v:10,t:"E logo, subindo ao barco com os seus discípulos, foi para as regiões de Dalmanuta."}
];

EV[96] = [
{p:"Mateus 16:1-12"},
{v:1,t:"Aproximaram-se dele os fariseus e os saduceus e, para o tentarem, pediram-lhe que lhes mostrasse um sinal do céu.",n:"Fariseus e saduceus juntos são, historicamente, uma aliança improvável: divergiam em quase tudo, da ressurreição à tradição oral. Só os une aqui o adversário comum."},
{v:2,t:"Mas ele lhes respondeu: Ao cair da tarde, dizeis: Vai fazer bom tempo, porque o céu está avermelhado."},
{v:3,t:"E, de manhã: Hoje haverá tempestade, porque o céu está avermelhado e sombrio. Sabeis discernir o aspecto do céu, mas não podeis discernir os sinais dos tempos."},
{v:4,t:"Uma geração má e adúltera pede um sinal, e nenhum sinal lhe será dado, senão o sinal de Jonas. E, deixando-os, partiu."},
{v:5,t:"Ao passarem para a outra margem, os discípulos esqueceram-se de levar pães."},
{v:6,t:"Jesus lhes disse: Olhai e acautelai-vos do fermento dos fariseus e dos saduceus.",n:"Fermento é, na Escritura, figura do que corrompe sem se ver: por isso se comia pão sem fermento na Páscoa. No tópico 77 o mesmo fermento servira de imagem do Reino — a figura vale nos dois sentidos, e o que importa é o que se esconde na massa."},
{v:7,t:"Eles discorriam entre si, dizendo: É porque não trouxemos pães."},
{v:8,t:"Sabendo-o, Jesus disse: Homens de pouca fé, por que discorreis entre vós que não tendes pães?"},
{v:9,t:"Ainda não compreendeis, nem vos lembrais dos cinco pães para os cinco mil, e de quantos cestos recolhestes?"},
{v:10,t:"Nem dos sete pães para os quatro mil, e de quantos cestos recolhestes?"},
{v:11,t:"Como não compreendeis que não foi de pães que vos falei? Acautelai-vos, sim, do fermento dos fariseus e dos saduceus."},
{v:12,t:"Então compreenderam que não dissera para se acautelarem do fermento dos pães, mas da doutrina dos fariseus e dos saduceus."},
{p:"Marcos 8:11-21"},
{v:11,t:"E saíram os fariseus e começaram a discutir com ele, pedindo-lhe um sinal do céu, para o tentarem."},
{v:12,t:"E ele, suspirando profundamente em seu espírito, disse: Por que esta geração pede um sinal? Em verdade vos digo: não será dado sinal a esta geração.",n:"São Marcos não abre exceção nenhuma: onde Mateus e Lucas ressalvam o sinal de Jonas, aqui a recusa é inteira. É a resposta mais seca dos evangelhos."},
{v:13,t:"E, deixando-os, subiu de novo ao barco e partiu para a outra margem."},
{v:14,t:"Os discípulos esqueceram-se de levar pães, e não tinham consigo no barco senão um pão.",n:"O pormenor do único pão é só de São Marcos, e fica sem explicação. Os antigos leram nele o próprio Jesus, que ia no barco com eles enquanto discutiam a falta de pão."},
{v:15,t:"E ele lhes ordenava, dizendo: Olhai e acautelai-vos do fermento dos fariseus e do fermento de Herodes."},
{v:16,t:"E discorriam entre si que não tinham pães."},
{v:17,t:"Sabendo-o, disse-lhes: Por que discorreis que não tendes pães? Ainda não entendeis nem compreendeis? Tendes o coração endurecido?"},
{v:18,t:"Tendo olhos, não vedes; e, tendo ouvidos, não ouvis? E não vos lembrais,",n:"A repreensão usa contra os discípulos as palavras que Isaías e Jeremias dirigiam ao povo endurecido, e as mesmas que, no tópico 77, explicavam por que os de fora não entendiam. A fronteira entre dentro e fora passa a correr dentro do grupo."},
{v:19,t:"quando parti os cinco pães para os cinco mil, quantos cestos cheios de pedaços recolhestes? Disseram-lhe: Doze."},
{v:20,t:"E, quando parti os sete para os quatro mil, quantos cestos cheios de pedaços recolhestes? E disseram: Sete."},
{v:21,t:"E dizia-lhes: Ainda não compreendeis?"}
];

EV[97] = [
{p:"Marcos 8:22-26"},
{v:22,t:"Chegaram a Betsaida; e trouxeram-lhe um cego e suplicavam-lhe que o tocasse."},
{v:23,t:"E, tomando o cego pela mão, levou-o para fora da aldeia; e, tendo-lhe cuspido nos olhos e imposto as mãos, perguntou-lhe: Vês alguma coisa?"},
{v:24,t:"Ele, levantando os olhos, disse: Vejo os homens, mas vejo-os como árvores que andam.",n:"É o único milagre dos evangelhos que se faz em duas etapas, e São Marcos põe-no exatamente entre a cegueira dos discípulos, que acabam de não compreender os pães, e a confissão de Pedro, que vê meio certo. A composição é o comentário."},
{v:25,t:"Depois impôs-lhe de novo as mãos sobre os olhos; e ele começou a ver, e ficou restabelecido, e via tudo com clareza, mesmo de longe."},
{v:26,t:"E mandou-o para casa, dizendo: Nem entres na aldeia."}
];

EV[98] = [
{p:"Mateus 16:13-28"},
{v:13,t:"Chegando Jesus à região de Cesareia de Filipe, perguntava aos seus discípulos: Quem dizem os homens ser o Filho do Homem?",n:"Cesareia de Filipe ficava junto a uma gruta consagrada ao deus Pã, num rochedo enorme, e fora reconstruída por Herodes Filipe em honra de César. A confissão de que Jesus é o Cristo faz-se diante do santuário de um deus pagão e do nome do imperador."},
{v:14,t:"Eles responderam: Uns, João Batista; outros, Elias; outros, Jeremias ou um dos profetas."},
{v:15,t:"Disse-lhes ele: E vós, quem dizeis que eu sou?"},
{v:16,t:"Respondendo Simão Pedro, disse: Tu és o Cristo, o Filho do Deus vivo."},
{v:17,t:"Jesus lhe respondeu: Bem-aventurado és tu, Simão, filho de Jonas, porque não foi carne nem sangue que te revelou isso, mas meu Pai, que está nos céus.",n:"Carne e sangue é expressão hebraica para o homem na sua condição mortal. O que Pedro disse não lhe veio de dedução nem de informação."},
{v:18,t:"E eu te digo que tu és Pedro, e sobre esta pedra edificarei a minha Igreja; e as portas do inferno não prevalecerão contra ela.",n:"Em grego o jogo é entre Petros, nome masculino, e petra, a rocha. Em aramaico, a língua em que a frase foi dita, é a mesma palavra nas duas vezes: Kefa. As portas do inferno são as do lugar dos mortos, e portas não atacam — a imagem é a de uma fortaleza que não resiste, e não a de um assalto."},
{v:19,t:"E a ti darei as chaves do Reino dos céus; e tudo o que ligares na terra será ligado nos céus, e tudo o que desligares na terra será desligado nos céus.",n:"As chaves vêm de Isaías 22, onde se dão ao mordomo do palácio: é ofício de administrador, não de dono. Ligar e desligar era, no vocabulário dos rabinos, declarar proibido ou permitido, e também excluir ou readmitir na comunidade."},
{v:20,t:"Então ordenou aos discípulos que a ninguém dissessem que ele era o Cristo."},
{v:21,t:"Desde então começou Jesus a mostrar aos seus discípulos que era necessário que ele fosse a Jerusalém e sofresse muito da parte dos anciãos, dos sumos sacerdotes e dos escribas, e fosse morto, e ressuscitasse ao terceiro dia.",n:"Desde então marca a viragem do evangelho. Até aqui a pergunta era quem ele é; daqui em diante, o que lhe há de acontecer — e a confissão só fica completa quando aceita a segunda parte."},
{v:22,t:"E Pedro, tomando-o à parte, começou a repreendê-lo, dizendo: Longe de ti, Senhor! Isso não te acontecerá."},
{v:23,t:"Mas ele, voltando-se, disse a Pedro: Vai para trás de mim, Satanás! Tu me serves de escândalo, porque não pensas as coisas de Deus, mas as dos homens.",n:"Vai para trás de mim é, à letra, o lugar do discípulo: atrás, seguindo. Não é só expulsão — é ordem de voltar ao seu posto. E Satanás quer dizer adversário: quem acabara de ser chamado pedra é agora pedra de tropeço."},
{v:24,t:"Então disse Jesus aos seus discípulos: Se alguém quer vir após mim, renuncie a si mesmo, tome a sua cruz e siga-me."},
{v:25,t:"Porque quem quiser salvar a sua vida a perderá; mas quem perder a sua vida por causa de mim a encontrará."},
{v:26,t:"Pois que aproveitará ao homem ganhar o mundo inteiro, se perder a sua alma? Ou que dará o homem em troca da sua alma?",n:"Alma e vida são, no grego, a mesma palavra: psyche. O verso joga com isso — quem tenta guardar a vida perde aquilo mesmo que queria guardar."},
{v:27,t:"Porque o Filho do Homem há de vir na glória de seu Pai, com os seus anjos, e então retribuirá a cada um segundo as suas obras."},
{v:28,t:"Em verdade vos digo: há alguns dos que aqui estão que não provarão a morte até que vejam o Filho do Homem vindo no seu Reino.",n:"Dos versículos mais debatidos. Lido como anúncio do fim do mundo, não se cumpriu; a colocação, porém, é significativa: nos três evangelhos vem imediatamente antes da Transfiguração, e é assim que a maior parte dos Padres o entendeu."},
{p:"Marcos 8:27-38"},
{v:27,t:"E saiu Jesus com os seus discípulos para as aldeias de Cesareia de Filipe; e, pelo caminho, perguntava aos seus discípulos: Quem dizem os homens que eu sou?"},
{v:28,t:"Eles lhe responderam: João Batista; outros, Elias; outros, um dos profetas."},
{v:29,t:"E ele lhes perguntou: E vós, quem dizeis que eu sou? Respondendo Pedro, disse: Tu és o Cristo.",n:"São Marcos não traz nem o elogio a Pedro nem as chaves: a confissão fica nua, e logo a seguir vem a repreensão. O segundo evangelho é o que menos poupa os apóstolos."},
{v:30,t:"E ordenou-lhes severamente que a ninguém falassem dele."},
{v:31,t:"E começou a ensinar-lhes que era necessário que o Filho do Homem sofresse muito, fosse rejeitado pelos anciãos, pelos sumos sacerdotes e pelos escribas, fosse morto e, depois de três dias, ressuscitasse."},
{v:32,t:"E dizia essa palavra abertamente. E Pedro, tomando-o à parte, começou a repreendê-lo."},
{v:33,t:"Mas ele, voltando-se e vendo os seus discípulos, repreendeu Pedro e disse: Vai para trás de mim, Satanás, porque não pensas as coisas de Deus, mas as dos homens."},
{v:34,t:"E, tendo chamado a multidão com os seus discípulos, disse-lhes: Se alguém quer vir após mim, renuncie a si mesmo, tome a sua cruz e siga-me."},
{v:35,t:"Porque quem quiser salvar a sua vida a perderá; mas quem perder a sua vida por causa de mim e do Evangelho a salvará."},
{v:36,t:"Pois que aproveita ao homem ganhar o mundo inteiro e perder a sua alma?"},
{v:37,t:"Que poderá o homem dar em troca da sua alma?"},
{v:38,t:"Porque, se alguém se envergonhar de mim e das minhas palavras nesta geração adúltera e pecadora, também o Filho do Homem se envergonhará dele quando vier na glória de seu Pai, com os santos anjos."},
{p:"Marcos 9:1"},
{v:1,t:"E dizia-lhes: Em verdade vos digo: há alguns dos que aqui estão que não provarão a morte até que vejam o Reino de Deus vindo com poder."},
{p:"Lucas 9:18-27"},
{v:18,t:"Aconteceu que, estando ele a orar a sós, com ele estavam os discípulos; e perguntou-lhes: Quem dizem as multidões que eu sou?",n:"São Lucas põe a confissão depois de uma oração, como faz em todos os momentos decisivos do seu evangelho: o batismo, a escolha dos Doze, a Transfiguração, o horto."},
{v:19,t:"Eles responderam: João Batista; outros, Elias; outros, que ressuscitou um dos antigos profetas."},
{v:20,t:"E disse-lhes: E vós, quem dizeis que eu sou? Respondendo Pedro, disse: O Cristo de Deus."},
{v:21,t:"Mas ele, repreendendo-os, ordenou que a ninguém dissessem isso,"},
{v:22,t:"dizendo: É necessário que o Filho do Homem sofra muito, seja rejeitado pelos anciãos, pelos sumos sacerdotes e pelos escribas, seja morto e ressuscite ao terceiro dia."},
{v:23,t:"E dizia a todos: Se alguém quer vir após mim, renuncie a si mesmo, tome cada dia a sua cruz e siga-me.",n:"Cada dia é acréscimo de São Lucas, e muda a figura: a cruz deixa de ser um acontecimento único e passa a ser a medida de uma vida inteira."},
{v:24,t:"Porque quem quiser salvar a sua vida a perderá; mas quem perder a sua vida por causa de mim a salvará."},
{v:25,t:"Pois que aproveita ao homem ganhar o mundo inteiro, se a si mesmo se perde ou se prejudica?"},
{v:26,t:"Porque, se alguém se envergonhar de mim e das minhas palavras, dele se envergonhará o Filho do Homem quando vier na sua glória e na do Pai e dos santos anjos."},
{v:27,t:"Digo-vos, na verdade: há alguns dos que aqui estão que não provarão a morte até que vejam o Reino de Deus."}
];

EV[99] = [
{p:"Mateus 17:22-23"},
{v:22,t:"Estando eles reunidos na Galileia, disse-lhes Jesus: O Filho do Homem há de ser entregue nas mãos dos homens,",n:"Entregue traduz paradidomi, o verbo que vai voltar a cada passo da Paixão: é o que se diz de Judas, do sinédrio e de Pilatos. O anúncio não nomeia quem entrega, e o passivo deixa em aberto se é Deus quem o faz."},
{v:23,t:"e o matarão, e ao terceiro dia ressuscitará. E eles ficaram muito tristes."},
{p:"Marcos 9:30-32"},
{v:30,t:"Saindo dali, atravessavam a Galileia; e ele não queria que ninguém o soubesse,"},
{v:31,t:"pois ensinava os seus discípulos e lhes dizia: O Filho do Homem será entregue nas mãos dos homens, e o matarão; e, morto, depois de três dias ressuscitará."},
{v:32,t:"Mas eles não entendiam essa palavra e temiam interrogá-lo."},
{p:"Lucas 9:43b-45"},
{v:43,t:"E todos se admiravam da grandeza de Deus. Enquanto todos se maravilhavam de tudo o que ele fazia, disse aos seus discípulos:",n:"A primeira metade deste versículo fecha o tópico anterior; a segunda abre este. O contraste é deliberado em São Lucas: no meio do entusiasmo da multidão, e por causa dele, vem o segundo anúncio da Paixão."},
{v:44,t:"Ponde vós nos vossos ouvidos estas palavras: o Filho do Homem há de ser entregue nas mãos dos homens."},
{v:45,t:"Mas eles não compreendiam essa palavra, e estava-lhes encoberta, de modo que não a percebiam; e temiam interrogá-lo a respeito dela.",n:"Estava-lhes encoberta: o passivo é o que os gramáticos chamam divino, e diz que era Deus quem a encobria. São Lucas usa a mesma construção no caminho de Emaús, quando os olhos dos discípulos estavam impedidos de o reconhecer."}
];

EV[100] = [
{p:"Mateus 18:1-35"},
{v:1,t:"Naquela hora, aproximaram-se os discípulos de Jesus, dizendo: Quem é, pois, o maior no Reino dos céus?"},
{v:2,t:"E ele, chamando uma criança, colocou-a no meio deles"},
{v:3,t:"e disse: Em verdade vos digo: se não vos converterdes e não vos tornardes como crianças, não entrareis no Reino dos céus.",n:"A criança não é aqui modelo de inocência, noção que a antiguidade não lhe atribuía: era quem não tinha estatuto nenhum, nem direitos nem voz. Tornar-se como ela é aceitar não contar — o oposto exato da pergunta que acabam de fazer."},
{v:4,t:"Portanto, quem se humilhar como esta criança, esse é o maior no Reino dos céus."},
{v:5,t:"E quem receber em meu nome uma criança como esta, a mim me recebe."},
{v:6,t:"Mas quem escandalizar um destes pequeninos que creem em mim, melhor lhe fora que se lhe pendurasse ao pescoço uma mó de moinho e fosse afundado no fundo do mar.",n:"A mó é a grande, movida por um animal, e não a de mão. Afogar com uma pedra ao pescoço era suplício conhecido do mundo greco-romano, e absolutamente estranho à lei judaica: a comparação escolhe de propósito a morte mais horrível que o auditório podia imaginar."},
{v:7,t:"Ai do mundo por causa dos escândalos! É necessário que venham escândalos, mas ai do homem por quem vem o escândalo!"},
{v:8,t:"Se a tua mão ou o teu pé te escandaliza, corta-o e lança-o fora de ti: melhor te é entrar na vida manco ou aleijado do que, tendo duas mãos ou dois pés, seres lançado no fogo eterno."},
{v:9,t:"E, se o teu olho te escandaliza, arranca-o e lança-o fora de ti: melhor te é entrar na vida com um só olho do que, tendo dois olhos, seres lançado no fogo da geena.",n:"Geena vem de Ge-Hinnom, o vale ao sul de Jerusalém onde se tinham oferecido crianças a Moloc e onde depois se queimava o lixo da cidade. O nome de um lugar real tornou-se a palavra para o inferno."},
{v:10,t:"Guardai-vos de desprezar um destes pequeninos, porque eu vos digo que os seus anjos, nos céus, veem sempre a face de meu Pai, que está nos céus.",n:"Alguns manuscritos acrescentam aqui um versículo 11 — porque o Filho do Homem veio salvar o que se perdera —, retomado de São Lucas. Falta nos mais antigos, e a Nova Vulgata omite-o: a numeração salta do 10 ao 12."},
{v:12,t:"Que vos parece? Se um homem tiver cem ovelhas e uma delas se extraviar, não deixará as noventa e nove nos montes para ir buscar a extraviada?"},
{v:13,t:"E, se acontecer encontrá-la, em verdade vos digo que se alegra mais com ela do que com as noventa e nove que não se extraviaram."},
{v:14,t:"Assim, não é da vontade de vosso Pai, que está nos céus, que se perca um só destes pequeninos."},
{v:15,t:"Se teu irmão pecar contra ti, vai e repreende-o entre ti e ele a sós; se te ouvir, ganhaste o teu irmão.",n:"Os três passos que se seguem — a sós, com testemunhas, diante da assembleia — são os do direito judaico e aparecem também nos regulamentos da comunidade de Qumran. O fim declarado não é punir: é ganhar o irmão."},
{v:16,t:"Mas, se não te ouvir, leva contigo mais um ou dois, para que pela boca de duas ou três testemunhas se confirme toda palavra."},
{v:17,t:"E, se não os ouvir, dize-o à Igreja; e, se também não ouvir a Igreja, seja para ti como o gentio e o publicano."},
{v:18,t:"Em verdade vos digo: tudo o que ligardes na terra será ligado no céu, e tudo o que desligardes na terra será desligado no céu."},
{v:19,t:"De novo vos digo: se dois de vós, na terra, concordarem sobre qualquer coisa que peçam, isso lhes será concedido por meu Pai, que está nos céus."},
{v:20,t:"Porque, onde dois ou três estiverem reunidos em meu nome, ali estou eu no meio deles.",n:"Os rabinos diziam que, onde dois se sentam a estudar a Lei, a Presença de Deus está entre eles. A frase segue a forma da sentença e troca a Lei pelo seu nome."},
{v:21,t:"Então, aproximando-se Pedro, disse-lhe: Senhor, quantas vezes pecará meu irmão contra mim, e eu lhe perdoarei? Até sete vezes?"},
{v:22,t:"Jesus lhe respondeu: Não te digo até sete vezes, mas até setenta vezes sete.",n:"A expressão vem do canto de Lamec, no capítulo 4 do Gênesis, onde a vingança se multiplica setenta e sete vezes. A mesma medida que servia para a vingança passa a servir para o perdão, e é assim que a espiral se inverte. O grego pode ler-se setenta vezes sete ou setenta e sete; em qualquer dos casos, quer dizer sem conta."},
{v:23,t:"Por isso o Reino dos céus é semelhante a um rei que quis ajustar contas com os seus servos."},
{v:24,t:"Tendo começado a ajustá-las, foi-lhe apresentado um que lhe devia dez mil talentos.",n:"Um talento valia cerca de seis mil denários, e o denário era o salário de um dia. Dez mil talentos são, portanto, algo como cento e sessenta mil anos de trabalho — a maior cifra e a maior unidade que a língua tinha, postas juntas. A dívida é de propósito impagável."},
{v:25,t:"E, não tendo ele com que pagar, o senhor mandou que fosse vendido, ele, sua mulher, seus filhos e tudo quanto tinha, e que se pagasse a dívida."},
{v:26,t:"Então o servo, prostrando-se, suplicava-lhe: Tem paciência comigo, e tudo te pagarei."},
{v:27,t:"Compadecido, o senhor daquele servo soltou-o e perdoou-lhe a dívida."},
{v:28,t:"Mas, saindo aquele servo, encontrou um dos seus companheiros que lhe devia cem denários; e, agarrando-o, sufocava-o, dizendo: Paga o que deves.",n:"Cem denários são cem dias de trabalho: dívida real, que se podia cobrar, mas seiscentas mil vezes menor do que a que acabara de ser perdoada. A parábola não compara ofensas graves com leves — compara o incomparável."},
{v:29,t:"Então o seu companheiro, prostrando-se, suplicava-lhe: Tem paciência comigo, e te pagarei."},
{v:30,t:"Ele, porém, não quis; antes foi lançá-lo na prisão, até que pagasse a dívida."},
{v:31,t:"Vendo os seus companheiros o que acontecera, ficaram muito tristes e foram contar ao seu senhor tudo o que se passara."},
{v:32,t:"Então o seu senhor o chamou e lhe disse: Servo mau, perdoei-te toda aquela dívida porque me suplicaste."},
{v:33,t:"Não devias tu também compadecer-te do teu companheiro, como eu me compadeci de ti?"},
{v:34,t:"E, indignado, o seu senhor entregou-o aos torturadores, até que pagasse toda a dívida."},
{v:35,t:"Assim também vos fará meu Pai celeste, se cada um de vós não perdoar de coração a seu irmão."},
{p:"Marcos 9:33-50"},
{v:33,t:"E vieram a Cafarnaum. Estando em casa, perguntava-lhes: De que discutíeis pelo caminho?"},
{v:34,t:"Mas eles calavam-se, pois pelo caminho tinham discutido entre si sobre quem era o maior.",n:"O silêncio diz tudo: discutiam a primazia no caminho em que ele acabava de anunciar que seria entregue e morto. São Marcos põe as duas coisas lado a lado sem comentar."},
{v:35,t:"E, sentando-se, chamou os Doze e disse-lhes: Se alguém quer ser o primeiro, seja o último de todos e o servo de todos."},
{v:36,t:"E, tomando uma criança, colocou-a no meio deles e, abraçando-a, disse-lhes:"},
{v:37,t:"Quem receber em meu nome uma destas crianças, a mim me recebe; e quem a mim me receber, não recebe a mim, mas àquele que me enviou."},
{v:38,t:"Disse-lhe João: Mestre, vimos alguém que expulsava demônios em teu nome, e o proibimos, porque não nos segue."},
{v:39,t:"Mas Jesus disse: Não o proibais, porque ninguém há que faça um milagre em meu nome e logo possa falar mal de mim."},
{v:40,t:"Pois quem não é contra nós é por nós.",n:"No tópico 75 lia-se o contrário: quem não está comigo está contra mim. As duas frases não se contradizem, porque não respondem à mesma pergunta — uma é dita a quem julga os outros, a outra a quem se julga a si mesmo."},
{v:41,t:"Porque quem vos der de beber um copo de água em meu nome, por serdes de Cristo, em verdade vos digo: não perderá a sua recompensa."},
{v:42,t:"E quem escandalizar um destes pequeninos que creem, melhor lhe fora que se lhe pendurasse ao pescoço uma mó de moinho e fosse lançado no mar."},
{v:43,t:"E, se a tua mão te escandaliza, corta-a: melhor te é entrar manco na vida do que, tendo duas mãos, ir para a geena, para o fogo inextinguível.",n:"Faltam aqui, nos manuscritos mais antigos, os versículos 44 e 46, que repetiam a frase do versículo 48. A Nova Vulgata omite-os, e a numeração salta duas vezes."},
{v:45,t:"E, se o teu pé te escandaliza, corta-o: melhor te é entrar coxo na vida do que, tendo dois pés, ser lançado na geena."},
{v:47,t:"E, se o teu olho te escandaliza, arranca-o: melhor te é entrar com um só olho no Reino de Deus do que, tendo dois olhos, ser lançado na geena,"},
{v:48,t:"onde o seu verme não morre e o fogo não se apaga.",n:"É o último versículo do livro de Isaías, citado à letra. O profeta falava dos cadáveres dos rebeldes, à vista de Jerusalém — e no vale da geena, precisamente."},
{v:49,t:"Porque cada um será salgado com fogo.",n:"Verso obscuro, que ninguém explicou de modo pacífico. O sal acompanhava todo sacrifício, segundo o Levítico; o fogo é o da prova. A leitura mais aceita junta as duas coisas: quem é provado pelo fogo fica preservado, como o que se salga."},
{v:50,t:"Bom é o sal; mas, se o sal se tornar insípido, com que o temperareis? Tende sal em vós mesmos e vivei em paz uns com os outros."},
{p:"Lucas 9:46-50"},
{v:46,t:"Surgiu entre eles a discussão sobre qual deles seria o maior."},
{v:47,t:"Mas Jesus, conhecendo o pensamento do seu coração, tomou uma criança, colocou-a junto de si"},
{v:48,t:"e disse-lhes: Quem receber esta criança em meu nome, a mim me recebe; e quem me receber, recebe aquele que me enviou; pois quem entre todos vós é o menor, esse é grande."},
{v:49,t:"Respondendo João, disse: Mestre, vimos alguém que expulsava demônios em teu nome, e o proibimos, porque não te segue conosco."},
{v:50,t:"E Jesus lhe disse: Não o proibais, porque quem não é contra vós é por vós."}
];

EV[101] = [
{p:"Mateus 17:1-13"},
{v:1,t:"Seis dias depois, Jesus tomou consigo Pedro, Tiago e João, seu irmão, e os levou à parte, a um monte alto.",n:"Seis dias depois da confissão de Pedro. Moisés esperou seis dias na nuvem antes de Deus lhe falar no Sinai, segundo o Êxodo 24 — e toda a cena que se segue é escrita com o vocabulário daquele capítulo: o monte, a nuvem, a voz, os três companheiros."},
{v:2,t:"E transfigurou-se diante deles: o seu rosto resplandeceu como o sol, e as suas vestes tornaram-se brancas como a luz.",n:"Transfigurou-se verte metamorphothe: mudou de forma. Não se diz que algo lhe foi acrescentado, mas que se viu o que estava; é assim que a tradição sempre o leu."},
{v:3,t:"E eis que lhes apareceram Moisés e Elias, falando com ele."},
{v:4,t:"Tomando a palavra, Pedro disse a Jesus: Senhor, é bom estarmos aqui; se queres, farei aqui três tendas: uma para ti, uma para Moisés e uma para Elias.",n:"As tendas são as da festa dos Tabernáculos, em que Israel morava oito dias em cabanas, lembrando o deserto. Pedro quer prolongar o que vê, e é isso que a voz do céu corrige: não se manda ficar, manda-se escutar."},
{v:5,t:"Ainda ele falava, quando uma nuvem luminosa os cobriu; e eis que da nuvem saiu uma voz, dizendo: Este é o meu Filho amado, em quem pus o meu agrado; escutai-o."},
{v:6,t:"Ouvindo isso, os discípulos caíram com o rosto em terra e tiveram grande medo."},
{v:7,t:"E Jesus aproximou-se, tocou-os e disse: Levantai-vos e não temais."},
{v:8,t:"Levantando os olhos, não viram ninguém, senão Jesus sozinho."},
{v:9,t:"E, ao descerem do monte, Jesus ordenou-lhes: A ninguém conteis a visão, até que o Filho do Homem ressuscite dos mortos."},
{v:10,t:"E os discípulos lhe perguntaram: Por que dizem, pois, os escribas que primeiro é necessário que venha Elias?"},
{v:11,t:"Ele respondeu: Elias, na verdade, há de vir e restaurará todas as coisas."},
{v:12,t:"Mas eu vos digo que Elias já veio, e não o reconheceram; antes, fizeram com ele tudo o que quiseram. Assim também o Filho do Homem há de sofrer às suas mãos."},
{v:13,t:"Então os discípulos compreenderam que lhes falara de João Batista."},
{p:"Marcos 9:2-13"},
{v:2,t:"Seis dias depois, Jesus tomou consigo Pedro, Tiago e João e os levou, a sós, à parte, a um monte alto; e transfigurou-se diante deles."},
{v:3,t:"E as suas vestes tornaram-se resplandecentes, de uma brancura tal, que nenhum lavandeiro na terra as poderia branquear assim.",n:"O pormenor do lavandeiro é de São Marcos, e é bem seu: em vez de comparar com o sol, compara com o ofício mais comum, e diz que nenhum daria aquilo."},
{v:4,t:"E apareceu-lhes Elias com Moisés, e falavam com Jesus."},
{v:5,t:"Tomando a palavra, Pedro disse a Jesus: Rabi, é bom estarmos aqui; façamos três tendas: uma para ti, uma para Moisés e uma para Elias."},
{v:6,t:"Pois não sabia o que dizer, porque estavam tomados de medo."},
{v:7,t:"E veio uma nuvem que os cobriu com a sua sombra; e da nuvem saiu uma voz: Este é o meu Filho amado; escutai-o."},
{v:8,t:"E, de repente, olhando ao redor, já não viram ninguém consigo, senão Jesus sozinho."},
{v:9,t:"E, ao descerem do monte, ordenou-lhes que a ninguém contassem o que tinham visto, senão quando o Filho do Homem tivesse ressuscitado dos mortos."},
{v:10,t:"Eles guardaram a palavra, discutindo entre si o que seria ressuscitar dos mortos.",n:"A ressurreição dos mortos no fim dos tempos era crença corrente entre os fariseus; o que os desconcerta é que um homem ressuscite antes disso, e sozinho. Só São Marcos anota a perplexidade."},
{v:11,t:"E o interrogavam, dizendo: Por que dizem os escribas que primeiro é necessário que venha Elias?"},
{v:12,t:"Ele lhes disse: Elias, vindo primeiro, restaura todas as coisas; e como está escrito do Filho do Homem, que há de sofrer muito e ser desprezado?"},
{v:13,t:"Mas eu vos digo que Elias já veio, e fizeram com ele tudo o que quiseram, como dele está escrito."},
{p:"Lucas 9:28-36"},
{v:28,t:"Aconteceu que, cerca de oito dias depois destas palavras, tomando consigo Pedro, João e Tiago, subiu ao monte para orar.",n:"Oito dias, onde os outros dizem seis: São Lucas conta provavelmente incluindo os dois extremos. E, como sempre nele, o que acontece começa numa oração."},
{v:29,t:"E, enquanto orava, o aspecto do seu rosto tornou-se outro, e a sua veste ficou de um branco fulgurante."},
{v:30,t:"E eis que dois homens falavam com ele: eram Moisés e Elias,"},
{v:31,t:"que, aparecendo em glória, falavam da sua partida, que ele havia de consumar em Jerusalém.",n:"Partida traduz exodos, e São Lucas é o único que diz de que falavam. A palavra escolhida faz da morte em Jerusalém o novo êxodo, e põe na boca de Moisés precisamente esse nome."},
{v:32,t:"Pedro e os que estavam com ele achavam-se pesados de sono; mas, despertando, viram a sua glória e os dois homens que estavam com ele.",n:"Os mesmos três adormecem no Getsêmani, e São Lucas é também quem o anota. A glória e a agonia têm as mesmas testemunhas, e ambas as vezes com sono."},
{v:33,t:"E aconteceu que, ao separarem-se deles, Pedro disse a Jesus: Mestre, é bom estarmos aqui; façamos três tendas: uma para ti, uma para Moisés e uma para Elias — não sabendo o que dizia."},
{v:34,t:"Enquanto dizia isso, veio uma nuvem que os cobriu com a sua sombra; e tiveram medo ao entrarem na nuvem."},
{v:35,t:"E da nuvem saiu uma voz, dizendo: Este é o meu Filho, o eleito; escutai-o.",n:"Onde Mateus e Marcos trazem o amado, São Lucas traz o eleito — o título do servo de Isaías 42, de quem se diz que Deus põe nele o seu agrado. A troca aponta para o mesmo lugar por outro caminho."},
{v:36,t:"E, ao soar a voz, Jesus foi achado sozinho. Eles guardaram silêncio e, naqueles dias, a ninguém contaram nada do que tinham visto."}
];

EV[102] = [
{p:"Mateus 17:14-20"},
{v:14,t:"E, chegando eles junto da multidão, aproximou-se dele um homem que, pondo-se de joelhos diante dele, disse:"},
{v:15,t:"Senhor, tem piedade do meu filho, porque é epiléptico e sofre muito; pois muitas vezes cai no fogo e muitas vezes na água.",n:"Epiléptico traduz, à letra, lunático: tinha-se por causa do mal a influência da lua. Conserva-se o termo médico, que é o que a palavra descreve, e registra-se aqui o que o grego diz."},
{v:16,t:"Eu o trouxe aos teus discípulos, e não puderam curá-lo."},
{v:17,t:"Jesus respondeu: Ó geração incrédula e perversa! Até quando estarei convosco? Até quando vos suportarei? Trazei-o aqui a mim.",n:"A queixa é a de Moisés e a dos profetas diante do povo no deserto, e aqui recai sobre os próprios discípulos, que desceram do monte da glória e nada puderam fazer no vale."},
{v:18,t:"E Jesus repreendeu o demônio, que saiu dele; e o menino ficou curado naquela hora."},
{v:19,t:"Então, aproximando-se a sós de Jesus, os discípulos disseram: Por que não pudemos nós expulsá-lo?"},
{v:20,t:"Ele lhes disse: Por causa da vossa pouca fé. Porque em verdade vos digo: se tiverdes fé como um grão de mostarda, direis a este monte: Passa daqui para lá, e ele passará; e nada vos será impossível.",n:"Alguns manuscritos acrescentam aqui um versículo 21 — mas esta casta não se expulsa senão pela oração e pelo jejum —, trazido de São Marcos. Falta nos mais antigos, e a Nova Vulgata omite-o; a perícope acaba no versículo 20."},
{p:"Marcos 9:14-29"},
{v:14,t:"E, chegando junto dos discípulos, viram grande multidão ao redor deles, e escribas que discutiam com eles."},
{v:15,t:"E logo toda a multidão, ao vê-lo, ficou admirada e, correndo, o saudava."},
{v:16,t:"E perguntou-lhes: De que discutis com eles?"},
{v:17,t:"E um da multidão lhe respondeu: Mestre, trouxe-te o meu filho, que tem um espírito mudo;"},
{v:18,t:"e, onde quer que o apanhe, lança-o por terra, e ele espuma, range os dentes e fica rígido. E disse aos teus discípulos que o expulsassem, e não puderam."},
{v:19,t:"Ele lhes respondeu: Ó geração incrédula! Até quando estarei convosco? Até quando vos suportarei? Trazei-o a mim."},
{v:20,t:"E trouxeram-no. Ao vê-lo, logo o espírito o convulsionou; e, caindo por terra, rolava, espumando."},
{v:21,t:"E perguntou ao pai: Há quanto tempo lhe acontece isso? Ele disse: Desde a infância;",n:"É o único caso em que Jesus pergunta a história clínica antes de curar. São Marcos conta este episódio com mais pormenor do que qualquer outro milagre, e é dos seus trechos mais longos."},
{v:22,t:"e muitas vezes o lançou no fogo e na água, para o matar. Mas, se podes alguma coisa, ajuda-nos, compadecido de nós."},
{v:23,t:"Jesus lhe disse: Se podes! Tudo é possível ao que crê.",n:"A resposta apanha a palavra do pai e devolve-a: o se podes não estava do lado de Jesus. A condição desloca-se de quem cura para quem pede."},
{v:24,t:"Logo o pai do menino exclamou, dizendo: Creio; ajuda a minha incredulidade.",n:"Das frases mais exatas que os evangelhos conservam sobre a fé: não a que tem certeza, mas a que pede que a supram. E é a esta que o milagre é concedido."},
{v:25,t:"Vendo Jesus que a multidão acorria, repreendeu o espírito imundo, dizendo: Espírito mudo e surdo, eu te ordeno: sai dele e não entres mais nele."},
{v:26,t:"E, gritando e convulsionando-o muito, saiu; e o menino ficou como morto, de modo que muitos diziam: Morreu."},
{v:27,t:"Mas Jesus, tomando-o pela mão, o levantou, e ele pôs-se de pé.",n:"Levantou traduz egeiro, e pôs-se de pé, aniste: são os dois verbos da ressurreição. São Marcos descreve a cura com as palavras que usará para o sepulcro vazio."},
{v:28,t:"E, quando entrou em casa, os seus discípulos lhe perguntavam em particular: Por que não pudemos nós expulsá-lo?"},
{v:29,t:"E ele lhes disse: Esta casta não pode sair de modo algum, senão pela oração.",n:"Muitos manuscritos acrescentam e pelo jejum, e é dessa forma que a frase se tornou proverbial. As testemunhas mais antigas trazem só a oração, e é o que a Nova Vulgata segue."},
{p:"Lucas 9:37-43a"},
{v:37,t:"Aconteceu que, no dia seguinte, ao descerem do monte, veio ao seu encontro uma grande multidão."},
{v:38,t:"E eis que um homem da multidão gritou, dizendo: Mestre, suplico-te que olhes para o meu filho, porque é o único que tenho;",n:"Filho único: São Lucas acrescenta-o, como faz com a filha de Jairo e com o filho da viúva de Naim. É pormenor dele, e sempre o mesmo."},
{v:39,t:"e eis que um espírito se apodera dele e, de repente, ele grita, e o espírito o convulsiona até espumar, e só a custo o larga, deixando-o exausto."},
{v:40,t:"Roguei aos teus discípulos que o expulsassem, e não puderam."},
{v:41,t:"Respondendo Jesus, disse: Ó geração incrédula e perversa! Até quando estarei convosco e vos suportarei? Traze aqui o teu filho."},
{v:42,t:"E, enquanto se aproximava, o demônio lançou-o por terra e o convulsionou. Mas Jesus repreendeu o espírito imundo, curou o menino e o devolveu a seu pai."},
{v:43,t:"E todos se admiravam da grandeza de Deus."}
];

EV[103] = [
{p:"Mateus 17:24-27"},
{v:24,t:"Tendo chegado a Cafarnaum, aproximaram-se de Pedro os cobradores da didracma e disseram: O vosso Mestre não paga a didracma?",n:"A didracma era o imposto anual de meio siclo que todo judeu adulto devia ao templo, mandado pelo Êxodo 30. Não é tributo de Roma: é contribuição religiosa, e é isso que dá sentido à pergunta seguinte."},
{v:25,t:"Ele disse: Paga. E, ao entrar em casa, Jesus falou primeiro, dizendo: Que te parece, Simão? De quem cobram os reis da terra tributos ou imposto? Dos seus filhos ou dos estranhos?"},
{v:26,t:"Ele respondeu: Dos estranhos. Disse-lhe Jesus: Logo, os filhos estão isentos.",n:"O argumento é discreto e vai fundo: se o templo é a casa do Pai, o Filho não paga para entrar em sua própria casa. A isenção afirma-se, e logo se renuncia a ela."},
{v:27,t:"Mas, para que não os escandalizemos, vai ao mar, lança o anzol, toma o primeiro peixe que subir e, abrindo-lhe a boca, encontrarás um estáter; toma-o e dá-o a eles por mim e por ti.",n:"O estáter valia exatamente duas didracmas: o suficiente para dois, e é o que se diz. Este é o único milagre dos evangelhos de que não se conta o desfecho — não se chega a dizer que o peixe foi apanhado."}
];

EV[104] = [
{p:"João 7:2-13"},
{v:2,t:"Estava próxima a festa dos judeus, a dos Tabernáculos.",n:"A festa dos Tabernáculos durava oito dias no outono, e nela se morava em cabanas de ramos, em memória do deserto. Tinha dois ritos próprios — o da água, tirada da fonte de Siloé, e o das grandes lâmpadas acesas no átrio —, e é sobre esses dois ritos que Jesus vai falar nos tópicos seguintes."},
{v:3,t:"Disseram-lhe, pois, os seus irmãos: Sai daqui e vai para a Judeia, para que também os teus discípulos vejam as obras que fazes."},
{v:4,t:"Porque ninguém faz coisa alguma em segredo, quando procura ser conhecido em público. Se fazes estas coisas, manifesta-te ao mundo."},
{v:5,t:"Pois nem os seus irmãos criam nele.",n:"O evangelista anota-o sem rodeios. O conselho que acabam de dar é o de um empresário: mostra-te onde há público. Não é hostilidade — é incompreensão, e o evangelho não a esconde."},
{v:6,t:"Disse-lhes, então, Jesus: O meu tempo ainda não chegou; mas o vosso tempo está sempre pronto."},
{v:7,t:"O mundo não vos pode odiar; a mim, porém, odeia, porque eu dou testemunho dele, de que as suas obras são más."},
{v:8,t:"Subi vós à festa; eu não subo a esta festa, porque o meu tempo ainda não se cumpriu.",n:"Alguns manuscritos leem ainda não subo, para evitar a aparente contradição com o versículo 10. A leitura mais difícil — e por isso provavelmente a original — é a que aqui se conserva: em São João, subir tem também o sentido de subir ao Pai, e é nesse sentido que a hora ainda não chegou."},
{v:9,t:"Tendo dito isso, ficou na Galileia."},
{v:10,t:"Mas, depois que os seus irmãos subiram à festa, então subiu também ele, não publicamente, mas como em segredo."},
{v:11,t:"Os judeus, pois, o procuravam na festa e diziam: Onde está ele?"},
{v:12,t:"E havia grande murmúrio a seu respeito entre as multidões. Uns diziam: É bom. Outros diziam: Não; antes engana a multidão."},
{v:13,t:"Ninguém, contudo, falava dele abertamente, por medo dos judeus.",n:"Nota do tradutor: São João usa os judeus quase sempre para designar as autoridades de Jerusalém que se opõem a Jesus, e não o povo judeu — como se vê aqui mesmo, onde quem tem medo dos judeus são judeus da Galileia. O evangelho é escrito por um judeu, sobre um judeu, num tempo em que a ruptura entre a sinagoga e os discípulos já se consumara, e a expressão guarda a dureza dessa ruptura. Traduz-se literalmente, porque é o que está escrito; registra-se aqui, porque a frase foi usada durante séculos para justificar perseguições que o texto não autoriza."}
];

EV[105] = [
{p:"João 7:14-52"},
{v:14,t:"Estando já a festa a meio, Jesus subiu ao templo e ensinava."},
{v:15,t:"Os judeus admiravam-se, dizendo: Como sabe este letras, sem ter estudado?",n:"Sem ter estudado quer dizer: sem ter frequentado a escola de um mestre reconhecido. O espanto não é com a inteligência, mas com a falta de credenciais."},
{v:16,t:"Respondeu-lhes Jesus: A minha doutrina não é minha, mas daquele que me enviou."},
{v:17,t:"Se alguém quiser fazer a vontade dele, conhecerá se a doutrina é de Deus ou se eu falo por mim mesmo.",n:"A ordem é inversa da que se esperaria: não se entende primeiro para depois obedecer, mas quer-se fazer primeiro, e então se conhece. É a regra que atravessa todo o quarto evangelho."},
{v:18,t:"Quem fala por si mesmo busca a sua própria glória; mas quem busca a glória daquele que o enviou, esse é verdadeiro, e nele não há injustiça."},
{v:19,t:"Não vos deu Moisés a lei? E nenhum de vós cumpre a lei. Por que procurais matar-me?"},
{v:20,t:"Respondeu a multidão: Tens um demônio. Quem procura matar-te?"},
{v:21,t:"Jesus lhes respondeu: Fiz uma só obra, e todos vos admirais.",n:"A obra é a cura do paralítico da piscina, contada no capítulo 5 e traduzida no tópico 30. Passaram-se meses, e a discussão continua no mesmo ponto."},
{v:22,t:"Por isso Moisés vos deu a circuncisão — não que venha de Moisés, mas dos patriarcas — e no sábado circuncidais um homem."},
{v:23,t:"Se um homem recebe a circuncisão no sábado, para que não se quebre a lei de Moisés, indignais-vos contra mim porque curei um homem inteiro no sábado?",n:"O argumento é rabínico e impecável: se a lei permite intervir num membro do corpo em dia de sábado, quanto mais no homem inteiro. Jesus discute com as regras dos seus adversários."},
{v:24,t:"Não julgueis pela aparência, mas julgai com justo juízo."},
{v:25,t:"Diziam, pois, alguns de Jerusalém: Não é este o que procuram matar?"},
{v:26,t:"E eis que fala abertamente, e nada lhe dizem. Terão os chefes reconhecido verdadeiramente que este é o Cristo?"},
{v:27,t:"Mas deste sabemos donde é; quando, porém, vier o Cristo, ninguém saberá donde ele é.",n:"Corria a ideia de que o Messias estaria oculto até se manifestar de repente. A objeção é, pois: sabemos demais sobre este para que seja ele. No versículo 41 far-se-á a objeção contrária — que não vem do lugar certo. As duas não podem ser verdadeiras ao mesmo tempo, e o evangelista põe-nas lado a lado."},
{v:28,t:"Ensinando no templo, Jesus exclamou: Vós me conheceis e sabeis donde sou. E, contudo, não vim por mim mesmo; mas é verdadeiro aquele que me enviou, o qual vós não conheceis."},
{v:29,t:"Eu o conheço, porque venho dele, e foi ele que me enviou."},
{v:30,t:"Procuravam, pois, prendê-lo; mas ninguém lhe deitou as mãos, porque ainda não chegara a sua hora."},
{v:31,t:"Muitos da multidão, porém, creram nele e diziam: Quando vier o Cristo, fará mais sinais do que os que este fez?"},
{v:32,t:"Os fariseus ouviram a multidão murmurar essas coisas a seu respeito; e os sumos sacerdotes e os fariseus enviaram guardas para o prenderem."},
{v:33,t:"Disse, pois, Jesus: Ainda um pouco de tempo estou convosco, e vou para aquele que me enviou."},
{v:34,t:"Haveis de buscar-me e não me achareis; e onde eu estou, vós não podeis ir."},
{v:35,t:"Diziam, pois, os judeus entre si: Para onde há de ir este, que não o havemos de achar? Irá para os dispersos entre os gregos e ensinará os gregos?",n:"A pergunta é irônica na intenção e profética sem o saber: é exatamente o que havia de acontecer. São João usa muitas vezes este recurso — os adversários dizem a verdade sem querer."},
{v:36,t:"Que palavra é esta que disse: Haveis de buscar-me e não me achareis; e onde eu estou, vós não podeis ir?"},
{v:37,t:"No último dia, o maior da festa, Jesus estava de pé e exclamou: Se alguém tem sede, venha a mim e beba.",n:"Em cada manhã da festa, os sacerdotes traziam da fonte de Siloé uma bilha de água e derramavam-na sobre o altar, pedindo a chuva. No último dia, o rito repetia-se sete vezes. É nesse momento, e de pé, que Jesus grita estas palavras."},
{v:38,t:"Quem crê em mim, como diz a Escritura, do seu interior correrão rios de água viva.",n:"A pontuação decide o sentido e os manuscritos antigos não a traziam. Pode ler-se como aqui — os rios correm do interior de quem crê — ou juntando venha a mim e beba quem crê em mim, e então os rios correm do próprio Cristo. A Nova Vulgata segue a primeira, e os Padres gregos preferiram-na; muitos latinos, a segunda."},
{v:39,t:"Isso disse ele do Espírito que haviam de receber os que nele cressem; pois ainda não havia Espírito, porque Jesus ainda não fora glorificado."},
{v:40,t:"Alguns da multidão, ouvindo essas palavras, diziam: Este é verdadeiramente o profeta."},
{v:41,t:"Outros diziam: Este é o Cristo. Mas outros diziam: Acaso vem o Cristo da Galileia?"},
{v:42,t:"Não diz a Escritura que o Cristo vem da descendência de Davi, e de Belém, a aldeia onde Davi estava?",n:"A objeção é boa e a resposta estava à mão: ele nascera em Belém, e era da casa de Davi. O evangelista não a dá, e deixa o leitor, que já sabe, a ver os adversários tropeçarem no que ignoram."},
{v:43,t:"Houve, pois, divisão entre a multidão por causa dele."},
{v:44,t:"Alguns deles queriam prendê-lo, mas ninguém lhe deitou as mãos."},
{v:45,t:"Voltaram, pois, os guardas aos sumos sacerdotes e fariseus, e estes lhes disseram: Por que não o trouxestes?"},
{v:46,t:"Responderam os guardas: Jamais homem algum falou como este homem."},
{v:47,t:"Responderam-lhes os fariseus: Também vós fostes enganados?"},
{v:48,t:"Acaso creu nele algum dos chefes ou dos fariseus?"},
{v:49,t:"Mas esta multidão, que não conhece a lei, é maldita."},
{v:50,t:"Disse-lhes Nicodemos, o que antes viera a ele e era um deles:"},
{v:51,t:"Acaso a nossa lei julga um homem sem primeiro o ouvir e saber o que ele faz?",n:"Nicodemos responde à pergunta do versículo 48 com a sua própria pessoa: é um dos chefes, e o está defendendo. E fá-lo invocando a lei que eles próprios acabaram de opor à multidão."},
{v:52,t:"Responderam-lhe: Também tu és da Galileia? Examina e vê que da Galileia não surge profeta."}
];

EV[106] = [
{p:"João 7:53"},
{v:53,t:"E cada um foi para sua casa.",n:"Nota do tradutor: o episódio que começa neste versículo falta nos manuscritos gregos mais antigos e melhores, e onde aparece surge por vezes noutros lugares — no fim de São João, ou depois de Lucas 21. O vocabulário e o estilo são mais próximos de São Lucas do que do quarto evangelho. Quase todos os estudiosos concluem, por isso, que não fazia parte do texto original de São João; e quase todos concluem também que é antiquíssimo e verdadeiro. O Concílio de Trento declarou-o canônico, e a Nova Vulgata mantém-no no seu lugar tradicional, como aqui se faz. É a página que a tradição não quis perder."},
{p:"João 8:1-11"},
{v:1,t:"Jesus, porém, foi para o monte das Oliveiras."},
{v:2,t:"E de madrugada voltou ao templo, e todo o povo vinha a ele; e, sentando-se, ensinava-os."},
{v:3,t:"Os escribas e os fariseus trouxeram uma mulher surpreendida em adultério e, pondo-a no meio,"},
{v:4,t:"disseram-lhe: Mestre, esta mulher foi surpreendida em flagrante adultério."},
{v:5,t:"Ora, Moisés mandou-nos na lei apedrejar tais mulheres. Tu, pois, que dizes?",n:"A lei condenava à morte os dois, o homem e a mulher, e não só ela. A ausência do outro, que o texto não comenta, mostra desde logo que não é justiça o que ali se procura."},
{v:6,t:"Diziam isso para o tentarem, a fim de terem de que o acusar. Mas Jesus, inclinando-se, escrevia com o dedo na terra.",n:"A armadilha tem duas mandíbulas: absolvê-la é contradizer Moisés; condená-la é usurpar um direito que Roma reservava a si. O que ele escrevia na terra ninguém o soube nunca, e o evangelho não o diz."},
{v:7,t:"Como insistissem em interrogá-lo, endireitou-se e disse-lhes: Quem de vós estiver sem pecado, atire nela a primeira pedra.",n:"A primeira pedra cabia, pelo Deuteronômio, às testemunhas de acusação. A resposta não revoga a lei: devolve-a a quem devia executá-la, e acrescenta-lhe uma condição."},
{v:8,t:"E, inclinando-se de novo, escrevia na terra."},
{v:9,t:"Eles, porém, ouvindo isso, foram saindo um a um, a começar pelos mais velhos; e ficou só Jesus, e a mulher, de pé, no meio."},
{v:10,t:"Endireitando-se, Jesus lhe disse: Mulher, onde estão eles? Ninguém te condenou?"},
{v:11,t:"Ela disse: Ninguém, Senhor. E Jesus disse: Nem eu te condeno. Vai e, de agora em diante, não peques mais.",n:"Santo Agostinho resume a cena numa frase que ficou: ficaram os dois, a miséria e a misericórdia. E as duas metades da última fala são inseparáveis — a absolvição não é indiferença, e o mandato não é condição."}
];

EV[107] = [
{p:"João 8:12-30"},
{v:12,t:"Falou-lhes, pois, Jesus de novo, dizendo: Eu sou a luz do mundo; quem me segue não andará nas trevas, mas terá a luz da vida.",n:"O segundo rito dos Tabernáculos era o das quatro grandes candeias acesas no átrio das mulheres, que iluminavam a cidade inteira durante a noite. Como fizera com a água, Jesus fala diante do rito e toma-o para si."},
{v:13,t:"Disseram-lhe, então, os fariseus: Tu dás testemunho de ti mesmo; o teu testemunho não é verdadeiro."},
{v:14,t:"Respondeu Jesus e disse-lhes: Ainda que eu dê testemunho de mim mesmo, o meu testemunho é verdadeiro, porque sei donde vim e para onde vou; mas vós não sabeis donde venho nem para onde vou."},
{v:15,t:"Vós julgais segundo a carne; eu não julgo ninguém."},
{v:16,t:"E, se eu julgo, o meu juízo é verdadeiro, porque não estou sozinho, mas eu e aquele que me enviou."},
{v:17,t:"E na vossa lei está escrito que o testemunho de dois homens é verdadeiro."},
{v:18,t:"Eu sou o que dou testemunho de mim mesmo, e dá testemunho de mim o Pai, que me enviou."},
{v:19,t:"Diziam-lhe, pois: Onde está o teu Pai? Respondeu Jesus: Não conheceis nem a mim nem a meu Pai; se me conhecêsseis, conheceríeis também a meu Pai."},
{v:20,t:"Estas palavras disse ele junto ao tesouro, ensinando no templo; e ninguém o prendeu, porque ainda não chegara a sua hora.",n:"O tesouro ficava no átrio das mulheres, onde estavam também as grandes candeias da festa. O evangelista dá a localização precisa, e ela confirma de que luz se estava falando."},
{v:21,t:"Disse-lhes de novo: Eu vou, e vós me buscareis, e morrereis no vosso pecado. Para onde eu vou, vós não podeis ir."},
{v:22,t:"Diziam, pois, os judeus: Acaso se matará a si mesmo, pois diz: Para onde eu vou, vós não podeis ir?"},
{v:23,t:"E dizia-lhes: Vós sois de baixo, eu sou de cima; vós sois deste mundo, eu não sou deste mundo."},
{v:24,t:"Por isso vos disse que morrereis nos vossos pecados; porque, se não crerdes que eu sou, morrereis nos vossos pecados.",n:"Eu sou, sem predicado nenhum: é assim que Deus se nomeia no Êxodo e em Isaías, e é a forma que o grego dos Setenta usa para traduzir o nome divino. No capítulo 8 aparece três vezes, e a terceira faz os ouvintes pegarem em pedras."},
{v:25,t:"Diziam-lhe, pois: Quem és tu? Respondeu-lhes Jesus: Desde o princípio, isso mesmo que vos digo."},
{v:26,t:"Muitas coisas tenho a dizer e a julgar a vosso respeito; mas aquele que me enviou é verdadeiro, e eu falo ao mundo as coisas que dele ouvi."},
{v:27,t:"Não compreenderam que lhes falava do Pai."},
{v:28,t:"Disse-lhes, pois, Jesus: Quando levantardes o Filho do Homem, então conhecereis que eu sou, e que nada faço por mim mesmo; mas falo o que o Pai me ensinou.",n:"Levantar tem, no quarto evangelho, os dois sentidos ao mesmo tempo: erguer na cruz e exaltar na glória. É o mesmo verbo, e São João nunca escolhe entre os dois."},
{v:29,t:"E aquele que me enviou está comigo; não me deixou sozinho, porque faço sempre o que lhe agrada."},
{v:30,t:"Dizendo ele essas coisas, muitos creram nele."}
];

EV[108] = [
{p:"João 8:31-59"},
{v:31,t:"Dizia, pois, Jesus aos judeus que nele creram: Se permanecerdes na minha palavra, sereis verdadeiramente meus discípulos;",n:"O diálogo mais áspero dos evangelhos começa com os que acabaram de crer. Não é uma discussão com adversários declarados: é com discípulos recentes, e é isso que a torna mais dura."},
{v:32,t:"e conhecereis a verdade, e a verdade vos libertará."},
{v:33,t:"Responderam-lhe: Somos descendência de Abraão e jamais fomos escravos de ninguém; como dizes tu: Vós vos tornareis livres?",n:"Jamais fomos escravos é dito por um povo que guardava todos os anos a memória da escravidão no Egito, e que naquele momento vivia sob ocupação romana. A frase desmente-se sozinha, e é esse o ponto."},
{v:34,t:"Jesus lhes respondeu: Em verdade, em verdade vos digo: todo o que comete o pecado é escravo do pecado."},
{v:35,t:"Ora, o escravo não permanece na casa para sempre; o filho permanece para sempre."},
{v:36,t:"Se, pois, o Filho vos libertar, sereis verdadeiramente livres."},
{v:37,t:"Sei que sois descendência de Abraão; mas procurais matar-me, porque a minha palavra não penetra em vós."},
{v:38,t:"Eu falo o que vi junto de meu Pai; e vós fazeis o que ouvistes de vosso pai."},
{v:39,t:"Responderam-lhe: Nosso pai é Abraão. Disse-lhes Jesus: Se sois filhos de Abraão, fazei as obras de Abraão.",n:"A distinção é a mesma que São Paulo fará na Carta aos Romanos: descendência não é o mesmo que filiação. Ser filho, na linguagem semítica, é parecer-se — e é pelas obras que se prova de quem se é filho."},
{v:40,t:"Mas agora procurais matar-me, a mim, homem que vos disse a verdade que ouvi de Deus; isso Abraão não fez."},
{v:41,t:"Vós fazeis as obras de vosso pai. Disseram-lhe, pois: Nós não nascemos de prostituição; temos um só pai: Deus."},
{v:42,t:"Disse-lhes Jesus: Se Deus fosse vosso Pai, certamente me amaríeis, pois eu saí de Deus e venho dele; não vim por mim mesmo, mas foi ele que me enviou."},
{v:43,t:"Por que não compreendeis a minha linguagem? Porque não podeis ouvir a minha palavra."},
{v:44,t:"Vós sois do pai, o diabo, e quereis realizar os desejos do vosso pai. Ele foi homicida desde o princípio e não permaneceu na verdade, porque não há verdade nele. Quando fala a mentira, fala do que lhe é próprio, porque é mentiroso e pai da mentira.",n:"Nota do tradutor: é o versículo mais duro do Novo Testamento, e foi dos mais usados na história do antissemitismo. Traduz-se sem atenuação, e registram-se duas coisas. A primeira é o destinatário: a frase é dita, dentro de uma disputa entre judeus, aos interlocutores concretos daquela discussão — os mesmos que o versículo 31 diz terem crido nele —, e não a um povo. A segunda é o critério: o que se imputa não é a origem, mas a intenção de matar, declarada no versículo 40. Ler o versículo como sentença sobre uma raça é contrariar o argumento de que faz parte, e é o que a Igreja declarou expressamente no Concílio Vaticano II."},
{v:45,t:"Mas, porque eu digo a verdade, não credes em mim."},
{v:46,t:"Quem de vós me convence de pecado? Se digo a verdade, por que não credes em mim?"},
{v:47,t:"Quem é de Deus ouve as palavras de Deus; por isso vós não ouvis, porque não sois de Deus."},
{v:48,t:"Responderam os judeus e lhe disseram: Não dizemos bem que tu és samaritano e tens um demônio?",n:"Samaritano era injúria corrente: dizia herege e estrangeiro ao mesmo tempo. Jesus responde à segunda acusação e deixa a primeira sem resposta."},
{v:49,t:"Respondeu Jesus: Eu não tenho demônio, mas honro meu Pai; e vós me desonrais."},
{v:50,t:"Eu, porém, não busco a minha glória; há quem a busque e julgue."},
{v:51,t:"Em verdade, em verdade vos digo: se alguém guardar a minha palavra, não verá jamais a morte."},
{v:52,t:"Disseram-lhe, pois, os judeus: Agora sabemos que tens um demônio. Abraão morreu, e também os profetas; e tu dizes: Se alguém guardar a minha palavra, não provará jamais a morte."},
{v:53,t:"És tu, porventura, maior do que nosso pai Abraão, que morreu? E os profetas morreram. Quem pretendes ser?"},
{v:54,t:"Respondeu Jesus: Se eu me glorifico a mim mesmo, a minha glória nada é; quem me glorifica é meu Pai, aquele de quem dizeis que é vosso Deus."},
{v:55,t:"E vós não o conheceis; eu, porém, o conheço. E, se disser que não o conheço, serei mentiroso como vós; mas eu o conheço e guardo a sua palavra."},
{v:56,t:"Abraão, vosso pai, exultou por ver o meu dia; viu-o e alegrou-se."},
{v:57,t:"Disseram-lhe, pois, os judeus: Ainda não tens cinquenta anos, e viste Abraão?"},
{v:58,t:"Disse-lhes Jesus: Em verdade, em verdade vos digo: antes que Abraão existisse, eu sou.",n:"A frase quebra a gramática de propósito: esperava-se eu era, e vem eu sou. Não se diz que existiu antes de Abraão — diz-se que é, num presente que não conhece antes nem depois. É a afirmação mais explícita do quarto evangelho, e o versículo seguinte mostra que os ouvintes a entenderam perfeitamente."},
{v:59,t:"Então pegaram em pedras para as atirar contra ele; mas Jesus escondeu-se e saiu do templo."}
];

EV[109] = [
{p:"João 9:1-41"},
{v:1,t:"E, ao passar, viu um homem cego de nascença.",n:"O capítulo inteiro é construído como um processo, com interrogatórios sucessivos, testemunhas convocadas e uma sentença de expulsão. E tem um movimento duplo: o cego vê cada vez melhor quem é Jesus — o homem chamado Jesus, um profeta, um enviado de Deus, o Senhor —, enquanto os que interrogam ficam cada vez mais cegos."},
{v:2,t:"E os seus discípulos lhe perguntaram: Rabi, quem pecou, este ou os seus pais, para que nascesse cego?",n:"A pergunta supõe a doutrina corrente da retribuição: toda desgraça tem uma culpa atrás. A hipótese de que o próprio cego tivesse pecado antes de nascer discutia-se a sério entre os rabinos."},
{v:3,t:"Respondeu Jesus: Nem este pecou, nem os seus pais; mas foi para que nele se manifestassem as obras de Deus.",n:"A resposta corta a pergunta em vez de a responder: recusa procurar a causa e aponta a finalidade. Não se diz que Deus o fez cego para se mostrar — diz-se que é ali, e não em nenhum passado, que se há de olhar."},
{v:4,t:"É necessário que façamos as obras daquele que me enviou, enquanto é dia; vem a noite, quando ninguém pode trabalhar."},
{v:5,t:"Enquanto estou no mundo, sou a luz do mundo."},
{v:6,t:"Tendo dito isso, cuspiu na terra, fez lodo com a saliva e aplicou-lhe o lodo sobre os olhos,",n:"Amassar era uma das trinta e nove obras proibidas no sábado. O gesto não era necessário à cura — é escolhido, e é ele que desencadeia todo o processo. Os Padres viram no barro a matéria de que o homem foi formado no Gênesis: o que faltava ao cego não é curado, é criado."},
{v:7,t:"e disse-lhe: Vai, lava-te na piscina de Siloé — que se traduz: Enviado. Ele foi, lavou-se e voltou vendo.",n:"Siloé é a piscina donde se tirava a água derramada sobre o altar na festa dos Tabernáculos, de que se falou no tópico 105. E o evangelista faz questão de traduzir o nome: Enviado é como São João chama Jesus ao longo de todo o evangelho."},
{v:8,t:"Então os vizinhos e os que antes o tinham visto pedir esmola diziam: Não é este o que se sentava e pedia esmola?"},
{v:9,t:"Uns diziam: É ele. Outros: Não, mas é parecido com ele. Ele dizia: Sou eu."},
{v:10,t:"Diziam-lhe, pois: Como se te abriram os olhos?"},
{v:11,t:"Respondeu ele: O homem chamado Jesus fez lodo, ungiu os meus olhos e disse-me: Vai a Siloé e lava-te. Fui, lavei-me e vi."},
{v:12,t:"E disseram-lhe: Onde está ele? Respondeu: Não sei."},
{v:13,t:"Levaram aos fariseus aquele que fora cego."},
{v:14,t:"Ora, era sábado o dia em que Jesus fizera o lodo e lhe abrira os olhos."},
{v:15,t:"De novo, pois, os fariseus lhe perguntaram como recobrara a vista. E ele lhes disse: Pôs-me lodo sobre os olhos, lavei-me e vejo."},
{v:16,t:"Diziam, pois, alguns dos fariseus: Este homem não é de Deus, porque não guarda o sábado. Outros diziam: Como pode um homem pecador fazer tais sinais? E havia divisão entre eles."},
{v:17,t:"Disseram, pois, de novo ao cego: Tu, que dizes daquele que te abriu os olhos? Ele disse: É um profeta."},
{v:18,t:"Os judeus, porém, não acreditaram que ele tivesse sido cego e recobrado a vista, até que chamaram os pais do que recobrara a vista."},
{v:19,t:"E os interrogaram, dizendo: É este o vosso filho, que dizeis ter nascido cego? Como, pois, vê ele agora?"},
{v:20,t:"Responderam os seus pais e disseram: Sabemos que este é o nosso filho e que nasceu cego;"},
{v:21,t:"mas como agora vê, não sabemos; e quem lhe abriu os olhos, nós não sabemos. Perguntai a ele; tem idade, ele falará de si mesmo.",n:"Os pais confirmam apenas o que não lhes custa nada e devolvem a pergunta ao filho. É um retrato da prudência que se cala, e o evangelista explica-o no versículo seguinte sem o desculpar."},
{v:22,t:"Isso disseram os seus pais porque temiam os judeus; pois já os judeus tinham combinado que, se alguém o confessasse como o Cristo, fosse expulso da sinagoga.",n:"A exclusão da sinagoga por confessar Jesus só se tornou prática geral algumas décadas depois, e muitos veem aqui o reflexo da situação da comunidade para a qual São João escrevia. O episódio é contado com as palavras do tempo em que foi escrito."},
{v:23,t:"Por isso os seus pais disseram: Tem idade; perguntai a ele."},
{v:24,t:"Chamaram, pois, segunda vez o homem que fora cego e lhe disseram: Dá glória a Deus; nós sabemos que esse homem é pecador.",n:"Dá glória a Deus era fórmula judicial de juramento: exigia-se que dissesse a verdade. Usam-na para lhe ditar a resposta."},
{v:25,t:"Respondeu ele: Se é pecador, não sei; uma coisa sei: eu era cego e agora vejo.",n:"A resposta não discute teologia: firma-se no que aconteceu. É das frases mais citadas do evangelho, e a sua força está em não afirmar mais do que se sabe."},
{v:26,t:"Disseram-lhe, pois: Que te fez ele? Como te abriu os olhos?"},
{v:27,t:"Respondeu-lhes: Já vos disse isso, e não ouvistes. Por que quereis ouvi-lo de novo? Acaso também vós quereis tornar-vos discípulos dele?",n:"O homem passa da defesa à ironia, e é o que lhe custa a expulsão. É o único personagem dos evangelhos que discute com os doutores e os vence sozinho."},
{v:28,t:"E o insultaram, dizendo: Tu é que és discípulo dele; nós somos discípulos de Moisés."},
{v:29,t:"Nós sabemos que Deus falou a Moisés; mas este, não sabemos donde é."},
{v:30,t:"Respondeu o homem e disse-lhes: Nisto está o admirável: que vós não saibais donde ele é, e no entanto me abriu os olhos."},
{v:31,t:"Sabemos que Deus não ouve os pecadores; mas, se alguém é religioso e faz a sua vontade, a esse ouve."},
{v:32,t:"Desde que o mundo é mundo, nunca se ouviu que alguém abrisse os olhos a um cego de nascença."},
{v:33,t:"Se este não fosse de Deus, nada poderia fazer."},
{v:34,t:"Responderam e lhe disseram: Tu nasceste todo em pecados, e nos ensinas a nós? E o expulsaram.",n:"Voltam à doutrina do versículo 2, que Jesus acabara de recusar, e usam-na como insulto. Não tendo argumento, invocam a origem — e expulsam."},
{v:35,t:"Jesus ouviu que o tinham expulsado e, encontrando-o, disse: Crês tu no Filho do Homem?",n:"Jesus procura-o justamente depois da expulsão. O homem é achado por quem o curou no momento em que perde tudo o que tinha por causa disso."},
{v:36,t:"Respondeu ele: E quem é, Senhor, para que eu creia nele?"},
{v:37,t:"Disse-lhe Jesus: Tu já o viste; é aquele que fala contigo.",n:"Tu já o viste: dito a quem era cego de nascença e o vê pela primeira vez. Em todo o quarto evangelho, só a ele e à samaritana Jesus se dá a conhecer assim, de modo direto."},
{v:38,t:"E ele disse: Creio, Senhor. E prostrou-se diante dele."},
{v:39,t:"E disse Jesus: Eu vim a este mundo para um juízo: para que os que não veem, vejam; e os que veem, se tornem cegos."},
{v:40,t:"Ouviram isso alguns dos fariseus que estavam com ele e disseram-lhe: Acaso também nós somos cegos?"},
{v:41,t:"Respondeu-lhes Jesus: Se fôsseis cegos, não teríeis pecado; mas agora dizeis: Vemos. O vosso pecado permanece.",n:"O capítulo fecha invertendo o que abriu. A cegueira de nascença não era culpa de ninguém; a que se escolhe, sim. E o que a torna incurável é precisamente a pretensão de ver."}
];

EV[110] = [
{p:"João 10:1-21"},
{v:1,t:"Em verdade, em verdade vos digo: quem não entra pela porta no redil das ovelhas, mas sobe por outra parte, esse é ladrão e salteador.",n:"O discurso continua a cena anterior, sem corte: os pastores que acabam de expulsar da sinagoga um homem por ter recobrado a vista são o pano de fundo. Por trás está o capítulo 34 de Ezequiel, contra os pastores de Israel que apascentavam a si mesmos."},
{v:2,t:"Mas quem entra pela porta é o pastor das ovelhas."},
{v:3,t:"A este o porteiro abre, e as ovelhas ouvem a sua voz; e ele chama pelo nome as suas ovelhas e as conduz para fora.",n:"Chamar pelo nome era, e ainda é, o costume dos pastores da Palestina: vários rebanhos passavam a noite no mesmo redil, e de manhã cada pastor separava o seu apenas pela voz, sem tocar nas ovelhas."},
{v:4,t:"Quando faz sair todas as suas, vai adiante delas; e as ovelhas o seguem, porque conhecem a sua voz."},
{v:5,t:"Mas a um estranho não seguirão; antes fugirão dele, porque não conhecem a voz dos estranhos."},
{v:6,t:"Jesus disse-lhes essa comparação; eles, porém, não compreenderam o que lhes dizia."},
{v:7,t:"Disse-lhes, pois, Jesus de novo: Em verdade, em verdade vos digo: eu sou a porta das ovelhas.",n:"A imagem muda: ele era o pastor, e agora é a porta. Não é incoerência — nos currais de pedra do campo não havia portão, e o pastor deitava-se atravessado na entrada. Era ele, com o corpo, a porta."},
{v:8,t:"Todos quantos vieram antes de mim são ladrões e salteadores; mas as ovelhas não os ouviram."},
{v:9,t:"Eu sou a porta. Se alguém entrar por mim, será salvo; e entrará, sairá e encontrará pastagem."},
{v:10,t:"O ladrão não vem senão para roubar, matar e destruir. Eu vim para que tenham vida, e a tenham em abundância."},
{v:11,t:"Eu sou o bom pastor. O bom pastor dá a sua vida pelas ovelhas.",n:"Bom traduz kalos, que diz também belo e nobre — não é o pastor competente, é o pastor como deve ser. E o que o define não é a habilidade nem o afeto: é morrer pelo rebanho, coisa que nenhum pastor real faria, porque as ovelhas não valem um homem."},
{v:12,t:"O mercenário, que não é pastor e a quem as ovelhas não pertencem, vê vir o lobo, abandona as ovelhas e foge — e o lobo as arrebata e dispersa —,"},
{v:13,t:"porque é mercenário e não se importa com as ovelhas."},
{v:14,t:"Eu sou o bom pastor; conheço as minhas, e as minhas me conhecem,"},
{v:15,t:"assim como o Pai me conhece e eu conheço o Pai; e dou a minha vida pelas ovelhas.",n:"A comparação é vertiginosa: o conhecimento entre o pastor e as ovelhas é posto na mesma frase, e na mesma medida, que o conhecimento entre o Pai e o Filho."},
{v:16,t:"Tenho ainda outras ovelhas, que não são deste redil; também a essas é necessário que eu conduza, e ouvirão a minha voz; e haverá um só rebanho e um só pastor.",n:"Um só rebanho, e não um só redil: a distinção importa, e a Vulgata antiga, ao traduzir ovile, deu origem a séculos de leitura no sentido de um só aprisco. A unidade prometida não é a de um cercado, é a de quem ouve a mesma voz."},
{v:17,t:"Por isso o Pai me ama: porque eu dou a minha vida, para de novo a receber."},
{v:18,t:"Ninguém a tira de mim, mas eu a dou por mim mesmo. Tenho poder de a dar e poder de a receber de novo. Este mandamento recebi de meu Pai.",n:"Dito meses antes da Paixão, e é a chave com que o quarto evangelho a lê: o que há de acontecer não será um homem vencido, mas um dom. Nenhum dos outros evangelhos o formula assim."},
{v:19,t:"Houve de novo divisão entre os judeus por causa dessas palavras."},
{v:20,t:"Muitos deles diziam: Tem um demônio e está louco; por que o ouvis?"},
{v:21,t:"Outros diziam: Estas palavras não são de quem tem demônio. Pode, porventura, um demônio abrir os olhos aos cegos?",n:"O argumento que fecha o discurso é o milagre do capítulo anterior. Os dois capítulos são, também por aqui, uma só cena."}
];

EV[111] = [
{p:"Mateus 19:1-2"},
{v:1,t:"E aconteceu que, tendo Jesus acabado estas palavras, partiu da Galileia e veio para as regiões da Judeia, além do Jordão."},
{v:2,t:"E seguiram-no grandes multidões, e ele as curou ali."},
{p:"Marcos 10:1"},
{v:1,t:"Levantando-se dali, foi para as regiões da Judeia, além do Jordão; e de novo se reuniram multidões junto dele; e, como costumava, de novo as ensinava."},
{p:"Lucas 9:51-56"},
{v:51,t:"Aconteceu que, ao completarem-se os dias da sua assunção, ele firmou o rosto para ir a Jerusalém.",n:"É o eixo do evangelho de São Lucas: a partir deste versículo, tudo o que se conta passa-se num caminho, e o caminho vai dar à cruz. Assunção traduz analempsis, o ser levado ao alto; e firmou o rosto é a expressão do servo de Isaías 50, que endurece o rosto como pedra para não recuar."},
{v:52,t:"E enviou mensageiros adiante de si; e eles, tendo partido, entraram numa aldeia de samaritanos, para lhe preparar pousada."},
{v:53,t:"Mas não o receberam, porque o seu rosto estava voltado para Jerusalém.",n:"Samaritanos e judeus disputavam havia séculos qual era o monte do culto verdadeiro: o Garizim ou Sião. Quem ia em peregrinação a Jerusalém era, pelo próprio destino da viagem, um adversário."},
{v:54,t:"Vendo isso, os discípulos Tiago e João disseram: Senhor, queres que mandemos descer fogo do céu e os consuma?",n:"É o que Elias fizera na Samaria, no segundo livro dos Reis, e os dois irmãos sabem-no. Alguns manuscritos acrescentam aqui a referência expressa a Elias e uma resposta mais longa; as testemunhas mais antigas trazem apenas a repreensão seca do versículo seguinte."},
{v:55,t:"Mas ele, voltando-se, repreendeu-os."},
{v:56,t:"E foram para outra aldeia.",n:"O capítulo 10 começará com um samaritano por herói, e no livro dos Atos a Samaria será a primeira terra evangelizada fora de Jerusalém. São Lucas prepara isso desde aqui."}
];

EV[112] = [
{p:"Lucas 9:57-62"},
{v:57,t:"Enquanto iam pelo caminho, alguém lhe disse: Hei de seguir-te para onde quer que fores."},
{v:58,t:"E disse-lhe Jesus: As raposas têm covis, e as aves do céu, ninhos; mas o Filho do Homem não tem onde reclinar a cabeça."},
{v:59,t:"E disse a outro: Segue-me. Mas ele respondeu: Senhor, permite-me ir primeiro enterrar meu pai."},
{v:60,t:"Jesus lhe disse: Deixa que os mortos enterrem os seus mortos; tu, porém, vai e anuncia o Reino de Deus."},
{v:61,t:"Outro ainda disse: Hei de seguir-te, Senhor; mas permite-me primeiro despedir-me dos de minha casa.",n:"É exatamente o que Eliseu pede a Elias, no primeiro livro dos Reis, e que Elias lhe concede. Aqui não se concede — e a diferença entre os dois episódios é o argumento."},
{v:62,t:"E Jesus lhe disse: Ninguém que põe a mão no arado e olha para trás é apto para o Reino de Deus.",n:"Quem arava conduzia o arado com uma mão e a junta com a outra; bastava virar a cabeça para o sulco sair torto. A imagem não é de nostalgia proibida, é de trabalho estragado."}
];

EV[113] = [
{p:"Lucas 10:1-24"},
{v:1,t:"Depois disso, designou o Senhor outros setenta e dois e enviou-os dois a dois adiante de si, a toda cidade e lugar aonde ele havia de ir.",n:"Os manuscritos dividem-se entre setenta e setenta e dois, e a Nova Vulgata lê setenta e dois. Os dois números remetem ao capítulo 10 do Gênesis, que conta as nações da terra — setenta no texto hebraico, setenta e dois no grego. Depois dos Doze, que eram as tribos de Israel, este segundo envio tem a medida do mundo."},
{v:2,t:"E dizia-lhes: A messe é grande, mas os trabalhadores são poucos. Rogai, pois, ao Senhor da messe que envie trabalhadores para a sua messe."},
{v:3,t:"Ide; eis que vos envio como cordeiros no meio de lobos."},
{v:4,t:"Não leveis bolsa, nem alforje, nem sandálias; e a ninguém saudeis pelo caminho.",n:"A saudação oriental era demorada, com perguntas pela casa inteira. A proibição não é descortesia: é a pressa de quem leva uma notícia que não espera — a mesma ordem que Eliseu dá ao seu servo em missão urgente."},
{v:5,t:"Em qualquer casa em que entrardes, dizei primeiro: Paz a esta casa."},
{v:6,t:"E, se ali houver um filho da paz, a vossa paz repousará sobre ele; se não, voltará para vós.",n:"Filho da paz é hebraísmo: quem é digno dela, quem a acolhe. E a paz é tratada como coisa real, que pousa ou regressa — não como fórmula de cortesia."},
{v:7,t:"Ficai na mesma casa, comendo e bebendo do que tiverem, porque o trabalhador é digno do seu salário. Não passeis de casa em casa."},
{v:8,t:"E, em qualquer cidade em que entrardes e vos receberem, comei o que vos puserem diante"},
{v:9,t:"e curai os enfermos que nela houver, e dizei-lhes: Está próximo de vós o Reino de Deus."},
{v:10,t:"Mas, em qualquer cidade em que entrardes e não vos receberem, saindo pelas suas praças, dizei:"},
{v:11,t:"Até o pó da vossa cidade, que se nos pegou aos pés, sacudimos contra vós; sabei, contudo, isto: está próximo o Reino de Deus.",n:"A mesma notícia é dada nas duas cidades, na que acolhe e na que recusa. O que muda não é o anúncio — é o que ele significa para cada uma."},
{v:12,t:"Digo-vos que naquele dia haverá menos rigor para Sodoma do que para aquela cidade."},
{v:13,t:"Ai de ti, Corazin! Ai de ti, Betsaida! Porque, se em Tiro e Sidônia se tivessem feito os milagres que em vós se fizeram, há muito, sentadas em cilício e cinza, teriam feito penitência."},
{v:14,t:"Contudo, no juízo haverá menos rigor para Tiro e Sidônia do que para vós."},
{v:15,t:"E tu, Cafarnaum, acaso serás elevada até ao céu? Até ao abismo descerás."},
{v:16,t:"Quem vos ouve, a mim me ouve; e quem vos rejeita, a mim me rejeita; e quem me rejeita, rejeita aquele que me enviou."},
{v:17,t:"Voltaram os setenta e dois com alegria, dizendo: Senhor, até os demônios se nos submetem em teu nome."},
{v:18,t:"E ele lhes disse: Eu via Satanás cair do céu como um raio.",n:"O tempo do verbo grego indica algo visto enquanto acontecia. Não é profecia do futuro nem lembrança de um mito antigo: é o que se dá enquanto setenta e dois homens vão pelas aldeias anunciando o Reino."},
{v:19,t:"Eis que vos dei poder de pisar sobre serpentes e escorpiões, e sobre todo o poder do inimigo; e nada vos fará dano."},
{v:20,t:"Contudo, não vos alegreis porque os espíritos se vos submetem; alegrai-vos antes porque os vossos nomes estão escritos nos céus.",n:"A correção é delicada e vai ao fundo: o motivo da alegria não pode ser o que se consegue fazer, mas o que se é. O primeiro depende do êxito; o segundo, não."},
{v:21,t:"Naquela hora, exultou no Espírito Santo e disse: Eu te louvo, Pai, Senhor do céu e da terra, porque escondeste estas coisas aos sábios e prudentes e as revelaste aos pequeninos. Sim, Pai, porque assim foi do teu agrado.",n:"É o mesmo passo que São Mateus traz no tópico 85. Só São Lucas diz que Jesus exultou, e é a única vez em todo o Novo Testamento que se atribui alegria ao próprio Cristo."},
{v:22,t:"Tudo me foi entregue por meu Pai; e ninguém conhece quem é o Filho senão o Pai, nem quem é o Pai senão o Filho, e aquele a quem o Filho o quiser revelar."},
{v:23,t:"E, voltando-se para os discípulos, disse em particular: Bem-aventurados os olhos que veem o que vós vedes."},
{v:24,t:"Porque eu vos digo que muitos profetas e reis desejaram ver o que vós vedes, e não viram; e ouvir o que ouvis, e não ouviram."}
];

EV[114] = [
{p:"Lucas 10:25-37"},
{v:25,t:"E eis que um doutor da lei se levantou, para o pôr à prova, dizendo: Mestre, que farei para herdar a vida eterna?"},
{v:26,t:"E ele lhe disse: Que está escrito na lei? Como lês?",n:"Jesus não responde: devolve a pergunta, e devolve-a ao próprio terreno do perguntador. O doutor da lei acaba por dar sozinho a resposta certa, e é por isso que precisa depois de justificar-se."},
{v:27,t:"Ele respondeu: Amarás o Senhor teu Deus de todo o teu coração, de toda a tua alma, com todas as tuas forças e com toda a tua mente; e ao teu próximo como a ti mesmo."},
{v:28,t:"Disse-lhe Jesus: Respondeste corretamente; faze isso e viverás."},
{v:29,t:"Mas ele, querendo justificar-se, disse a Jesus: E quem é o meu próximo?",n:"A pergunta procura um limite: até onde vai a obrigação. A parábola não lhe responde — inverte-a. No fim, a pergunta já não é quem é o meu próximo, mas de quem me fiz próximo, e essa não tem limite nenhum."},
{v:30,t:"Tomando a palavra, Jesus disse: Um homem descia de Jerusalém para Jericó e caiu nas mãos de salteadores, que o despojaram, o espancaram e foram embora, deixando-o meio morto.",n:"A estrada descia mil metros em vinte e sete quilômetros, por desfiladeiros desertos, e tinha fama justificada de perigosa. O homem não é identificado: nem judeu, nem estrangeiro, nem justo, nem pecador — está despido e meio morto, e é tudo o que se sabe dele."},
{v:31,t:"Por acaso, descia um sacerdote por aquele caminho e, vendo-o, passou ao largo.",n:"O contato com um cadáver tornava impuro, e um sacerdote impuro não podia exercer o seu ministério. Os dois que passam ao largo têm, portanto, uma razão da lei para o fazer. A parábola não a discute: deixa-a em pé, e mostra o resultado."},
{v:32,t:"Do mesmo modo, um levita, chegando àquele lugar e vendo-o, passou ao largo."},
{v:33,t:"Mas um samaritano, que ia de viagem, chegou perto dele e, vendo-o, compadeceu-se;",n:"O auditório esperava, depois do sacerdote e do levita, um leigo israelita — era assim que se dividia o povo. Vem um samaritano, isto é, um herege e um inimigo. Contada a um doutor da lei de Jerusalém, a escolha é quase insultuosa."},
{v:34,t:"e, aproximando-se, atou-lhe as feridas, deitando nelas azeite e vinho; e, pondo-o sobre a sua própria montaria, levou-o a uma hospedaria e cuidou dele."},
{v:35,t:"No dia seguinte, tirou dois denários, deu-os ao hospedeiro e disse: Cuida dele; e o que gastares a mais, eu te pagarei quando voltar.",n:"Dois denários pagavam cerca de duas semanas de hospedagem. E o crédito aberto sem limite é o pormenor mais caro da parábola: o samaritano não só socorre, como fica responsável."},
{v:36,t:"Qual destes três te parece ter sido o próximo daquele que caiu nas mãos dos salteadores?"},
{v:37,t:"Ele disse: Aquele que usou de misericórdia para com ele. E Jesus lhe disse: Vai e faze tu o mesmo.",n:"O doutor da lei não consegue dizer a palavra samaritano, e responde por rodeio. É o último pormenor da cena, e São Lucas não o comenta."}
];

EV[115] = [
{p:"Lucas 10:38-42"},
{v:38,t:"Enquanto iam de caminho, entrou ele numa aldeia; e certa mulher, chamada Marta, o recebeu em sua casa."},
{v:39,t:"Tinha ela uma irmã chamada Maria, a qual, sentada aos pés do Senhor, ouvia a sua palavra.",n:"Sentar-se aos pés de um mestre é a expressão técnica para ser seu discípulo — São Paulo diz que se sentou aos pés de Gamaliel. A mulheres não se ensinava a Lei, e a cena, antes de qualquer outra coisa, mostra Maria no lugar de um discípulo, sem que ninguém a mande sair dele."},
{v:40,t:"Marta, porém, andava ocupada com muito serviço. Aproximando-se, disse: Senhor, não te importa que minha irmã me deixe servir sozinha? Dize-lhe, pois, que me ajude."},
{v:41,t:"Respondendo, disse-lhe o Senhor: Marta, Marta, andas inquieta e te preocupas com muitas coisas;",n:"A repetição do nome é, na Escritura, sinal de ternura e de chamamento — Abraão, Abraão; Samuel, Samuel; Simão, Simão. A resposta não é uma reprimenda seca."},
{v:42,t:"mas uma só é necessária. Maria escolheu a melhor parte, que não lhe será tirada.",n:"Não se condena o serviço: São Lucas é o evangelista que mais insiste nele, e a parábola do samaritano vem imediatamente antes. O que se diz é que a inquietação com muitas coisas não é a mesma coisa que servir, e que há uma ordem entre ouvir e fazer."}
];

EV[116] = [
{p:"João 10:22-42"},
{v:22,t:"Celebrava-se então em Jerusalém a festa da Dedicação. Era inverno,",n:"A Dedicação, em hebraico Hanucá, celebra a purificação do templo por Judas Macabeu, em 164 antes de Cristo, depois de ter sido profanado. Dura oito dias em dezembro e acendem-se luzes. É a única festa judaica de instituição não bíblica que os evangelhos mencionam."},
{v:23,t:"e Jesus passeava no templo, no pórtico de Salomão."},
{v:24,t:"Rodearam-no, pois, os judeus e lhe diziam: Até quando nos deixarás em suspenso? Se tu és o Cristo, dize-o abertamente."},
{v:25,t:"Respondeu-lhes Jesus: Eu vos disse, e não credes. As obras que eu faço em nome de meu Pai, essas dão testemunho de mim."},
{v:26,t:"Mas vós não credes, porque não sois das minhas ovelhas."},
{v:27,t:"As minhas ovelhas ouvem a minha voz; eu as conheço, e elas me seguem."},
{v:28,t:"E eu lhes dou a vida eterna, e jamais perecerão, e ninguém as arrebatará da minha mão."},
{v:29,t:"O que meu Pai me deu é maior do que tudo, e ninguém o pode arrebatar da mão do Pai."},
{v:30,t:"Eu e o Pai somos um.",n:"O grego diz uma coisa só, no neutro, e não um só, no masculino: não se afirma que sejam uma só pessoa, mas que são um na obra e no poder de que se acabou de falar. Foi sobre esta distinção que se travaram as controvérsias dos primeiros séculos, e os ouvintes, no versículo seguinte, entendem que se disse o bastante para apedrejar."},
{v:31,t:"De novo os judeus pegaram em pedras para o apedrejar."},
{v:32,t:"Respondeu-lhes Jesus: Muitas obras boas vos mostrei, vindas do Pai; por qual delas me apedrejais?"},
{v:33,t:"Responderam-lhe os judeus: Não te apedrejamos por obra boa, mas por blasfêmia; porque tu, sendo homem, te fazes Deus."},
{v:34,t:"Respondeu-lhes Jesus: Não está escrito na vossa lei: Eu disse: sois deuses?",n:"A citação é do Salmo 82, versículo 6, já traduzido aqui. O argumento é do tipo que os rabinos chamavam do menor para o maior: se a Escritura pôde chamar deuses a juízes injustos, não é blasfêmia que se chame Filho de Deus aquele a quem o Pai enviou."},
{v:35,t:"Se chamou deuses àqueles a quem foi dirigida a palavra de Deus — e a Escritura não pode ser anulada —,"},
{v:36,t:"àquele que o Pai santificou e enviou ao mundo dizeis vós: Blasfemas, porque disse: Sou Filho de Deus?"},
{v:37,t:"Se não faço as obras de meu Pai, não creiais em mim."},
{v:38,t:"Mas, se as faço, ainda que não creiais em mim, crede nas obras, para que conheçais e reconheçais que o Pai está em mim, e eu no Pai.",n:"Oferece-se um caminho mais baixo a quem não pode dar o passo maior: crede ao menos no que vedes fazer. É a única vez em que Jesus propõe começar pelas obras, quando a pessoa não consegue começar por ele."},
{v:39,t:"Procuravam, pois, de novo prendê-lo; mas ele escapou-lhes das mãos."},
{v:40,t:"E foi de novo para além do Jordão, ao lugar onde João primeiro batizava; e ali ficou."},
{v:41,t:"E muitos vieram a ele e diziam: João, na verdade, não fez sinal algum; mas tudo o que João disse deste homem era verdade.",n:"O epitáfio do Batista é feito por gente anônima e diz duas coisas: não fez milagres, e não errou em nada. São João fecha assim o seu ministério público, no mesmo lugar onde o começara."},
{v:42,t:"E muitos ali creram nele."}
];

EV[117] = [
{p:"Lucas 11:1-13"},
{v:1,t:"E aconteceu que, estando ele orando em certo lugar, quando acabou, um dos seus discípulos lhe disse: Senhor, ensina-nos a orar, como também João ensinou aos seus discípulos.",n:"Cada mestre dava aos seus uma oração própria, que os identificava. O pedido é, portanto, também um pedido de identidade: dá-nos a oração que nos faça teus."},
{v:2,t:"E ele lhes disse: Quando orardes, dizei: Pai, santificado seja o teu nome; venha o teu Reino;",n:"A versão de São Lucas é mais curta do que a de São Mateus, traduzida no tópico 53: faltam-lhe duas petições, e começa por Pai, sem mais. É provavelmente a forma mais antiga. Pai traduz aqui o aramaico Abbá, que São Paulo conserva sem traduzir nas suas cartas — palavra da intimidade familiar, que nenhum judeu usaria para falar a Deus."},
{v:3,t:"dá-nos cada dia o nosso pão cotidiano;",n:"Cotidiano verte epiousios, palavra que não existe em nenhum outro texto grego conhecido, e que os tradutores discutem desde São Jerônimo. Pode querer dizer o necessário para subsistir, o de cada dia, ou o do dia que vem. A Vulgata traduz de um modo em São Mateus e de outro em São Lucas, sinal de que a dificuldade é antiga."},
{v:4,t:"e perdoa-nos os nossos pecados, pois também nós perdoamos a todo o que nos deve; e não nos deixes cair em tentação."},
{v:5,t:"E disse-lhes: Qual de vós, tendo um amigo, irá a ele à meia-noite e lhe dirá: Amigo, empresta-me três pães,"},
{v:6,t:"pois um amigo meu chegou de viagem à minha casa, e não tenho o que lhe oferecer;"},
{v:7,t:"e ele, de dentro, responderá: Não me incomodes; a porta já está fechada, e os meus filhos estão comigo na cama; não posso levantar-me para te dar?",n:"A casa de um camponês era de uma só divisão, e a família dormia toda no mesmo estrado. Levantar-se significava acordar todos. E a recusa da hospitalidade a um viajante era, naquela sociedade, quase impensável — o que dá toda a força ao absurdo da cena."},
{v:8,t:"Eu vos digo: ainda que não se levante para lhe dar os pães por ser seu amigo, há de levantar-se e dar-lhe quanto precisar por causa da sua importunidade.",n:"Importunidade traduz anaideia, que à letra é falta de vergonha. Não se elogia a insistência como virtude: descreve-se o que faz alguém que não tem outro recurso, e diz-se que também assim se obtém."},
{v:9,t:"E eu vos digo: pedi, e recebereis; buscai, e achareis; batei, e a porta vos será aberta."},
{v:10,t:"Porque todo o que pede, recebe; e quem busca, acha; e a quem bate, será aberto."},
{v:11,t:"Qual de vós, sendo pai, se o filho lhe pedir um peixe, em vez de peixe lhe dará uma serpente?"},
{v:12,t:"Ou, se lhe pedir um ovo, lhe dará um escorpião?",n:"Os pares são escolhidos pela semelhança: uma enguia parece um peixe, e o escorpião branco, enrolado, parece um ovo. O pai mau não daria pedras — daria coisas que se parecem com o que se pediu."},
{v:13,t:"Se, pois, vós, sendo maus, sabeis dar boas dádivas aos vossos filhos, quanto mais o Pai do céu dará o Espírito Santo aos que o pedirem.",n:"Onde São Mateus diz coisas boas, São Lucas diz o Espírito Santo. É a substituição mais significativa que faz a um texto comum: o dom que se promete a quem pede não é uma coisa, é Deus mesmo."}
];

EV[118] = [
{p:"Lucas 11:33-36"},
{v:33,t:"Ninguém acende uma lâmpada e a põe em lugar escondido nem debaixo do alqueire, mas no candelabro, para que os que entram vejam a luz."},
{v:34,t:"A lâmpada do corpo é o teu olho. Quando o teu olho é simples, todo o teu corpo é luminoso; mas, quando é mau, também o teu corpo é tenebroso.",n:"Simples traduz haplous, que diz o que não tem dobras — o olhar indiviso —, e em grego da época também o generoso. O olho mau era, na linguagem judaica, a inveja e a avareza. A frase fala de visão e de mesquinhez ao mesmo tempo."},
{v:35,t:"Vê, pois, que a luz que há em ti não seja trevas."},
{v:36,t:"Se, pois, todo o teu corpo for luminoso, sem ter parte alguma tenebrosa, será todo luminoso, como quando a lâmpada te ilumina com o seu fulgor."}
];

EV[119] = [
{p:"Lucas 11:37-54"},
{v:37,t:"Enquanto falava, um fariseu convidou-o para almoçar em sua casa; e ele entrou e pôs-se à mesa."},
{v:38,t:"O fariseu, vendo isso, admirou-se de que ele não se tivesse lavado antes do almoço."},
{v:39,t:"Mas o Senhor lhe disse: Vós, fariseus, limpais o exterior do copo e do prato, mas o vosso interior está cheio de rapina e de maldade."},
{v:40,t:"Insensatos! Aquele que fez o exterior não fez também o interior?"},
{v:41,t:"Dai antes em esmola o que está dentro, e eis que tudo será puro para vós.",n:"Frase difícil, que admite duas leituras: dai em esmola o conteúdo dos pratos, em vez de vos preocupardes com a louça; ou dai a partir do interior, do coração. Em ambas, a pureza deixa de ser coisa de superfície e passa a ser coisa de dar."},
{v:42,t:"Mas ai de vós, fariseus, que pagais o dízimo da hortelã, da arruda e de toda hortaliça, e deixais de lado a justiça e o amor de Deus! Estas coisas era preciso praticar, sem deixar de lado aquelas."},
{v:43,t:"Ai de vós, fariseus, que amais os primeiros assentos nas sinagogas e as saudações nas praças!"},
{v:44,t:"Ai de vós, que sois como os sepulcros que não se veem, sobre os quais os homens andam sem o saber!",n:"Pisar um sepulcro tornava impuro, e por isso se caiavam as sepulturas antes das festas, para que ninguém se contaminasse sem querer. O sepulcro sem marca contamina quem passa, sem que ninguém perceba."},
{v:45,t:"Então um dos doutores da lei, tomando a palavra, disse-lhe: Mestre, dizendo isso, também a nós nos ofendes."},
{v:46,t:"Ele disse: Ai de vós também, doutores da lei, porque carregais os homens com fardos insuportáveis, e vós mesmos nem com um dedo tocais os fardos!"},
{v:47,t:"Ai de vós, que edificais os sepulcros dos profetas, e foram os vossos pais que os mataram!"},
{v:48,t:"Assim, sois testemunhas e aprovais as obras de vossos pais: porque eles os mataram, e vós edificais os seus sepulcros."},
{v:49,t:"Por isso também disse a Sabedoria de Deus: Hei de enviar-lhes profetas e apóstolos, e a alguns deles matarão e perseguirão,"},
{v:50,t:"para que se peça conta a esta geração do sangue de todos os profetas, derramado desde a criação do mundo,"},
{v:51,t:"desde o sangue de Abel até ao sangue de Zacarias, que pereceu entre o altar e o santuário. Sim, eu vos digo: será pedida conta a esta geração.",n:"Abel é o primeiro homem assassinado na Escritura, no Gênesis; Zacarias, o último, no fim do segundo livro das Crônicas, que era o último livro da Bíblia hebraica. De A a Z, diríamos: todo o sangue justo, do primeiro livro ao último."},
{v:52,t:"Ai de vós, doutores da lei, que tomastes a chave da ciência! Vós mesmos não entrastes, e impedistes os que queriam entrar."},
{v:53,t:"Quando ele saiu dali, os escribas e os fariseus começaram a pressioná-lo fortemente e a provocá-lo a falar sobre muitas coisas,"},
{v:54,t:"armando-lhe ciladas, para apanharem alguma palavra da sua boca."}
];

EV[120] = [
{p:"Lucas 12:1-12"},
{v:1,t:"Entretanto, tendo-se reunido multidões aos milhares, a ponto de se pisarem uns aos outros, começou a dizer, primeiro aos seus discípulos: Acautelai-vos do fermento dos fariseus, que é a hipocrisia."},
{v:2,t:"Nada há encoberto que não venha a ser descoberto, nem oculto que não venha a ser conhecido."},
{v:3,t:"Por isso, tudo o que dissestes nas trevas será ouvido à luz; e o que falastes ao ouvido, nos quartos, será proclamado sobre os telhados."},
{v:4,t:"Digo-vos a vós, meus amigos: não temais os que matam o corpo e depois disso nada mais podem fazer.",n:"Meus amigos: é a única vez nos sinóticos que Jesus chama assim aos discípulos. E vem justamente antes de lhes falar em morte."},
{v:5,t:"Vou mostrar-vos a quem deveis temer: temei aquele que, depois de matar, tem poder de lançar na geena. Sim, eu vos digo: a este temei."},
{v:6,t:"Não se vendem cinco passarinhos por dois asses? E nenhum deles é esquecido diante de Deus.",n:"São Mateus dizia dois por um asse; São Lucas, cinco por dois — quem comprava duas porções levava uma de brinde. Nem o passarinho que se dava de graça, e que não valia nada, é esquecido."},
{v:7,t:"Até os cabelos da vossa cabeça estão todos contados. Não temais: mais valeis vós do que muitos passarinhos."},
{v:8,t:"Eu vos digo: todo aquele que me confessar diante dos homens, também o Filho do Homem o confessará diante dos anjos de Deus;"},
{v:9,t:"mas quem me negar diante dos homens será negado diante dos anjos de Deus."},
{v:10,t:"E a todo aquele que disser uma palavra contra o Filho do Homem, será perdoado; mas a quem blasfemar contra o Espírito Santo não será perdoado."},
{v:11,t:"Quando vos levarem às sinagogas, aos magistrados e às autoridades, não vos preocupeis com o modo como vos defendereis nem com o que haveis de dizer;"},
{v:12,t:"porque o Espírito Santo vos ensinará naquela mesma hora o que deveis dizer."}
];

EV[121] = [
{p:"Lucas 12:13-34"},
{v:13,t:"Alguém da multidão lhe disse: Mestre, dize a meu irmão que reparta comigo a herança."},
{v:14,t:"Ele lhe respondeu: Homem, quem me constituiu juiz ou partidor entre vós?",n:"Pedir a um rabi que arbitrasse questões de herança era comum. A recusa é a frase que os hebreus disseram a Moisés no Egito — quem te constituiu chefe e juiz sobre nós? —, e Jesus toma-a para si: não veio repartir heranças, veio mudar o que se deseja herdar."},
{v:15,t:"E disse-lhes: Olhai e guardai-vos de toda avareza, porque a vida de um homem não consiste na abundância dos bens que possui."},
{v:16,t:"E contou-lhes uma parábola, dizendo: O campo de um homem rico produziu muito."},
{v:17,t:"E ele pensava consigo mesmo: Que farei, pois não tenho onde recolher os meus frutos?"},
{v:18,t:"E disse: Farei isto: derrubarei os meus celeiros e construirei maiores, e ali recolherei todo o meu trigo e os meus bens;"},
{v:19,t:"e direi à minha alma: Alma, tens muitos bens guardados para muitos anos; descansa, come, bebe e regala-te.",n:"O homem só fala consigo mesmo: meus celeiros, meus frutos, minha alma. Em toda a parábola não aparece mais ninguém — nem família, nem trabalhadores, nem pobres — até que Deus fale."},
{v:20,t:"Mas Deus lhe disse: Insensato! Esta noite te pedirão a tua alma; e o que preparaste, para quem será?",n:"Pedirão está no plural impessoal e usa o verbo de quem reclama um empréstimo. A vida era emprestada, e o credor cobra-a de volta."},
{v:21,t:"Assim é o que entesoura para si mesmo e não é rico diante de Deus."},
{v:22,t:"E disse aos seus discípulos: Por isso vos digo: não vos preocupeis com a vossa vida, quanto ao que haveis de comer, nem com o corpo, quanto ao que haveis de vestir."},
{v:23,t:"A vida é mais do que o alimento, e o corpo mais do que a roupa."},
{v:24,t:"Olhai os corvos: não semeiam nem colhem, não têm despensa nem celeiro, e Deus os alimenta. Quanto mais valeis vós do que as aves!",n:"Onde São Mateus diz as aves do céu, São Lucas diz os corvos — ave impura segundo o Levítico, a que ninguém daria valor. Até esses Deus alimenta."},
{v:25,t:"Qual de vós, por mais que se preocupe, pode acrescentar um côvado à duração da sua vida?"},
{v:26,t:"Se, pois, nem o mínimo podeis, por que vos preocupais com o resto?"},
{v:27,t:"Olhai os lírios, como crescem: não trabalham nem fiam; e eu vos digo que nem Salomão, em toda a sua glória, se vestiu como um deles."},
{v:28,t:"Se, pois, Deus assim veste a erva que hoje está no campo e amanhã é lançada no forno, quanto mais a vós, homens de pouca fé!"},
{v:29,t:"Também vós não procureis o que haveis de comer ou beber, nem andeis inquietos."},
{v:30,t:"Porque são os gentios do mundo que procuram todas estas coisas; e vosso Pai sabe que precisais delas."},
{v:31,t:"Buscai antes o seu Reino, e estas coisas vos serão acrescentadas."},
{v:32,t:"Não temas, pequeno rebanho, porque aprouve a vosso Pai dar-vos o Reino.",n:"Pequeno rebanho: a expressão está no diminutivo em grego, e é das mais ternas do evangelho. O Reino não é prêmio de quem o conquista, é dom de quem quis dá-lo."},
{v:33,t:"Vendei o que possuís e dai esmola. Fazei para vós bolsas que não envelhecem, um tesouro inesgotável nos céus, aonde o ladrão não chega e a traça não destrói."},
{v:34,t:"Porque, onde está o vosso tesouro, ali estará também o vosso coração."}
];

EV[122] = [
{p:"Lucas 12:35-59"},
{v:35,t:"Estejam cingidos os vossos rins e acesas as vossas lâmpadas.",n:"Cingir os rins era prender a túnica comprida no cinto para poder andar depressa ou trabalhar. É a ordem dada a Israel na noite da Páscoa: comei-a com os rins cingidos, prontos para partir."},
{v:36,t:"Sede semelhantes a homens que esperam o seu senhor quando volta das bodas, para lhe abrirem logo que chegar e bater."},
{v:37,t:"Felizes aqueles servos que o senhor, ao chegar, encontrar vigiando! Em verdade vos digo que ele se cingirá, os fará sentar à mesa e, passando, os servirá.",n:"Nenhum senhor da antiguidade servia os seus servos. A parábola inverte a ordem social no meio da frase, e é a mesma inversão que o lava-pés há de encenar."},
{v:38,t:"E, se chegar na segunda vigília ou na terceira e assim os encontrar, felizes serão eles."},
{v:39,t:"Sabei, porém, isto: se o dono da casa soubesse a que hora havia de vir o ladrão, não deixaria arrombar a sua casa."},
{v:40,t:"Vós também estai preparados, porque na hora em que não pensais virá o Filho do Homem."},
{v:41,t:"Disse-lhe então Pedro: Senhor, dizes esta parábola para nós ou também para todos?"},
{v:42,t:"E o Senhor disse: Quem é, pois, o administrador fiel e prudente, que o senhor porá à frente da sua criadagem, para lhes dar a ração de trigo a seu tempo?",n:"A resposta à pergunta de Pedro é outra pergunta. A parábola é para todos, mas pesa mais sobre quem recebeu encargo sobre os outros — é o que dizem os versículos 47 e 48."},
{v:43,t:"Feliz aquele servo que o seu senhor, ao chegar, encontrar fazendo assim!"},
{v:44,t:"Em verdade vos digo que o porá à frente de todos os seus bens."},
{v:45,t:"Mas, se aquele servo disser no seu coração: O meu senhor demora a vir; e começar a espancar os criados e as criadas, e a comer, a beber e a embriagar-se,"},
{v:46,t:"virá o senhor daquele servo no dia em que não o espera e na hora que não sabe, e o separará, e lhe dará a sorte dos infiéis."},
{v:47,t:"O servo que conheceu a vontade do seu senhor e não se preparou nem agiu segundo a sua vontade receberá muitos açoites;"},
{v:48,t:"mas o que não a conheceu e fez coisas dignas de açoites receberá poucos. A quem muito foi dado, muito se pedirá; e a quem muito se confiou, mais se lhe exigirá."},
{v:49,t:"Eu vim lançar fogo sobre a terra, e como desejaria que já estivesse aceso!"},
{v:50,t:"Tenho de receber um batismo, e como me angustio até que se cumpra!",n:"Batismo é aqui a Paixão, como na resposta aos filhos de Zebedeu: ser mergulhado. É dos raros versículos em que Jesus fala do que sente diante do que o espera, e o que diz é angústia."},
{v:51,t:"Pensais que vim trazer paz à terra? Não, eu vos digo, mas divisão."},
{v:52,t:"Porque, daqui em diante, estarão cinco divididos numa casa: três contra dois, e dois contra três;"},
{v:53,t:"estarão divididos o pai contra o filho e o filho contra o pai, a mãe contra a filha e a filha contra a mãe, a sogra contra a nora e a nora contra a sogra."},
{v:54,t:"Dizia também às multidões: Quando vedes subir uma nuvem do poente, logo dizeis: Vem chuva; e assim acontece."},
{v:55,t:"E, quando sopra o vento do sul, dizeis: Haverá calor; e assim acontece.",n:"Na Palestina o poente é o Mediterrâneo, donde vem a chuva, e o sul é o deserto, donde vem o vento quente. Os ouvintes liam o céu com toda a exatidão."},
{v:56,t:"Hipócritas, sabeis discernir o aspecto da terra e do céu; como é que não discernis este tempo?"},
{v:57,t:"E por que não julgais por vós mesmos o que é justo?"},
{v:58,t:"Quando fores com o teu adversário ao magistrado, procura, no caminho, livrar-te dele, para que não te arraste ao juiz, e o juiz te entregue ao oficial de justiça, e o oficial de justiça te lance na prisão."},
{v:59,t:"Digo-te que não sairás de lá enquanto não pagares o último centavo."}
];

EV[123] = [
{p:"Lucas 13:1-9"},
{v:1,t:"Naquele mesmo tempo, estavam presentes alguns que lhe contavam o caso dos galileus cujo sangue Pilatos misturara com o dos seus sacrifícios.",n:"O episódio não é conhecido por outra fonte, mas combina com o que o historiador Flávio Josefo conta de Pilatos, que mais de uma vez mandou massacrar multidões. Galileus mortos no templo, enquanto ofereciam sacrifícios, pelo governador romano."},
{v:2,t:"E ele lhes respondeu: Pensais que esses galileus eram mais pecadores do que todos os outros galileus, por terem sofrido tal coisa?"},
{v:3,t:"Não, eu vos digo; mas, se não vos converterdes, perecereis todos do mesmo modo."},
{v:4,t:"Ou aqueles dezoito sobre os quais caiu a torre de Siloé e os matou: pensais que eram mais culpados do que todos os outros habitantes de Jerusalém?",n:"Os dois casos são escolhidos pelo contraste: um é violência política, o outro um desastre sem culpado. A resposta é a mesma para os dois, e recusa nas duas vezes a pergunta pela culpa dos mortos, para a voltar para os vivos."},
{v:5,t:"Não, eu vos digo; mas, se não vos converterdes, perecereis todos da mesma maneira."},
{v:6,t:"E contou esta parábola: Um homem tinha uma figueira plantada na sua vinha; e veio procurar fruto nela, e não o encontrou."},
{v:7,t:"Disse então ao vinhateiro: Eis que há três anos venho procurar fruto nesta figueira e não o encontro. Corta-a; por que há de ocupar ainda a terra inutilmente?"},
{v:8,t:"Mas ele respondeu: Senhor, deixa-a ainda este ano, até que eu cave ao redor dela e lhe deite adubo."},
{v:9,t:"Talvez dê fruto no futuro; se não, tu a cortarás.",n:"A parábola acaba sem desfecho: não se diz se a figueira deu fruto nem se foi cortada. O ano concedido é o tempo em que o ouvinte está."}
];

EV[124] = [
{p:"Lucas 13:10-17"},
{v:10,t:"Estava ele ensinando numa das sinagogas, num sábado."},
{v:11,t:"E eis que estava ali uma mulher que havia dezoito anos tinha um espírito que a tornava enferma; andava encurvada e não podia de modo algum endireitar-se."},
{v:12,t:"Vendo-a, Jesus chamou-a e disse-lhe: Mulher, estás livre da tua enfermidade."},
{v:13,t:"E impôs-lhe as mãos; e ela logo se endireitou e glorificava a Deus."},
{v:14,t:"Mas o chefe da sinagoga, indignado porque Jesus curara em dia de sábado, dizia à multidão: Há seis dias em que se deve trabalhar; vinde, pois, nesses dias para serdes curados, e não em dia de sábado.",n:"O chefe da sinagoga não se dirige a Jesus: fala à multidão, e repreende a vítima em vez de quem a curou."},
{v:15,t:"Respondeu-lhe o Senhor: Hipócritas! Cada um de vós não solta da manjedoura, no sábado, o seu boi ou o seu jumento, e não o leva a beber?"},
{v:16,t:"E esta filha de Abraão, que Satanás tinha presa havia dezoito anos, não devia ser solta desta prisão em dia de sábado?",n:"Filha de Abraão é expressão que não aparece em nenhum outro lugar da Escritura. O argumento joga com o verbo soltar: se se solta o animal para beber, quanto mais esta. E o Deuteronômio funda o sábado precisamente na libertação do Egito."},
{v:17,t:"Dizendo ele isso, todos os seus adversários ficavam envergonhados; e toda a multidão se alegrava com todas as coisas gloriosas que ele fazia."}
];

EV[125] = [
{p:"Lucas 13:18-30"},
{v:18,t:"Dizia, pois: A que é semelhante o Reino de Deus, e a que o compararei?"},
{v:19,t:"É semelhante a um grão de mostarda que um homem tomou e lançou na sua horta; cresceu e tornou-se árvore, e as aves do céu fizeram ninho nos seus ramos."},
{v:20,t:"E disse ainda: A que compararei o Reino de Deus?"},
{v:21,t:"É semelhante ao fermento que uma mulher tomou e escondeu em três medidas de farinha, até ficar tudo levedado."},
{v:22,t:"E ia passando pelas cidades e aldeias, ensinando e caminhando para Jerusalém."},
{v:23,t:"Alguém lhe perguntou: Senhor, são poucos os que se salvam? Ele lhes disse:"},
{v:24,t:"Esforçai-vos por entrar pela porta estreita, porque muitos, eu vos digo, procurarão entrar e não conseguirão.",n:"A pergunta pede um número e a resposta dá uma ordem: não se diz quantos, diz-se o que fazer. Esforçai-vos traduz agonizesthe, o verbo do atleta na competição, donde vem agonia."},
{v:25,t:"Quando o dono da casa se tiver levantado e fechado a porta, e vós, ficando de fora, começardes a bater à porta, dizendo: Senhor, abre-nos!, ele vos responderá: Não sei donde sois."},
{v:26,t:"Então começareis a dizer: Comemos e bebemos na tua presença, e tu ensinaste nas nossas praças."},
{v:27,t:"E ele vos dirá: Não sei donde sois; afastai-vos de mim, todos os que praticais a iniquidade."},
{v:28,t:"Ali haverá choro e ranger de dentes, quando virdes Abraão, Isaac e Jacó e todos os profetas no Reino de Deus, e vós lançados fora."},
{v:29,t:"E virão do oriente e do ocidente, do norte e do sul, e hão de sentar-se à mesa no Reino de Deus."},
{v:30,t:"E eis que há últimos que serão primeiros, e primeiros que serão últimos."}
];

EV[126] = [
{p:"Lucas 13:31-35"},
{v:31,t:"Naquela mesma hora, aproximaram-se alguns fariseus, dizendo-lhe: Sai e vai-te daqui, porque Herodes quer matar-te."},
{v:32,t:"Ele lhes disse: Ide dizer a essa raposa: Eis que expulso demônios e faço curas hoje e amanhã, e no terceiro dia chego ao fim.",n:"Raposa era, na linguagem dos rabinos, o bicho pequeno e astuto, por oposição ao leão: é tratar Herodes de manhoso e de menor. E chego ao fim traduz teleioumai, sou levado à consumação — da mesma raiz de tudo está consumado, a última palavra na cruz segundo São João."},
{v:33,t:"Contudo, é necessário que eu siga o meu caminho hoje, amanhã e depois de amanhã, porque não convém que um profeta pereça fora de Jerusalém."},
{v:34,t:"Jerusalém, Jerusalém, que matas os profetas e apedrejas os que te são enviados! Quantas vezes quis reunir os teus filhos, como a galinha reúne a sua ninhada debaixo das asas, e não quiseste!",n:"A imagem da ave que abriga os filhos sob as asas é a que o Deuteronômio e os salmos usam para Deus. Jesus toma-a para si, e escolhe a ave mais doméstica e menos heroica de todas."},
{v:35,t:"Eis que a vossa casa vos ficará abandonada. E eu vos digo que não me vereis até que venha o dia em que digais: Bendito o que vem em nome do Senhor!",n:"É o versículo 26 do Salmo 118, que a multidão há de gritar, poucos capítulos adiante, na entrada em Jerusalém."}
];

EV[127] = [
{p:"Lucas 14:1-15"},
{v:1,t:"Aconteceu que, tendo ele entrado, num sábado, na casa de um dos chefes dos fariseus para comer, eles o observavam."},
{v:2,t:"E eis que diante dele estava um homem hidrópico."},
{v:3,t:"Tomando a palavra, Jesus disse aos doutores da lei e aos fariseus: É lícito ou não curar no sábado?"},
{v:4,t:"Eles, porém, calaram-se. E ele, tomando o homem, curou-o e despediu-o."},
{v:5,t:"E disse-lhes: Qual de vós, se o filho ou o boi lhe cair num poço, não o tirará logo, mesmo em dia de sábado?",n:"Parte dos manuscritos lê o jumento ou o boi, que é a dupla habitual; a Nova Vulgata segue os que leem o filho ou o boi, leitura mais difícil e por isso provavelmente original. O argumento sobe do animal ao filho, e ninguém lhe responde."},
{v:6,t:"E não lhe puderam responder a isso."},
{v:7,t:"Observando como os convidados escolhiam os primeiros lugares, contou-lhes uma parábola, dizendo:"},
{v:8,t:"Quando fores convidado por alguém para umas bodas, não te sentes no primeiro lugar, para que não aconteça que tenha sido convidado alguém mais digno do que tu,"},
{v:9,t:"e, vindo o que te convidou a ti e a ele, te diga: Dá o lugar a este; e então, envergonhado, vás ocupar o último lugar."},
{v:10,t:"Mas, quando fores convidado, vai sentar-te no último lugar, para que, quando vier o que te convidou, te diga: Amigo, sobe mais para cima. Então terás honra diante de todos os que estiverem contigo à mesa.",n:"O conselho está em Provérbios 25, quase à letra. Mas não é lição de etiqueta: o versículo seguinte dá-lhe a medida do Reino, onde quem distribui os lugares é outro."},
{v:11,t:"Porque todo o que se exalta será humilhado, e o que se humilha será exaltado."},
{v:12,t:"E dizia também ao que o tinha convidado: Quando deres um almoço ou um jantar, não chames os teus amigos, nem os teus irmãos, nem os teus parentes, nem os vizinhos ricos, para que não aconteça que também eles te convidem por sua vez e tenhas a recompensa."},
{v:13,t:"Mas, quando deres um banquete, chama os pobres, os aleijados, os coxos e os cegos;",n:"A lista é a mesma dos que a regra de Qumran excluía da assembleia dos santos, e a mesma que o dono da casa manda buscar na parábola seguinte. Os excluídos de todas as mesas são os convidados desta."},
{v:14,t:"e serás feliz, porque eles não têm com que te retribuir; e serás retribuído na ressurreição dos justos."},
{v:15,t:"Ouvindo isso, um dos que estavam com ele à mesa disse-lhe: Feliz aquele que comer o pão no Reino de Deus!"}
];

EV[128] = [
{p:"Lucas 14:16-24"},
{v:16,t:"Ele, porém, lhe disse: Um homem deu um grande jantar e convidou muitos."},
{v:17,t:"E, à hora do jantar, enviou o seu servo a dizer aos convidados: Vinde, porque tudo já está pronto.",n:"Era costume convidar duas vezes: primeiro para o dia, depois, quando tudo estava pronto, para a hora. Quem recusa o segundo convite já tinha aceitado o primeiro."},
{v:18,t:"E todos, à uma, começaram a desculpar-se. O primeiro disse-lhe: Comprei um campo e preciso ir vê-lo; peço-te que me dês por desculpado.",n:"As desculpas são de propósito inverossímeis: ninguém compra um campo sem o ver, nem cinco juntas de bois sem as experimentar. Quem as ouvia percebia que eram pretextos."},
{v:19,t:"Outro disse: Comprei cinco juntas de bois e vou experimentá-las; peço-te que me dês por desculpado."},
{v:20,t:"E outro disse: Casei-me, e por isso não posso ir."},
{v:21,t:"O servo voltou e contou isso ao seu senhor. Então, irado, o dono da casa disse ao servo: Sai depressa pelas praças e ruas da cidade e traze aqui os pobres, os aleijados, os cegos e os coxos."},
{v:22,t:"Disse o servo: Senhor, fez-se o que mandaste, e ainda há lugar."},
{v:23,t:"E o senhor disse ao servo: Sai pelos caminhos e pelas cercas e obriga-os a entrar, para que a minha casa se encha.",n:"Nota do tradutor: obriga-os a entrar, em latim compelle intrare, foi invocado por Santo Agostinho, e depois dele durante séculos, para justificar a coação em matéria de fé. O texto não o diz. No Oriente, o pobre convidado por um rico recusava por decoro, e era preciso insistir e levá-lo pela mão; é essa a obrigação de que se fala — a da hospitalidade que não aceita recusa, e não a da força."},
{v:24,t:"Porque eu vos digo que nenhum daqueles homens que foram convidados provará o meu jantar."}
];

EV[129] = [
{p:"Lucas 14:25-35"},
{v:25,t:"Iam com ele grandes multidões; e, voltando-se, disse-lhes:"},
{v:26,t:"Se alguém vem a mim e não odeia seu pai, sua mãe, sua mulher, seus filhos, seus irmãos e suas irmãs, e até a própria vida, não pode ser meu discípulo.",n:"Odiar é, no hebraico, o modo de dizer preferir menos: no Gênesis, Jacó odiava Lia, e o texto explica que amava mais a Raquel. São Mateus traduz a mesma frase por quem ama o pai mais do que a mim. Conserva-se a palavra dura, que é a que São Lucas escreveu, e diz-se aqui o que ela quer dizer."},
{v:27,t:"E quem não carrega a sua cruz e não vem após mim não pode ser meu discípulo."},
{v:28,t:"Pois qual de vós, querendo construir uma torre, não se senta primeiro para calcular a despesa e ver se tem com que acabá-la?"},
{v:29,t:"Para que não aconteça que, depois de lançar os alicerces e não podendo acabá-la, todos os que o virem comecem a zombar dele,"},
{v:30,t:"dizendo: Este homem começou a construir e não pôde acabar."},
{v:31,t:"Ou qual é o rei que, indo guerrear contra outro rei, não se senta primeiro a considerar se com dez mil pode enfrentar o que vem contra ele com vinte mil?"},
{v:32,t:"Do contrário, enquanto o outro ainda está longe, envia-lhe uma embaixada e pede as condições de paz."},
{v:33,t:"Assim, pois, qualquer de vós que não renuncia a tudo o que possui não pode ser meu discípulo.",n:"As duas parábolas pedem cálculo, e a conclusão parece virar a lógica: calcula-se para concluir que é preciso dar tudo. Quem faz as contas com honestidade descobre que não tem com que acabar a torre por si."},
{v:34,t:"Bom é o sal; mas, se o sal se tornar insípido, com que se há de temperar?"},
{v:35,t:"Não é útil nem para a terra nem para o esterco; lançam-no fora. Quem tem ouvidos para ouvir, ouça."}
];

EV[130] = [
{p:"Lucas 15:1-7"},
{v:1,t:"Aproximavam-se dele todos os publicanos e pecadores para o ouvir."},
{v:2,t:"E os fariseus e os escribas murmuravam, dizendo: Este recebe pecadores e come com eles.",n:"As três parábolas do capítulo 15 são uma só resposta a este murmúrio. Cada uma acaba numa festa, e a terceira acaba com alguém que não quer entrar nela."},
{v:3,t:"Então lhes contou esta parábola, dizendo:"},
{v:4,t:"Qual de vós, tendo cem ovelhas e perdendo uma delas, não deixa as noventa e nove no deserto e vai atrás da perdida até encontrá-la?"},
{v:5,t:"E, quando a encontra, põe-na sobre os ombros, cheio de alegria,"},
{v:6,t:"e, chegando a casa, reúne os amigos e vizinhos e diz-lhes: Alegrai-vos comigo, porque encontrei a minha ovelha que estava perdida."},
{v:7,t:"Digo-vos que assim haverá mais alegria no céu por um só pecador que se converte do que por noventa e nove justos que não precisam de conversão."}
];

EV[131] = [
{p:"Lucas 15:8-10"},
{v:8,t:"Ou qual é a mulher que, tendo dez dracmas e perdendo uma, não acende a lâmpada, varre a casa e a procura cuidadosamente até encontrá-la?",n:"A dracma valia um dia de trabalho. As casas pobres não tinham janela, e o chão era de terra batida: procurar uma moeda era varrer às cegas. A parábola põe, sem comentário, uma mulher a fazer as vezes de Deus."},
{v:9,t:"E, quando a encontra, reúne as amigas e vizinhas, dizendo: Alegrai-vos comigo, porque encontrei a dracma que tinha perdido."},
{v:10,t:"Assim, eu vos digo, há alegria diante dos anjos de Deus por um só pecador que se converte."}
];

EV[132] = [
{p:"Lucas 15:11-32"},
{v:11,t:"Disse ainda: Um homem tinha dois filhos."},
{v:12,t:"O mais novo disse ao pai: Pai, dá-me a parte dos bens que me cabe. E ele repartiu entre eles os seus haveres.",n:"Pedir a herança em vida do pai equivalia, nos costumes da época, a desejar-lhe a morte. O pai não discute: dá, e dá aos dois."},
{v:13,t:"Poucos dias depois, o filho mais novo, juntando tudo, partiu para uma terra distante e ali dissipou os seus bens, vivendo dissolutamente."},
{v:14,t:"Depois de ter gastado tudo, sobreveio uma grande fome naquela terra, e ele começou a passar necessidade."},
{v:15,t:"Foi então pôr-se ao serviço de um dos cidadãos daquela terra, que o mandou para os seus campos guardar porcos.",n:"Guardar porcos, animal impuro, para um estrangeiro, era para um judeu o último degrau: dizia-se entre os rabinos maldito quem cria porcos."},
{v:16,t:"E desejava encher o estômago com as alfarrobas que os porcos comiam, mas ninguém lhe dava nada."},
{v:17,t:"Caindo em si, disse: Quantos empregados de meu pai têm pão em abundância, e eu aqui morro de fome!"},
{v:18,t:"Vou levantar-me, irei ter com meu pai e lhe direi: Pai, pequei contra o céu e diante de ti;"},
{v:19,t:"já não sou digno de ser chamado teu filho; trata-me como a um dos teus empregados."},
{v:20,t:"E, levantando-se, foi ter com seu pai. Estando ele ainda longe, seu pai viu-o, encheu-se de compaixão, correu, lançou-se ao seu pescoço e cobriu-o de beijos.",n:"Um homem velho e honrado, no Oriente, não corria: tinha de levantar a túnica e expor as pernas, o que era vergonhoso. O pai faz a coisa indigna antes que o filho diga uma palavra."},
{v:21,t:"E o filho lhe disse: Pai, pequei contra o céu e diante de ti; já não sou digno de ser chamado teu filho.",n:"O filho não chega a acabar o discurso que ensaiara: falta-lhe a última frase, trata-me como a um dos teus empregados. O pai interrompe-o antes."},
{v:22,t:"Mas o pai disse aos seus servos: Trazei depressa a melhor túnica e vesti-o; ponde-lhe um anel no dedo e sandálias nos pés.",n:"A túnica é a de honra; o anel, o do selo, que dá autoridade sobre os bens; as sandálias, a marca do homem livre — os escravos andavam descalços. As três coisas desfazem, uma a uma, o que o filho pedira para ser."},
{v:23,t:"Trazei o novilho cevado e matai-o; comamos e façamos festa,"},
{v:24,t:"porque este meu filho estava morto e voltou à vida; estava perdido e foi encontrado. E começaram a festejar."},
{v:25,t:"Ora, o filho mais velho estava no campo. Quando voltou e se aproximou da casa, ouviu a música e as danças."},
{v:26,t:"E, chamando um dos criados, perguntou-lhe o que era aquilo."},
{v:27,t:"Este lhe disse: Teu irmão voltou, e teu pai mandou matar o novilho cevado, porque o recuperou com saúde."},
{v:28,t:"Ele indignou-se e não queria entrar. Então o pai saiu e insistia com ele.",n:"O pai sai de casa duas vezes, uma por cada filho. A segunda saída é tão humilhante quanto a primeira corrida: o dono da casa deixa os convidados para ir rogar a um filho que não quer entrar."},
{v:29,t:"Mas ele respondeu ao pai: Há tantos anos que te sirvo sem nunca transgredir uma ordem tua, e nunca me deste um cabrito para eu fazer festa com os meus amigos."},
{v:30,t:"Mas, quando veio este teu filho, que devorou os teus bens com prostitutas, mandaste matar para ele o novilho cevado.",n:"Este teu filho: o mais velho não diz meu irmão. E o pai, no versículo 32, devolve-lhe a palavra que recusou — este teu irmão."},
{v:31,t:"Disse-lhe o pai: Filho, tu estás sempre comigo, e tudo o que é meu é teu."},
{v:32,t:"Mas era preciso fazer festa e alegrar-se, porque este teu irmão estava morto e voltou à vida; estava perdido e foi encontrado.",n:"A parábola acaba sem se saber se o filho mais velho entrou. Os que ouviam eram os fariseus do versículo 2, que murmuravam por Jesus comer com pecadores: o fim fica em aberto porque são eles que têm de decidir."}
];

EV[133] = [
{p:"Lucas 16:1-17"},
{v:1,t:"Dizia também aos discípulos: Havia um homem rico que tinha um administrador, e este foi denunciado a ele como quem dissipava os seus bens."},
{v:2,t:"Chamou-o e disse-lhe: Que é isto que ouço dizer de ti? Presta contas da tua administração, porque já não podes ser administrador."},
{v:3,t:"Disse então o administrador consigo mesmo: Que farei, pois o meu senhor me tira a administração? Cavar, não tenho forças; mendigar, tenho vergonha."},
{v:4,t:"Já sei o que hei de fazer, para que, quando for afastado da administração, haja quem me receba em sua casa."},
{v:5,t:"E, chamando um a um os devedores do seu senhor, disse ao primeiro: Quanto deves ao meu senhor?"},
{v:6,t:"Ele respondeu: Cem medidas de azeite. Disse-lhe: Toma a tua conta, senta-te depressa e escreve cinquenta."},
{v:7,t:"Depois disse a outro: E tu, quanto deves? Ele respondeu: Cem medidas de trigo. Disse-lhe: Toma a tua conta e escreve oitenta."},
{v:8,t:"E o senhor louvou o administrador desonesto, por ter agido com esperteza; porque os filhos deste mundo são mais espertos com os da sua geração do que os filhos da luz.",n:"A parábola mais embaraçosa dos evangelhos. O que se louva não é a desonestidade — o administrador continua a ser chamado desonesto —, mas a lucidez de quem, sabendo que vai perder tudo, usa o que ainda tem nas mãos para garantir o futuro. Senhor pode ser o patrão da história ou o próprio Jesus: o grego diz kyrios, e os dois sentidos são possíveis."},
{v:9,t:"E eu vos digo: fazei amigos com o dinheiro da iniquidade, para que, quando ele vos faltar, vos recebam nas moradas eternas.",n:"Dinheiro traduz mamona, palavra aramaica que São Lucas conserva e que designa a riqueza tratada como coisa a que se serve. É iníquo não por ser mal ganho, mas por prometer o que não pode dar."},
{v:10,t:"Quem é fiel no mínimo é fiel também no muito; e quem é injusto no mínimo é injusto também no muito."},
{v:11,t:"Se, pois, não fostes fiéis no dinheiro iníquo, quem vos confiará o verdadeiro bem?"},
{v:12,t:"E, se não fostes fiéis no que era alheio, quem vos dará o que é vosso?"},
{v:13,t:"Nenhum servo pode servir a dois senhores: ou há de odiar um e amar o outro, ou há de dedicar-se a um e desprezar o outro. Não podeis servir a Deus e ao dinheiro."},
{v:14,t:"Os fariseus, que eram amigos do dinheiro, ouviam tudo isso e zombavam dele."},
{v:15,t:"E disse-lhes: Vós sois os que vos justificais diante dos homens, mas Deus conhece os vossos corações; porque o que é elevado entre os homens é abominação diante de Deus."},
{v:16,t:"A Lei e os Profetas duraram até João; desde então é anunciado o Reino de Deus, e cada um se esforça para entrar nele."},
{v:17,t:"É mais fácil passarem o céu e a terra do que cair um só traço da Lei."}
];

EV[134] = [
{p:"Lucas 16:19-31"},
{v:19,t:"Havia um homem rico que se vestia de púrpura e linho fino e se banqueteava esplendidamente todos os dias.",n:"O rico não tem nome; a tradição latina chamou-lhe Dives, que é simplesmente rico em latim. O pobre é o único personagem de todas as parábolas que tem nome: Lázaro, forma grega de Eleazar, Deus ajuda."},
{v:20,t:"E um pobre, chamado Lázaro, jazia à sua porta, coberto de chagas,"},
{v:21,t:"desejando saciar-se com o que caía da mesa do rico; e até os cães vinham lamber-lhe as chagas."},
{v:22,t:"Aconteceu que morreu o pobre e foi levado pelos anjos ao seio de Abraão; morreu também o rico e foi sepultado."},
{v:23,t:"E, no abismo, estando em tormentos, levantou os olhos e viu ao longe Abraão, e Lázaro no seu seio."},
{v:24,t:"E, clamando, disse: Pai Abraão, tem piedade de mim e manda Lázaro molhar na água a ponta do dedo para me refrescar a língua, porque estou atormentado nesta chama.",n:"Mesmo no tormento, o rico continua a tratar Lázaro como um criado que se pode mandar. Sabia-lhe o nome — e nunca lhe abrira a porta."},
{v:25,t:"Mas Abraão lhe disse: Filho, lembra-te de que recebeste os teus bens em vida, e Lázaro, igualmente, os males; agora, porém, ele aqui é consolado, e tu és atormentado."},
{v:26,t:"E, além de tudo isso, entre nós e vós está firmado um grande abismo, de modo que os que quisessem passar daqui para vós não podem, nem os de lá passar para nós."},
{v:27,t:"Disse ele: Rogo-te, pois, pai, que o mandes à casa de meu pai,"},
{v:28,t:"pois tenho cinco irmãos, para que os advirta, a fim de que não venham também eles para este lugar de tormento."},
{v:29,t:"Disse-lhe Abraão: Têm Moisés e os Profetas; que os ouçam."},
{v:30,t:"Ele disse: Não, pai Abraão; mas, se alguém dentre os mortos for ter com eles, hão de converter-se."},
{v:31,t:"Respondeu-lhe: Se não ouvem Moisés e os Profetas, tampouco se deixarão persuadir, ainda que alguém ressuscite dentre os mortos.",n:"A frase final soa como profecia: um homem chamado Lázaro havia de voltar dos mortos, no capítulo 11 de São João, e o sinédrio decidiria, por causa disso, matar Jesus."}
];

EV[135] = [
{p:"Lucas 17:1-10"},
{v:1,t:"Disse aos seus discípulos: É impossível que não venham escândalos; mas ai daquele por quem vêm!"},
{v:2,t:"Melhor lhe fora que se lhe pusesse ao pescoço uma mó de moinho e fosse lançado ao mar, do que escandalizar um destes pequeninos."},
{v:3,t:"Tende cuidado convosco. Se teu irmão pecar, repreende-o; e, se se arrepender, perdoa-lhe."},
{v:4,t:"E, se pecar contra ti sete vezes no dia e sete vezes no dia voltar a ti, dizendo: Arrependo-me, perdoa-lhe."},
{v:5,t:"Disseram então os apóstolos ao Senhor: Aumenta-nos a fé.",n:"O pedido vem logo depois da exigência de perdoar sete vezes por dia: é diante do perdão, e não de um milagre, que os apóstolos sentem que lhes falta fé."},
{v:6,t:"E o Senhor disse: Se tivésseis fé como um grão de mostarda, diríeis a esta amoreira: Arranca-te e planta-te no mar; e ela vos obedeceria.",n:"A amoreira-negra tinha fama de ter as raízes mais profundas de todas as árvores; os rabinos diziam que ela podia viver seiscentos anos. Arrancá-la e plantá-la na água é duplamente impossível."},
{v:7,t:"Qual de vós, tendo um servo lavrando ou apascentando, lhe dirá, quando ele voltar do campo: Vem depressa e senta-te à mesa?"},
{v:8,t:"Não lhe dirá antes: Prepara-me o jantar, cinge-te e serve-me, enquanto como e bebo; e depois comerás e beberás tu?"},
{v:9,t:"Acaso fica agradecido ao servo por ter feito o que lhe foi mandado?"},
{v:10,t:"Assim também vós, quando tiverdes feito tudo o que vos foi mandado, dizei: Somos servos inúteis; fizemos apenas o que devíamos fazer.",n:"Inúteis traduz achreioi, que não diz sem valor, mas sem direito a pagamento: servos a quem nada se deve. E a mesma parábola que manda dizer isto foi precedida, no capítulo 12, pela do senhor que se cinge para servir os servos — as duas coisas vêm juntas."}
];

EV[136] = [
{p:"João 11:1-45"},
{v:1,t:"Estava doente um certo Lázaro, de Betânia, a aldeia de Maria e de Marta, sua irmã."},
{v:2,t:"Maria era a que ungiu o Senhor com perfume e lhe enxugou os pés com os seus cabelos; e era seu irmão Lázaro que estava doente.",n:"O evangelista refere-se à unção como coisa já conhecida do leitor, embora só a conte no capítulo seguinte. Escreve para quem já sabe a história."},
{v:3,t:"As irmãs mandaram, pois, dizer a Jesus: Senhor, eis que está doente aquele que amas."},
{v:4,t:"Ouvindo isso, Jesus disse: Esta doença não é para a morte, mas para a glória de Deus, para que por ela seja glorificado o Filho de Deus."},
{v:5,t:"Jesus amava Marta, e a sua irmã, e Lázaro."},
{v:6,t:"Quando, pois, soube que ele estava doente, ficou ainda dois dias no lugar onde estava.",n:"O pois liga a demora ao amor do versículo anterior, e é de propósito desconcertante: porque os amava, esperou. O quarto evangelho não explica a lógica; conta o que ela produziu."},
{v:7,t:"Depois disso, disse aos discípulos: Voltemos para a Judeia."},
{v:8,t:"Disseram-lhe os discípulos: Rabi, ainda há pouco os judeus procuravam apedrejar-te, e voltas para lá?"},
{v:9,t:"Respondeu Jesus: Não são doze as horas do dia? Se alguém anda de dia, não tropeça, porque vê a luz deste mundo;"},
{v:10,t:"mas, se anda de noite, tropeça, porque a luz não está nele."},
{v:11,t:"Disse isso e, depois, acrescentou: Lázaro, o nosso amigo, dorme; mas vou despertá-lo."},
{v:12,t:"Disseram-lhe, pois, os discípulos: Senhor, se dorme, há de salvar-se."},
{v:13,t:"Jesus, porém, falara da sua morte; mas eles pensavam que falava do repouso do sono."},
{v:14,t:"Então Jesus disse-lhes claramente: Lázaro morreu;"},
{v:15,t:"e alegro-me por vossa causa de não ter estado lá, para que creiais. Mas vamos ter com ele."},
{v:16,t:"Disse então Tomé, chamado Dídimo, aos companheiros: Vamos também nós, para morrermos com ele.",n:"Dídimo quer dizer gêmeo, e é tradução grega do aramaico Tomé. O discípulo que ficou conhecido pela dúvida aparece pela primeira vez disposto a morrer."},
{v:17,t:"Chegando, Jesus encontrou-o já sepultado havia quatro dias."},
{v:18,t:"Betânia ficava perto de Jerusalém, a uns quinze estádios."},
{v:19,t:"E muitos dos judeus tinham ido ter com Marta e Maria para as consolar a respeito do irmão."},
{v:20,t:"Marta, quando ouviu que Jesus chegava, saiu-lhe ao encontro; Maria, porém, ficou sentada em casa."},
{v:21,t:"Disse Marta a Jesus: Senhor, se tivesses estado aqui, meu irmão não teria morrido."},
{v:22,t:"Mas, mesmo agora, sei que tudo o que pedires a Deus, Deus te concederá."},
{v:23,t:"Disse-lhe Jesus: Teu irmão há de ressuscitar."},
{v:24,t:"Disse-lhe Marta: Sei que há de ressuscitar na ressurreição, no último dia."},
{v:25,t:"Disse-lhe Jesus: Eu sou a ressurreição e a vida; quem crê em mim, ainda que esteja morto, viverá;",n:"Marta falava da ressurreição como de um acontecimento futuro, no último dia; a resposta põe-na no presente e numa pessoa. Não se diz eu farei ressuscitar, mas eu sou."},
{v:26,t:"e todo o que vive e crê em mim não morrerá eternamente. Crês nisto?"},
{v:27,t:"Disse-lhe ela: Sim, Senhor; eu creio que tu és o Cristo, o Filho de Deus, que havia de vir ao mundo.",n:"É a mesma confissão que Pedro faz nos sinóticos, e no quarto evangelho é Marta quem a faz, com os mesmos títulos, antes do milagre e não depois."},
{v:28,t:"Dito isso, foi chamar Maria, sua irmã, e disse-lhe em segredo: O Mestre está aí e te chama."},
{v:29,t:"Ela, ao ouvir isso, levantou-se depressa e foi ter com ele."},
{v:30,t:"Jesus ainda não tinha entrado na aldeia, mas estava no lugar onde Marta o encontrara."},
{v:31,t:"Os judeus que estavam com ela em casa e a consolavam, vendo Maria levantar-se depressa e sair, seguiram-na, pensando que ia ao sepulcro chorar ali."},
{v:32,t:"Quando Maria chegou onde estava Jesus, vendo-o, lançou-se a seus pés e disse-lhe: Senhor, se tivesses estado aqui, meu irmão não teria morrido."},
{v:33,t:"Jesus, quando a viu chorar, e também os judeus que tinham vindo com ela, comoveu-se profundamente no espírito e perturbou-se,",n:"Comoveu-se traduz enebrimesato, verbo que em grego diz o resfolegar do cavalo e, nas pessoas, a indignação que se contém. Não é só tristeza: é revolta diante da morte. O versículo 38 repete-o."},
{v:34,t:"e disse: Onde o pusestes? Disseram-lhe: Senhor, vem e vê."},
{v:35,t:"Jesus chorou.",n:"O versículo mais curto da Escritura. O verbo não é o do pranto ruidoso das carpideiras, usado no versículo 33, mas o das lágrimas silenciosas. É a única vez que os evangelhos dizem que Jesus chorou por alguém."},
{v:36,t:"Diziam, pois, os judeus: Vede como o amava!"},
{v:37,t:"Mas alguns deles disseram: Este, que abriu os olhos ao cego, não podia fazer também que este não morresse?"},
{v:38,t:"Jesus, pois, comovendo-se de novo em si mesmo, foi ao sepulcro. Era uma gruta, e tinha uma pedra posta à entrada."},
{v:39,t:"Disse Jesus: Tirai a pedra. Disse-lhe Marta, irmã do morto: Senhor, já cheira mal, porque é o quarto dia.",n:"Corria entre os judeus a crença de que a alma rondava o corpo durante três dias e o deixava ao quarto, quando começava a corrupção. Ao quarto dia a morte era, para todos, definitiva."},
{v:40,t:"Disse-lhe Jesus: Não te disse que, se creres, verás a glória de Deus?"},
{v:41,t:"Tiraram, pois, a pedra. E Jesus, levantando os olhos ao alto, disse: Pai, dou-te graças porque me ouviste."},
{v:42,t:"Eu sabia que sempre me ouves; mas disse-o por causa da multidão que me rodeia, para que creiam que tu me enviaste."},
{v:43,t:"Tendo dito isso, clamou em alta voz: Lázaro, vem para fora!"},
{v:44,t:"E saiu o morto, atados os pés e as mãos com faixas, e o rosto envolto num sudário. Disse-lhes Jesus: Desatai-o e deixai-o ir.",n:"Lázaro sai com as faixas e o sudário e precisa de que o desatem. No capítulo 20, no sepulcro de Jesus, as faixas e o sudário ficarão dobrados no lugar: o que é chamado de volta não é o mesmo que ressuscita."},
{v:45,t:"Muitos, pois, dos judeus que tinham ido ter com Maria e viram o que Jesus fizera creram nele."}
];

EV[137] = [
{p:"João 11:46-57"},
{v:46,t:"Alguns deles, porém, foram ter com os fariseus e contaram-lhes o que Jesus fizera."},
{v:47,t:"Os sumos sacerdotes e os fariseus reuniram então o sinédrio e diziam: Que faremos? Este homem faz muitos sinais."},
{v:48,t:"Se o deixarmos assim, todos crerão nele, e virão os romanos e destruirão o nosso lugar e a nossa nação.",n:"O nosso lugar é o templo. Mataram-no para o salvar, e os romanos destruíram-no do mesmo modo, no ano 70 — quando São João escrevia, os leitores já o sabiam."},
{v:49,t:"Mas um deles, Caifás, que era sumo sacerdote naquele ano, disse-lhes: Vós nada sabeis,"},
{v:50,t:"nem considerais que vos convém que um só homem morra pelo povo, e que não pereça a nação inteira."},
{v:51,t:"Ora, ele não disse isso por si mesmo; mas, sendo sumo sacerdote naquele ano, profetizou que Jesus havia de morrer pela nação,",n:"Caifás fala como político, e o evangelista lê nas suas palavras uma profecia que ele não sabia que fazia. A frase cínica diz, sem querer, o sentido da cruz."},
{v:52,t:"e não somente pela nação, mas também para reunir na unidade os filhos de Deus que estavam dispersos."},
{v:53,t:"Desde aquele dia, resolveram matá-lo."},
{v:54,t:"Por isso Jesus já não andava em público entre os judeus, mas retirou-se para uma região vizinha do deserto, para uma cidade chamada Efraim, e ali ficou com os seus discípulos."},
{v:55,t:"Estava próxima a Páscoa dos judeus, e muitos daquela região subiram a Jerusalém antes da Páscoa, para se purificarem."},
{v:56,t:"Procuravam, pois, Jesus e diziam uns aos outros, estando no templo: Que vos parece? Não virá à festa?"},
{v:57,t:"Os sumos sacerdotes e os fariseus tinham dado ordens para que, se alguém soubesse onde ele estava, o denunciasse, para o prenderem."}
];

EV[138] = [
{p:"Lucas 17:11-19"},
{v:11,t:"Aconteceu que, indo ele para Jerusalém, passava entre a Samaria e a Galileia."},
{v:12,t:"Ao entrar numa aldeia, vieram ao seu encontro dez homens leprosos, que pararam ao longe"},
{v:13,t:"e levantaram a voz, dizendo: Jesus, Mestre, tem piedade de nós!"},
{v:14,t:"Vendo-os, disse-lhes: Ide mostrar-vos aos sacerdotes. E aconteceu que, enquanto iam, ficaram purificados.",n:"Mostrar-se ao sacerdote era o que o Levítico mandava fazer depois da cura, para ser declarado limpo. São mandados antes de estarem curados, e é no caminho que a cura acontece."},
{v:15,t:"Um deles, vendo-se curado, voltou, glorificando a Deus em alta voz,"},
{v:16,t:"e prostrou-se com o rosto em terra aos pés de Jesus, dando-lhe graças. E este era samaritano.",n:"Na lepra, judeus e samaritanos viviam juntos, excluídos da mesma maneira. Curados, os nove podiam voltar ao templo; o samaritano não tinha templo aonde ir, e voltou a Jesus."},
{v:17,t:"Tomando a palavra, Jesus disse: Não foram purificados os dez? Onde estão os outros nove?"},
{v:18,t:"Não houve quem voltasse para dar glória a Deus, senão este estrangeiro?"},
{v:19,t:"E disse-lhe: Levanta-te e vai; a tua fé te salvou.",n:"Os dez foram purificados; só a este se diz que a fé o salvou. O verbo muda, e a diferença entre os dois é o caminho de volta."}
];

EV[139] = [
{p:"Lucas 17:20-37"},
{v:20,t:"Interrogado pelos fariseus sobre quando viria o Reino de Deus, respondeu-lhes: O Reino de Deus não vem de modo observável,"},
{v:21,t:"nem se dirá: Ei-lo aqui!, ou: Ei-lo ali!; porque eis que o Reino de Deus está no meio de vós.",n:"No meio de vós traduz entos hymon, que também pode querer dizer dentro de vós, como leram a Vulgata e a Nova Vulgata. Dito aos fariseus, o primeiro sentido parece mais natural: o Reino já está entre eles, na pessoa de quem lhes fala. As duas leituras têm defensores desde a antiguidade."},
{v:22,t:"E disse aos discípulos: Virão dias em que desejareis ver um só dos dias do Filho do Homem, e não o vereis."},
{v:23,t:"E vos dirão: Ei-lo ali!, ou: Ei-lo aqui!; não vades, nem os sigais."},
{v:24,t:"Porque, como o relâmpago, fulgurando de uma extremidade do céu, brilha até à outra, assim será o Filho do Homem no seu dia."},
{v:25,t:"Mas primeiro é necessário que ele sofra muito e seja rejeitado por esta geração."},
{v:26,t:"E, como aconteceu nos dias de Noé, assim será também nos dias do Filho do Homem:"},
{v:27,t:"comiam, bebiam, casavam-se e davam-se em casamento, até ao dia em que Noé entrou na arca; e veio o dilúvio e fez perecer a todos.",n:"Nenhuma das coisas enumeradas é pecado: comer, casar, plantar, construir. O que se censura é viver como se nada fosse acontecer."},
{v:28,t:"Do mesmo modo, como aconteceu nos dias de Ló: comiam, bebiam, compravam, vendiam, plantavam e edificavam;"},
{v:29,t:"mas, no dia em que Ló saiu de Sodoma, choveu do céu fogo e enxofre e fez perecer a todos."},
{v:30,t:"Assim será no dia em que o Filho do Homem se revelar."},
{v:31,t:"Naquele dia, quem estiver no terraço e tiver os seus bens em casa, não desça para os buscar; e, do mesmo modo, quem estiver no campo não volte para trás."},
{v:32,t:"Lembrai-vos da mulher de Ló."},
{v:33,t:"Quem procurar salvar a sua vida há de perdê-la; e quem a perder há de conservá-la."},
{v:34,t:"Eu vos digo: naquela noite estarão dois numa cama; um será tomado, e o outro será deixado."},
{v:35,t:"Duas mulheres estarão moendo juntas; uma será tomada, e a outra será deixada.",n:"Alguns manuscritos acrescentam um versículo 36 — dois estarão no campo; um será tomado, e o outro deixado —, trazido de São Mateus. Falta nos mais antigos, e a Nova Vulgata omite-o; a numeração salta do 35 ao 37."},
{v:37,t:"Tomando a palavra, disseram-lhe: Onde, Senhor? Ele lhes disse: Onde estiver o corpo, ali se ajuntarão também os abutres.",n:"Abutres traduz aetoi, que em grego serve para a águia e para o abutre; a tradição latina leu águias. O provérbio é o da carniça, e fala do inevitável: onde há o corpo morto, as aves vêm."}
];

EV[140] = [
{p:"Lucas 18:1-8"},
{v:1,t:"Contou-lhes também uma parábola sobre a necessidade de orar sempre, sem desanimar,"},
{v:2,t:"dizendo: Havia numa cidade um juiz que não temia a Deus nem respeitava os homens."},
{v:3,t:"Havia também naquela cidade uma viúva, que ia ter com ele, dizendo: Faze-me justiça contra o meu adversário.",n:"A viúva é, em toda a lei de Israel, a figura de quem não tem defensor: sem marido que a represente e sem dinheiro para subornar. Só lhe resta insistir."},
{v:4,t:"E durante muito tempo ele não quis. Mas depois disse consigo mesmo: Ainda que eu não tema a Deus nem respeite os homens,"},
{v:5,t:"todavia, como esta viúva me importuna, vou fazer-lhe justiça, para que não venha continuamente esgotar-me a paciência.",n:"Esgotar-me traduz hypopiazo, termo do pugilismo: deixar o olho roxo. O juiz tem medo de levar um soco da viúva. A parábola tem humor, e o argumento sobe de um juiz assim a Deus."},
{v:6,t:"E disse o Senhor: Ouvi o que diz o juiz iníquo."},
{v:7,t:"E Deus não fará justiça aos seus escolhidos, que clamam a ele dia e noite, ainda que os faça esperar?"},
{v:8,t:"Digo-vos que depressa lhes fará justiça. Mas, quando vier o Filho do Homem, acaso achará fé sobre a terra?",n:"A parábola acaba numa pergunta que muda de lado. Não se duvida de que Deus faça justiça: duvida-se de que haja quem continue a pedir."}
];

EV[141] = [
{p:"Lucas 18:9-14"},
{v:9,t:"Disse também esta parábola a alguns que confiavam em si mesmos, por se julgarem justos, e desprezavam os outros:"},
{v:10,t:"Dois homens subiram ao templo para orar: um fariseu e o outro publicano."},
{v:11,t:"O fariseu, de pé, orava assim consigo mesmo: Ó Deus, dou-te graças porque não sou como os outros homens, ladrões, injustos, adúlteros, nem como este publicano.",n:"Consigo mesmo pode também ler-se para si mesmo. O grego admite as duas coisas, e as duas dizem o mesmo: é uma oração que não sai de quem a faz."},
{v:12,t:"Jejuo duas vezes por semana e pago o dízimo de tudo o que ganho.",n:"A lei só mandava jejuar um dia por ano, no Dia da Expiação. O fariseu faz muito mais do que lhe pedem, e não mente em nada do que diz."},
{v:13,t:"O publicano, porém, mantendo-se à distância, nem sequer ousava levantar os olhos ao céu, mas batia no peito, dizendo: Ó Deus, tem piedade de mim, pecador.",n:"Destas palavras nasceu, nas Igrejas do Oriente, a oração de Jesus, repetida sem cessar pelos monges: Senhor Jesus Cristo, Filho de Deus, tem piedade de mim, pecador."},
{v:14,t:"Digo-vos que este desceu justificado para sua casa, e não aquele; porque todo o que se exalta será humilhado, e o que se humilha será exaltado."}
];

EV[142] = [
{p:"Mateus 19:3-12"},
{v:3,t:"Aproximaram-se dele alguns fariseus para o pôr à prova, e perguntaram: É lícito ao homem repudiar a sua mulher por qualquer motivo?",n:"Por qualquer motivo é o ponto da armadilha. As duas grandes escolas rabínicas divergiam: a de Shammai só admitia o repúdio por coisa indecente; a de Hillel, por qualquer motivo, até por uma comida queimada. Pede-se a Jesus que escolha um partido."},
{v:4,t:"Ele respondeu: Não lestes que o Criador, desde o princípio, os fez homem e mulher,"},
{v:5,t:"e disse: Por isso o homem deixará pai e mãe e se unirá à sua mulher, e os dois serão uma só carne?"},
{v:6,t:"Assim, já não são dois, mas uma só carne. Portanto, o que Deus uniu, o homem não separe.",n:"A resposta não escolhe entre as duas escolas: recua de Moisés para o Gênesis, de uma concessão da lei para a intenção da criação."},
{v:7,t:"Disseram-lhe: Por que, então, Moisés mandou dar carta de divórcio e repudiá-la?"},
{v:8,t:"Ele lhes disse: Foi por causa da dureza do vosso coração que Moisés vos permitiu repudiar as vossas mulheres; mas no princípio não foi assim."},
{v:9,t:"Eu vos digo: quem repudiar a sua mulher, exceto por união ilegítima, e casar com outra, comete adultério.",n:"União ilegítima traduz porneia, palavra que não é a do adultério, moicheia, que aparece no mesmo versículo. A cláusula só existe em São Mateus e tem sido lida de maneiras diferentes pelas Igrejas. A leitura que a Igreja católica segue entende-a das uniões que a lei declarava nulas — por exemplo, entre parentes próximos, segundo o Levítico 18 —, em que não havia verdadeiro matrimônio a dissolver. Traduz-se a palavra pelo que ela designa, e registra-se que a questão é debatida."},
{v:10,t:"Disseram-lhe os discípulos: Se tal é a condição do homem em relação à mulher, não convém casar."},
{v:11,t:"Ele, porém, lhes disse: Nem todos compreendem esta palavra, mas somente aqueles a quem foi dado."},
{v:12,t:"Porque há eunucos que nasceram assim do ventre de suas mães; e há eunucos que foram feitos pelos homens; e há eunucos que a si mesmos se fizeram tais por causa do Reino dos céus. Quem puder compreender, compreenda.",n:"Eunuco era insulto e exclusão: a lei vedava-lhes a assembleia do Senhor. Jesus usa a palavra dura para falar dos que renunciam ao casamento pelo Reino — e é esse o fundamento que a Igreja deu ao celibato consagrado."},
{p:"Marcos 10:2-12"},
{v:2,t:"E, aproximando-se uns fariseus, perguntavam-lhe, para o pôr à prova, se era lícito ao marido repudiar a mulher."},
{v:3,t:"Ele lhes respondeu: Que vos mandou Moisés?"},
{v:4,t:"Eles disseram: Moisés permitiu escrever carta de divórcio e repudiá-la."},
{v:5,t:"Jesus lhes disse: Foi por causa da dureza do vosso coração que ele vos escreveu esse preceito."},
{v:6,t:"Mas, desde o princípio da criação, Deus os fez homem e mulher."},
{v:7,t:"Por isso o homem deixará seu pai e sua mãe e se unirá à sua mulher,"},
{v:8,t:"e os dois serão uma só carne. Assim, já não são dois, mas uma só carne."},
{v:9,t:"Portanto, o que Deus uniu, o homem não separe."},
{v:10,t:"Em casa, os discípulos interrogaram-no de novo sobre isso."},
{v:11,t:"E ele lhes disse: Quem repudiar a sua mulher e casar com outra comete adultério contra ela;"},
{v:12,t:"e, se ela repudiar o marido e casar com outro, comete adultério.",n:"A lei judaica não permitia à mulher repudiar o marido; a romana, sim. São Marcos escreve para leitores de Roma e aplica-lhes o ensino com a mesma igualdade: vale para os dois."},
{p:"Lucas 16:18"},
{v:18,t:"Todo aquele que repudia a sua mulher e casa com outra comete adultério; e quem casa com a repudiada pelo marido comete adultério."}
];

EV[143] = [
{p:"Mateus 19:13-15"},
{v:13,t:"Então lhe apresentaram umas crianças, para que lhes impusesse as mãos e orasse; mas os discípulos as repreendiam."},
{v:14,t:"Jesus, porém, disse: Deixai as crianças e não as impeçais de vir a mim, porque de tais é o Reino dos céus."},
{v:15,t:"E, tendo-lhes imposto as mãos, partiu dali."},
{p:"Marcos 10:13-16"},
{v:13,t:"Apresentavam-lhe crianças para que as tocasse; mas os discípulos repreendiam-nos."},
{v:14,t:"Vendo isso, Jesus indignou-se e disse-lhes: Deixai vir a mim as crianças e não as impeçais, porque delas é o Reino de Deus.",n:"Indignou-se traduz aganakteo, e é a única vez que o evangelho o diz de Jesus. A indignação é contra os seus próprios discípulos, que achavam que lhe poupavam tempo."},
{v:15,t:"Em verdade vos digo: quem não receber o Reino de Deus como uma criança não entrará nele."},
{v:16,t:"E, abraçando-as, abençoava-as, impondo-lhes as mãos."},
{p:"Lucas 18:15-17"},
{v:15,t:"Traziam-lhe também as crianças pequenas, para que as tocasse; mas os discípulos, vendo isso, repreendiam-nos.",n:"Crianças pequenas traduz brephe, que São Lucas usa também para o menino na manjedoura: bebês de colo. Nem sequer vinham por seus pés."},
{v:16,t:"Jesus, porém, chamou-as a si, dizendo: Deixai vir a mim as crianças e não as impeçais, porque de tais é o Reino de Deus."},
{v:17,t:"Em verdade vos digo: quem não receber o Reino de Deus como uma criança não entrará nele."}
];

EV[144] = [
{p:"Mateus 19:16-30"},
{v:16,t:"E eis que alguém, aproximando-se, lhe disse: Mestre, que devo fazer de bom para alcançar a vida eterna?",n:"O personagem é composto pela memória comum a partir dos três evangelhos: só São Mateus diz que era jovem, só São Lucas que era chefe, e os três que era rico. O jovem rico da tradição é, a rigor, uma harmonia."},
{v:17,t:"Ele lhe disse: Por que me perguntas sobre o que é bom? Um só é o Bom. Se queres entrar na vida, guarda os mandamentos."},
{v:18,t:"Disse-lhe ele: Quais? Jesus respondeu: Não matarás, não cometerás adultério, não furtarás, não dirás falso testemunho,"},
{v:19,t:"honra teu pai e tua mãe, e amarás o teu próximo como a ti mesmo."},
{v:20,t:"Disse-lhe o jovem: Tudo isso tenho guardado; que me falta ainda?"},
{v:21,t:"Jesus lhe disse: Se queres ser perfeito, vai, vende o que tens e dá-o aos pobres, e terás um tesouro no céu; depois vem e segue-me."},
{v:22,t:"Ouvindo essa palavra, o jovem foi-se embora triste, porque possuía muitos bens.",n:"É o único chamado ao seguimento, em todos os evangelhos, que é recusado. E o evangelista não o condena: diz que foi embora triste."},
{v:23,t:"Disse então Jesus aos seus discípulos: Em verdade vos digo que um rico dificilmente entrará no Reino dos céus."},
{v:24,t:"E digo-vos ainda: é mais fácil um camelo passar pelo buraco de uma agulha do que um rico entrar no Reino de Deus.",n:"Não há aqui porta estreita em Jerusalém chamada agulha, nem corda confundida com camelo: são explicações tardias para abrandar a frase. O camelo era o maior animal da Palestina, e o buraco da agulha a menor abertura conhecida. O Talmude usa a mesma figura com um elefante. Quer dizer impossível, e é assim que os discípulos o entendem no versículo seguinte."},
{v:25,t:"Ouvindo isso, os discípulos ficaram muito espantados e disseram: Quem, então, pode ser salvo?"},
{v:26,t:"Jesus, fitando neles o olhar, disse: Aos homens isso é impossível; mas a Deus tudo é possível."},
{v:27,t:"Então Pedro, tomando a palavra, disse-lhe: Eis que nós deixamos tudo e te seguimos; que haverá, pois, para nós?"},
{v:28,t:"Jesus lhes disse: Em verdade vos digo que vós, que me seguistes, na regeneração, quando o Filho do Homem se sentar no trono da sua glória, também vos sentareis sobre doze tronos, para julgar as doze tribos de Israel."},
{v:29,t:"E todo aquele que tiver deixado casas, ou irmãos, ou irmãs, ou pai, ou mãe, ou filhos, ou campos, por causa do meu nome, receberá cem vezes mais e herdará a vida eterna."},
{v:30,t:"Muitos primeiros, porém, serão últimos, e muitos últimos serão primeiros."},
{p:"Marcos 10:17-31"},
{v:17,t:"Ao sair ele para o caminho, alguém correu ao seu encontro e, ajoelhando-se diante dele, perguntou-lhe: Bom Mestre, que devo fazer para herdar a vida eterna?"},
{v:18,t:"Jesus lhe disse: Por que me chamas bom? Ninguém é bom senão Deus somente.",n:"A resposta não nega que ele seja bom: pergunta ao homem se sabe o que está dizendo. Chamar bom a um mestre era, no judaísmo, quase inaudito, porque o título pertencia a Deus."},
{v:19,t:"Conheces os mandamentos: Não mates, não cometas adultério, não furtes, não digas falso testemunho, não defraudes, honra teu pai e tua mãe."},
{v:20,t:"Ele lhe respondeu: Mestre, tudo isso tenho guardado desde a minha juventude."},
{v:21,t:"Jesus, fitando nele o olhar, amou-o e disse-lhe: Falta-te uma coisa: vai, vende tudo o que tens e dá-o aos pobres, e terás um tesouro no céu; depois vem e segue-me.",n:"Amou-o: só São Marcos o diz, e é a única vez nos sinóticos que se diz de Jesus que amou alguém em particular. O que se pede vem depois do amor, e é por causa dele."},
{v:22,t:"Mas ele, desgostoso com essa palavra, foi-se embora triste, porque possuía muitos bens."},
{v:23,t:"Então Jesus, olhando em redor, disse aos seus discípulos: Como é difícil aos que têm riquezas entrar no Reino de Deus!"},
{v:24,t:"Os discípulos ficaram espantados com as suas palavras. Mas Jesus, tomando de novo a palavra, disse-lhes: Filhos, como é difícil entrar no Reino de Deus!"},
{v:25,t:"É mais fácil um camelo passar pelo buraco de uma agulha do que um rico entrar no Reino de Deus."},
{v:26,t:"Eles ficaram ainda mais espantados, e diziam uns aos outros: Quem, então, pode ser salvo?"},
{v:27,t:"Fitando neles o olhar, Jesus disse: Aos homens é impossível, mas não a Deus; porque a Deus tudo é possível."},
{v:28,t:"Pedro começou a dizer-lhe: Eis que nós deixamos tudo e te seguimos."},
{v:29,t:"Jesus respondeu: Em verdade vos digo: ninguém há que tenha deixado casa, ou irmãos, ou irmãs, ou mãe, ou pai, ou filhos, ou campos, por causa de mim e por causa do Evangelho,"},
{v:30,t:"que não receba cem vezes mais agora, no tempo presente, em casas, irmãos, irmãs, mães, filhos e campos, com perseguições, e, no mundo vindouro, a vida eterna.",n:"Com perseguições é acréscimo de São Marcos, e quase irônico no meio da promessa. E na lista do que se recebe cem vezes mais aparecem irmãos, mães e filhos — mas não pais: na nova família, Pai há um só."},
{v:31,t:"Muitos primeiros serão últimos, e os últimos serão primeiros."},
{p:"Lucas 18:18-30"},
{v:18,t:"Um dos chefes perguntou-lhe: Bom Mestre, que devo fazer para herdar a vida eterna?"},
{v:19,t:"Jesus lhe disse: Por que me chamas bom? Ninguém é bom senão Deus somente."},
{v:20,t:"Conheces os mandamentos: Não cometas adultério, não mates, não furtes, não digas falso testemunho, honra teu pai e tua mãe."},
{v:21,t:"Ele disse: Tudo isso tenho guardado desde a minha juventude."},
{v:22,t:"Ouvindo isso, Jesus disse-lhe: Ainda te falta uma coisa: vende tudo o que tens e distribui-o aos pobres, e terás um tesouro nos céus; depois vem e segue-me."},
{v:23,t:"Mas ele, ouvindo isso, ficou muito triste, porque era muito rico."},
{v:24,t:"Vendo-o Jesus assim, disse: Como é difícil aos que têm riquezas entrar no Reino de Deus!"},
{v:25,t:"Pois é mais fácil um camelo entrar pelo buraco de uma agulha do que um rico entrar no Reino de Deus."},
{v:26,t:"Os que ouviam disseram: Quem, então, pode ser salvo?"},
{v:27,t:"Ele respondeu: O que é impossível aos homens é possível a Deus.",n:"No capítulo seguinte de São Lucas, um rico entra: Zaqueu. É a resposta narrativa a esta frase."},
{v:28,t:"Pedro disse: Eis que nós deixamos o que tínhamos e te seguimos."},
{v:29,t:"Ele lhes disse: Em verdade vos digo que ninguém há que tenha deixado casa, ou mulher, ou irmãos, ou pais, ou filhos, por causa do Reino de Deus,"},
{v:30,t:"que não receba muito mais no tempo presente e, no mundo vindouro, a vida eterna."}
];

EV[145] = [
{p:"Mateus 20:1-16"},
{v:1,t:"Porque o Reino dos céus é semelhante a um pai de família que saiu de madrugada para contratar trabalhadores para a sua vinha."},
{v:2,t:"Tendo ajustado com os trabalhadores um denário por dia, mandou-os para a sua vinha.",n:"O denário era o salário justo de um dia, o que bastava para sustentar uma família até ao dia seguinte. Menos do que isso era passar fome."},
{v:3,t:"Saindo cerca da hora terceira, viu outros que estavam na praça, desocupados,"},
{v:4,t:"e disse-lhes: Ide também vós para a vinha, e eu vos darei o que for justo."},
{v:5,t:"E eles foram. Saindo de novo cerca da hora sexta e da nona, fez o mesmo."},
{v:6,t:"Saindo cerca da hora undécima, encontrou outros que lá estavam e disse-lhes: Por que estais aqui o dia inteiro desocupados?",n:"As horas contavam-se a partir do nascer do sol: a terceira são nove da manhã, a sexta meio-dia, a nona três da tarde, a undécima cinco da tarde — uma hora antes do fim do trabalho."},
{v:7,t:"Responderam-lhe: Porque ninguém nos contratou. Disse-lhes: Ide também vós para a vinha."},
{v:8,t:"Ao cair da tarde, disse o senhor da vinha ao seu administrador: Chama os trabalhadores e paga-lhes o salário, começando pelos últimos até aos primeiros."},
{v:9,t:"Vindo os da hora undécima, receberam um denário cada um."},
{v:10,t:"Vindo os primeiros, pensaram que haviam de receber mais; mas também eles receberam um denário cada um."},
{v:11,t:"E, ao recebê-lo, murmuravam contra o pai de família,"},
{v:12,t:"dizendo: Estes últimos trabalharam uma só hora, e tu os igualaste a nós, que suportamos o peso do dia e o calor."},
{v:13,t:"Mas ele respondeu a um deles: Amigo, não te faço injustiça. Não ajustaste comigo um denário?"},
{v:14,t:"Toma o que é teu e vai-te. Quero dar a este último tanto quanto a ti."},
{v:15,t:"Não me é lícito fazer o que quero com o que é meu? Ou é mau o teu olho porque eu sou bom?",n:"Mau o teu olho é a inveja, como no tópico 118. A queixa dos primeiros é justa pela medida do salário e injusta pela medida da necessidade: os últimos também tinham famílias para comer naquela noite."},
{v:16,t:"Assim, os últimos serão primeiros, e os primeiros, últimos."}
];

EV[146] = [
{p:"Mateus 20:17-19"},
{v:17,t:"Estando para subir a Jerusalém, Jesus tomou à parte os doze discípulos e, pelo caminho, disse-lhes:"},
{v:18,t:"Eis que subimos a Jerusalém, e o Filho do Homem será entregue aos sumos sacerdotes e aos escribas, e o condenarão à morte,"},
{v:19,t:"e o entregarão aos gentios, para ser escarnecido, açoitado e crucificado; e ao terceiro dia ressuscitará.",n:"O terceiro anúncio é o mais pormenorizado, e enumera, pela ordem, o que a Paixão há de ser: a entrega, a condenação, a passagem aos romanos, os escárnios, os açoites, a cruz."},
{p:"Marcos 10:32-34"},
{v:32,t:"Estavam no caminho, subindo para Jerusalém, e Jesus ia à frente deles; eles estavam espantados, e os que o seguiam tinham medo. Tomando de novo os Doze à parte, começou a dizer-lhes o que lhe havia de acontecer:",n:"A imagem é só de São Marcos: Jesus caminha sozinho à frente, e os outros atrás, a certa distância, com medo. Perceberam aonde ele ia antes de ele o dizer."},
{v:33,t:"Eis que subimos a Jerusalém, e o Filho do Homem será entregue aos sumos sacerdotes e aos escribas; e o condenarão à morte e o entregarão aos gentios;"},
{v:34,t:"e hão de escarnecer dele, cuspir nele, açoitá-lo e matá-lo; e, depois de três dias, ressuscitará."},
{p:"Lucas 18:31-34"},
{v:31,t:"Tomando consigo os Doze, disse-lhes: Eis que subimos a Jerusalém, e vai cumprir-se tudo o que foi escrito pelos profetas a respeito do Filho do Homem."},
{v:32,t:"Pois será entregue aos gentios, será escarnecido, ultrajado e cuspido;"},
{v:33,t:"e, depois de o açoitarem, hão de matá-lo; e ao terceiro dia ressuscitará."},
{v:34,t:"Eles, porém, nada disso compreenderam; esta palavra lhes era oculta, e não entendiam o que se dizia."}
];

EV[147] = [
{p:"Mateus 20:20-28"},
{v:20,t:"Então aproximou-se dele a mãe dos filhos de Zebedeu, com seus filhos, e prostrou-se para lhe fazer um pedido.",n:"Em São Marcos são os próprios Tiago e João que fazem o pedido; em São Mateus, a mãe. A diferença poupa os apóstolos — mas a resposta de Jesus, logo a seguir, é dirigida a eles, no plural."},
{v:21,t:"Ele perguntou-lhe: Que queres? Ela disse: Manda que estes meus dois filhos se sentem no teu Reino, um à tua direita e outro à tua esquerda."},
{v:22,t:"Jesus respondeu: Não sabeis o que pedis. Podeis beber o cálice que eu hei de beber? Disseram-lhe: Podemos."},
{v:23,t:"Ele lhes disse: O meu cálice, sim, bebereis; mas sentar-se à minha direita e à minha esquerda não me cabe concedê-lo; é para aqueles para quem meu Pai o preparou.",n:"A profecia cumpriu-se: Tiago foi o primeiro dos apóstolos a morrer mártir, sob Herodes Agripa, segundo os Atos. E a próxima vez que o evangelho fala de alguém à direita e à esquerda de Jesus é no Calvário, com os dois ladrões."},
{v:24,t:"Ouvindo isso, os dez indignaram-se contra os dois irmãos."},
{v:25,t:"Jesus, porém, chamando-os, disse: Sabeis que os chefes das nações as dominam e que os grandes exercem sobre elas o poder."},
{v:26,t:"Não será assim entre vós; mas quem quiser tornar-se grande entre vós, seja o vosso servidor;"},
{v:27,t:"e quem quiser ser o primeiro entre vós, seja o vosso escravo;"},
{v:28,t:"assim como o Filho do Homem não veio para ser servido, mas para servir e dar a sua vida em resgate por muitos.",n:"Resgate traduz lytron, o preço pago para libertar um escravo ou um prisioneiro. Por muitos é semitismo, que não opõe muitos a todos, mas um a muitos: é a linguagem do servo de Isaías 53, que carrega o pecado de muitos."},
{p:"Marcos 10:35-45"},
{v:35,t:"Aproximaram-se dele Tiago e João, filhos de Zebedeu, dizendo: Mestre, queremos que nos faças o que te vamos pedir."},
{v:36,t:"Ele lhes disse: Que quereis que vos faça?"},
{v:37,t:"Disseram-lhe: Concede-nos que, na tua glória, nos sentemos um à tua direita e outro à tua esquerda."},
{v:38,t:"Jesus lhes disse: Não sabeis o que pedis. Podeis beber o cálice que eu bebo, ou ser batizados com o batismo com que eu sou batizado?"},
{v:39,t:"Disseram-lhe: Podemos. Jesus lhes disse: O cálice que eu bebo, bebereis; e com o batismo com que eu sou batizado, sereis batizados;"},
{v:40,t:"mas sentar-se à minha direita ou à minha esquerda não me cabe concedê-lo; é para aqueles para quem foi preparado."},
{v:41,t:"Ouvindo isso, os dez começaram a indignar-se contra Tiago e João."},
{v:42,t:"Jesus, chamando-os, disse-lhes: Sabeis que os que são tidos por chefes das nações as dominam, e os seus grandes exercem sobre elas o poder."},
{v:43,t:"Não é assim entre vós; mas quem quiser tornar-se grande entre vós seja o vosso servidor;"},
{v:44,t:"e quem quiser ser o primeiro entre vós seja escravo de todos."},
{v:45,t:"Pois também o Filho do Homem não veio para ser servido, mas para servir e dar a sua vida em resgate por muitos."}
];

EV[148] = [
{p:"Mateus 20:29-34"},
{v:29,t:"Ao saírem de Jericó, seguiu-o uma grande multidão."},
{v:30,t:"E eis que dois cegos, sentados à beira do caminho, ouvindo que Jesus passava, gritaram: Senhor, Filho de Davi, tem piedade de nós!",n:"São Mateus fala de dois cegos; São Marcos e São Lucas, de um só. São Mateus dobra também os endemoninhados de Gadara e, na entrada em Jerusalém, os animais. Os três relatos contam a mesma cena com a liberdade com que se contava então."},
{v:31,t:"A multidão repreendia-os para que se calassem; mas eles gritavam ainda mais: Senhor, Filho de Davi, tem piedade de nós!"},
{v:32,t:"Jesus parou, chamou-os e disse: Que quereis que vos faça?"},
{v:33,t:"Disseram-lhe: Senhor, que se abram os nossos olhos."},
{v:34,t:"Jesus, compadecido, tocou-lhes os olhos; e logo recobraram a vista e o seguiram."},
{p:"Marcos 10:46-52"},
{v:46,t:"Chegaram a Jericó. E, ao sair ele de Jericó com os seus discípulos e uma grande multidão, estava sentado à beira do caminho, mendigando, um cego, Bartimeu, filho de Timeu.",n:"Bartimeu é o aramaico bar Timai, filho de Timeu, e São Marcos traduz o nome como sempre faz. É o único curado, em todo o segundo evangelho, cujo nome se conserva — sinal provável de que era conhecido da comunidade."},
{v:47,t:"Ouvindo que era Jesus de Nazaré, começou a gritar: Jesus, Filho de Davi, tem piedade de mim!"},
{v:48,t:"Muitos o repreendiam para que se calasse; mas ele gritava ainda mais: Filho de Davi, tem piedade de mim!"},
{v:49,t:"Jesus parou e disse: Chamai-o. E chamaram o cego, dizendo-lhe: Coragem! Levanta-te, ele te chama."},
{v:50,t:"Ele, lançando fora o manto, deu um salto e foi ter com Jesus.",n:"O manto era tudo o que um mendigo tinha: servia de cama à noite e, estendido no chão, de lugar onde recebia as moedas. Larga-o antes de saber se será curado."},
{v:51,t:"Jesus, tomando a palavra, disse-lhe: Que queres que te faça? O cego respondeu-lhe: Rabbuni, que eu veja."},
{v:52,t:"Jesus disse-lhe: Vai, a tua fé te salvou. E logo recobrou a vista e seguia-o pelo caminho.",n:"Pelo caminho: o que vai dar a Jerusalém e à cruz. O último curado do evangelho de São Marcos é também o último que se torna discípulo, e segue-o para onde ele vai."},
{p:"Lucas 18:35-43"},
{v:35,t:"Aconteceu que, ao aproximar-se ele de Jericó, estava um cego sentado à beira do caminho, mendigando."},
{v:36,t:"Ouvindo passar a multidão, perguntou o que era aquilo."},
{v:37,t:"Disseram-lhe que passava Jesus de Nazaré."},
{v:38,t:"Então gritou: Jesus, Filho de Davi, tem piedade de mim!"},
{v:39,t:"Os que iam à frente repreendiam-no para que se calasse; mas ele gritava ainda mais: Filho de Davi, tem piedade de mim!"},
{v:40,t:"Jesus parou e mandou que o trouxessem; e, quando ele se aproximou, perguntou-lhe:"},
{v:41,t:"Que queres que te faça? Ele disse: Senhor, que eu veja."},
{v:42,t:"Jesus disse-lhe: Vê; a tua fé te salvou."},
{v:43,t:"E logo recobrou a vista e seguia-o, glorificando a Deus. E todo o povo, vendo isso, deu louvores a Deus."}
];

EV[149] = [
{p:"Lucas 19:1-10"},
{v:1,t:"Tendo entrado em Jericó, atravessava a cidade."},
{v:2,t:"E eis que um homem chamado Zaqueu, chefe dos publicanos e rico,",n:"Jericó era posto aduaneiro na estrada do comércio entre a Judeia e o oriente, e Zaqueu era chefe dos cobradores: o título só aparece aqui. Zaqueu é forma do hebraico Zakkai, que quer dizer puro, inocente — o nome e o ofício dizem o contrário um do outro."},
{v:3,t:"procurava ver quem era Jesus, mas não podia, por causa da multidão, porque era de pequena estatura."},
{v:4,t:"Correndo à frente, subiu a um sicômoro para o ver, porque ele havia de passar por ali.",n:"Um homem rico e importante, no Oriente, não corria nem subia em árvores. Zaqueu faz as duas coisas, à vista de toda a cidade."},
{v:5,t:"Quando Jesus chegou àquele lugar, olhando para cima, disse-lhe: Zaqueu, desce depressa, porque hoje é preciso que eu fique em tua casa.",n:"Hoje é a palavra de São Lucas: hoje nasceu o Salvador, hoje se cumpriu esta Escritura, hoje estarás comigo no paraíso. E é preciso é o verbo que o evangelho usa para a Paixão: a visita a Zaqueu é posta na mesma necessidade."},
{v:6,t:"Ele desceu depressa e recebeu-o com alegria."},
{v:7,t:"Vendo isso, todos murmuravam, dizendo: Foi hospedar-se em casa de um pecador."},
{v:8,t:"Zaqueu, porém, de pé, disse ao Senhor: Eis, Senhor, que dou aos pobres metade dos meus bens; e, se defraudei alguém em alguma coisa, restituo-lhe o quádruplo.",n:"A lei mandava restituir o roubado com um quinto a mais. O quádruplo era a pena do Êxodo para quem roubasse uma ovelha e a matasse. Zaqueu aplica a si mesmo a medida mais severa da lei, sem que ninguém lho peça."},
{v:9,t:"Jesus disse-lhe: Hoje entrou a salvação nesta casa, porque também este é filho de Abraão.",n:"Filho de Abraão faz par com a filha de Abraão curada no sábado, no tópico 124. São as duas únicas vezes que a expressão aparece, e ambas para gente que os outros tinham excluído."},
{v:10,t:"Pois o Filho do Homem veio procurar e salvar o que estava perdido."}
];

EV[150] = [
{p:"Lucas 19:11-28"},
{v:11,t:"Enquanto ouviam estas coisas, acrescentou uma parábola, por estar perto de Jerusalém e pensarem eles que o Reino de Deus havia de manifestar-se imediatamente."},
{v:12,t:"Disse, pois: Um homem de nobre estirpe partiu para uma região distante, a fim de receber para si um reino e voltar.",n:"Os ouvintes reconheciam a história: Arquelau, filho de Herodes, fora a Roma, no ano 4 antes de Cristo, receber de Augusto o reino do pai, e os judeus mandaram atrás dele uma embaixada para o impedir. O palácio de Arquelau ficava precisamente em Jericó."},
{v:13,t:"Chamando dez dos seus servos, deu-lhes dez minas e disse-lhes: Negociai até que eu volte.",n:"A mina valia cem denários, cerca de quatro meses de salário — muito menos que o talento da parábola de São Mateus. Todos recebem o mesmo, e o que se mede é só o que cada um fez com ele."},
{v:14,t:"Mas os seus concidadãos odiavam-no e enviaram atrás dele uma embaixada, dizendo: Não queremos que este reine sobre nós."},
{v:15,t:"Aconteceu que, ao voltar, depois de ter recebido o reino, mandou chamar os servos a quem dera o dinheiro, para saber quanto cada um tinha ganhado."},
{v:16,t:"Apresentou-se o primeiro, dizendo: Senhor, a tua mina rendeu dez minas."},
{v:17,t:"Disse-lhe: Muito bem, servo bom! Porque foste fiel no pouco, terás autoridade sobre dez cidades."},
{v:18,t:"Veio o segundo, dizendo: Senhor, a tua mina rendeu cinco minas."},
{v:19,t:"Disse também a este: Tu terás autoridade sobre cinco cidades."},
{v:20,t:"Veio o outro, dizendo: Senhor, aqui está a tua mina, que guardei num lenço;"},
{v:21,t:"porque tive medo de ti, que és homem severo: tiras o que não puseste e colhes o que não semeaste."},
{v:22,t:"Disse-lhe: Pela tua própria boca te julgo, servo mau. Sabias que sou homem severo, que tiro o que não pus e colho o que não semeei;"},
{v:23,t:"por que, então, não puseste o meu dinheiro no banco? Assim, ao voltar, eu o teria recebido com juros."},
{v:24,t:"E disse aos que estavam presentes: Tirai-lhe a mina e dai-a ao que tem dez."},
{v:25,t:"Disseram-lhe: Senhor, ele já tem dez minas!"},
{v:26,t:"Eu vos digo que a todo aquele que tem será dado; mas ao que não tem, até o que tem lhe será tirado."},
{v:27,t:"Quanto a esses meus inimigos, que não quiseram que eu reinasse sobre eles, trazei-os aqui e matai-os na minha presença.",n:"O fim é duríssimo, e é o de um rei do tempo de Arquelau, que fez exatamente isso aos que se lhe opuseram. A parábola usa a história real como imagem, e o versículo seguinte diz que rei é este e como vai receber o seu reino: subindo para Jerusalém."},
{v:28,t:"Dito isso, seguia à frente deles, subindo para Jerusalém."}
];

EV[151] = [
{p:"Mateus 26:6-13"},
{v:6,t:"Estando Jesus em Betânia, em casa de Simão, o leproso,"},
{v:7,t:"aproximou-se dele uma mulher com um vaso de alabastro de perfume precioso, e derramou-o sobre a sua cabeça, enquanto ele estava à mesa.",n:"Ungir a cabeça era o gesto com que se consagravam os reis. A mulher sem nome faz, sem saber ou sabendo, o que nenhum sacerdote fez: unge o Messias."},
{v:8,t:"Vendo isso, os discípulos indignaram-se e disseram: Para que este desperdício?"},
{v:9,t:"Esse perfume podia ser vendido por muito dinheiro, e dado aos pobres."},
{v:10,t:"Percebendo isso, Jesus disse-lhes: Por que molestais esta mulher? Ela fez uma boa obra para comigo."},
{v:11,t:"Pobres sempre os tendes convosco; mas a mim nem sempre me tendes.",n:"A frase cita o Deuteronômio 15, que continua: por isso te ordeno que abras a mão ao teu irmão pobre. Não é dispensa de cuidar dos pobres — é lembrança de que a ocasião de o fazer não acaba nunca, e esta acaba."},
{v:12,t:"Derramando este perfume sobre o meu corpo, ela o fez para a minha sepultura."},
{v:13,t:"Em verdade vos digo: onde quer que for anunciado este Evangelho, no mundo inteiro, também o que ela fez será contado em sua memória."},
{p:"Marcos 14:3-9"},
{v:3,t:"Estando ele em Betânia, em casa de Simão, o leproso, sentado à mesa, veio uma mulher trazendo um vaso de alabastro com perfume de nardo puro, de grande preço; e, quebrando o vaso, derramou-o sobre a sua cabeça.",n:"O nardo vinha da Índia, e o frasco de alabastro fechava-se de modo que só se abria partindo o gargalo: não havia como guardar metade. Quebrar o vaso é dar tudo de uma vez."},
{v:4,t:"Alguns, indignados, diziam entre si: Para que este desperdício de perfume?"},
{v:5,t:"Podia vender-se este perfume por mais de trezentos denários e dar-se o dinheiro aos pobres. E censuravam-na."},
{v:6,t:"Mas Jesus disse: Deixai-a. Por que a molestais? Ela fez uma boa obra para comigo."},
{v:7,t:"Pobres sempre os tendes convosco, e, quando quiserdes, podeis fazer-lhes bem; mas a mim nem sempre me tendes."},
{v:8,t:"Ela fez o que pôde: antecipou-se a ungir o meu corpo para a sepultura.",n:"No domingo, as mulheres hão de ir ao sepulcro com perfumes para ungir o corpo, e não o encontrarão. Esta unção antecipada é a única que o corpo de Jesus recebeu."},
{v:9,t:"Em verdade vos digo: onde quer que for anunciado o Evangelho, no mundo inteiro, também o que ela fez será contado em sua memória."},
{p:"Lucas 7:36-50"},
{v:36,t:"Um dos fariseus convidou-o para comer com ele. E, tendo entrado na casa do fariseu, pôs-se à mesa.",n:"A unção contada por São Lucas é outro episódio, noutro tempo e lugar — na Galileia, em casa de um fariseu, por uma mulher conhecida como pecadora —, e a harmonia junta-os por afinidade. A tradição latina identificou esta mulher com Maria Madalena e com Maria de Betânia; os evangelhos não o dizem."},
{v:37,t:"E eis que uma mulher da cidade, que era pecadora, sabendo que ele estava à mesa em casa do fariseu, trouxe um vaso de alabastro com perfume"},
{v:38,t:"e, pondo-se por trás, aos pés dele, chorando, começou a banhar-lhe os pés com as lágrimas, e enxugava-os com os cabelos da sua cabeça, e beijava-lhe os pés e ungia-os com o perfume."},
{v:39,t:"Vendo isso, o fariseu que o convidara disse consigo: Se este fosse profeta, saberia quem e qual é a mulher que o toca, pois é pecadora."},
{v:40,t:"Jesus, tomando a palavra, disse-lhe: Simão, tenho uma coisa a dizer-te. Ele respondeu: Dize, Mestre.",n:"O fariseu pensara que Jesus não sabia quem era a mulher. Jesus responde ao pensamento que não foi dito — e prova assim que é profeta, pelo critério do próprio fariseu."},
{v:41,t:"Um credor tinha dois devedores: um devia quinhentos denários, e o outro cinquenta."},
{v:42,t:"Não tendo eles com que pagar, perdoou aos dois. Qual deles, pois, o amará mais?"},
{v:43,t:"Respondeu Simão: Suponho que aquele a quem mais perdoou. Ele lhe disse: Julgaste bem."},
{v:44,t:"E, voltando-se para a mulher, disse a Simão: Vês esta mulher? Entrei em tua casa, e não me deste água para os pés; mas ela banhou os meus pés com as lágrimas e enxugou-os com os seus cabelos."},
{v:45,t:"Não me deste o beijo; mas ela, desde que entrei, não cessou de me beijar os pés."},
{v:46,t:"Não me ungiste a cabeça com óleo; mas ela ungiu os meus pés com perfume."},
{v:47,t:"Por isso te digo: são-lhe perdoados os seus muitos pecados, porque muito amou; mas aquele a quem pouco se perdoa, pouco ama.",n:"Porque muito amou é das frases mais discutidas do evangelho. A parábola que a precede diz que o amor vem depois do perdão, como efeito dele; e o fim do versículo confirma-o. O porque indica, assim, o sinal pelo qual se vê o perdão — o grande amor mostra que muito foi perdoado —, e não o preço com que se paga."},
{v:48,t:"E disse a ela: Os teus pecados estão perdoados."},
{v:49,t:"Os que estavam com ele à mesa começaram a dizer entre si: Quem é este, que até perdoa pecados?"},
{v:50,t:"Mas ele disse à mulher: A tua fé te salvou; vai em paz."},
{p:"João 12:1-8"},
{v:1,t:"Seis dias antes da Páscoa, Jesus foi a Betânia, onde estava Lázaro, a quem Jesus ressuscitara dos mortos."},
{v:2,t:"Ofereceram-lhe ali um jantar; Marta servia, e Lázaro era um dos que estavam à mesa com ele."},
{v:3,t:"Então Maria, tomando uma libra de perfume de nardo puro, de grande preço, ungiu os pés de Jesus e enxugou-os com os seus cabelos; e a casa encheu-se do perfume do bálsamo.",n:"Em São João é Maria de Betânia quem unge, e unge os pés, não a cabeça. A libra era perto de um terço de quilo: uma quantidade que ninguém gastaria de uma só vez."},
{v:4,t:"Disse então Judas Iscariotes, um dos seus discípulos, aquele que o havia de entregar:"},
{v:5,t:"Por que não se vendeu este perfume por trezentos denários, para dá-los aos pobres?",n:"Trezentos denários eram o salário de um ano inteiro de trabalho."},
{v:6,t:"Disse isso não porque se importasse com os pobres, mas porque era ladrão e, tendo a bolsa, tirava o que nela se lançava."},
{v:7,t:"Disse então Jesus: Deixa-a; ela o guardou para o dia da minha sepultura."},
{v:8,t:"Pois pobres sempre os tendes convosco; mas a mim nem sempre me tendes."}
];

EV[152] = [
{p:"Mateus 26:1-5"},
{v:1,t:"E aconteceu que, tendo Jesus acabado todos estes discursos, disse aos seus discípulos:"},
{v:2,t:"Sabeis que daqui a dois dias é a Páscoa, e o Filho do Homem será entregue para ser crucificado."},
{v:3,t:"Então os sumos sacerdotes e os anciãos do povo reuniram-se no palácio do sumo sacerdote, chamado Caifás,"},
{v:4,t:"e deliberaram prender Jesus à traição e matá-lo."},
{v:5,t:"Mas diziam: Não durante a festa, para que não haja tumulto entre o povo.",n:"Queriam evitar a festa, com Jerusalém cheia de peregrinos, e é justamente na festa que tudo acontece. O calendário acaba por ser o de Deus, e não o deles."},
{p:"Mateus 26:14-16"},
{v:14,t:"Então um dos Doze, chamado Judas Iscariotes, foi ter com os sumos sacerdotes"},
{v:15,t:"e disse: Que me dareis, se eu o entregar a vós? E eles fixaram-lhe trinta moedas de prata.",n:"Trinta siclos de prata eram, no Êxodo, a indenização pela morte de um escravo. E são o salário irrisório que o profeta Zacarias recebe, no capítulo 11, e que Deus manda lançar no tesouro do templo. São Mateus há de voltar a este número quando contar o fim de Judas."},
{v:16,t:"Desde então, procurava uma ocasião oportuna para o entregar."},
{p:"Marcos 14:1-2"},
{v:1,t:"Faltavam dois dias para a Páscoa e os Ázimos. E os sumos sacerdotes e os escribas procuravam como prendê-lo à traição e matá-lo."},
{v:2,t:"Pois diziam: Não durante a festa, para que não haja tumulto entre o povo."},
{p:"Marcos 14:10-11"},
{v:10,t:"Então Judas Iscariotes, um dos Doze, foi ter com os sumos sacerdotes para o entregar a eles.",n:"São Marcos põe a traição logo depois da unção em Betânia, como se uma coisa respondesse à outra: a mulher gasta tudo com ele; Judas vende-o."},
{v:11,t:"Ouvindo isso, alegraram-se e prometeram dar-lhe dinheiro. E ele procurava como o entregar em ocasião oportuna."},
{p:"Lucas 22:1-6"},
{v:1,t:"Aproximava-se a festa dos Ázimos, chamada Páscoa."},
{v:2,t:"E os sumos sacerdotes e os escribas procuravam como haviam de matá-lo, pois temiam o povo."},
{v:3,t:"Entrou, então, Satanás em Judas, chamado Iscariotes, que era do número dos Doze.",n:"No fim das tentações do deserto, São Lucas escrevera que o diabo se afastou dele até ao tempo oportuno. É aqui que volta."},
{v:4,t:"E foi combinar com os sumos sacerdotes e os chefes da guarda o modo de entregá-lo a eles."},
{v:5,t:"Eles alegraram-se e ajustaram dar-lhe dinheiro."},
{v:6,t:"Ele concordou, e procurava ocasião oportuna para entregá-lo a eles, longe da multidão."},
{p:"João 12:9-11"},
{v:9,t:"Uma grande multidão de judeus soube que ele estava ali, e vieram, não só por causa de Jesus, mas também para ver Lázaro, a quem ressuscitara dos mortos."},
{v:10,t:"Os sumos sacerdotes, porém, resolveram matar também Lázaro,"},
{v:11,t:"porque, por causa dele, muitos dos judeus se afastavam e criam em Jesus.",n:"Resolvem matar um homem por estar vivo. O evangelista deixa a decisão sem comentário, e ela diz o bastante."}
];

EV[153] = [
{p:"Mateus 21:1-11"},
{v:1,t:"Quando se aproximaram de Jerusalém e chegaram a Betfagé, junto ao monte das Oliveiras, Jesus enviou dois discípulos,"},
{v:2,t:"dizendo-lhes: Ide à aldeia que está defronte de vós, e logo encontrareis uma jumenta amarrada, e com ela um jumentinho; desamarrai-os e trazei-os a mim."},
{v:3,t:"E, se alguém vos disser alguma coisa, respondei: O Senhor precisa deles; e logo os deixará vir."},
{v:4,t:"Isto aconteceu para que se cumprisse o que foi dito pelo profeta:"},
{v:5,t:"Dizei à filha de Sião: Eis que o teu rei vem a ti, manso e montado numa jumenta, num jumentinho, filho de animal de carga.",n:"A profecia é de Zacarias 9, e anuncia um rei que vem montado não no cavalo de guerra, mas no animal de trabalho dos pobres. O versículo seguinte do profeta diz o que esse rei faz: tira os carros de guerra de Efraim e fala de paz às nações."},
{v:6,t:"Os discípulos foram e fizeram como Jesus lhes ordenara."},
{v:7,t:"Trouxeram a jumenta e o jumentinho, puseram sobre eles os seus mantos, e ele montou.",n:"São Mateus lê o paralelismo de Zacarias à letra — uma jumenta, um jumentinho — e põe na cena dois animais, onde os outros evangelistas põem um só. É o seu modo de mostrar a profecia cumprida até ao pormenor."},
{v:8,t:"Grande parte da multidão estendeu os seus mantos pelo caminho; outros cortavam ramos das árvores e os espalhavam pelo caminho.",n:"Estender os mantos no chão era a homenagem prestada a Jeú quando foi aclamado rei, no segundo livro dos Reis."},
{v:9,t:"E as multidões que iam à frente e as que o seguiam gritavam: Hosana ao Filho de Davi! Bendito o que vem em nome do Senhor! Hosana nas alturas!",n:"É o Salmo 118, versículos 25 e 26, cantado nas festas. Hosana, que era grito de súplica — salva-nos! —, tornara-se aclamação."},
{v:10,t:"Quando entrou em Jerusalém, toda a cidade se agitou, dizendo: Quem é este?",n:"Agitou-se traduz eseisthe, o verbo do terremoto. São Mateus usa-o ainda na morte de Jesus e na ressurreição."},
{v:11,t:"E as multidões diziam: Este é o profeta Jesus, de Nazaré da Galileia."},
{p:"Marcos 11:1-11"},
{v:1,t:"Quando se aproximavam de Jerusalém, de Betfagé e de Betânia, junto ao monte das Oliveiras, enviou dois dos seus discípulos"},
{v:2,t:"e disse-lhes: Ide à aldeia que está defronte de vós; e logo que nela entrardes, encontrareis um jumentinho amarrado, sobre o qual nenhum homem ainda montou; desamarrai-o e trazei-o.",n:"Um animal em que ninguém montou era o exigido, segundo a lei, para os usos sagrados — como a novilha vermelha dos Números, sobre a qual nunca se pôs jugo."},
{v:3,t:"E, se alguém vos disser: Por que fazeis isso?, dizei: O Senhor precisa dele, e logo o mandará de volta para cá."},
{v:4,t:"Foram e encontraram o jumentinho amarrado junto de uma porta, do lado de fora, na rua, e desamarraram-no."},
{v:5,t:"Alguns dos que ali estavam disseram-lhes: Que fazeis, desamarrando o jumentinho?"},
{v:6,t:"Eles responderam como Jesus lhes tinha dito, e deixaram-nos ir."},
{v:7,t:"Trouxeram o jumentinho a Jesus, puseram-lhe em cima os seus mantos, e ele montou."},
{v:8,t:"Muitos estenderam os seus mantos pelo caminho, e outros, ramos que cortavam nos campos."},
{v:9,t:"E os que iam à frente e os que seguiam gritavam: Hosana! Bendito o que vem em nome do Senhor!"},
{v:10,t:"Bendito o Reino que vem, o de nosso pai Davi! Hosana nas alturas!"},
{v:11,t:"E entrou em Jerusalém, no templo; e, depois de observar tudo em redor, sendo já tarde, saiu para Betânia com os Doze.",n:"Em São Marcos, a entrada triunfal acaba num silêncio: Jesus olha o templo e vai-se embora. O que viu só se saberá no dia seguinte."},
{p:"Lucas 19:29-44"},
{v:29,t:"Quando se aproximou de Betfagé e de Betânia, junto ao monte chamado das Oliveiras, enviou dois discípulos,"},
{v:30,t:"dizendo: Ide à aldeia que está defronte; ao entrardes nela, encontrareis um jumentinho amarrado, sobre o qual nenhum homem ainda montou; desamarrai-o e trazei-o."},
{v:31,t:"E, se alguém vos perguntar: Por que o desamarrais?, direis assim: O Senhor precisa dele."},
{v:32,t:"Os que foram enviados partiram e encontraram tudo como ele lhes dissera."},
{v:33,t:"Quando desamarravam o jumentinho, os seus donos disseram-lhes: Por que desamarrais o jumentinho?"},
{v:34,t:"Eles responderam: O Senhor precisa dele."},
{v:35,t:"Levaram-no a Jesus e, lançando os seus mantos sobre o jumentinho, fizeram Jesus montar."},
{v:36,t:"E, enquanto ele avançava, estendiam os seus mantos pelo caminho."},
{v:37,t:"Quando já se aproximava da descida do monte das Oliveiras, toda a multidão dos discípulos, cheia de alegria, começou a louvar a Deus em alta voz por todos os milagres que tinham visto,"},
{v:38,t:"dizendo: Bendito o Rei que vem em nome do Senhor! Paz no céu e glória nas alturas!",n:"Na noite de Belém, os anjos cantaram glória nas alturas e paz na terra. Aqui os discípulos cantam paz no céu e glória nas alturas: a paz que foi anunciada à terra volta agora para o céu, porque a cidade não a quis."},
{v:39,t:"Alguns dos fariseus que estavam no meio da multidão disseram-lhe: Mestre, repreende os teus discípulos."},
{v:40,t:"Ele respondeu: Eu vos digo que, se estes se calarem, as pedras gritarão."},
{v:41,t:"Quando se aproximou, ao ver a cidade, chorou sobre ela,",n:"Só São Lucas o conta. É a segunda vez que os evangelhos dizem que Jesus chorou — a primeira foi diante do sepulcro de Lázaro —, e o verbo aqui é o do pranto alto, não das lágrimas silenciosas."},
{v:42,t:"dizendo: Se também tu conhecesses, ao menos neste teu dia, o que te pode trazer a paz! Mas agora isso está escondido aos teus olhos."},
{v:43,t:"Porque virão dias sobre ti em que os teus inimigos te cercarão de trincheiras, te sitiarão e te apertarão de todos os lados;",n:"No cerco do ano 70, Tito mandou erguer à volta de Jerusalém uma muralha de terra e estacas para que ninguém saísse, e a cidade morreu de fome antes de ser tomada. A descrição corresponde ao que o historiador Josefo conta."},
{v:44,t:"e te deitarão por terra, a ti e aos teus filhos que estão dentro de ti, e não deixarão em ti pedra sobre pedra, porque não conheceste o tempo em que foste visitada."},
{p:"João 12:12-19"},
{v:12,t:"No dia seguinte, a grande multidão que viera à festa, ouvindo que Jesus vinha a Jerusalém,"},
{v:13,t:"tomou ramos de palmeiras e saiu ao seu encontro, clamando: Hosana! Bendito o que vem em nome do Senhor, o Rei de Israel!",n:"Só São João diz que os ramos eram de palmeira, e é dele que vem o nome do domingo de Ramos. A palmeira era, desde os Macabeus, o emblema da vitória e da libertação nacional: estava cunhada nas moedas da revolta contra os gregos."},
{v:14,t:"E Jesus, tendo encontrado um jumentinho, montou nele, como está escrito:"},
{v:15,t:"Não temas, filha de Sião; eis que o teu Rei vem, montado num jumentinho."},
{v:16,t:"Os seus discípulos não compreenderam isso a princípio; mas, quando Jesus foi glorificado, então se lembraram de que isso estava escrito a respeito dele e de que assim lhe tinham feito."},
{v:17,t:"A multidão que estava com ele quando chamou Lázaro do sepulcro e o ressuscitou dos mortos dava testemunho."},
{v:18,t:"Por isso também a multidão foi ao seu encontro: porque ouviram que ele tinha feito esse sinal."},
{v:19,t:"Disseram então os fariseus entre si: Vedes que nada conseguis? Eis que o mundo inteiro vai atrás dele!",n:"Mais uma frase dos adversários que diz a verdade sem o saber. O versículo seguinte começa: havia alguns gregos entre os que tinham subido para adorar na festa."}
];

EV[154] = [
{p:"Mateus 21:18-22"},
{v:18,t:"De manhã, voltando para a cidade, teve fome."},
{v:19,t:"E, vendo uma figueira à beira do caminho, foi até ela, e nada encontrou nela senão folhas; e disse-lhe: Nunca mais nasça fruto de ti. E a figueira secou imediatamente.",n:"É o único milagre de castigo nos evangelhos, e é um gesto profético, à maneira de Jeremias e Ezequiel: uma ação que diz alguma coisa. Nos profetas, a figueira sem figos é Israel quando Deus vem procurar fruto e não o encontra."},
{v:20,t:"Vendo isso, os discípulos admiraram-se e disseram: Como secou tão depressa a figueira?"},
{v:21,t:"Jesus respondeu-lhes: Em verdade vos digo: se tiverdes fé e não duvidardes, não só fareis o que foi feito à figueira, mas até, se disserdes a este monte: Ergue-te e lança-te no mar, assim será feito."},
{v:22,t:"E tudo o que pedirdes na oração, com fé, recebereis."},
{p:"Marcos 11:12-14"},
{v:12,t:"No dia seguinte, ao saírem de Betânia, teve fome."},
{v:13,t:"E, vendo de longe uma figueira que tinha folhas, foi ver se acharia nela alguma coisa; mas, chegando a ela, nada encontrou senão folhas, porque não era tempo de figos.",n:"Não era tempo de figos: a frase é de São Marcos e torna a cena absurda de propósito — ninguém esperaria figos em abril. O leitor é obrigado a perceber que não se trata de fruticultura. E Marcos põe a figueira antes e depois da expulsão dos vendilhões: o que se passa com a árvore diz o que se passa com o templo, cheio de folhagem e sem fruto."},
{v:14,t:"E, tomando a palavra, disse-lhe: Nunca mais ninguém coma fruto de ti. E os seus discípulos ouviram."},
{p:"Marcos 11:20-25"},
{v:20,t:"De manhã, ao passarem, viram a figueira seca até às raízes."},
{v:21,t:"E Pedro, lembrando-se, disse-lhe: Rabi, eis que a figueira que amaldiçoaste secou."},
{v:22,t:"Jesus, tomando a palavra, disse-lhes: Tende fé em Deus."},
{v:23,t:"Em verdade vos digo que, se alguém disser a este monte: Ergue-te e lança-te no mar, e não duvidar no seu coração, mas crer que se fará o que diz, assim lhe será feito.",n:"Este monte, dito no caminho para Jerusalém, é provavelmente o próprio monte do templo. A fé que se pede é capaz de remover aquilo que parecia a coisa mais firme do mundo."},
{v:24,t:"Por isso vos digo: tudo o que pedirdes na oração, crede que o recebestes, e assim será para vós."},
{v:25,t:"E, quando estiverdes de pé orando, perdoai, se tendes alguma coisa contra alguém, para que também vosso Pai, que está nos céus, vos perdoe as vossas ofensas.",n:"Alguns manuscritos acrescentam um versículo 26, tirado de São Mateus: mas, se não perdoardes, também vosso Pai não vos perdoará. Falta nos mais antigos, e a Nova Vulgata omite-o."}
];

EV[155] = [
{p:"Mateus 21:12-17"},
{v:12,t:"Jesus entrou no templo e expulsou todos os que ali vendiam e compravam; derrubou as mesas dos cambistas e as cadeiras dos que vendiam pombas,",n:"O comércio era legal e útil: vendiam-se os animais para os sacrifícios, e trocava-se a moeda romana, que tinha a imagem do imperador, pela de Tiro, a única aceita para o imposto do templo. As pombas eram a oferta dos pobres."},
{v:13,t:"e disse-lhes: Está escrito: A minha casa será chamada casa de oração; mas vós fazeis dela um covil de ladrões.",n:"Duas citações num versículo: casa de oração é de Isaías 56; covil de ladrões, de Jeremias 7. O covil não é o lugar onde se rouba, mas onde os salteadores se escondem depois de roubar — o templo usado como refúgio por quem vive mal lá fora."},
{v:14,t:"Aproximaram-se dele, no templo, cegos e coxos, e ele os curou.",n:"Cegos e coxos eram mantidos fora do templo, segundo uma tradição que remontava a Davi. São os primeiros a quem Jesus abre a casa que acabou de limpar."},
{v:15,t:"Mas os sumos sacerdotes e os escribas, vendo as maravilhas que fizera e as crianças que gritavam no templo: Hosana ao Filho de Davi!, indignaram-se"},
{v:16,t:"e disseram-lhe: Ouves o que estes dizem? Jesus respondeu-lhes: Sim. Nunca lestes: Da boca dos pequeninos e das crianças de peito tiraste o louvor?",n:"É o versículo 3 do Salmo 8, na forma da antiga versão grega. O salmo continua: por causa dos teus adversários, para fazer calar o inimigo."},
{v:17,t:"E, deixando-os, saiu da cidade para Betânia, e ali pernoitou."},
{p:"Marcos 11:15-19"},
{v:15,t:"Chegaram a Jerusalém. E, entrando no templo, começou a expulsar os que ali vendiam e compravam; derrubou as mesas dos cambistas e as cadeiras dos que vendiam pombas,"},
{v:16,t:"e não permitia que ninguém atravessasse o templo levando qualquer objeto."},
{v:17,t:"E ensinava-os, dizendo: Não está escrito: A minha casa será chamada casa de oração para todos os povos? Mas vós fizestes dela um covil de ladrões.",n:"Só São Marcos completa a citação de Isaías: para todos os povos. E o mercado ficava precisamente no átrio dos gentios, o único lugar do templo onde um estrangeiro podia rezar — era ali, e só ali, que o barulho do comércio lhe roubava o lugar."},
{v:18,t:"Os sumos sacerdotes e os escribas ouviram isso e procuravam como o haviam de matar; pois tinham-lhe medo, porque toda a multidão estava maravilhada com o seu ensino."},
{v:19,t:"E, quando chegava a tarde, saíam da cidade."},
{p:"Lucas 19:45-48"},
{v:45,t:"E, entrando no templo, começou a expulsar os que vendiam,"},
{v:46,t:"dizendo-lhes: Está escrito: A minha casa será casa de oração; mas vós fizestes dela um covil de ladrões."},
{v:47,t:"E ensinava todos os dias no templo. Os sumos sacerdotes, os escribas e os chefes do povo procuravam matá-lo;"},
{v:48,t:"mas não encontravam o que haviam de fazer, porque todo o povo estava suspenso das suas palavras."}
];

EV[156] = [
{p:"Mateus 21:23-27"},
{v:23,t:"Tendo ele entrado no templo, aproximaram-se dele, enquanto ensinava, os sumos sacerdotes e os anciãos do povo, dizendo: Com que autoridade fazes estas coisas? E quem te deu essa autoridade?",n:"Estas coisas é a expulsão dos vendilhões da véspera. Os sumos sacerdotes eram as autoridades do templo, e perguntam, com razão formal, quem lhe deu licença."},
{v:24,t:"Jesus respondeu-lhes: Também eu vos farei uma pergunta; se me responderdes, também eu vos direi com que autoridade faço estas coisas."},
{v:25,t:"O batismo de João, donde era? Do céu ou dos homens? Eles discorriam entre si: Se dissermos: Do céu, ele nos dirá: Por que, então, não crestes nele?",n:"Responder a uma pergunta com outra era método corrente entre os rabinos, e esta não é uma fuga: contém a resposta. Se a autoridade de João vinha do céu, a de quem João anunciou também vem."},
{v:26,t:"E, se dissermos: Dos homens, tememos a multidão, porque todos têm João por profeta."},
{v:27,t:"Responderam, pois, a Jesus: Não sabemos. E ele lhes disse: Nem eu vos digo com que autoridade faço estas coisas."},
{p:"Marcos 11:27-33"},
{v:27,t:"Voltaram a Jerusalém. E, enquanto ele andava pelo templo, aproximaram-se dele os sumos sacerdotes, os escribas e os anciãos,"},
{v:28,t:"e disseram-lhe: Com que autoridade fazes estas coisas? Ou quem te deu autoridade para fazê-las?"},
{v:29,t:"Jesus disse-lhes: Vou fazer-vos uma pergunta; respondei-me, e eu vos direi com que autoridade faço estas coisas."},
{v:30,t:"O batismo de João era do céu ou dos homens? Respondei-me."},
{v:31,t:"Eles discorriam entre si: Se dissermos: Do céu, ele dirá: Por que, então, não crestes nele?"},
{v:32,t:"Mas, se dissermos: Dos homens...? Temiam o povo, pois todos tinham João verdadeiramente por profeta.",n:"A frase fica interrompida no grego, como a de quem não ousa acabá-la. O evangelista completa-a com o motivo: tinham medo."},
{v:33,t:"Responderam, pois, a Jesus: Não sabemos. E Jesus lhes disse: Nem eu vos digo com que autoridade faço estas coisas."},
{p:"Lucas 20:1-8"},
{v:1,t:"Aconteceu num daqueles dias que, estando ele ensinando o povo no templo e anunciando o Evangelho, sobrevieram os sumos sacerdotes e os escribas com os anciãos,"},
{v:2,t:"e falaram-lhe, dizendo: Dize-nos com que autoridade fazes estas coisas, ou quem é que te deu esta autoridade."},
{v:3,t:"Ele respondeu-lhes: Também eu vos farei uma pergunta. Dizei-me:"},
{v:4,t:"O batismo de João era do céu ou dos homens?"},
{v:5,t:"Eles discorriam entre si, dizendo: Se dissermos: Do céu, ele dirá: Por que não crestes nele?"},
{v:6,t:"E, se dissermos: Dos homens, todo o povo nos apedrejará, porque está convencido de que João era profeta."},
{v:7,t:"Responderam, pois, que não sabiam donde era."},
{v:8,t:"E Jesus lhes disse: Nem eu vos digo com que autoridade faço estas coisas."}
];

EV[157] = [
{p:"Mateus 21:28-32"},
{v:28,t:"Que vos parece? Um homem tinha dois filhos. Dirigindo-se ao primeiro, disse: Filho, vai hoje trabalhar na vinha."},
{v:29,t:"Ele respondeu: Não quero; mas depois, arrependido, foi.",n:"Os manuscritos trocam a ordem dos dois filhos, e com ela a resposta do versículo 31. A Nova Vulgata segue esta ordem, que é a das testemunhas mais antigas: primeiro o que diz não e vai."},
{v:30,t:"Dirigindo-se ao outro, disse-lhe o mesmo. Este respondeu: Eu vou, senhor; mas não foi."},
{v:31,t:"Qual dos dois fez a vontade do pai? Disseram-lhe: O primeiro. Jesus disse-lhes: Em verdade vos digo que os publicanos e as prostitutas vos precedem no Reino de Deus.",n:"Vos precedem não diz que eles ficarão de fora: diz que vão à frente. A porta continua aberta para os que ouvem, e a parábola é dita para que ainda se arrependam."},
{v:32,t:"Porque veio João até vós no caminho da justiça, e não crestes nele; mas os publicanos e as prostitutas creram nele. E vós, vendo isso, nem depois vos arrependestes para crer nele."}
];

EV[158] = [
{p:"Mateus 21:33-46"},
{v:33,t:"Ouvi outra parábola. Havia um pai de família que plantou uma vinha, cercou-a com uma sebe, cavou nela um lagar e edificou uma torre; depois arrendou-a a vinhateiros e partiu para longe.",n:"A primeira frase é quase uma citação do canto da vinha de Isaías 5, que todos conheciam: a vinha é Israel. Os ouvintes sabiam de que se falava desde a primeira linha."},
{v:34,t:"Quando se aproximou o tempo dos frutos, enviou os seus servos aos vinhateiros para receberem os frutos."},
{v:35,t:"Mas os vinhateiros, agarrando os servos, espancaram um, mataram outro e apedrejaram outro."},
{v:36,t:"Enviou de novo outros servos, em maior número que os primeiros; e fizeram-lhes o mesmo."},
{v:37,t:"Por último, enviou-lhes o seu filho, dizendo: Hão de respeitar o meu filho."},
{v:38,t:"Mas os vinhateiros, vendo o filho, disseram entre si: Este é o herdeiro; vinde, matemo-lo e fiquemos com a sua herança."},
{v:39,t:"E, agarrando-o, lançaram-no fora da vinha e mataram-no.",n:"São Mateus e São Lucas invertem a ordem de São Marcos: primeiro lançam-no fora, depois matam-no. É a ordem da Paixão, fora das muralhas da cidade."},
{v:40,t:"Quando, pois, vier o senhor da vinha, que fará àqueles vinhateiros?"},
{v:41,t:"Disseram-lhe: Fará perecer miseravelmente esses malvados e arrendará a vinha a outros vinhateiros, que lhe entreguem os frutos a seu tempo.",n:"Como Davi diante da parábola de Natã, os ouvintes pronunciam a sentença sem perceber que é a sua."},
{v:42,t:"Disse-lhes Jesus: Nunca lestes nas Escrituras: A pedra que os construtores rejeitaram veio a ser a pedra angular; pelo Senhor foi feito isso, e é maravilhoso aos nossos olhos?"},
{v:43,t:"Por isso vos digo que o Reino de Deus vos será tirado e será dado a um povo que produza os seus frutos."},
{v:44,t:"E quem cair sobre esta pedra ficará despedaçado; e aquele sobre quem ela cair será esmagado.",n:"O versículo falta em alguns manuscritos, e há quem o julgue trazido de São Lucas. A Nova Vulgata conserva-o."},
{v:45,t:"Os sumos sacerdotes e os fariseus, ouvindo as suas parábolas, compreenderam que falava deles."},
{v:46,t:"E, procurando prendê-lo, tiveram medo das multidões, porque estas o tinham por profeta."},
{p:"Marcos 12:1-12"},
{v:1,t:"E começou a falar-lhes em parábolas: Um homem plantou uma vinha, cercou-a com uma sebe, cavou um lagar e edificou uma torre; depois arrendou-a a vinhateiros e partiu para longe."},
{v:2,t:"No tempo próprio, enviou um servo aos vinhateiros, para receber deles a sua parte dos frutos da vinha."},
{v:3,t:"Mas eles, agarrando-o, espancaram-no e mandaram-no embora de mãos vazias."},
{v:4,t:"Enviou-lhes de novo outro servo; também a este feriram na cabeça e ultrajaram."},
{v:5,t:"Enviou ainda outro, e a este mataram; e muitos outros, dos quais espancaram uns e mataram outros."},
{v:6,t:"Restava-lhe ainda um, o filho amado. Enviou-o por último, dizendo: Hão de respeitar o meu filho.",n:"O filho amado é o nome que a voz do céu lhe deu no batismo e na Transfiguração. Na parábola é o último enviado, e depois dele não há mais nenhum."},
{v:7,t:"Mas aqueles vinhateiros disseram entre si: Este é o herdeiro; vinde, matemo-lo, e a herança será nossa."},
{v:8,t:"E, agarrando-o, mataram-no e lançaram-no fora da vinha."},
{v:9,t:"Que fará, pois, o senhor da vinha? Virá, fará perecer os vinhateiros e dará a vinha a outros."},
{v:10,t:"Não lestes esta Escritura: A pedra que os construtores rejeitaram veio a ser a pedra angular;"},
{v:11,t:"pelo Senhor foi feito isso, e é maravilhoso aos nossos olhos?"},
{v:12,t:"Procuravam prendê-lo, mas tiveram medo da multidão; pois compreenderam que tinha dito a parábola a respeito deles. E, deixando-o, foram-se embora."},
{p:"Lucas 20:9-19"},
{v:9,t:"Começou então a contar ao povo esta parábola: Um homem plantou uma vinha, arrendou-a a vinhateiros e ausentou-se por muito tempo."},
{v:10,t:"No tempo próprio, enviou um servo aos vinhateiros, para que lhe dessem do fruto da vinha. Mas os vinhateiros, espancando-o, mandaram-no embora de mãos vazias."},
{v:11,t:"Tornou a enviar outro servo; mas eles, depois de espancá-lo também e de ultrajá-lo, mandaram-no embora de mãos vazias."},
{v:12,t:"Tornou a enviar um terceiro; e a este também feriram e lançaram fora."},
{v:13,t:"Disse então o senhor da vinha: Que farei? Enviarei o meu filho amado; talvez o respeitem."},
{v:14,t:"Mas os vinhateiros, vendo-o, discorreram entre si, dizendo: Este é o herdeiro; matemo-lo, para que a herança seja nossa."},
{v:15,t:"E, lançando-o fora da vinha, mataram-no. Que lhes fará, pois, o senhor da vinha?"},
{v:16,t:"Virá, fará perecer esses vinhateiros e dará a vinha a outros. Ouvindo isso, disseram: Tal não aconteça!"},
{v:17,t:"Mas ele, fitando neles o olhar, disse: Que significa, então, o que está escrito: A pedra que os construtores rejeitaram veio a ser a pedra angular?"},
{v:18,t:"Todo o que cair sobre essa pedra ficará despedaçado; e aquele sobre quem ela cair será esmagado."},
{v:19,t:"Os escribas e os sumos sacerdotes procuravam deitar-lhe as mãos naquela mesma hora, mas tiveram medo do povo; porque compreenderam que tinha dito essa parábola a respeito deles."}
];

EV[159] = [
{p:"Mateus 22:1-14"},
{v:1,t:"Tomando a palavra, Jesus falou-lhes de novo em parábolas, dizendo:"},
{v:2,t:"O Reino dos céus é semelhante a um rei que celebrou as bodas de seu filho."},
{v:3,t:"Enviou os seus servos a chamar os convidados para as bodas, mas eles não quiseram vir."},
{v:4,t:"Enviou de novo outros servos, dizendo: Dizei aos convidados: Eis que preparei o meu banquete; os meus bois e os animais cevados já foram abatidos, e tudo está pronto: vinde às bodas."},
{v:5,t:"Mas eles, sem fazerem caso, foram-se, um para o seu campo, outro para o seu negócio;"},
{v:6,t:"e os outros, agarrando os servos, ultrajaram-nos e mataram-nos."},
{v:7,t:"O rei, indignado, enviou as suas tropas, exterminou aqueles assassinos e incendiou a sua cidade.",n:"Um rei que manda queimar uma cidade antes de acabar o jantar: o pormenor é desproporcionado para uma parábola, e os leitores de São Mateus reconheciam nele o incêndio de Jerusalém no ano 70."},
{v:8,t:"Disse então aos servos: As bodas estão prontas, mas os convidados não eram dignos."},
{v:9,t:"Ide, pois, às encruzilhadas dos caminhos e convidai para as bodas todos os que encontrardes."},
{v:10,t:"Os servos saíram pelos caminhos e reuniram todos os que encontraram, maus e bons; e a sala das bodas encheu-se de convidados."},
{v:11,t:"Entrando o rei para ver os convidados, viu ali um homem que não estava vestido com a veste nupcial,",n:"Quem é trazido da rua não tem roupa de festa, e é por isso que se entende que o rei a fornecia à entrada. Não se censura a pobreza do homem, mas a recusa da veste que lhe davam: entrou no banquete sem aceitar ser convidado."},
{v:12,t:"e disse-lhe: Amigo, como entraste aqui sem a veste nupcial? Ele, porém, emudeceu."},
{v:13,t:"Disse então o rei aos serventes: Amarrai-lhe os pés e as mãos e lançai-o nas trevas exteriores; ali haverá pranto e ranger de dentes."},
{v:14,t:"Porque muitos são os chamados, mas poucos os escolhidos."}
];

EV[160] = [
{p:"Mateus 22:15-22"},
{v:15,t:"Então os fariseus retiraram-se e deliberaram como o apanhariam em alguma palavra."},
{v:16,t:"E enviaram-lhe os seus discípulos, juntamente com os herodianos, dizendo: Mestre, sabemos que és verdadeiro e ensinas o caminho de Deus segundo a verdade, sem te importares com ninguém, porque não olhas à aparência dos homens.",n:"Fariseus e herodianos estavam em lados opostos: os primeiros detestavam o imposto de Roma, os segundos viviam dele. A pergunta é feita para que qualquer resposta seja fatal — sim, e Jesus é colaborador; não, e é rebelde."},
{v:17,t:"Dize-nos, pois, que te parece: é lícito pagar tributo a César, ou não?"},
{v:18,t:"Jesus, conhecendo a sua malícia, disse: Por que me tentais, hipócritas?"},
{v:19,t:"Mostrai-me a moeda do tributo. Eles apresentaram-lhe um denário.",n:"Eles têm a moeda, e tiram-na do bolso dentro do templo. O denário de Tibério trazia a efígie do imperador e a inscrição filho do divino Augusto: uma imagem proibida pela lei, com um título blasfemo."},
{v:20,t:"E ele lhes perguntou: De quem é esta imagem e esta inscrição?"},
{v:21,t:"Responderam-lhe: De César. Então lhes disse: Dai, pois, a César o que é de César, e a Deus o que é de Deus.",n:"Os Padres leram a frase a partir da palavra imagem: a moeda traz a imagem de César, e é a ele que se deve; o homem traz a imagem de Deus, segundo o Gênesis, e deve-se inteiro a Deus. A resposta não reparte o mundo em duas metades iguais."},
{v:22,t:"Ouvindo isso, ficaram admirados; e, deixando-o, foram-se embora."},
{p:"Marcos 12:13-17"},
{v:13,t:"Enviaram-lhe alguns dos fariseus e dos herodianos, para o apanharem em alguma palavra."},
{v:14,t:"Chegando, disseram-lhe: Mestre, sabemos que és verdadeiro e não te importas com ninguém, porque não olhas à aparência dos homens, mas ensinas o caminho de Deus segundo a verdade. É lícito pagar tributo a César, ou não? Devemos pagar, ou não devemos?"},
{v:15,t:"Mas ele, conhecendo a sua hipocrisia, disse-lhes: Por que me tentais? Trazei-me um denário para que eu o veja."},
{v:16,t:"Eles trouxeram-no. E ele lhes perguntou: De quem é esta imagem e esta inscrição? Responderam-lhe: De César."},
{v:17,t:"Jesus disse-lhes: Dai a César o que é de César, e a Deus o que é de Deus. E admiravam-se muito dele."},
{p:"Lucas 20:20-26"},
{v:20,t:"Observando-o, enviaram espiões que se fingiam justos, para o apanharem em alguma palavra e o entregarem à jurisdição e à autoridade do governador."},
{v:21,t:"Perguntaram-lhe: Mestre, sabemos que falas e ensinas com retidão, e não fazes acepção de pessoas, mas ensinas o caminho de Deus segundo a verdade."},
{v:22,t:"É-nos lícito pagar tributo a César, ou não?"},
{v:23,t:"Ele, porém, percebendo a sua astúcia, disse-lhes:"},
{v:24,t:"Mostrai-me um denário. De quem tem a imagem e a inscrição? Responderam: De César."},
{v:25,t:"Ele lhes disse: Dai, pois, a César o que é de César, e a Deus o que é de Deus."},
{v:26,t:"E não puderam apanhá-lo em palavra alguma diante do povo; e, admirados da sua resposta, calaram-se.",n:"Diante de Pilatos, dias depois, hão de acusá-lo precisamente de proibir que se pague o tributo a César. São Lucas conta-o no capítulo 23, e o leitor sabe que é falso."}
];

EV[161] = [
{p:"Mateus 22:23-33"},
{v:23,t:"Naquele dia, aproximaram-se dele saduceus, que dizem não haver ressurreição, e interrogaram-no,",n:"Os saduceus eram o partido das famílias sacerdotais. Só reconheciam como Escritura os cinco livros de Moisés, e neles não encontravam a ressurreição. É por isso que Jesus lhes responde com um texto de Moisés."},
{v:24,t:"dizendo: Mestre, Moisés disse: Se alguém morrer sem filhos, seu irmão casará com a viúva e suscitará descendência a seu irmão."},
{v:25,t:"Ora, havia entre nós sete irmãos. O primeiro, tendo casado, morreu; e, não tendo descendência, deixou a mulher a seu irmão."},
{v:26,t:"O mesmo aconteceu com o segundo e com o terceiro, até ao sétimo."},
{v:27,t:"Por último, depois de todos, morreu também a mulher."},
{v:28,t:"Na ressurreição, pois, de qual dos sete será ela mulher, uma vez que todos a tiveram?"},
{v:29,t:"Jesus respondeu-lhes: Errais, por não conhecerdes as Escrituras nem o poder de Deus."},
{v:30,t:"Porque, na ressurreição, nem os homens casam nem as mulheres são dadas em casamento; mas são como os anjos no céu."},
{v:31,t:"E, quanto à ressurreição dos mortos, não lestes o que Deus vos disse:"},
{v:32,t:"Eu sou o Deus de Abraão, o Deus de Isaac e o Deus de Jacó? Ele não é Deus de mortos, mas de vivos.",n:"O argumento está no tempo do verbo. Deus diz a Moisés eu sou, e não eu fui, o Deus de Abraão — séculos depois de Abraão ter morrido. Se a relação continua, continua quem está nela."},
{v:33,t:"E as multidões, ouvindo isso, ficaram maravilhadas com o seu ensino."},
{p:"Marcos 12:18-27"},
{v:18,t:"Aproximaram-se dele alguns saduceus, que dizem não haver ressurreição, e interrogaram-no, dizendo:"},
{v:19,t:"Mestre, Moisés deixou-nos escrito que, se morrer o irmão de alguém e deixar mulher sem filhos, seu irmão tome a mulher e suscite descendência a seu irmão."},
{v:20,t:"Havia sete irmãos. O primeiro tomou mulher e morreu sem deixar descendência."},
{v:21,t:"O segundo tomou-a e morreu sem deixar descendência; e o terceiro, do mesmo modo."},
{v:22,t:"E nenhum dos sete deixou descendência. Por último, depois de todos, morreu também a mulher."},
{v:23,t:"Na ressurreição, quando ressuscitarem, de qual deles será ela mulher? Pois os sete a tiveram por mulher."},
{v:24,t:"Jesus lhes disse: Não é por isto que errais, por não conhecerdes as Escrituras nem o poder de Deus?"},
{v:25,t:"Porque, quando ressuscitarem dos mortos, nem os homens casam nem as mulheres são dadas em casamento; mas são como os anjos nos céus."},
{v:26,t:"E, quanto aos mortos que ressuscitam, não lestes no livro de Moisés, no trecho da sarça, como Deus lhe falou, dizendo: Eu sou o Deus de Abraão, o Deus de Isaac e o Deus de Jacó?",n:"No trecho da sarça: não havia divisão em capítulos, e as passagens citavam-se pelo assunto. É o capítulo 3 do Êxodo."},
{v:27,t:"Ele não é Deus de mortos, mas de vivos. Estais muito enganados."},
{p:"Lucas 20:27-40"},
{v:27,t:"Aproximaram-se alguns dos saduceus, que negam haver ressurreição, e perguntaram-lhe,"},
{v:28,t:"dizendo: Mestre, Moisés deixou-nos escrito: Se o irmão de alguém morrer, tendo mulher, e não deixar filhos, seu irmão tome a mulher e suscite descendência a seu irmão."},
{v:29,t:"Havia, pois, sete irmãos. O primeiro tomou mulher e morreu sem filhos."},
{v:30,t:"Tomou-a o segundo,"},
{v:31,t:"depois o terceiro; e assim os sete, e morreram sem deixar filhos."},
{v:32,t:"Por fim, morreu também a mulher."},
{v:33,t:"Na ressurreição, pois, de qual deles será ela mulher? Pois os sete a tiveram por mulher."},
{v:34,t:"Jesus lhes disse: Os filhos deste mundo casam e são dados em casamento;"},
{v:35,t:"mas os que forem julgados dignos de alcançar o mundo futuro e a ressurreição dos mortos nem casam nem são dados em casamento;"},
{v:36,t:"pois já não podem morrer, porque são semelhantes aos anjos e são filhos de Deus, sendo filhos da ressurreição.",n:"São Lucas dá a razão que os outros não dão: o casamento existe, neste mundo, para vencer a morte com a descendência. Onde já não se morre, essa função acaba."},
{v:37,t:"E que os mortos ressuscitam, também Moisés o mostrou no trecho da sarça, quando chama ao Senhor o Deus de Abraão, o Deus de Isaac e o Deus de Jacó."},
{v:38,t:"Ele não é Deus de mortos, mas de vivos; porque para ele todos vivem."},
{v:39,t:"Alguns dos escribas, tomando a palavra, disseram: Mestre, falaste bem."},
{v:40,t:"E já não ousavam fazer-lhe pergunta alguma."}
];

EV[162] = [
{p:"Mateus 22:34-40"},
{v:34,t:"Os fariseus, ouvindo que ele fizera calar os saduceus, reuniram-se em grupo,"},
{v:35,t:"e um deles, doutor da lei, perguntou-lhe, para o pôr à prova:"},
{v:36,t:"Mestre, qual é o grande mandamento da Lei?",n:"Os rabinos contavam na Lei seiscentos e treze preceitos, e discutia-se se havia entre eles uns maiores que outros. A pergunta era das mais debatidas da época."},
{v:37,t:"Jesus disse-lhe: Amarás o Senhor teu Deus de todo o teu coração, de toda a tua alma e de todo o teu entendimento.",n:"É o Deuteronômio 6, a oração que todo judeu piedoso recitava de manhã e à tarde. Nada nesta resposta era novo."},
{v:38,t:"Este é o grande e o primeiro mandamento."},
{v:39,t:"O segundo é semelhante a este: Amarás o teu próximo como a ti mesmo.",n:"O segundo vem do Levítico 19, perdido no meio de leis de pureza e de colheita. O que é novo é juntá-lo ao primeiro e dizer que se parecem: ninguém antes os tinha posto lado a lado desta maneira."},
{v:40,t:"Destes dois mandamentos dependem toda a Lei e os Profetas.",n:"Dependem traduz kremantai, estão pendurados, como uma porta nos seus gonzos. Tirados os dois, o resto cai."},
{p:"Marcos 12:28-34"},
{v:28,t:"Aproximou-se um dos escribas, que os tinha ouvido discutir e, vendo que lhes respondera bem, perguntou-lhe: Qual é o primeiro de todos os mandamentos?"},
{v:29,t:"Jesus respondeu: O primeiro é: Ouve, Israel: o Senhor nosso Deus é o único Senhor;"},
{v:30,t:"e amarás o Senhor teu Deus de todo o teu coração, de toda a tua alma, de todo o teu entendimento e com todas as tuas forças."},
{v:31,t:"O segundo é este: Amarás o teu próximo como a ti mesmo. Não há outro mandamento maior do que estes."},
{v:32,t:"Disse-lhe o escriba: Muito bem, Mestre; disseste com verdade que ele é único e que não há outro além dele;"},
{v:33,t:"e que amá-lo de todo o coração, com todo o entendimento e com todas as forças, e amar o próximo como a si mesmo, vale mais do que todos os holocaustos e sacrifícios."},
{v:34,t:"Vendo Jesus que ele respondera sabiamente, disse-lhe: Não estás longe do Reino de Deus. E ninguém mais ousava interrogá-lo.",n:"Em São Marcos, o escriba não vem armar uma cilada: pergunta de boa-fé, concorda e recebe um elogio. É o único escriba de todo o segundo evangelho de quem se diz bem, e é dito dentro do templo, no meio das disputas."}
];

EV[163] = [
{p:"Mateus 22:41-46"},
{v:41,t:"Estando reunidos os fariseus, Jesus interrogou-os,"},
{v:42,t:"dizendo: Que pensais do Cristo? De quem é filho? Responderam-lhe: De Davi."},
{v:43,t:"Disse-lhes: Como é, então, que Davi, movido pelo Espírito, lhe chama Senhor, quando diz:"},
{v:44,t:"Disse o Senhor ao meu Senhor: Senta-te à minha direita, até que eu ponha os teus inimigos debaixo dos teus pés?",n:"É o primeiro versículo do Salmo 110, já traduzido aqui, o texto do Antigo Testamento mais citado pelo Novo. Depois de ter respondido a todos, Jesus faz a sua pergunta, e ninguém responde."},
{v:45,t:"Se, pois, Davi lhe chama Senhor, como é seu filho?"},
{v:46,t:"E ninguém lhe podia responder palavra; e, desde aquele dia, ninguém mais ousou interrogá-lo."},
{p:"Marcos 12:35-37"},
{v:35,t:"Tomando a palavra, Jesus dizia, ensinando no templo: Como dizem os escribas que o Cristo é filho de Davi?"},
{v:36,t:"O próprio Davi disse, movido pelo Espírito Santo: Disse o Senhor ao meu Senhor: Senta-te à minha direita, até que eu ponha os teus inimigos debaixo dos teus pés."},
{v:37,t:"O próprio Davi lhe chama Senhor; como, pois, é seu filho? E a grande multidão ouvia-o com agrado."},
{p:"Lucas 20:41-44"},
{v:41,t:"Ele lhes disse: Como dizem que o Cristo é filho de Davi?"},
{v:42,t:"Pois o próprio Davi diz no livro dos Salmos: Disse o Senhor ao meu Senhor: Senta-te à minha direita,"},
{v:43,t:"até que eu ponha os teus inimigos por escabelo dos teus pés."},
{v:44,t:"Davi, pois, lhe chama Senhor; como, então, é seu filho?"}
];

EV[164] = [
{p:"Mateus 23:1-39"},
{v:1,t:"Então Jesus falou às multidões e aos seus discípulos,"},
{v:2,t:"dizendo: Na cátedra de Moisés sentaram-se os escribas e os fariseus.",n:"A cátedra de Moisés era uma cadeira de pedra real, na frente da sinagoga, de onde se ensinava a Lei; conserva-se uma, do tempo, na sinagoga de Corazin. O que se reconhece é a autoridade do ensino; o que se critica, logo a seguir, é a vida de quem ensina."},
{v:3,t:"Fazei, pois, e observai tudo o que vos disserem; mas não imiteis as suas obras, porque dizem e não fazem."},
{v:4,t:"Atam fardos pesados e difíceis de carregar e põem-nos sobre os ombros dos homens; mas eles mesmos nem com o dedo os querem mover."},
{v:5,t:"Fazem todas as suas obras para serem vistos pelos homens: alargam os seus filactérios e aumentam as franjas dos seus mantos;",n:"Os filactérios são as pequenas caixas de couro com versículos da Lei que se atavam à testa e ao braço para a oração, segundo o Deuteronômio 6. As franjas, as borlas do manto mandadas pelos Números. Jesus usava-as também: o que se censura é o tamanho, feito para ser visto."},
{v:6,t:"gostam dos primeiros lugares nos banquetes e dos primeiros assentos nas sinagogas,"},
{v:7,t:"das saudações nas praças e de serem chamados rabi pelos homens."},
{v:8,t:"Vós, porém, não vos façais chamar rabi, porque um só é o vosso Mestre, e todos vós sois irmãos."},
{v:9,t:"E a ninguém na terra chameis vosso pai, porque um só é o vosso Pai, o que está nos céus.",n:"Pai era título de honra dos grandes mestres. O versículo não proíbe a palavra — São Paulo chama-se pai dos coríntios —, mas a pretensão de uma autoridade que só pertence a Deus. Todos, mestres incluídos, ficam do mesmo lado: irmãos."},
{v:10,t:"Nem vos façais chamar guias, porque um só é o vosso Guia, o Cristo."},
{v:11,t:"O maior dentre vós será o vosso servidor."},
{v:12,t:"Quem se exaltar será humilhado, e quem se humilhar será exaltado."},
{v:13,t:"Mas ai de vós, escribas e fariseus hipócritas, porque fechais aos homens o Reino dos céus! Vós não entrais, nem deixais entrar os que querem entrar.",n:"Nota do tradutor: começam aqui os sete ais, a página mais dura dos evangelhos contra os fariseus, traduzida sem atenuação. Três coisas se devem ter presentes. O próprio Jesus reconhece, no versículo 3, a autoridade do ensino deles. O farisaísmo era o movimento religioso mais próximo dele, e as suas censuras são as de dentro, como as dos profetas, e não as de um estranho. E a palavra fariseu tornou-se na língua comum sinônimo de hipócrita, com injustiça para um movimento que também produziu Nicodemos, Gamaliel e São Paulo — e as frases deste capítulo foram usadas durante séculos contra o povo judeu, sem que o texto o autorize."},
{v:15,t:"Ai de vós, escribas e fariseus hipócritas, porque percorreis o mar e a terra para fazer um prosélito e, quando o conseguis, fazeis dele um filho da geena duas vezes pior do que vós!",n:"Alguns manuscritos trazem antes deste um versículo 14, tirado de São Marcos e de São Lucas: devorais as casas das viúvas, pretextando longas orações. Falta nos mais antigos, e a Nova Vulgata omite-o; a numeração salta do 13 ao 15."},
{v:16,t:"Ai de vós, guias cegos, que dizeis: Se alguém jurar pelo santuário, isso nada é; mas, se jurar pelo ouro do santuário, fica obrigado!"},
{v:17,t:"Insensatos e cegos! Que é maior: o ouro, ou o santuário que santifica o ouro?"},
{v:18,t:"E: Se alguém jurar pelo altar, isso nada é; mas, se jurar pela oferta que está sobre ele, fica obrigado!"},
{v:19,t:"Cegos! Que é maior: a oferta, ou o altar que santifica a oferta?"},
{v:20,t:"Pois quem jura pelo altar jura por ele e por tudo o que está sobre ele;"},
{v:21,t:"e quem jura pelo santuário jura por ele e por aquele que nele habita;"},
{v:22,t:"e quem jura pelo céu jura pelo trono de Deus e por aquele que nele está sentado."},
{v:23,t:"Ai de vós, escribas e fariseus hipócritas, porque pagais o dízimo da hortelã, do endro e do cominho, e deixastes de lado o mais importante da Lei: a justiça, a misericórdia e a fidelidade! Estas coisas era preciso praticar, sem deixar de lado aquelas."},
{v:24,t:"Guias cegos, que filtrais o mosquito e engolis o camelo!",n:"Coava-se o vinho para não engolir um inseto, que era impuro. Em aramaico a frase tinha rima: qalma, o mosquito, e gamla, o camelo — o maior e o menor dos animais impuros."},
{v:25,t:"Ai de vós, escribas e fariseus hipócritas, porque limpais o exterior do copo e do prato, mas por dentro estão cheios de rapina e de intemperança!"},
{v:26,t:"Fariseu cego! Limpa primeiro o interior do copo, para que também o exterior fique limpo."},
{v:27,t:"Ai de vós, escribas e fariseus hipócritas, porque sois semelhantes a sepulcros caiados, que por fora parecem formosos, mas por dentro estão cheios de ossos de mortos e de toda imundície!",n:"Antes da Páscoa caiavam-se os sepulcros de branco, para que os peregrinos os vissem e não se tornassem impuros ao tocá-los. Era primavera, e Jerusalém estava rodeada deles, brancos ao sol."},
{v:28,t:"Assim também vós: por fora pareceis justos aos homens, mas por dentro estais cheios de hipocrisia e de iniquidade."},
{v:29,t:"Ai de vós, escribas e fariseus hipócritas, porque edificais os sepulcros dos profetas e adornais os monumentos dos justos,"},
{v:30,t:"e dizeis: Se tivéssemos vivido nos dias de nossos pais, não teríamos sido cúmplices deles no sangue dos profetas!"},
{v:31,t:"Assim, testemunhais contra vós mesmos que sois filhos dos que mataram os profetas."},
{v:32,t:"Completai, pois, vós a medida de vossos pais!"},
{v:33,t:"Serpentes, raça de víboras! Como escapareis da condenação da geena?"},
{v:34,t:"Por isso, eis que eu vos envio profetas, sábios e escribas: a uns matareis e crucificareis, a outros açoitareis nas vossas sinagogas e perseguireis de cidade em cidade,"},
{v:35,t:"para que caia sobre vós todo o sangue justo derramado sobre a terra, desde o sangue do justo Abel até ao sangue de Zacarias, filho de Baraquias, que matastes entre o santuário e o altar.",n:"O Zacarias assassinado no templo, no segundo livro das Crônicas, era filho de Joiada; filho de Baraquias era o profeta Zacarias, autor do livro. A confusão é antiga e não tem solução pacífica; São Lucas, no mesmo dito, não traz o nome do pai. Conserva-se o texto como está."},
{v:36,t:"Em verdade vos digo: tudo isso há de vir sobre esta geração."},
{v:37,t:"Jerusalém, Jerusalém, que matas os profetas e apedrejas os que te são enviados! Quantas vezes quis reunir os teus filhos, como a galinha reúne os seus pintinhos debaixo das asas, e não quiseste!",n:"Os ais acabam em lamento. O capítulo mais duro dos evangelhos não termina numa condenação, mas no desejo frustrado de abrigar."},
{v:38,t:"Eis que a vossa casa vos ficará deserta."},
{v:39,t:"Pois eu vos digo: de agora em diante não me vereis, até que digais: Bendito o que vem em nome do Senhor!"},
{p:"Marcos 12:38-40"},
{v:38,t:"E dizia no seu ensino: Guardai-vos dos escribas, que gostam de andar com longas vestes, de ser saudados nas praças,"},
{v:39,t:"e de ocupar os primeiros assentos nas sinagogas e os primeiros lugares nos banquetes;"},
{v:40,t:"que devoram as casas das viúvas e, para disfarçar, fazem longas orações. Estes receberão uma condenação mais severa.",n:"Os escribas não recebiam salário pelo ensino e viviam de ofertas; a acusação é a de explorar a devoção de mulheres sem defesa. O episódio seguinte, em São Marcos, mostra justamente uma viúva a dar tudo o que tinha ao templo."},
{p:"Lucas 20:45-47"},
{v:45,t:"Ouvindo-o todo o povo, disse aos seus discípulos:"},
{v:46,t:"Guardai-vos dos escribas, que gostam de andar com longas vestes, e amam as saudações nas praças, os primeiros assentos nas sinagogas e os primeiros lugares nos banquetes;"},
{v:47,t:"que devoram as casas das viúvas e, para disfarçar, fazem longas orações. Estes receberão uma condenação mais severa."}
];

EV[165] = [
{p:"Marcos 12:41-44"},
{v:41,t:"Sentado defronte do tesouro, Jesus observava como a multidão lançava dinheiro no tesouro; e muitos ricos lançavam muito.",n:"O tesouro eram treze caixas em forma de trombeta, no átrio das mulheres, cada uma destinada a uma espécie de oferta. As moedas faziam barulho ao cair, e as grandes ofertas ouviam-se."},
{v:42,t:"Chegando uma viúva pobre, lançou duas pequenas moedas, que valem um quadrante.",n:"As duas moedas são léptons, a menor moeda que circulava. O quadrante, com que São Marcos as explica aos romanos, valia a sexagésima quarta parte de um denário: menos de dez minutos de trabalho."},
{v:43,t:"E, chamando os seus discípulos, disse-lhes: Em verdade vos digo que esta viúva pobre lançou mais do que todos os que lançaram no tesouro."},
{v:44,t:"Porque todos lançaram do que lhes sobrava; ela, porém, da sua pobreza, lançou tudo o que tinha, todo o seu sustento.",n:"Todo o seu sustento traduz holon ton bion, à letra toda a sua vida. É a última cena de Jesus no templo, em São Marcos, antes da Paixão: uma mulher que dá a vida inteira."},
{p:"Lucas 21:1-4"},
{v:1,t:"Levantando os olhos, viu os ricos que lançavam as suas ofertas no tesouro."},
{v:2,t:"Viu também uma viúva pobre que lançava ali duas pequenas moedas,"},
{v:3,t:"e disse: Em verdade vos digo que esta viúva pobre lançou mais do que todos."},
{v:4,t:"Porque todos esses lançaram nas ofertas do que lhes sobrava; ela, porém, da sua indigência, lançou tudo o que tinha para viver."}
];

EV[166] = [
{p:"João 12:20-36"},
{v:20,t:"Havia alguns gregos entre os que tinham subido para adorar durante a festa.",n:"Gregos são aqui pagãos simpatizantes do judaísmo, que vinham adorar o Deus de Israel sem se tornarem judeus. É a chegada deles, e não a entrada triunfal, que faz Jesus dizer que chegou a hora."},
{v:21,t:"Estes aproximaram-se de Filipe, que era de Betsaida da Galileia, e fizeram-lhe este pedido: Senhor, queremos ver Jesus."},
{v:22,t:"Filipe foi dizê-lo a André; André e Filipe foram dizê-lo a Jesus.",n:"Filipe e André são os dois únicos apóstolos com nome grego. Os pagãos dirigem-se a quem lhes parece mais próximo."},
{v:23,t:"Jesus respondeu-lhes: Chegou a hora em que o Filho do Homem vai ser glorificado.",n:"Desde Caná, o quarto evangelho repete que a hora ainda não tinha chegado. Aqui chega — e o que se anuncia como glorificação é a morte, como o versículo seguinte explica."},
{v:24,t:"Em verdade, em verdade vos digo: se o grão de trigo, caindo na terra, não morrer, fica só; mas, se morrer, dá muito fruto."},
{v:25,t:"Quem ama a sua vida perde-a; e quem odeia a sua vida neste mundo há de guardá-la para a vida eterna."},
{v:26,t:"Se alguém me serve, siga-me; e, onde eu estiver, ali estará também o meu servo. Se alguém me servir, meu Pai o honrará."},
{v:27,t:"Agora a minha alma está perturbada. E que direi? Pai, salva-me desta hora? Mas foi para isto que cheguei a esta hora.",n:"São João não conta a agonia do horto; esta é a sua forma dela, dita à luz do dia e diante de todos. A pergunta que se faz em voz alta é a mesma oração do Getsêmani, e a resposta também."},
{v:28,t:"Pai, glorifica o teu nome. Veio então uma voz do céu: Já o glorifiquei, e tornarei a glorificá-lo."},
{v:29,t:"A multidão que ali estava e ouvira dizia que tinha sido um trovão. Outros diziam: Um anjo falou-lhe."},
{v:30,t:"Jesus respondeu: Não foi por mim que veio esta voz, mas por vós."},
{v:31,t:"Agora é o juízo deste mundo; agora o príncipe deste mundo vai ser lançado fora."},
{v:32,t:"E eu, quando for levantado da terra, atrairei todos a mim.",n:"Atrairei é o verbo helkyo do capítulo 6, o de puxar uma rede. E levantado tem os dois sentidos que o evangelista explica no versículo seguinte: erguido na cruz e exaltado."},
{v:33,t:"Dizia isso para indicar de que morte havia de morrer."},
{v:34,t:"A multidão respondeu-lhe: Nós ouvimos da Lei que o Cristo permanece para sempre; como dizes tu que é necessário que o Filho do Homem seja levantado? Quem é esse Filho do Homem?"},
{v:35,t:"Disse-lhes Jesus: Ainda por pouco tempo a luz está entre vós. Andai enquanto tendes a luz, para que as trevas não vos surpreendam; quem anda nas trevas não sabe para onde vai."},
{v:36,t:"Enquanto tendes a luz, crede na luz, para que vos torneis filhos da luz. Tendo dito isso, Jesus retirou-se e ocultou-se deles.",n:"É a última palavra de Jesus ao povo no quarto evangelho, e depois dela ele esconde-se. O resto será dito só aos discípulos, à mesa."}
];

EV[167] = [
{p:"João 12:37-50"},
{v:37,t:"Embora tivesse feito tantos sinais diante deles, não criam nele,",n:"O evangelista faz aqui o balanço do ministério público. Os sinais foram sete, contados de Caná a Lázaro, e o resultado é este versículo."},
{v:38,t:"para que se cumprisse a palavra do profeta Isaías, que disse: Senhor, quem creu na nossa pregação? E a quem foi revelado o braço do Senhor?",n:"É a primeira linha do canto do servo sofredor, Isaías 53. O mesmo capítulo que diz a incredulidade diz a Paixão que vem."},
{v:39,t:"Por isso não podiam crer, porque Isaías disse ainda:"},
{v:40,t:"Cegou-lhes os olhos e endureceu-lhes o coração, para que não vejam com os olhos, nem compreendam com o coração, e se convertam, e eu os cure.",n:"É o texto de Isaías 6, citado também no discurso das parábolas, no tópico 77. A Escritura não é aqui a causa da incredulidade, mas a sua explicação depois do fato: o evangelista procura nos profetas como pôde ser que não cressem."},
{v:41,t:"Isaías disse isso porque viu a sua glória e falou dele.",n:"No capítulo 6 de Isaías, o profeta vê a glória do Senhor no templo. São João diz que era a glória de Cristo que ele via — uma das afirmações mais altas do quarto evangelho, dita de passagem."},
{v:42,t:"Contudo, até muitos dos chefes creram nele; mas, por causa dos fariseus, não o confessavam, para não serem expulsos da sinagoga;"},
{v:43,t:"porque amaram mais a glória dos homens do que a glória de Deus.",n:"Glória traduz doxa nas duas vezes, e a palavra tem o duplo sentido que o português também conserva: o esplendor de Deus e a reputação entre os homens. Tinham de escolher entre uma e outra."},
{v:44,t:"Jesus, porém, clamou e disse: Quem crê em mim não crê em mim, mas naquele que me enviou;"},
{v:45,t:"e quem me vê, vê aquele que me enviou."},
{v:46,t:"Eu vim ao mundo como luz, para que todo aquele que crê em mim não permaneça nas trevas."},
{v:47,t:"E, se alguém ouve as minhas palavras e não as guarda, eu não o julgo; porque não vim para julgar o mundo, mas para salvar o mundo."},
{v:48,t:"Quem me rejeita e não recebe as minhas palavras tem quem o julgue: a palavra que eu disse, essa o julgará no último dia."},
{v:49,t:"Porque eu não falei por mim mesmo; mas o Pai, que me enviou, esse me prescreveu o que devo dizer e o que devo falar."},
{v:50,t:"E sei que o seu mandamento é vida eterna. Por isso, o que eu falo, falo-o como o Pai me disse."}
];

EV[168] = [
{p:"Mateus 24:1-51"},
{v:1,t:"Jesus saiu do templo e ia-se embora, quando se aproximaram dele os seus discípulos para lhe mostrarem as construções do templo.",n:"O templo reconstruído por Herodes era uma das maravilhas do mundo antigo, e ainda estava em obras. Algumas pedras do muro tinham mais de dez metros de comprimento."},
{v:2,t:"Mas ele lhes disse: Vedes tudo isto? Em verdade vos digo: não ficará aqui pedra sobre pedra que não seja derrubada."},
{v:3,t:"Estando ele sentado no monte das Oliveiras, aproximaram-se dele os discípulos em particular, dizendo: Dize-nos quando acontecerão essas coisas, e qual será o sinal da tua vinda e do fim do mundo.",n:"Os discípulos fazem duas perguntas numa só — quando cairá o templo e quando será o fim —, e o discurso responde às duas entrelaçadas. Separar o que se refere à destruição de Jerusalém, no ano 70, do que se refere ao fim dos tempos é a dificuldade de todo este capítulo, e os intérpretes nunca a resolveram por inteiro."},
{v:4,t:"Jesus respondeu-lhes: Cuidado para que ninguém vos engane."},
{v:5,t:"Porque muitos virão em meu nome, dizendo: Eu sou o Cristo; e enganarão a muitos."},
{v:6,t:"Ouvireis falar de guerras e de rumores de guerras; cuidado, não vos alarmeis; porque é necessário que isso aconteça, mas ainda não é o fim."},
{v:7,t:"Porque se levantará nação contra nação e reino contra reino; e haverá fomes e terremotos em vários lugares."},
{v:8,t:"Mas tudo isso é o princípio das dores.",n:"Dores traduz odines, as dores do parto. As desgraças não são o fim de nada: são o trabalho de um nascimento."},
{v:9,t:"Então vos entregarão à tribulação e vos matarão; e sereis odiados por todas as nações por causa do meu nome."},
{v:10,t:"Nesse tempo, muitos tropeçarão, hão de trair-se uns aos outros e odiar-se mutuamente."},
{v:11,t:"E surgirão muitos falsos profetas, e enganarão a muitos."},
{v:12,t:"E, por se multiplicar a iniquidade, esfriará a caridade de muitos."},
{v:13,t:"Mas quem perseverar até ao fim, esse será salvo."},
{v:14,t:"E este Evangelho do Reino será anunciado em todo o mundo, em testemunho a todas as nações; e então virá o fim."},
{v:15,t:"Quando, pois, virdes a abominação da desolação, de que falou o profeta Daniel, instalada no lugar santo — quem lê, entenda —,",n:"A abominação da desolação é a expressão de Daniel para o altar pagão que Antíoco Epífanes mandou erguer no templo em 167 antes de Cristo. E quem lê, entenda é aparte dirigido ao leitor do evangelho, e não aos ouvintes de Jesus: o evangelista interrompe o discurso para piscar o olho a quem tem o livro nas mãos."},
{v:16,t:"então os que estiverem na Judeia fujam para os montes;"},
{v:17,t:"quem estiver no terraço não desça para tirar o que houver em sua casa;"},
{v:18,t:"e quem estiver no campo não volte atrás para buscar o seu manto."},
{v:19,t:"Ai das que estiverem grávidas e das que amamentarem naqueles dias!"},
{v:20,t:"Orai para que a vossa fuga não aconteça no inverno nem em dia de sábado.",n:"No inverno, as torrentes enchem e os caminhos tornam-se impraticáveis. No sábado, a lei limitava a distância que se podia andar, e as portas da cidade fechavam-se. Só São Mateus, que escreve para cristãos vindos do judaísmo, acrescenta o sábado."},
{v:21,t:"Porque haverá então grande tribulação, como nunca houve desde o princípio do mundo até agora, nem jamais haverá."},
{v:22,t:"E, se aqueles dias não fossem abreviados, ninguém se salvaria; mas, por causa dos escolhidos, serão abreviados aqueles dias."},
{v:23,t:"Então, se alguém vos disser: Eis aqui o Cristo!, ou: Ei-lo ali!, não acrediteis."},
{v:24,t:"Porque surgirão falsos cristos e falsos profetas, e farão grandes sinais e prodígios, para enganar, se possível, até os escolhidos."},
{v:25,t:"Eis que vos predisse isso."},
{v:26,t:"Se, pois, vos disserem: Eis que ele está no deserto!, não saiais; Eis que ele está nos aposentos!, não acrediteis."},
{v:27,t:"Porque, como o relâmpago sai do oriente e se mostra até ao ocidente, assim será a vinda do Filho do Homem.",n:"A vinda do Filho do Homem não se anunciará por boatos nem se esconderá em lugar nenhum: será vista por todos ao mesmo tempo, como o relâmpago. Quem precisa de ser informado de onde ele está não está diante dele."},
{v:28,t:"Onde estiver o cadáver, ali se ajuntarão os abutres."},
{v:29,t:"Logo depois da tribulação daqueles dias, o sol escurecerá, a lua não dará a sua claridade, as estrelas cairão do céu e as potências dos céus serão abaladas.",n:"É a linguagem dos profetas — Isaías 13 e 34, Joel 2 — para dizer a queda de um império ou o juízo de Deus sobre a história. Não descreve a astronomia: diz que o que parecia fixo cai."},
{v:30,t:"Então aparecerá no céu o sinal do Filho do Homem; e então todas as tribos da terra se lamentarão e verão o Filho do Homem vindo sobre as nuvens do céu, com poder e grande glória."},
{v:31,t:"E ele enviará os seus anjos com trombeta de grande som, e eles reunirão os seus escolhidos dos quatro ventos, de uma extremidade dos céus à outra."},
{v:32,t:"Aprendei da figueira esta parábola: quando o seu ramo se torna tenro e brotam as folhas, sabeis que o verão está próximo."},
{v:33,t:"Assim também vós, quando virdes todas estas coisas, sabei que ele está próximo, às portas."},
{v:34,t:"Em verdade vos digo: não passará esta geração sem que todas estas coisas aconteçam.",n:"Dos versículos mais discutidos de todo o Novo Testamento. Se estas coisas são a ruína de Jerusalém, cumpriram-se quarenta anos depois, dentro daquela geração. Se incluem o fim do mundo, a frase é das mais difíceis dos evangelhos, e já os Padres propuseram leituras diversas de geração. O texto fica como está."},
{v:35,t:"O céu e a terra passarão, mas as minhas palavras não passarão."},
{v:36,t:"Quanto àquele dia e àquela hora, ninguém sabe, nem os anjos dos céus, nem o Filho, mas somente o Pai.",n:"Nem o Filho falta em alguns manuscritos de São Mateus, talvez suprimido por embaraço; em São Marcos está em todos. Os Padres discutiram-no longamente: uns entenderam que Cristo o ignorava enquanto homem, outros que não lhe cabia revelá-lo. O que o versículo exclui, em todo o caso, é que alguém faça cálculos."},
{v:37,t:"Como foram os dias de Noé, assim será a vinda do Filho do Homem."},
{v:38,t:"Pois, como nos dias anteriores ao dilúvio comiam e bebiam, casavam-se e davam-se em casamento, até ao dia em que Noé entrou na arca,"},
{v:39,t:"e não perceberam nada até que veio o dilúvio e os levou a todos, assim será também a vinda do Filho do Homem."},
{v:40,t:"Então estarão dois no campo: um será tomado, e o outro deixado."},
{v:41,t:"Duas mulheres estarão moendo no moinho: uma será tomada, e a outra deixada."},
{v:42,t:"Vigiai, pois, porque não sabeis em que dia virá o vosso Senhor."},
{v:43,t:"Mas sabei isto: se o dono da casa soubesse em que vigília viria o ladrão, vigiaria e não deixaria arrombar a sua casa."},
{v:44,t:"Por isso, estai também vós preparados, porque na hora em que não pensais virá o Filho do Homem."},
{v:45,t:"Quem é, pois, o servo fiel e prudente, a quem o senhor pôs à frente da sua criadagem, para lhes dar o alimento a seu tempo?"},
{v:46,t:"Feliz aquele servo que o seu senhor, ao chegar, encontrar procedendo assim!"},
{v:47,t:"Em verdade vos digo que o porá à frente de todos os seus bens."},
{v:48,t:"Mas, se aquele servo mau disser no seu coração: O meu senhor demora,"},
{v:49,t:"e começar a espancar os seus companheiros, e a comer e beber com os bêbados,"},
{v:50,t:"virá o senhor daquele servo no dia em que não o espera e na hora que não sabe,"},
{v:51,t:"e o separará, e lhe dará a sorte dos hipócritas: ali haverá pranto e ranger de dentes."},
{p:"Marcos 13:1-37"},
{v:1,t:"Ao sair ele do templo, disse-lhe um dos seus discípulos: Mestre, vê que pedras e que construções!"},
{v:2,t:"Jesus disse-lhe: Vês estas grandes construções? Não ficará pedra sobre pedra que não seja derrubada."},
{v:3,t:"Estando ele sentado no monte das Oliveiras, defronte do templo, Pedro, Tiago, João e André perguntaram-lhe em particular:"},
{v:4,t:"Dize-nos quando acontecerão essas coisas, e qual será o sinal de que todas elas estão para se cumprir."},
{v:5,t:"Jesus começou a dizer-lhes: Cuidado para que ninguém vos engane."},
{v:6,t:"Muitos virão em meu nome, dizendo: Sou eu; e enganarão a muitos."},
{v:7,t:"Quando ouvirdes falar de guerras e de rumores de guerras, não vos alarmeis; é necessário que isso aconteça, mas ainda não é o fim."},
{v:8,t:"Porque se levantará nação contra nação e reino contra reino; haverá terremotos em vários lugares, e haverá fomes. Isto é o princípio das dores."},
{v:9,t:"Cuidai, porém, de vós mesmos. Hão de entregar-vos aos tribunais e sereis açoitados nas sinagogas; e comparecereis diante de governadores e reis por minha causa, para lhes dar testemunho."},
{v:10,t:"E é necessário que primeiro o Evangelho seja anunciado a todas as nações."},
{v:11,t:"Quando vos levarem para vos entregar, não vos preocupeis antecipadamente com o que haveis de dizer; mas dizei o que vos for dado naquela hora, porque não sois vós que falais, mas o Espírito Santo."},
{v:12,t:"O irmão entregará à morte o irmão, e o pai, o filho; os filhos se levantarão contra os pais e os farão morrer."},
{v:13,t:"E sereis odiados por todos por causa do meu nome; mas quem perseverar até ao fim, esse será salvo."},
{v:14,t:"Quando virdes a abominação da desolação instalada onde não deve estar — quem lê, entenda —, então os que estiverem na Judeia fujam para os montes;",n:"No grego, instalada está no masculino, embora abominação seja feminino: o evangelista pensa numa pessoa, e não num objeto. Onde não deve estar diz o mesmo que o lugar santo de São Mateus, com mais cautela."},
{v:15,t:"quem estiver no terraço não desça nem entre para tirar alguma coisa de sua casa;"},
{v:16,t:"e quem estiver no campo não volte atrás para buscar o seu manto."},
{v:17,t:"Ai das que estiverem grávidas e das que amamentarem naqueles dias!"},
{v:18,t:"Orai para que isso não aconteça no inverno."},
{v:19,t:"Porque aqueles dias serão de tal tribulação, como não houve desde o princípio da criação que Deus criou até agora, nem jamais haverá."},
{v:20,t:"E, se o Senhor não abreviasse aqueles dias, ninguém se salvaria; mas, por causa dos escolhidos que ele escolheu, abreviou aqueles dias."},
{v:21,t:"Então, se alguém vos disser: Eis aqui o Cristo!, ou: Ei-lo ali!, não acrediteis."},
{v:22,t:"Porque surgirão falsos cristos e falsos profetas, e farão sinais e prodígios para enganar, se possível, os escolhidos."},
{v:23,t:"Vós, porém, tende cuidado: eis que vos predisse tudo."},
{v:24,t:"Mas, naqueles dias, depois daquela tribulação, o sol escurecerá e a lua não dará a sua claridade;"},
{v:25,t:"as estrelas cairão do céu, e as potências que estão nos céus serão abaladas."},
{v:26,t:"E então verão o Filho do Homem vindo nas nuvens, com grande poder e glória.",n:"É a figura de Daniel 7: alguém como um filho de homem vem sobre as nuvens e recebe de Deus o domínio eterno. Diante do sinédrio, dias depois, Jesus há de citar o mesmo texto, e será condenado por ele."},
{v:27,t:"E então enviará os anjos e reunirá os seus escolhidos dos quatro ventos, da extremidade da terra à extremidade do céu."},
{v:28,t:"Aprendei da figueira esta parábola: quando o seu ramo se torna tenro e brotam as folhas, sabeis que o verão está próximo."},
{v:29,t:"Assim também vós, quando virdes acontecer estas coisas, sabei que ele está próximo, às portas."},
{v:30,t:"Em verdade vos digo: não passará esta geração sem que todas estas coisas aconteçam."},
{v:31,t:"O céu e a terra passarão, mas as minhas palavras não passarão."},
{v:32,t:"Quanto àquele dia ou àquela hora, ninguém sabe, nem os anjos no céu, nem o Filho, mas somente o Pai."},
{v:33,t:"Tende cuidado, vigiai, porque não sabeis quando será o tempo."},
{v:34,t:"É como um homem que partiu de viagem: deixou a sua casa, deu autoridade aos seus servos, a cada um o seu trabalho, e ordenou ao porteiro que vigiasse."},
{v:35,t:"Vigiai, pois, porque não sabeis quando virá o dono da casa: se à tarde, se à meia-noite, se ao cantar do galo, se de manhã;",n:"As quatro vigílias da noite romana são, em São Marcos, as quatro horas da noite da Paixão: à tarde, a ceia; à meia-noite, o Getsêmani, onde os discípulos dormem; ao cantar do galo, a negação de Pedro; de manhã, a entrega a Pilatos. O discurso sobre o fim prepara, sem o dizer, o relato que vem a seguir."},
{v:36,t:"para que, vindo de repente, não vos encontre dormindo."},
{v:37,t:"O que vos digo a vós, digo a todos: Vigiai!"},
{p:"Lucas 21:5-38"},
{v:5,t:"Como alguns falassem do templo, que estava ornado de belas pedras e de ofertas votivas, disse:"},
{v:6,t:"Destas coisas que vedes, virão dias em que não ficará pedra sobre pedra que não seja derrubada."},
{v:7,t:"Perguntaram-lhe: Mestre, quando acontecerá isso? E qual será o sinal de que essas coisas estão para acontecer?"},
{v:8,t:"Ele respondeu: Cuidado para não serdes enganados. Porque muitos virão em meu nome, dizendo: Sou eu!, e: O tempo está próximo! Não andeis atrás deles."},
{v:9,t:"Quando ouvirdes falar de guerras e de revoluções, não vos assusteis; porque é necessário que isso aconteça primeiro, mas não será logo o fim."},
{v:10,t:"Disse-lhes então: Há de levantar-se nação contra nação e reino contra reino;"},
{v:11,t:"haverá grandes terremotos e, em vários lugares, fomes e pestes; haverá também fenômenos terríveis e grandes sinais no céu."},
{v:12,t:"Mas, antes de tudo isso, hão de deitar-vos as mãos e perseguir-vos, entregando-vos às sinagogas e às prisões, levando-vos diante de reis e governadores por causa do meu nome."},
{v:13,t:"Isso vos acontecerá para dardes testemunho."},
{v:14,t:"Assentai, pois, nos vossos corações não preparar de antemão a vossa defesa;"},
{v:15,t:"porque eu vos darei palavras e sabedoria a que nenhum dos vossos adversários poderá resistir nem contradizer."},
{v:16,t:"Sereis entregues até por vossos pais, irmãos, parentes e amigos; e farão morrer alguns de vós."},
{v:17,t:"E sereis odiados por todos por causa do meu nome."},
{v:18,t:"Mas não se perderá um só cabelo da vossa cabeça.",n:"Dito logo depois de farão morrer alguns de vós, o versículo não promete que ninguém morrerá. Promete que nada se perde — nem na morte."},
{v:19,t:"É pela vossa perseverança que salvareis as vossas almas."},
{v:20,t:"Quando virdes Jerusalém cercada de exércitos, sabei que está próxima a sua desolação.",n:"Onde Mateus e Marcos falam, em linguagem de Daniel, da abominação da desolação, São Lucas diz a coisa sem figura: exércitos à volta de Jerusalém. Eusébio conta que os cristãos da cidade, lembrando este aviso, fugiram para Pela, do outro lado do Jordão, antes do cerco."},
{v:21,t:"Então os que estiverem na Judeia fujam para os montes; os que estiverem dentro da cidade retirem-se; e os que estiverem nos campos não entrem nela."},
{v:22,t:"Porque esses são dias de vingança, para que se cumpra tudo o que está escrito."},
{v:23,t:"Ai das que estiverem grávidas e das que amamentarem naqueles dias! Porque haverá grande angústia sobre a terra e ira contra este povo."},
{v:24,t:"Cairão ao fio da espada e serão levados cativos para todas as nações; e Jerusalém será pisada pelos gentios, até que se cumpram os tempos dos gentios."},
{v:25,t:"E haverá sinais no sol, na lua e nas estrelas; e sobre a terra, angústia das nações, aturdidas pelo bramido do mar e das ondas;"},
{v:26,t:"os homens desfalecerão de medo e da expectativa do que há de vir sobre o mundo; porque as potências dos céus serão abaladas."},
{v:27,t:"E então verão o Filho do Homem vindo numa nuvem, com poder e grande glória."},
{v:28,t:"Quando essas coisas começarem a acontecer, erguei-vos e levantai a cabeça, porque a vossa redenção está próxima.",n:"Enquanto os outros desfalecem de medo, os discípulos são mandados levantar a cabeça. O mesmo acontecimento é pavor para uns e libertação para outros."},
{v:29,t:"E disse-lhes uma parábola: Olhai a figueira e todas as árvores."},
{v:30,t:"Quando já começam a brotar, vendo-o, sabeis por vós mesmos que o verão já está próximo."},
{v:31,t:"Assim também vós, quando virdes acontecer estas coisas, sabei que o Reino de Deus está próximo."},
{v:32,t:"Em verdade vos digo: não passará esta geração sem que tudo isso aconteça."},
{v:33,t:"O céu e a terra passarão, mas as minhas palavras não passarão."},
{v:34,t:"Tende cuidado convosco, para que os vossos corações não se tornem pesados pela devassidão, pela embriaguez e pelas preocupações da vida, e aquele dia não vos surpreenda de repente,"},
{v:35,t:"como um laço; porque há de vir sobre todos os que habitam a face de toda a terra."},
{v:36,t:"Vigiai, pois, orando em todo o tempo, para que tenhais força de escapar de todas essas coisas que hão de acontecer e de estar de pé diante do Filho do Homem."},
{v:37,t:"Durante o dia ensinava no templo; e à noite saía e pernoitava no monte chamado das Oliveiras."},
{v:38,t:"E todo o povo madrugava para ir ter com ele no templo e ouvi-lo."}
];

EV[169] = [
{p:"Mateus 25:1-13"},
{v:1,t:"Então o Reino dos céus será semelhante a dez virgens que, tomando as suas lâmpadas, saíram ao encontro do esposo.",n:"Nas bodas da Palestina, o noivo ia buscar a noiva à casa dos pais dela e levava-a em cortejo, de noite, para a sua. As amigas da noiva esperavam no caminho, com tochas, para entrar com o cortejo."},
{v:2,t:"Cinco delas eram insensatas, e cinco prudentes."},
{v:3,t:"As insensatas, tomando as lâmpadas, não levaram azeite consigo;"},
{v:4,t:"as prudentes, porém, levaram azeite nas vasilhas, juntamente com as lâmpadas."},
{v:5,t:"Como o esposo demorasse, adormeceram todas e dormiram.",n:"Todas adormecem, prudentes e insensatas. O que distingue umas das outras não é ter vigiado sem dormir, mas ter levado azeite."},
{v:6,t:"À meia-noite, ouviu-se um grito: Eis o esposo! Saí ao seu encontro!"},
{v:7,t:"Então todas aquelas virgens se levantaram e prepararam as suas lâmpadas."},
{v:8,t:"E as insensatas disseram às prudentes: Dai-nos do vosso azeite, porque as nossas lâmpadas estão se apagando."},
{v:9,t:"Mas as prudentes responderam: Não, para que não falte a nós e a vós; ide antes aos vendedores e comprai para vós.",n:"A recusa parece pouco caridosa, e é essa a lição: há coisas que não se emprestam na última hora. Os Padres leram o azeite como as obras, ou o amor, que cada um tem de ter por si."},
{v:10,t:"Enquanto iam comprar, chegou o esposo; e as que estavam preparadas entraram com ele para as bodas, e fechou-se a porta."},
{v:11,t:"Depois chegaram também as outras virgens, dizendo: Senhor, senhor, abre-nos!"},
{v:12,t:"Mas ele respondeu: Em verdade vos digo: não vos conheço."},
{v:13,t:"Vigiai, pois, porque não sabeis nem o dia nem a hora."}
];

EV[170] = [
{p:"Mateus 25:14-30"},
{v:14,t:"Pois será como um homem que, partindo de viagem, chamou os seus servos e lhes entregou os seus bens."},
{v:15,t:"A um deu cinco talentos, a outro dois e a outro um, a cada um segundo a sua capacidade; e partiu.",n:"O talento valia seis mil denários, o salário de uns vinte anos de trabalho: mesmo um só era uma fortuna. É desta parábola que vem o sentido de talento como dom ou aptidão, nas línguas da Europa."},
{v:16,t:"Logo, o que recebera cinco talentos foi negociar com eles e ganhou outros cinco."},
{v:17,t:"Do mesmo modo, o que recebera dois ganhou outros dois."},
{v:18,t:"Mas o que recebera um foi, cavou na terra e escondeu o dinheiro do seu senhor.",n:"Enterrar o dinheiro era o modo mais seguro de o guardar, e a lei rabínica isentava de responsabilidade quem enterrasse um depósito. O terceiro servo fez o que era prudente e legal. A parábola condena-o por isso mesmo."},
{v:19,t:"Depois de muito tempo, veio o senhor daqueles servos e ajustou contas com eles."},
{v:20,t:"Aproximando-se o que recebera cinco talentos, apresentou outros cinco talentos, dizendo: Senhor, entregaste-me cinco talentos; eis que ganhei outros cinco."},
{v:21,t:"Disse-lhe o seu senhor: Muito bem, servo bom e fiel! Foste fiel no pouco, sobre o muito te porei; entra na alegria do teu senhor."},
{v:22,t:"Aproximando-se também o que recebera dois talentos, disse: Senhor, entregaste-me dois talentos; eis que ganhei outros dois."},
{v:23,t:"Disse-lhe o seu senhor: Muito bem, servo bom e fiel! Foste fiel no pouco, sobre o muito te porei; entra na alegria do teu senhor.",n:"O que ganhou dois recebe exatamente as mesmas palavras que o que ganhou cinco. Não se mede o resultado, mas a fidelidade ao que se recebeu."},
{v:24,t:"Aproximando-se, por fim, o que recebera um talento, disse: Senhor, sei que és homem duro, que colhes onde não semeaste e ajuntas onde não espalhaste;"},
{v:25,t:"e, com medo, fui esconder o teu talento na terra. Eis aqui tens o que é teu."},
{v:26,t:"Respondeu-lhe o seu senhor: Servo mau e preguiçoso! Sabias que colho onde não semeei e ajunto onde não espalhei?"},
{v:27,t:"Devias, então, ter entregado o meu dinheiro aos banqueiros, e, ao voltar, eu receberia o que é meu com juros."},
{v:28,t:"Tirai-lhe, pois, o talento e dai-o ao que tem dez talentos."},
{v:29,t:"Porque a todo aquele que tem será dado, e terá em abundância; mas ao que não tem, até o que tem lhe será tirado."},
{v:30,t:"E o servo inútil, lançai-o nas trevas exteriores; ali haverá pranto e ranger de dentes."}
];

EV[171] = [
{p:"Mateus 25:31-46"},
{v:31,t:"Quando o Filho do Homem vier na sua glória, e todos os anjos com ele, então se sentará no trono da sua glória."},
{v:32,t:"E serão reunidas diante dele todas as nações; e ele separará uns dos outros, como o pastor separa as ovelhas dos cabritos.",n:"Ovelhas e cabras pastavam juntas durante o dia e eram separadas à noite, porque as cabras precisam de abrigo do frio. Era uma cena de todos os dias."},
{v:33,t:"E porá as ovelhas à sua direita, e os cabritos à esquerda."},
{v:34,t:"Então dirá o Rei aos que estiverem à sua direita: Vinde, benditos de meu Pai, recebei em herança o Reino que vos está preparado desde a fundação do mundo.",n:"O Reino foi preparado para eles; o fogo do versículo 41, para o diabo e os seus anjos. Nenhum lugar foi preparado para os homens senão o primeiro."},
{v:35,t:"Porque tive fome, e me destes de comer; tive sede, e me destes de beber; era estrangeiro, e me acolhestes;"},
{v:36,t:"estava nu, e me vestistes; estava doente, e me visitastes; estava na prisão, e fostes ver-me.",n:"São as seis obras de misericórdia corporais. A tradição acrescentou-lhes uma sétima, enterrar os mortos, tirada do livro de Tobias."},
{v:37,t:"Então os justos lhe responderão: Senhor, quando foi que te vimos com fome e te demos de comer? Ou com sede e te demos de beber?",n:"Os justos ficam tão surpreendidos como os outros. Nenhum dos dois grupos sabia, e é isso que torna a cena tão séria: o que decide não é o que se fez por Cristo sabendo que era Cristo."},
{v:38,t:"Quando foi que te vimos estrangeiro e te acolhemos? Ou nu e te vestimos?"},
{v:39,t:"Quando foi que te vimos doente ou na prisão e fomos ver-te?"},
{v:40,t:"E o Rei lhes responderá: Em verdade vos digo: todas as vezes que o fizestes a um só destes meus irmãos menores, a mim o fizestes.",n:"Quem são os irmãos menores é debatido. Pode ser todo necessitado, como leu a maior parte da tradição; ou, mais estritamente, os discípulos pobres e perseguidos, como no capítulo 10, onde quem dá um copo de água a um destes pequeninos não perde a recompensa. Uma leitura não exclui a outra."},
{v:41,t:"Depois dirá também aos que estiverem à esquerda: Afastai-vos de mim, malditos, para o fogo eterno, preparado para o diabo e os seus anjos."},
{v:42,t:"Porque tive fome, e não me destes de comer; tive sede, e não me destes de beber;"},
{v:43,t:"era estrangeiro, e não me acolhestes; estava nu, e não me vestistes; doente e na prisão, e não me visitastes."},
{v:44,t:"Então também eles lhe responderão: Senhor, quando foi que te vimos com fome, ou com sede, ou estrangeiro, ou nu, ou doente, ou na prisão, e não te servimos?"},
{v:45,t:"Então lhes responderá: Em verdade vos digo: todas as vezes que não o fizestes a um só destes menores, a mim não o fizestes.",n:"Os da esquerda não são acusados de nenhum mal cometido: só do bem que não fizeram. É o último discurso de Jesus em São Mateus antes da Paixão."},
{v:46,t:"E irão estes para o castigo eterno, e os justos para a vida eterna."}
];

EV[172] = [
{p:"Mateus 26:17-19"},
{v:17,t:"No primeiro dia dos Ázimos, os discípulos aproximaram-se de Jesus e disseram: Onde queres que te preparemos a ceia da Páscoa?",n:"Os três primeiros evangelhos fazem da última ceia a refeição pascal; São João põe a morte de Jesus na véspera da Páscoa, à hora em que se imolavam os cordeiros no templo. A divergência é das mais estudadas dos evangelhos e não tem solução pacífica; os dois relatos dizem, cada um à sua maneira, que Jesus é a Páscoa."},
{v:18,t:"Ele respondeu: Ide à cidade, à casa de fulano, e dizei-lhe: O Mestre diz: O meu tempo está próximo; em tua casa celebrarei a Páscoa com os meus discípulos."},
{v:19,t:"Os discípulos fizeram como Jesus lhes ordenara e prepararam a Páscoa."},
{p:"Marcos 14:12-16"},
{v:12,t:"No primeiro dia dos Ázimos, quando se imolava a Páscoa, disseram-lhe os discípulos: Onde queres que vamos preparar-te a ceia da Páscoa?"},
{v:13,t:"Enviou dois dos seus discípulos e disse-lhes: Ide à cidade, e virá ao vosso encontro um homem levando um cântaro de água; segui-o.",n:"Carregar água era trabalho de mulheres. Um homem com um cântaro seria notado na rua: é um sinal combinado, e a discrição de toda a cena sugere que Jesus queria que ninguém soubesse de antemão onde ia estar — nem Judas."},
{v:14,t:"E, onde ele entrar, dizei ao dono da casa: O Mestre pergunta: Onde é a minha sala, em que hei de comer a Páscoa com os meus discípulos?"},
{v:15,t:"E ele vos mostrará uma grande sala no andar de cima, mobiliada e pronta; preparai ali para nós."},
{v:16,t:"Os discípulos partiram, foram à cidade, encontraram tudo como ele lhes dissera e prepararam a Páscoa."},
{p:"Lucas 22:7-13"},
{v:7,t:"Chegou o dia dos Ázimos, em que se devia imolar a Páscoa."},
{v:8,t:"Jesus enviou Pedro e João, dizendo: Ide preparar-nos a Páscoa, para que a comamos."},
{v:9,t:"Perguntaram-lhe: Onde queres que a preparemos?"},
{v:10,t:"Ele lhes disse: Eis que, ao entrardes na cidade, virá ao vosso encontro um homem levando um cântaro de água; segui-o até à casa em que ele entrar,"},
{v:11,t:"e dizei ao dono da casa: O Mestre te pergunta: Onde é a sala em que hei de comer a Páscoa com os meus discípulos?"},
{v:12,t:"E ele vos mostrará uma grande sala no andar de cima, mobiliada; preparai ali."},
{v:13,t:"Foram e encontraram tudo como ele lhes dissera, e prepararam a Páscoa."}
];

EV[173] = [
{p:"Mateus 26:20"},
{v:20,t:"Chegada a tarde, pôs-se à mesa com os Doze."},
{p:"Marcos 14:17-18a"},
{v:17,t:"Chegada a tarde, veio ele com os Doze."},
{v:18,t:"E, estando eles à mesa e comendo,"},
{p:"Lucas 22:14-16"},
{v:14,t:"Chegada a hora, pôs-se à mesa, e os apóstolos com ele."},
{v:15,t:"E disse-lhes: Desejei ardentemente comer convosco esta Páscoa, antes de padecer.",n:"O grego conserva o hebraísmo com desejo desejei, que diz o desejo levado ao extremo. É a única vez que os evangelhos põem na boca de Jesus o que ele desejava."},
{v:16,t:"Pois vos digo que não a comerei mais, até que ela se cumpra no Reino de Deus."}
];

EV[174] = [
{p:"Lucas 22:24-30"},
{v:24,t:"Surgiu também entre eles uma discussão sobre qual deles parecia ser o maior.",n:"São Lucas põe a disputa sobre o primeiro lugar à mesa da própria ceia, logo depois da instituição da Eucaristia. Não esconde nada dos apóstolos, nem nessa noite."},
{v:25,t:"Jesus disse-lhes: Os reis das nações dominam sobre elas, e os que exercem autoridade sobre elas são chamados benfeitores.",n:"Benfeitor, em grego Euergetes, era título oficial de reis helenísticos, como Ptolomeu III do Egito. A ironia é fina: os que dominam fazem-se chamar os que fazem o bem."},
{v:26,t:"Mas entre vós não seja assim; pelo contrário, o maior entre vós seja como o mais novo, e o que governa, como o que serve."},
{v:27,t:"Pois qual é o maior: o que está à mesa ou o que serve? Não é o que está à mesa? Eu, porém, estou no meio de vós como aquele que serve."},
{v:28,t:"Vós sois os que permanecestes comigo nas minhas provações;"},
{v:29,t:"e eu disponho para vós um Reino, como meu Pai o dispôs para mim,"},
{v:30,t:"para que comais e bebais à minha mesa no meu Reino, e vos senteis em tronos para julgar as doze tribos de Israel."},
{p:"João 13:1-20"},
{v:1,t:"Antes da festa da Páscoa, sabendo Jesus que chegara a sua hora de passar deste mundo para o Pai, tendo amado os seus que estavam no mundo, amou-os até ao fim.",n:"Até ao fim traduz eis telos, que quer dizer ao mesmo tempo até ao último momento e até ao extremo. A palavra volta na cruz: tetelestai, tudo está consumado. O versículo abre a segunda metade do quarto evangelho e dá a chave de tudo o que se segue."},
{v:2,t:"Durante a ceia, tendo já o diabo posto no coração de Judas, filho de Simão Iscariotes, o propósito de o entregar,"},
{v:3,t:"sabendo Jesus que o Pai lhe tinha posto tudo nas mãos, e que saíra de Deus e para Deus voltava,"},
{v:4,t:"levantou-se da ceia, tirou o manto e, tomando uma toalha, cingiu-se com ela.",n:"Lavar os pés era serviço de escravo, e dos mais baixos: a lei rabínica dispensava dele até o escravo judeu. O evangelista diz primeiro que tudo lhe fora posto nas mãos — e o que as mãos fazem, então, é isto."},
{v:5,t:"Depois deitou água numa bacia e começou a lavar os pés dos discípulos e a enxugá-los com a toalha com que estava cingido."},
{v:6,t:"Chegou, pois, a Simão Pedro. Este lhe disse: Senhor, tu vais lavar-me os pés?"},
{v:7,t:"Jesus respondeu-lhe: O que eu faço, tu não o sabes agora, mas hás de compreendê-lo depois."},
{v:8,t:"Disse-lhe Pedro: Nunca me lavarás os pés! Jesus respondeu-lhe: Se eu não te lavar, não terás parte comigo."},
{v:9,t:"Disse-lhe Simão Pedro: Senhor, então não só os pés, mas também as mãos e a cabeça!"},
{v:10,t:"Jesus disse-lhe: Quem tomou banho não precisa lavar senão os pés, porque está todo limpo. E vós estais limpos, mas não todos.",n:"Quem ia a um banquete tomava banho em casa e, ao chegar, só tinha de lavar os pés sujos do caminho. A imagem distingue o que já está feito do que se tem de refazer todos os dias."},
{v:11,t:"Pois sabia quem o havia de entregar; por isso disse: Não estais todos limpos."},
{v:12,t:"Depois de lhes ter lavado os pés, retomou o manto, pôs-se de novo à mesa e disse-lhes: Compreendeis o que vos fiz?"},
{v:13,t:"Vós me chamais Mestre e Senhor, e dizeis bem, porque o sou."},
{v:14,t:"Se, pois, eu, o Senhor e Mestre, vos lavei os pés, também vós deveis lavar os pés uns dos outros."},
{v:15,t:"Porque vos dei o exemplo, para que, como eu vos fiz, façais também vós."},
{v:16,t:"Em verdade, em verdade vos digo: o servo não é maior do que o seu senhor, nem o enviado maior do que aquele que o enviou."},
{v:17,t:"Se sabeis estas coisas, felizes sereis se as praticardes."},
{v:18,t:"Não falo de todos vós; eu conheço os que escolhi. Mas é para que se cumpra a Escritura: O que come o meu pão levantou contra mim o calcanhar.",n:"É o versículo 10 do Salmo 41. Levantar o calcanhar é o coice do cavalo, ou o gesto de desprezo de quem dá as costas. Os pés que acabam de ser lavados incluem os de Judas."},
{v:19,t:"Desde já vos digo isto, antes que aconteça, para que, quando acontecer, creiais que eu sou."},
{v:20,t:"Em verdade, em verdade vos digo: quem recebe aquele que eu enviar, a mim me recebe; e quem me recebe, recebe aquele que me enviou."}
];

EV[175] = [
{p:"Mateus 26:26-29"},
{v:26,t:"Enquanto comiam, Jesus tomou o pão, abençoou-o, partiu-o e deu-o aos discípulos, dizendo: Tomai e comei; isto é o meu corpo.",n:"Abençoar o pão era a bênção judaica de toda refeição: bendito sejas, Senhor nosso Deus, que fazes sair o pão da terra. O que é novo são as palavras que Jesus acrescenta, e é sobre elas que se funda a fé da Igreja na presença real."},
{v:27,t:"E, tomando o cálice, deu graças e deu-o a eles, dizendo: Bebei dele todos,"},
{v:28,t:"porque isto é o meu sangue, o sangue da aliança, que é derramado por muitos para remissão dos pecados.",n:"O sangue da aliança é a expressão de Moisés no Sinai, no Êxodo 24, ao aspergir o povo com o sangue dos sacrifícios. Por muitos é a fórmula do servo de Isaías 53. E para remissão dos pecados só São Mateus o acrescenta."},
{v:29,t:"Eu vos digo: desde agora não beberei mais deste fruto da videira, até ao dia em que o beber de novo convosco no Reino de meu Pai."},
{p:"Marcos 14:22-25"},
{v:22,t:"Enquanto comiam, tomou o pão, abençoou-o, partiu-o e deu-o a eles, dizendo: Tomai; isto é o meu corpo."},
{v:23,t:"E, tomando o cálice, deu graças e deu-o a eles; e todos beberam dele."},
{v:24,t:"E disse-lhes: Isto é o meu sangue, o sangue da aliança, que é derramado por muitos."},
{v:25,t:"Em verdade vos digo que não beberei mais do fruto da videira, até àquele dia em que o beber novo no Reino de Deus."},
{p:"Lucas 22:17-20"},
{v:17,t:"E, tomando um cálice, deu graças e disse: Tomai-o e reparti-o entre vós;",n:"São Lucas fala de dois cálices, um antes e outro depois do pão. A ceia pascal tinha quatro cálices de vinho, e o relato conserva a memória dessa ordem."},
{v:18,t:"pois vos digo que, de agora em diante, não beberei mais do fruto da videira, até que venha o Reino de Deus."},
{v:19,t:"E, tomando o pão, deu graças, partiu-o e deu-o a eles, dizendo: Isto é o meu corpo, que é dado por vós; fazei isto em memória de mim.",n:"Fazei isto em memória de mim só está em São Lucas e em São Paulo, na primeira carta aos Coríntios, já traduzida aqui: são as duas formas mais antigas do relato. Memória traduz anamnesis, que na liturgia judaica não é só recordar, mas tornar presente o que se recorda."},
{v:20,t:"Do mesmo modo, depois da ceia, tomou o cálice, dizendo: Este cálice é a nova aliança no meu sangue, que é derramado por vós.",n:"A nova aliança é a promessa de Jeremias 31, a única vez que o Antigo Testamento usa a expressão. Parte dos manuscritos ocidentais omite a segunda metade do versículo 19 e o versículo 20; a Nova Vulgata segue os que os trazem, que são a grande maioria."}
];

EV[176] = [
{p:"Mateus 26:21-25"},
{v:21,t:"E, enquanto comiam, disse: Em verdade vos digo que um de vós me há de entregar."},
{v:22,t:"Eles, muito entristecidos, começaram a perguntar-lhe, cada um: Acaso sou eu, Senhor?"},
{v:23,t:"Ele respondeu: O que mete comigo a mão no prato, esse me há de entregar.",n:"Todos metiam a mão no mesmo prato, e a resposta não aponta ninguém: diz a gravidade da coisa. Trair aquele com quem se partilha o pão era, no Oriente, a pior das traições."},
{v:24,t:"O Filho do Homem vai, como está escrito a seu respeito; mas ai daquele homem por quem o Filho do Homem é entregue! Melhor seria para esse homem não ter nascido."},
{v:25,t:"Judas, que o havia de entregar, perguntou: Acaso sou eu, Rabi? Ele lhe respondeu: Tu o disseste.",n:"Os outros dizem Senhor; Judas diz Rabi. E tu o disseste é a mesma resposta que Jesus dará ao sumo sacerdote: uma afirmação que deixa com quem perguntou a responsabilidade do que foi dito."},
{p:"Marcos 14:18b-21"},
{v:18,t:"Jesus disse: Em verdade vos digo que um de vós, que come comigo, me há de entregar."},
{v:19,t:"Eles começaram a entristecer-se e a dizer-lhe, um após outro: Acaso sou eu?"},
{v:20,t:"Ele lhes disse: É um dos Doze, o que mete comigo a mão no prato."},
{v:21,t:"O Filho do Homem vai, como está escrito a seu respeito; mas ai daquele homem por quem o Filho do Homem é entregue! Melhor seria para esse homem não ter nascido."},
{p:"Lucas 22:21-23"},
{v:21,t:"Mas eis que a mão daquele que me entrega está comigo à mesa."},
{v:22,t:"Porque o Filho do Homem vai segundo o que está determinado; mas ai daquele homem por quem ele é entregue!"},
{v:23,t:"Começaram, então, a perguntar entre si qual deles seria o que ia fazer isso."},
{p:"João 13:21-30"},
{v:21,t:"Tendo dito isso, Jesus perturbou-se no espírito e declarou: Em verdade, em verdade vos digo que um de vós me há de entregar."},
{v:22,t:"Os discípulos olhavam uns para os outros, sem saber de quem falava."},
{v:23,t:"Um dos seus discípulos, aquele que Jesus amava, estava reclinado ao lado de Jesus.",n:"É a primeira aparição do discípulo que Jesus amava, que o quarto evangelho nunca nomeia e que a tradição identificou com São João. À mesa, cada um se reclinava sobre o cotovelo esquerdo; o que ficava à direita de Jesus tinha a cabeça junto ao peito dele."},
{v:24,t:"Simão Pedro fez-lhe sinal e disse-lhe: Pergunta-lhe de quem está falando."},
{v:25,t:"Ele, inclinando-se sobre o peito de Jesus, disse-lhe: Senhor, quem é?"},
{v:26,t:"Jesus respondeu: É aquele a quem eu der o bocado que vou molhar. E, tendo molhado o bocado, tomou-o e deu-o a Judas, filho de Simão Iscariotes.",n:"Oferecer ao convidado um bocado molhado no prato era gesto de honra e de amizade. É o último gesto de Jesus para com Judas, e é um gesto de amigo."},
{v:27,t:"E, depois do bocado, entrou nele Satanás. Disse-lhe, pois, Jesus: O que fazes, faze-o depressa."},
{v:28,t:"Nenhum dos que estavam à mesa compreendeu por que lhe dissera isso."},
{v:29,t:"Pois alguns pensavam que, como Judas tinha a bolsa, Jesus lhe dissera: Compra o que precisamos para a festa; ou que desse alguma coisa aos pobres."},
{v:30,t:"Tendo tomado o bocado, ele saiu logo. E era noite.",n:"E era noite: três palavras, e das mais lembradas do quarto evangelho. Não é só a hora. Judas sai da luz, que o evangelho disse ser Jesus, para a noite."}
];

EV[177] = [
{p:"João 13:31-38"},
{v:31,t:"Depois que ele saiu, disse Jesus: Agora foi glorificado o Filho do Homem, e Deus foi glorificado nele.",n:"Começam aqui os discursos de despedida, que ocupam os capítulos 13 a 17. A saída de Judas desencadeia a Paixão, e é nesse momento que Jesus fala de glória."},
{v:32,t:"Se Deus foi glorificado nele, Deus também o glorificará em si mesmo, e logo o glorificará."},
{v:33,t:"Filhinhos, ainda um pouco estou convosco. Haveis de procurar-me; e, como disse aos judeus: Para onde eu vou, vós não podeis ir, assim também vos digo agora."},
{v:34,t:"Dou-vos um mandamento novo: que vos ameis uns aos outros; como eu vos amei, também vós vos deveis amar uns aos outros.",n:"Amar o próximo estava já no Levítico. O que é novo é a medida: como eu vos amei — e acabava de lavar-lhes os pés."},
{v:35,t:"Nisto todos conhecerão que sois meus discípulos: se tiverdes amor uns aos outros."},
{v:36,t:"Disse-lhe Simão Pedro: Senhor, para onde vais? Jesus respondeu: Para onde eu vou, não me podes seguir agora; mas hás de seguir-me mais tarde."},
{v:37,t:"Disse-lhe Pedro: Senhor, por que não posso seguir-te agora? Darei a minha vida por ti."},
{v:38,t:"Respondeu Jesus: Darás a tua vida por mim? Em verdade, em verdade te digo: não cantará o galo sem que me tenhas negado três vezes.",n:"Pedro havia de dar a vida, de fato, como Jesus lhe anunciará no último capítulo. Mas não naquela noite."},
{p:"João 14:1-31"},
{v:1,t:"Não se perturbe o vosso coração. Credes em Deus, crede também em mim."},
{v:2,t:"Na casa de meu Pai há muitas moradas; se não fosse assim, eu vos teria dito; pois vou preparar-vos um lugar.",n:"Moradas traduz monai, do verbo menein, permanecer, que é a palavra-chave destes capítulos: permanecei em mim, e eu em vós. A casa do Pai é o lugar onde se permanece."},
{v:3,t:"E, quando eu for e vos tiver preparado um lugar, virei de novo e vos tomarei comigo, para que, onde eu estiver, estejais vós também."},
{v:4,t:"E para onde eu vou vós conheceis o caminho."},
{v:5,t:"Disse-lhe Tomé: Senhor, não sabemos para onde vais; como podemos conhecer o caminho?"},
{v:6,t:"Disse-lhe Jesus: Eu sou o caminho, a verdade e a vida; ninguém vem ao Pai senão por mim.",n:"Tomé pergunta por um caminho e recebe uma pessoa. As três palavras não são três coisas: a verdade e a vida dizem de que caminho se trata."},
{v:7,t:"Se me conhecêsseis, conheceríeis também a meu Pai; e desde agora o conheceis e o vistes."},
{v:8,t:"Disse-lhe Filipe: Senhor, mostra-nos o Pai, e isso nos basta."},
{v:9,t:"Disse-lhe Jesus: Há tanto tempo estou convosco, e não me conheces, Filipe? Quem me vê, vê o Pai. Como dizes tu: Mostra-nos o Pai?"},
{v:10,t:"Não crês que eu estou no Pai e o Pai está em mim? As palavras que eu vos digo não as digo por mim mesmo; mas o Pai, que permanece em mim, é quem faz as suas obras."},
{v:11,t:"Crede-me: eu estou no Pai e o Pai está em mim; crede ao menos por causa das próprias obras."},
{v:12,t:"Em verdade, em verdade vos digo: quem crê em mim fará também as obras que eu faço, e fará maiores do que estas, porque eu vou para o Pai."},
{v:13,t:"E tudo o que pedirdes em meu nome, eu o farei, para que o Pai seja glorificado no Filho."},
{v:14,t:"Se me pedirdes alguma coisa em meu nome, eu a farei."},
{v:15,t:"Se me amais, guardareis os meus mandamentos."},
{v:16,t:"E eu rogarei ao Pai, e ele vos dará outro Paráclito, para que esteja convosco para sempre:",n:"Paráclito é o parakletos, o chamado para junto de alguém: o advogado que assiste o réu, o que defende e consola. Outro, porque o primeiro foi o próprio Jesus — é o nome que a primeira carta de São João lhe dá."},
{v:17,t:"o Espírito da verdade, que o mundo não pode receber, porque não o vê nem o conhece; vós o conheceis, porque permanece convosco e estará em vós."},
{v:18,t:"Não vos deixarei órfãos; virei a vós."},
{v:19,t:"Ainda um pouco, e o mundo já não me verá; vós, porém, me vereis, porque eu vivo e vós vivereis."},
{v:20,t:"Naquele dia conhecereis que eu estou em meu Pai, e vós em mim, e eu em vós."},
{v:21,t:"Quem tem os meus mandamentos e os guarda, esse é o que me ama; e quem me ama será amado por meu Pai, e eu o amarei e me manifestarei a ele."},
{v:22,t:"Disse-lhe Judas, não o Iscariotes: Senhor, como é que te hás de manifestar a nós e não ao mundo?"},
{v:23,t:"Respondeu-lhe Jesus: Se alguém me ama, guardará a minha palavra, e meu Pai o amará, e viremos a ele e faremos nele a nossa morada.",n:"Morada é a mesma palavra do versículo 2, e o movimento inverte-se: lá, Jesus ia preparar um lugar para eles na casa do Pai; aqui, o Pai e o Filho vêm morar em quem os ama."},
{v:24,t:"Quem não me ama não guarda as minhas palavras. E a palavra que ouvis não é minha, mas do Pai, que me enviou."},
{v:25,t:"Disse-vos estas coisas enquanto permaneço convosco."},
{v:26,t:"Mas o Paráclito, o Espírito Santo, que o Pai enviará em meu nome, esse vos ensinará todas as coisas e vos recordará tudo o que eu vos disse."},
{v:27,t:"Deixo-vos a paz, a minha paz vos dou; não a dou como o mundo a dá. Não se perturbe o vosso coração, nem se intimide.",n:"A paz, shalom, era a saudação de despedida de todos os dias. Jesus toma a palavra comum e diz que a sua não é a mesma: o mundo deseja a paz ao despedir-se; ele dá-a."},
{v:28,t:"Ouvistes que eu vos disse: Vou e volto a vós. Se me amásseis, havíeis de alegrar-vos por eu ir para o Pai, porque o Pai é maior do que eu.",n:"O Pai é maior do que eu foi o versículo de que os arianos fizeram bandeira, no século IV. Os Padres responderam de dois modos, que a Igreja conserva: dito da humanidade de Cristo, ou da ordem de origem, em que o Pai é a fonte e o Filho é gerado, sem que isso diminua a igualdade da natureza."},
{v:29,t:"E disse-vos agora, antes que aconteça, para que, quando acontecer, creiais."},
{v:30,t:"Já não falarei muito convosco, porque vem o príncipe deste mundo; e ele nada tem em mim;"},
{v:31,t:"mas é para que o mundo saiba que eu amo o Pai e que faço como o Pai me ordenou. Levantai-vos, vamo-nos daqui.",n:"Depois deste levantai-vos, o discurso continua ainda três capítulos antes de saírem, no capítulo 18. Muitos estudiosos veem aqui a costura de discursos reunidos depois; outros, que se levantaram e Jesus continuou a falar pelo caminho. O texto não decide."}
];

EV[178] = [
{p:"Mateus 26:30"},
{v:30,t:"Tendo cantado o hino, saíram para o monte das Oliveiras.",n:"O hino é o Hallel, os Salmos 113 a 118, que se cantava no fim da ceia pascal e que já foi traduzido aqui. O último deles diz: a pedra que os construtores rejeitaram veio a ser a pedra angular."},
{p:"Marcos 14:26"},
{v:26,t:"Tendo cantado o hino, saíram para o monte das Oliveiras."},
{p:"Lucas 22:39"},
{v:39,t:"Saindo, foi, como de costume, para o monte das Oliveiras; e os discípulos o seguiram."}
];

EV[179] = [
{p:"Mateus 26:31-35"},
{v:31,t:"Então Jesus lhes disse: Todos vós vos escandalizareis por minha causa esta noite, pois está escrito: Ferirei o pastor, e as ovelhas do rebanho serão dispersas.",n:"A citação é de Zacarias 13, versículo 7. No profeta, quem fere o pastor é o próprio Deus: a dispersão faz parte do que tem de acontecer."},
{v:32,t:"Mas, depois que eu ressuscitar, irei adiante de vós para a Galileia."},
{v:33,t:"Pedro, tomando a palavra, disse-lhe: Ainda que todos se escandalizem por tua causa, eu nunca me escandalizarei."},
{v:34,t:"Jesus disse-lhe: Em verdade te digo que esta noite, antes que o galo cante, três vezes me negarás."},
{v:35,t:"Disse-lhe Pedro: Ainda que seja preciso morrer contigo, não te negarei. E o mesmo disseram todos os discípulos."},
{p:"Marcos 14:27-31"},
{v:27,t:"E Jesus lhes disse: Todos vos escandalizareis, porque está escrito: Ferirei o pastor, e as ovelhas serão dispersas."},
{v:28,t:"Mas, depois que eu ressuscitar, irei adiante de vós para a Galileia."},
{v:29,t:"Pedro disse-lhe: Ainda que todos se escandalizem, eu não."},
{v:30,t:"Jesus disse-lhe: Em verdade te digo que hoje, nesta mesma noite, antes que o galo cante duas vezes, três vezes me negarás.",n:"Duas vezes é pormenor só de São Marcos, e só ele conta, no capítulo 14, que o galo cantou duas vezes. A antiga tradição, que via em São Marcos o intérprete de Pedro, encontrava nisto a lembrança do próprio apóstolo."},
{v:31,t:"Mas ele insistia ainda mais: Ainda que seja preciso morrer contigo, não te negarei. E todos diziam o mesmo."},
{p:"Lucas 22:31-38"},
{v:31,t:"Simão, Simão, eis que Satanás pediu para vos peneirar como o trigo;",n:"No grego, a primeira frase está no plural — Satanás pediu para vos peneirar a todos — e a seguinte no singular: roguei por ti. A oração de Jesus é por Pedro, para que ele depois sustente os outros."},
{v:32,t:"mas eu roguei por ti, para que a tua fé não desfaleça; e tu, quando te converteres, confirma os teus irmãos."},
{v:33,t:"Ele lhe disse: Senhor, estou pronto a ir contigo para a prisão e para a morte."},
{v:34,t:"Jesus respondeu: Eu te digo, Pedro: o galo não cantará hoje sem que três vezes tenhas negado que me conheces."},
{v:35,t:"E disse-lhes: Quando vos enviei sem bolsa, sem alforje e sem sandálias, faltou-vos alguma coisa? Eles responderam: Nada."},
{v:36,t:"Disse-lhes então: Mas agora, quem tem bolsa tome-a, e do mesmo modo o alforje; e quem não tem espada venda o manto e compre uma.",n:"A frase é figurada: acabou o tempo em que eram recebidos em toda parte, e vem o tempo da hostilidade. Os discípulos entendem-na à letra e mostram duas espadas — e a resposta de Jesus, no versículo 38, encerra a conversa."},
{v:37,t:"Porque eu vos digo que é necessário que se cumpra em mim o que está escrito: Foi contado entre os malfeitores. Pois o que me diz respeito está chegando ao fim.",n:"É o último versículo do canto do servo, Isaías 53. São Lucas é o único que o põe na boca de Jesus, e cumpre-se à letra no Calvário, entre dois malfeitores."},
{v:38,t:"Eles disseram: Senhor, eis aqui duas espadas. Ele lhes disse: Basta."},
{p:"João 13:38"},
{v:38,t:"Respondeu Jesus: Darás a tua vida por mim? Em verdade, em verdade te digo: não cantará o galo sem que me tenhas negado três vezes."}
];

EV[180] = [
{p:"João 15:1-17"},
{v:1,t:"Eu sou a videira verdadeira, e meu Pai é o agricultor.",n:"A videira é, em Isaías, Jeremias e no Salmo 80, a figura de Israel, que Deus plantou e que não deu o fruto esperado. Verdadeira quer dizer a que cumpre o que as outras figuravam: a videira é agora uma pessoa, e os ramos vivem dela."},
{v:2,t:"Todo ramo em mim que não dá fruto, ele o corta; e todo o que dá fruto, ele o limpa, para que dê mais fruto.",n:"Em grego há um jogo que o português só em parte conserva: airei, corta, e kathairei, limpa ou poda. E o versículo seguinte continua o jogo — vós já estais limpos, katharoi."},
{v:3,t:"Vós já estais limpos, por causa da palavra que vos disse."},
{v:4,t:"Permanecei em mim, e eu em vós. Como o ramo não pode dar fruto por si mesmo, se não permanecer na videira, assim também vós, se não permanecerdes em mim."},
{v:5,t:"Eu sou a videira, vós os ramos. Quem permanece em mim, e eu nele, esse dá muito fruto; porque sem mim nada podeis fazer."},
{v:6,t:"Se alguém não permanecer em mim, é lançado fora, como o ramo, e seca; e os ajuntam, lançam-nos no fogo, e ardem."},
{v:7,t:"Se permanecerdes em mim, e as minhas palavras permanecerem em vós, pedi o que quiserdes, e vos será concedido."},
{v:8,t:"Nisto é glorificado meu Pai: que deis muito fruto e vos torneis meus discípulos."},
{v:9,t:"Como o Pai me amou, também eu vos amei. Permanecei no meu amor."},
{v:10,t:"Se guardardes os meus mandamentos, permanecereis no meu amor, assim como eu guardei os mandamentos de meu Pai e permaneço no seu amor."},
{v:11,t:"Disse-vos estas coisas para que a minha alegria esteja em vós, e a vossa alegria seja completa."},
{v:12,t:"Este é o meu mandamento: que vos ameis uns aos outros, como eu vos amei."},
{v:13,t:"Ninguém tem maior amor do que este: dar a vida pelos seus amigos."},
{v:14,t:"Vós sois meus amigos, se fizerdes o que eu vos mando."},
{v:15,t:"Já não vos chamo servos, porque o servo não sabe o que faz o seu senhor; mas chamei-vos amigos, porque vos dei a conhecer tudo o que ouvi de meu Pai.",n:"Amigo de Deus era o título de Abraão e de Moisés, com quem Deus falava face a face. A diferença entre o servo e o amigo, diz o versículo, não é o que cada um faz, mas o que cada um sabe."},
{v:16,t:"Não fostes vós que me escolhestes, mas fui eu que vos escolhi e vos designei para que vades e deis fruto, e o vosso fruto permaneça; para que tudo o que pedirdes ao Pai em meu nome, ele vos conceda."},
{v:17,t:"Isto vos mando: que vos ameis uns aos outros."}
];

EV[181] = [
{p:"João 15:18-27"},
{v:18,t:"Se o mundo vos odeia, sabei que primeiro me odiou a mim."},
{v:19,t:"Se fôsseis do mundo, o mundo amaria o que é seu; mas, porque não sois do mundo, e eu vos escolhi do meio do mundo, por isso o mundo vos odeia.",n:"Mundo tem em São João dois sentidos: o mundo que Deus amou a ponto de dar o seu Filho, e o mundo enquanto se fecha a Deus. É deste segundo que se fala aqui, e não da terra nem dos homens."},
{v:20,t:"Lembrai-vos da palavra que vos disse: O servo não é maior do que o seu senhor. Se me perseguiram a mim, também vos perseguirão a vós; se guardaram a minha palavra, também guardarão a vossa."},
{v:21,t:"Mas tudo isso vos farão por causa do meu nome, porque não conhecem aquele que me enviou."},
{v:22,t:"Se eu não tivesse vindo e não lhes tivesse falado, não teriam pecado; mas agora não têm desculpa do seu pecado."},
{v:23,t:"Quem me odeia, odeia também a meu Pai."},
{v:24,t:"Se eu não tivesse feito no meio deles as obras que nenhum outro fez, não teriam pecado; mas agora viram e odiaram, tanto a mim como a meu Pai."},
{v:25,t:"Mas é para que se cumpra a palavra escrita na sua Lei: Odiaram-me sem motivo.",n:"É o versículo 5 do Salmo 69, já traduzido aqui, com uma nota que remete para este lugar; está também no Salmo 35. Chama-se Lei a toda a Escritura, e não só aos cinco livros de Moisés."},
{v:26,t:"Quando vier o Paráclito, que eu vos enviarei da parte do Pai, o Espírito da verdade, que procede do Pai, ele dará testemunho de mim.",n:"Que procede do Pai é a frase que o Credo de Niceia e Constantinopla recolheu. O acréscimo latino e do Filho, o Filioque, foi o ponto da maior controvérsia entre as Igrejas do Oriente e do Ocidente — e este versículo, que fala do Espírito enviado pelo Filho e procedente do Pai, é o texto sobre o qual as duas tradições leem as suas fórmulas."},
{v:27,t:"E também vós dareis testemunho, porque estais comigo desde o princípio."},
{p:"João 16:1-4"},
{v:1,t:"Disse-vos estas coisas para que não vos escandalizeis."},
{v:2,t:"Hão de expulsar-vos das sinagogas; e chegará a hora em que todo aquele que vos matar julgará prestar culto a Deus.",n:"Julgará prestar culto a Deus: o pior da perseguição que se anuncia não é a violência, mas a boa consciência de quem a pratica. Saulo de Tarso, antes da conversão, foi exatamente isso."},
{v:3,t:"E farão isso porque não conheceram o Pai nem a mim."},
{v:4,t:"Mas eu vos disse estas coisas para que, quando chegar a hora, vos lembreis de que eu vos avisei. Não vos disse isto desde o princípio, porque estava convosco."}
];

EV[182] = [
{p:"João 16:5-33"},
{v:5,t:"Mas agora vou para aquele que me enviou, e nenhum de vós me pergunta: Para onde vais?",n:"Pedro e Tomé tinham feito essa pergunta, no capítulo 13 e no 14. A frase é das que sugerem que os discursos de despedida reúnem palavras ditas em momentos diferentes."},
{v:6,t:"Mas, porque vos disse estas coisas, a tristeza encheu o vosso coração."},
{v:7,t:"Contudo, eu vos digo a verdade: convém-vos que eu vá; porque, se eu não for, o Paráclito não virá a vós; mas, se eu for, eu o enviarei a vós."},
{v:8,t:"E ele, quando vier, convencerá o mundo a respeito do pecado, da justiça e do juízo:",n:"Convencerá traduz elenchei, verbo de tribunal: provar a culpa, desmascarar. O Paráclito, o advogado, faz-se acusador, e o processo em que Jesus foi condenado é reaberto com as partes trocadas."},
{v:9,t:"do pecado, porque não creem em mim;"},
{v:10,t:"da justiça, porque vou para o Pai, e já não me vereis;"},
{v:11,t:"do juízo, porque o príncipe deste mundo já está julgado."},
{v:12,t:"Tenho ainda muitas coisas a dizer-vos, mas não as podeis suportar agora."},
{v:13,t:"Quando, porém, vier ele, o Espírito da verdade, ele vos guiará a toda a verdade; porque não falará por si mesmo, mas dirá tudo o que tiver ouvido e vos anunciará as coisas que hão de vir."},
{v:14,t:"Ele me glorificará, porque receberá do que é meu e o anunciará a vós."},
{v:15,t:"Tudo o que o Pai tem é meu; por isso disse que ele receberá do que é meu e o anunciará a vós."},
{v:16,t:"Um pouco, e já não me vereis; e outra vez um pouco, e me vereis."},
{v:17,t:"Disseram então alguns dos seus discípulos entre si: Que é isto que nos diz: Um pouco, e não me vereis; e outra vez um pouco, e me vereis; e: Porque vou para o Pai?"},
{v:18,t:"Diziam, pois: Que é este um pouco? Não sabemos de que fala."},
{v:19,t:"Jesus conheceu que queriam interrogá-lo e disse-lhes: Perguntais entre vós a respeito do que disse: Um pouco, e não me vereis; e outra vez um pouco, e me vereis?"},
{v:20,t:"Em verdade, em verdade vos digo que chorareis e lamentareis, e o mundo se alegrará; vós ficareis tristes, mas a vossa tristeza se converterá em alegria."},
{v:21,t:"A mulher, quando dá à luz, tem tristeza, porque chegou a sua hora; mas, depois que deu à luz a criança, já não se lembra da aflição, pela alegria de ter nascido um homem para o mundo.",n:"Chegou a sua hora é a expressão que o quarto evangelho reserva para a Paixão. A imagem diz que a cruz é um parto: a dor não desaparece, muda de sentido."},
{v:22,t:"Assim também vós: agora estais tristes; mas eu vos verei de novo, e o vosso coração se alegrará, e ninguém vos tirará a vossa alegria."},
{v:23,t:"Naquele dia nada me perguntareis. Em verdade, em verdade vos digo: se pedirdes alguma coisa ao Pai em meu nome, ele vos dará."},
{v:24,t:"Até agora nada pedistes em meu nome; pedi, e recebereis, para que a vossa alegria seja completa."},
{v:25,t:"Disse-vos estas coisas em comparações; vem a hora em que já não vos falarei em comparações, mas vos falarei claramente a respeito do Pai."},
{v:26,t:"Naquele dia pedireis em meu nome; e não vos digo que rogarei ao Pai por vós;"},
{v:27,t:"pois o próprio Pai vos ama, porque vós me amastes e crestes que eu saí de Deus."},
{v:28,t:"Saí do Pai e vim ao mundo; agora deixo o mundo e vou para o Pai.",n:"O versículo resume em duas linhas todo o quarto evangelho: a descida e a subida, o prólogo e a Páscoa."},
{v:29,t:"Disseram-lhe os seus discípulos: Eis que agora falas claramente e não dizes comparação nenhuma."},
{v:30,t:"Agora sabemos que sabes todas as coisas e não precisas de que ninguém te interrogue; por isso cremos que saíste de Deus."},
{v:31,t:"Jesus respondeu-lhes: Agora credes?"},
{v:32,t:"Eis que vem a hora, e já chegou, em que sereis dispersos, cada um para o seu lado, e me deixareis sozinho; mas não estou sozinho, porque o Pai está comigo."},
{v:33,t:"Disse-vos estas coisas para que tenhais paz em mim. No mundo tereis tribulações; mas tende coragem: eu venci o mundo.",n:"Eu venci está no perfeito grego, que diz uma coisa acabada e com efeito permanente. É dito na véspera da cruz, antes da derrota que todos iam ver."}
];

EV[183] = [
{p:"João 17:1-26"},
{v:1,t:"Tendo dito estas coisas, Jesus levantou os olhos ao céu e disse: Pai, chegou a hora: glorifica o teu Filho, para que o Filho te glorifique,",n:"Chama-se a este capítulo a oração sacerdotal desde o século XVI. É a mais longa oração de Jesus que os evangelhos conservam, e é dita em voz alta, diante dos discípulos: eles ouvem-no rezar por eles."},
{v:2,t:"assim como lhe deste poder sobre toda carne, para que dê a vida eterna a todos os que lhe deste."},
{v:3,t:"E a vida eterna é esta: que te conheçam a ti, o único Deus verdadeiro, e a Jesus Cristo, a quem enviaste.",n:"A única definição de vida eterna em toda a Escritura. Conhecer é, na Bíblia, mais do que saber: é a intimidade, a palavra com que o Gênesis diz a união de Adão e Eva."},
{v:4,t:"Eu te glorifiquei na terra, consumando a obra que me deste para fazer."},
{v:5,t:"E agora, Pai, glorifica-me junto de ti com a glória que eu tinha junto de ti antes que o mundo existisse."},
{v:6,t:"Manifestei o teu nome aos homens que me deste do mundo. Eram teus, e tu os deste a mim; e guardaram a tua palavra."},
{v:7,t:"Agora reconheceram que tudo o que me deste vem de ti;"},
{v:8,t:"porque lhes dei as palavras que tu me deste, e eles as receberam, e reconheceram verdadeiramente que saí de ti, e creram que tu me enviaste."},
{v:9,t:"Eu rogo por eles; não rogo pelo mundo, mas por aqueles que me deste, porque são teus;"},
{v:10,t:"e tudo o que é meu é teu, e o que é teu é meu; e neles sou glorificado."},
{v:11,t:"Já não estou no mundo; mas eles estão no mundo, e eu vou para ti. Pai santo, guarda-os no teu nome, que me deste, para que sejam um, como nós."},
{v:12,t:"Quando eu estava com eles, guardava-os no teu nome, que me deste; guardei-os, e nenhum deles se perdeu, senão o filho da perdição, para que se cumprisse a Escritura.",n:"Filho da perdição é hebraísmo para quem está votado à perdição, e aqui designa Judas. A mesma expressão volta na segunda carta aos Tessalonicenses."},
{v:13,t:"Mas agora vou para ti, e digo estas coisas no mundo, para que tenham em si mesmos a minha alegria completa."},
{v:14,t:"Dei-lhes a tua palavra, e o mundo os odiou, porque não são do mundo, como eu não sou do mundo."},
{v:15,t:"Não peço que os tires do mundo, mas que os guardes do maligno."},
{v:16,t:"Não são do mundo, como eu não sou do mundo."},
{v:17,t:"Santifica-os na verdade: a tua palavra é a verdade."},
{v:18,t:"Como tu me enviaste ao mundo, também eu os enviei ao mundo."},
{v:19,t:"E por eles eu me santifico a mim mesmo, para que também eles sejam santificados na verdade.",n:"Santificar-se é, na linguagem do culto, consagrar-se como vítima: é o verbo que o Deuteronômio usa para os primogênitos oferecidos. Jesus fala da morte que vai aceitar."},
{v:20,t:"Não rogo somente por estes, mas também por aqueles que, pela sua palavra, hão de crer em mim,"},
{v:21,t:"para que todos sejam um; como tu, Pai, estás em mim, e eu em ti, que também eles estejam em nós, para que o mundo creia que tu me enviaste.",n:"A oração pela unidade dos que hão de crer é a que as Igrejas separadas mais citam umas às outras. A razão dada é missionária: a unidade é o que há de fazer o mundo crer."},
{v:22,t:"E eu dei-lhes a glória que tu me deste, para que sejam um, como nós somos um:"},
{v:23,t:"eu neles, e tu em mim, para que sejam perfeitos na unidade, e o mundo conheça que tu me enviaste e os amaste como amaste a mim."},
{v:24,t:"Pai, quero que, onde eu estou, estejam também comigo aqueles que me deste, para que vejam a minha glória, que me deste, porque me amaste antes da fundação do mundo."},
{v:25,t:"Pai justo, o mundo não te conheceu; mas eu te conheci, e estes reconheceram que tu me enviaste."},
{v:26,t:"E eu lhes dei a conhecer o teu nome, e hei de dá-lo a conhecer, para que o amor com que me amaste esteja neles, e eu neles."}
];

EV[184] = [
{p:"Mateus 26:36-56"},
{v:36,t:"Então Jesus foi com eles a um lugar chamado Getsêmani e disse aos discípulos: Sentai-vos aqui, enquanto eu vou ali orar.",n:"Getsêmani é o aramaico gat shemanim, o lagar do azeite: um olival com a sua prensa, ao pé do monte das Oliveiras. O nome não foi escolhido por ninguém, e diz o que ali acontece."},
{v:37,t:"E, tomando consigo Pedro e os dois filhos de Zebedeu, começou a entristecer-se e a angustiar-se."},
{v:38,t:"Então lhes disse: A minha alma está triste até à morte; ficai aqui e vigiai comigo.",n:"A minha alma está triste é o refrão dos Salmos 42 e 43. Até à morte quer dizer: uma tristeza que mata."},
{v:39,t:"E, adiantando-se um pouco, prostrou-se com o rosto em terra e orava, dizendo: Meu Pai, se é possível, passe de mim este cálice; contudo, não seja como eu quero, mas como tu queres.",n:"O cálice é, nos profetas e no Salmo 75, o cálice da ira que Deus dá a beber aos culpados. Jesus pede que passe, e aceita bebê-lo: a oração não esconde o pavor, e não se detém nele."},
{v:40,t:"Voltou aos discípulos e encontrou-os dormindo; e disse a Pedro: Então não pudestes vigiar uma hora comigo?"},
{v:41,t:"Vigiai e orai, para não cairdes em tentação; o espírito está pronto, mas a carne é fraca."},
{v:42,t:"Afastando-se de novo, pela segunda vez, orou, dizendo: Meu Pai, se este cálice não pode passar sem que eu o beba, faça-se a tua vontade.",n:"Faça-se a tua vontade: são as palavras do Pai-nosso, que ele ensinara aos discípulos. É a única vez que os evangelhos o mostram a rezá-las por si."},
{v:43,t:"E, voltando, encontrou-os de novo dormindo, porque os seus olhos estavam pesados."},
{v:44,t:"E, deixando-os, afastou-se de novo e orou pela terceira vez, dizendo as mesmas palavras."},
{v:45,t:"Então voltou aos discípulos e disse-lhes: Dormi agora e descansai! Eis que chegou a hora, e o Filho do Homem vai ser entregue nas mãos dos pecadores."},
{v:46,t:"Levantai-vos, vamos! Eis que está perto aquele que me entrega."},
{v:47,t:"Ainda ele falava, quando chegou Judas, um dos Doze, e com ele uma grande multidão com espadas e varapaus, enviada pelos sumos sacerdotes e pelos anciãos do povo."},
{v:48,t:"O traidor tinha-lhes dado este sinal: Aquele que eu beijar, é esse; prendei-o."},
{v:49,t:"E logo, aproximando-se de Jesus, disse: Salve, Rabi! E beijou-o.",n:"O beijo era a saudação do discípulo ao mestre. O sinal combinado era necessário: de noite, entre as oliveiras, os guardas não conheciam o rosto de quem vinham prender."},
{v:50,t:"Jesus disse-lhe: Amigo, a que vieste? Então se aproximaram, deitaram as mãos a Jesus e prenderam-no.",n:"Amigo traduz hetaire, a mesma palavra que São Mateus pôs na boca do dono da vinha para o trabalhador que murmura e na do rei para o convidado sem veste nupcial. É o tratamento que se dá, sem rancor, a quem está em erro."},
{v:51,t:"E eis que um dos que estavam com Jesus, estendendo a mão, desembainhou a espada e, ferindo o servo do sumo sacerdote, cortou-lhe a orelha."},
{v:52,t:"Então Jesus lhe disse: Mete a tua espada no seu lugar, porque todos os que tomam a espada pela espada perecerão."},
{v:53,t:"Ou pensas que eu não poderia rogar a meu Pai, e ele não me mandaria agora mesmo mais de doze legiões de anjos?",n:"Doze legiões são setenta e duas mil: uma para cada um dos doze que ele tinha, e o número é de propósito desmedido. O que prende Jesus não é a força dos que vieram."},
{v:54,t:"Como, então, se cumpririam as Escrituras, segundo as quais assim deve acontecer?"},
{v:55,t:"Naquela hora disse Jesus às multidões: Saístes com espadas e varapaus para me prender, como a um salteador? Todos os dias estava sentado no templo, ensinando, e não me prendestes."},
{v:56,t:"Mas tudo isso aconteceu para que se cumprissem as Escrituras dos profetas. Então todos os discípulos, abandonando-o, fugiram."},
{p:"Marcos 14:32-52"},
{v:32,t:"Chegaram a um lugar chamado Getsêmani, e ele disse aos seus discípulos: Sentai-vos aqui, enquanto eu oro."},
{v:33,t:"E tomou consigo Pedro, Tiago e João, e começou a sentir pavor e angústia.",n:"Pavor traduz ekthambeisthai, verbo fortíssimo: o espanto de quem se vê diante do insuportável. São Marcos é o evangelista que menos atenua, e diz a coisa com a palavra mais dura que tinha."},
{v:34,t:"E disse-lhes: A minha alma está triste até à morte; ficai aqui e vigiai."},
{v:35,t:"E, adiantando-se um pouco, caiu por terra e orava para que, se fosse possível, passasse dele aquela hora."},
{v:36,t:"E dizia: Abbá, Pai, tudo te é possível; afasta de mim este cálice; mas não o que eu quero, e sim o que tu queres.",n:"Abbá é a palavra aramaica com que as crianças chamavam o pai. É a única vez nos evangelhos que ela se conserva na língua original, e é aqui, no horto. São Paulo mostra que as primeiras comunidades a repetiam na oração."},
{v:37,t:"Voltou e encontrou-os dormindo, e disse a Pedro: Simão, dormes? Não pudeste vigiar uma hora?",n:"Chama-lhe Simão, e não Pedro: o nome da rocha não lhe cabe nessa noite."},
{v:38,t:"Vigiai e orai, para não cairdes em tentação; o espírito está pronto, mas a carne é fraca."},
{v:39,t:"Afastou-se de novo e orou, dizendo as mesmas palavras."},
{v:40,t:"E, voltando outra vez, encontrou-os dormindo, porque os seus olhos estavam pesados; e não sabiam o que lhe responder."},
{v:41,t:"Voltou pela terceira vez e disse-lhes: Dormi agora e descansai! Basta; chegou a hora. Eis que o Filho do Homem vai ser entregue nas mãos dos pecadores."},
{v:42,t:"Levantai-vos, vamos! Eis que está perto aquele que me entrega."},
{v:43,t:"E logo, ainda ele falava, chegou Judas, um dos Doze, e com ele uma multidão com espadas e varapaus, enviada pelos sumos sacerdotes, pelos escribas e pelos anciãos."},
{v:44,t:"O traidor tinha-lhes dado um sinal, dizendo: Aquele que eu beijar, é esse; prendei-o e levai-o com cautela."},
{v:45,t:"E, logo que chegou, aproximou-se dele e disse: Rabi! E beijou-o."},
{v:46,t:"Eles lançaram-lhe as mãos e prenderam-no."},
{v:47,t:"Um dos que ali estavam, desembainhando a espada, feriu o servo do sumo sacerdote e cortou-lhe a orelha."},
{v:48,t:"Tomando a palavra, Jesus disse-lhes: Saístes com espadas e varapaus para me prender, como a um salteador?"},
{v:49,t:"Todos os dias estava convosco no templo, ensinando, e não me prendestes. Mas é para que se cumpram as Escrituras."},
{v:50,t:"Então todos, abandonando-o, fugiram."},
{v:51,t:"Seguia-o um jovem, envolto apenas num lençol, sobre o corpo nu; e agarraram-no.",n:"Só São Marcos conta este episódio, e não diz quem era o jovem. A antiga tradição viu nele o próprio evangelista, que assina assim o seu livro: o único que ainda o seguia, e que também fugiu."},
{v:52,t:"Mas ele, largando o lençol, fugiu nu."},
{p:"Lucas 22:40-53"},
{v:40,t:"Chegando ao lugar, disse-lhes: Orai para não cairdes em tentação."},
{v:41,t:"E afastou-se deles cerca de um tiro de pedra; e, pondo-se de joelhos, orava,"},
{v:42,t:"dizendo: Pai, se queres, afasta de mim este cálice; contudo, não se faça a minha vontade, mas a tua."},
{v:43,t:"Apareceu-lhe então um anjo do céu, que o confortava.",n:"Os versículos 43 e 44 faltam em alguns manuscritos antigos importantes e estão noutros igualmente antigos; já os Padres do século II os citam. A Nova Vulgata conserva-os."},
{v:44,t:"E, estando em agonia, orava mais intensamente; e o seu suor tornou-se como gotas de sangue que caíam sobre a terra.",n:"Agonia traduz agonia, a única vez que a palavra aparece no Novo Testamento: não é ainda o morrer, é a luta do atleta no momento decisivo. O suor é comparado a gotas de sangue — o texto diz como —, embora a medicina conheça o fenômeno, raro, do suor de sangue sob angústia extrema."},
{v:45,t:"Levantando-se da oração, veio aos discípulos e encontrou-os dormindo, por causa da tristeza."},
{v:46,t:"E disse-lhes: Por que dormis? Levantai-vos e orai, para não cairdes em tentação."},
{v:47,t:"Ainda ele falava, quando apareceu uma multidão; e o que se chamava Judas, um dos Doze, ia à frente deles, e aproximou-se de Jesus para o beijar."},
{v:48,t:"Jesus disse-lhe: Judas, com um beijo entregas o Filho do Homem?"},
{v:49,t:"Vendo os que estavam com ele o que ia acontecer, disseram: Senhor, feriremos à espada?"},
{v:50,t:"E um deles feriu o servo do sumo sacerdote e cortou-lhe a orelha direita."},
{v:51,t:"Mas Jesus, tomando a palavra, disse: Deixai, basta. E, tocando-lhe a orelha, curou-o.",n:"Só São Lucas conta a cura, e é o último milagre dos evangelhos antes da cruz: feito a um dos que o vinham prender."},
{v:52,t:"Disse então Jesus aos sumos sacerdotes, aos chefes da guarda do templo e aos anciãos que tinham vindo contra ele: Saístes com espadas e varapaus, como contra um salteador?"},
{v:53,t:"Todos os dias estava convosco no templo, e não estendestes as mãos contra mim. Mas esta é a vossa hora e o poder das trevas."},
{p:"João 18:1-12"},
{v:1,t:"Tendo dito isso, Jesus saiu com os seus discípulos para além da torrente do Cedron, onde havia um horto, no qual entrou com os seus discípulos.",n:"Atravessar o Cedron é o que Davi fez, no segundo livro de Samuel, ao fugir de Jerusalém, traído pelo seu conselheiro Aquitofel — que depois se enforcou. O paralelo não é dito, mas quem conhecia a história via-o."},
{v:2,t:"Judas, que o entregava, também conhecia aquele lugar, porque Jesus muitas vezes se reunira ali com os seus discípulos."},
{v:3,t:"Judas, pois, tendo tomado a coorte e guardas dos sumos sacerdotes e dos fariseus, foi ali com lanternas, archotes e armas.",n:"A coorte romana tinha seiscentos homens; aqui é certamente um destacamento dela. Vêm com lanternas numa noite de lua cheia, a da Páscoa, procurar a luz do mundo."},
{v:4,t:"Jesus, sabendo tudo o que lhe havia de acontecer, adiantou-se e disse-lhes: A quem procurais?"},
{v:5,t:"Responderam-lhe: A Jesus, o Nazareno. Disse-lhes Jesus: Sou eu. E Judas, que o entregava, estava também com eles."},
{v:6,t:"Quando lhes disse: Sou eu, recuaram e caíram por terra.",n:"Sou eu é ego eimi, o nome divino de que o quarto evangelho fez uso ao longo de todo o livro. Os que vêm prendê-lo caem por terra ao ouvi-lo: ninguém o leva sem que ele se entregue."},
{v:7,t:"Perguntou-lhes de novo: A quem procurais? Eles disseram: A Jesus, o Nazareno."},
{v:8,t:"Jesus respondeu: Já vos disse que sou eu. Se, pois, me procurais a mim, deixai ir estes."},
{v:9,t:"Era para que se cumprisse a palavra que tinha dito: Dos que me deste, não perdi nenhum."},
{v:10,t:"Então Simão Pedro, que tinha uma espada, desembainhou-a e feriu o servo do sumo sacerdote, cortando-lhe a orelha direita. O nome do servo era Malco.",n:"Só São João diz que foi Pedro quem feriu, e só ele dá o nome do servo. Escrevia quando Pedro já tinha morrido, e o nome já não o comprometia."},
{v:11,t:"Disse então Jesus a Pedro: Mete a espada na bainha. Não hei de beber o cálice que o Pai me deu?"},
{v:12,t:"Então a coorte, o tribuno e os guardas dos judeus prenderam Jesus e amarraram-no."}
];

EV[185] = [
{p:"João 18:13-14"},
{v:13,t:"E levaram-no primeiro a Anás, que era sogro de Caifás, o sumo sacerdote daquele ano.",n:"Anás fora sumo sacerdote entre os anos 6 e 15, deposto pelos romanos; mas continuava a ser o verdadeiro poder no templo: cinco dos seus filhos e o genro, Caifás, ocuparam o cargo depois dele. Só São João conta este primeiro interrogatório."},
{v:14,t:"Caifás era o que tinha aconselhado aos judeus que convinha que um só homem morresse pelo povo."},
{p:"João 18:19-24"},
{v:19,t:"O sumo sacerdote interrogou Jesus acerca dos seus discípulos e da sua doutrina."},
{v:20,t:"Jesus respondeu-lhe: Falei abertamente ao mundo; ensinei sempre na sinagoga e no templo, onde todos os judeus se reúnem, e nada disse em segredo."},
{v:21,t:"Por que me interrogas? Interroga os que ouviram o que eu lhes disse; eles sabem o que eu disse.",n:"Pela lei judaica, o acusado não podia ser obrigado a testemunhar contra si mesmo: a acusação tinha de vir de testemunhas. Jesus reclama o direito que o processo lhe devia."},
{v:22,t:"Tendo ele dito isso, um dos guardas que ali estavam deu uma bofetada em Jesus, dizendo: É assim que respondes ao sumo sacerdote?"},
{v:23,t:"Jesus respondeu-lhe: Se falei mal, dá testemunho do que está mal; mas, se falei bem, por que me bates?",n:"Santo Agostinho notou que Jesus, que mandara oferecer a outra face, não a oferece aqui: protesta. A mansidão não é silêncio diante da injustiça, e a pergunta fica feita."},
{v:24,t:"Anás, então, mandou-o amarrado a Caifás, o sumo sacerdote."}
];

EV[186] = [
{p:"Mateus 26:57-75"},
{v:57,t:"Os que tinham prendido Jesus levaram-no ao sumo sacerdote Caifás, onde estavam reunidos os escribas e os anciãos."},
{v:58,t:"Pedro seguia-o de longe até ao pátio do sumo sacerdote; e, entrando, sentou-se com os servos, para ver o fim."},
{v:59,t:"Os sumos sacerdotes e todo o sinédrio procuravam um falso testemunho contra Jesus, para o condenarem à morte,",n:"As regras que a Mixná, escrita mais tarde, atribui ao sinédrio proibiam julgar causas de morte de noite e em véspera de festa, e exigiam um dia de intervalo antes da sentença. Não é certo que valessem já neste tempo, mas o relato deixa ver a pressa e a irregularidade de tudo."},
{v:60,t:"e não o encontraram, embora se apresentassem muitas falsas testemunhas. Por fim, apresentaram-se duas,"},
{v:61,t:"que disseram: Este disse: Posso destruir o santuário de Deus e reedificá-lo em três dias.",n:"A frase deformava uma palavra verdadeira, que São João conserva no capítulo 2: destruí este santuário, e em três dias o levantarei. O evangelista explica ali que ele falava do santuário do seu corpo."},
{v:62,t:"Levantando-se, o sumo sacerdote disse-lhe: Nada respondes? Que é isto que estes testemunham contra ti?"},
{v:63,t:"Jesus, porém, calava-se. E o sumo sacerdote disse-lhe: Conjuro-te pelo Deus vivo que nos digas se tu és o Cristo, o Filho de Deus.",n:"O silêncio é o do servo de Isaías 53: como cordeiro levado ao matadouro, não abriu a boca. Só quando o sumo sacerdote o põe sob juramento Jesus fala."},
{v:64,t:"Jesus respondeu-lhe: Tu o disseste. Mas eu vos digo: doravante vereis o Filho do Homem sentado à direita do Poder e vindo sobre as nuvens do céu.",n:"A resposta junta o Salmo 110 — sentado à direita — e Daniel 7 — vindo sobre as nuvens. O Poder é modo judaico de dizer Deus sem pronunciar o nome. Jesus não se limita a responder à pergunta: anuncia que os seus juízes hão de vê-lo como juiz."},
{v:65,t:"Então o sumo sacerdote rasgou as suas vestes, dizendo: Blasfemou! Que necessidade temos ainda de testemunhas? Eis que acabais de ouvir a blasfêmia.",n:"Rasgar as vestes era o gesto obrigatório do juiz que ouvia uma blasfêmia. O sumo sacerdote dispensa as testemunhas que não conseguira encontrar: a condenação faz-se pela confissão do réu."},
{v:66,t:"Que vos parece? Eles responderam: É réu de morte."},
{v:67,t:"Então cuspiram-lhe no rosto e deram-lhe socos; e outros o esbofeteavam,"},
{v:68,t:"dizendo: Profetiza-nos, Cristo: quem é que te bateu?",n:"Zombam do profeta pedindo-lhe uma profecia — e, no mesmo momento, lá fora no pátio, cumpre-se à letra a que ele fizera a Pedro."},
{v:69,t:"Pedro, entretanto, estava sentado fora, no pátio. Aproximou-se dele uma criada, dizendo: Também tu estavas com Jesus, o Galileu."},
{v:70,t:"Mas ele negou diante de todos, dizendo: Não sei o que dizes."},
{v:71,t:"Saindo ele para o pórtico, viu-o outra criada e disse aos que ali estavam: Este estava com Jesus, o Nazareno."},
{v:72,t:"E ele negou de novo, com juramento: Não conheço esse homem."},
{v:73,t:"Pouco depois, aproximando-se os que ali estavam, disseram a Pedro: Certamente tu também és um deles, pois o teu modo de falar te denuncia.",n:"O aramaico da Galileia distinguia-se pelo modo de pronunciar as guturais, e os de Jerusalém faziam troça dele. O sotaque denuncia Pedro enquanto ele jura que não é quem é."},
{v:74,t:"Então começou a praguejar e a jurar: Não conheço esse homem! E logo o galo cantou.",n:"Praguejar traduz katanathematizein: lançar maldições sobre si mesmo se estivesse mentindo. Não conheço esse homem — nem sequer diz o nome."},
{v:75,t:"E Pedro lembrou-se da palavra que Jesus dissera: Antes que o galo cante, três vezes me negarás. E, saindo para fora, chorou amargamente."},
{p:"Marcos 14:53-72"},
{v:53,t:"Levaram Jesus ao sumo sacerdote, e reuniram-se todos os sumos sacerdotes, os anciãos e os escribas."},
{v:54,t:"Pedro seguiu-o de longe até dentro do pátio do sumo sacerdote, e estava sentado com os guardas, aquecendo-se ao fogo."},
{v:55,t:"Os sumos sacerdotes e todo o sinédrio procuravam um testemunho contra Jesus, para o condenarem à morte, e não o encontravam."},
{v:56,t:"Pois muitos testemunhavam falsamente contra ele, mas os testemunhos não concordavam.",n:"A lei do Deuteronômio exigia duas testemunhas concordes para condenar à morte. As testemunhas contradizem-se, e o processo, pela própria lei, devia acabar ali."},
{v:57,t:"Levantaram-se alguns e deram contra ele este falso testemunho:"},
{v:58,t:"Nós o ouvimos dizer: Destruirei este santuário feito por mãos humanas, e em três dias edificarei outro, não feito por mãos humanas."},
{v:59,t:"Mas nem assim o seu testemunho concordava."},
{v:60,t:"Levantando-se então o sumo sacerdote no meio, interrogou Jesus, dizendo: Nada respondes? Que é isto que estes testemunham contra ti?"},
{v:61,t:"Ele, porém, calava-se e nada respondia. De novo o sumo sacerdote o interrogou e lhe disse: És tu o Cristo, o Filho do Bendito?",n:"O Bendito é outro modo de evitar o nome de Deus. Em todo o evangelho de São Marcos, Jesus impôs silêncio a quem o reconhecia; é aqui, diante dos que o vão condenar, que o silêncio se rompe."},
{v:62,t:"Jesus disse: Eu sou. E vereis o Filho do Homem sentado à direita do Poder e vindo com as nuvens do céu.",n:"Só São Marcos traz a resposta direta, sem rodeio: eu sou — ego eimi, as palavras com que Deus se nomeia. É a única vez no segundo evangelho que Jesus declara abertamente quem é, e é o que o leva à morte."},
{v:63,t:"Então o sumo sacerdote, rasgando as suas vestes, disse: Que necessidade temos ainda de testemunhas?"},
{v:64,t:"Ouvistes a blasfêmia. Que vos parece? E todos o condenaram como réu de morte."},
{v:65,t:"E alguns começaram a cuspir nele, a cobrir-lhe o rosto e a dar-lhe socos, dizendo: Profetiza! E os guardas davam-lhe bofetadas."},
{v:66,t:"Estando Pedro em baixo, no pátio, chegou uma das criadas do sumo sacerdote;"},
{v:67,t:"e, vendo Pedro que se aquecia, fitou-o e disse: Também tu estavas com o Nazareno, Jesus."},
{v:68,t:"Mas ele negou, dizendo: Não sei nem compreendo o que dizes. E saiu para o vestíbulo; e o galo cantou."},
{v:69,t:"A criada, vendo-o, começou de novo a dizer aos que ali estavam: Este é um deles."},
{v:70,t:"Mas ele negou outra vez. Pouco depois, os que ali estavam disseram de novo a Pedro: Certamente és um deles, pois também és galileu."},
{v:71,t:"Ele, porém, começou a praguejar e a jurar: Não conheço esse homem de quem falais."},
{v:72,t:"E logo o galo cantou pela segunda vez. E Pedro lembrou-se da palavra que Jesus lhe dissera: Antes que o galo cante duas vezes, três vezes me negarás. E começou a chorar."},
{p:"Lucas 22:54-65"},
{v:54,t:"Tendo-o prendido, levaram-no e fizeram-no entrar na casa do sumo sacerdote. Pedro seguia de longe."},
{v:55,t:"Tendo acendido fogo no meio do pátio e sentando-se juntos, Pedro sentou-se no meio deles."},
{v:56,t:"Uma criada, vendo-o sentado junto da fogueira, fitou-o e disse: Este também estava com ele."},
{v:57,t:"Mas ele negou, dizendo: Mulher, não o conheço."},
{v:58,t:"Pouco depois, outro, vendo-o, disse: Tu também és um deles. Mas Pedro disse: Homem, não sou."},
{v:59,t:"Passada cerca de uma hora, outro afirmava com insistência: Certamente este também estava com ele, pois também é galileu."},
{v:60,t:"Mas Pedro disse: Homem, não sei o que dizes. E no mesmo instante, estando ele ainda falando, o galo cantou."},
{v:61,t:"E o Senhor, voltando-se, olhou para Pedro. E Pedro lembrou-se da palavra que o Senhor lhe dissera: Antes que o galo cante hoje, três vezes me negarás.",n:"Só São Lucas conta o olhar. Jesus estava no mesmo pátio, e a negação foi feita à vista dele. O que faz Pedro chorar não é só o galo: é ter sido olhado."},
{v:62,t:"E, saindo para fora, chorou amargamente."},
{v:63,t:"Os homens que guardavam Jesus zombavam dele e espancavam-no;"},
{v:64,t:"e, vendando-lhe os olhos, perguntavam-lhe: Profetiza: quem é que te bateu?"},
{v:65,t:"E diziam muitas outras coisas contra ele, blasfemando."},
{p:"João 18:15-18"},
{v:15,t:"Simão Pedro e outro discípulo seguiam Jesus. Esse discípulo era conhecido do sumo sacerdote, e entrou com Jesus no pátio do sumo sacerdote.",n:"O outro discípulo não é nomeado. A tradição identificou-o com o discípulo amado; é, em todo o caso, a testemunha por quem o quarto evangelho sabe o que se passou lá dentro."},
{v:16,t:"Pedro, porém, ficou fora, junto à porta. Saiu, então, o outro discípulo, que era conhecido do sumo sacerdote, falou à porteira e fez Pedro entrar."},
{v:17,t:"Disse então a Pedro a criada porteira: Não és tu também um dos discípulos deste homem? Ele disse: Não sou.",n:"Não sou é, em grego, ouk eimi — o exato contrário do ego eimi com que Jesus acabara de se entregar no horto. O quarto evangelho põe as duas frases uma diante da outra."},
{v:18,t:"Os servos e os guardas estavam ali e, tendo feito uma fogueira de brasas, porque fazia frio, aqueciam-se; e Pedro estava também com eles, aquecendo-se.",n:"Fogueira de brasas traduz anthrakia, palavra que em todo o Novo Testamento só aparece aqui e no capítulo 21, junto ao lago, onde Jesus ressuscitado perguntará a Pedro três vezes se o ama. As três negações e as três respostas acontecem, ambas, junto de um fogo de brasas."},
{p:"João 18:25-27"},
{v:25,t:"Simão Pedro estava lá, aquecendo-se. Disseram-lhe então: Não és tu também um dos seus discípulos? Ele negou, dizendo: Não sou."},
{v:26,t:"Um dos servos do sumo sacerdote, parente daquele a quem Pedro cortara a orelha, disse: Não te vi eu no horto com ele?"},
{v:27,t:"Pedro negou outra vez. E logo o galo cantou."}
];

EV[187] = [
{p:"Mateus 27:1"},
{v:1,t:"Chegada a manhã, todos os sumos sacerdotes e os anciãos do povo deliberaram contra Jesus, para o condenarem à morte.",n:"A sessão da manhã dá forma legal ao que se decidira de noite. E o sinédrio não podia executar a sentença: por isso a decisão é a de entregá-lo ao governador."},
{p:"Marcos 15:1"},
{v:1,t:"Logo de manhã, os sumos sacerdotes, com os anciãos, os escribas e todo o sinédrio, tomaram uma decisão; e, tendo amarrado Jesus, levaram-no e entregaram-no a Pilatos."},
{p:"Lucas 22:66-71"},
{v:66,t:"Quando amanheceu, reuniu-se o conselho dos anciãos do povo, sumos sacerdotes e escribas, e levaram-no ao seu sinédrio,"},
{v:67,t:"dizendo: Se tu és o Cristo, dize-nos. Ele lhes disse: Se eu vos disser, não crereis;"},
{v:68,t:"e, se vos interrogar, não me respondereis."},
{v:69,t:"Mas, desde agora, o Filho do Homem estará sentado à direita do poder de Deus."},
{v:70,t:"Disseram todos: Tu és, então, o Filho de Deus? Ele lhes disse: Vós dizeis que eu sou.",n:"Vós dizeis que eu sou pode ler-se como vós o dizeis, e eu sou. A construção grega deixa a resposta nas palavras deles, e eles entendem-na como afirmação."},
{v:71,t:"E eles disseram: Que necessidade temos ainda de testemunho? Nós mesmos o ouvimos da sua boca."}
];

EV[188] = [
{p:"Mateus 27:3-10"},
{v:3,t:"Então Judas, que o entregara, vendo que ele fora condenado, tomado de remorso, devolveu as trinta moedas de prata aos sumos sacerdotes e aos anciãos,",n:"Remorso traduz metameletheis, arrepender-se no sentido de lamentar o que se fez; não é a metanoia, a conversão, que o Novo Testamento usa para Pedro e os pecadores que voltam. Judas lamenta, e não volta."},
{v:4,t:"dizendo: Pequei, entregando sangue inocente. Mas eles disseram: Que nos importa? Isso é contigo."},
{v:5,t:"E ele, lançando as moedas no santuário, retirou-se e foi enforcar-se.",n:"Os Atos dos Apóstolos contam a morte de Judas de outra maneira — caiu de cabeça num campo e rebentou. As duas tradições não foram harmonizadas pelos evangelistas, e cada uma liga o campo ao preço do sangue."},
{v:6,t:"Os sumos sacerdotes, tomando as moedas, disseram: Não é lícito lançá-las no tesouro, porque são preço de sangue.",n:"Os mesmos que pagaram para que o sangue fosse derramado têm escrúpulo de pôr o dinheiro no cofre do templo."},
{v:7,t:"E, tendo deliberado, compraram com elas o campo do oleiro, para sepultura dos estrangeiros."},
{v:8,t:"Por isso aquele campo tem sido chamado, até ao dia de hoje, Campo de Sangue."},
{v:9,t:"Cumpriu-se então o que foi dito pelo profeta Jeremias: Tomaram as trinta moedas de prata, preço daquele que foi avaliado, a quem avaliaram os filhos de Israel,",n:"A citação é quase toda de Zacarias 11, onde o profeta recebe trinta moedas e as lança ao oleiro no templo. São Mateus atribui-a a Jeremias, que também fala de um oleiro e da compra de um campo. É dificuldade antiga; a explicação mais provável é que o evangelista fundiu os dois textos e deu o nome do profeta maior."},
{v:10,t:"e deram-nas pelo campo do oleiro, como o Senhor me ordenara."}
];

EV[189] = [
{p:"Mateus 27:2"},
{v:2,t:"E, tendo-o amarrado, levaram-no e entregaram-no ao governador Pilatos.",n:"Pôncio Pilatos foi prefeito da Judeia de 26 a 36. Uma inscrição com o seu nome e título, encontrada em Cesareia em 1961, é o único documento contemporâneo, fora dos evangelhos e dos historiadores, que o menciona."},
{p:"Mateus 27:11-14"},
{v:11,t:"Jesus compareceu diante do governador, e o governador interrogou-o, dizendo: És tu o rei dos judeus? Jesus respondeu: Tu o dizes.",n:"Diante de Pilatos a acusação muda de natureza: já não é blasfêmia, que a Roma não interessava, mas pretensão de ser rei — crime contra César. A pergunta é política, e a resposta devolve-a a quem a fez."},
{v:12,t:"E, sendo acusado pelos sumos sacerdotes e pelos anciãos, nada respondeu."},
{v:13,t:"Disse-lhe então Pilatos: Não ouves quantas coisas testemunham contra ti?"},
{v:14,t:"E ele não lhe respondeu nem uma só palavra, de modo que o governador ficou muito admirado."},
{p:"Marcos 15:2-5"},
{v:2,t:"Pilatos interrogou-o: És tu o rei dos judeus? Ele respondeu-lhe: Tu o dizes."},
{v:3,t:"E os sumos sacerdotes acusavam-no de muitas coisas."},
{v:4,t:"Pilatos interrogou-o de novo, dizendo: Nada respondes? Vê de quantas coisas te acusam."},
{v:5,t:"Mas Jesus não respondeu mais nada, de modo que Pilatos ficou admirado."},
{p:"Lucas 23:1-7"},
{v:1,t:"Levantando-se toda aquela assembleia, levaram-no a Pilatos."},
{v:2,t:"E começaram a acusá-lo, dizendo: Encontramos este homem sublevando a nossa nação, proibindo que se pague o tributo a César e dizendo-se o Cristo, rei.",n:"As três acusações estão formuladas para um governador romano. A segunda é falsa, e o leitor de São Lucas sabe-o: no capítulo 20, Jesus mandara dar a César o que é de César."},
{v:3,t:"Pilatos interrogou-o: És tu o rei dos judeus? Ele respondeu-lhe: Tu o dizes."},
{v:4,t:"Pilatos disse aos sumos sacerdotes e às multidões: Não encontro culpa alguma neste homem.",n:"É a primeira de três declarações de inocência que São Lucas põe na boca de Pilatos. O juiz romano absolve, e é ele quem condena."},
{v:5,t:"Mas eles insistiam, dizendo: Ele agita o povo, ensinando por toda a Judeia, desde a Galileia, onde começou, até aqui."},
{v:6,t:"Ouvindo isso, Pilatos perguntou se o homem era galileu."},
{v:7,t:"E, sabendo que era da jurisdição de Herodes, remeteu-o a Herodes, que também estava em Jerusalém naqueles dias."},
{p:"João 18:28-38"},
{v:28,t:"De Caifás levaram Jesus ao pretório. Era de manhã cedo. Eles não entraram no pretório, para não se contaminarem e poderem comer a Páscoa.",n:"Entrar na casa de um pagão tornava impuro, e impedia de comer a Páscoa nessa tarde. A ironia de São João é seca: guardam-se da impureza enquanto entregam um inocente. E, pelo seu calendário, Jesus morrerá à hora em que se imolam os cordeiros."},
{v:29,t:"Pilatos saiu, pois, ao encontro deles e disse: Que acusação trazeis contra este homem?"},
{v:30,t:"Responderam-lhe: Se ele não fosse malfeitor, não o teríamos entregado a ti."},
{v:31,t:"Disse-lhes então Pilatos: Tomai-o vós e julgai-o segundo a vossa lei. Disseram-lhe os judeus: Não nos é lícito matar ninguém.",n:"Roma reservava ao governador o direito de condenar à morte. Os apedrejamentos que o Novo Testamento conta, como o de Estêvão, foram execuções fora da lei ou em tempos de vacância do cargo."},
{v:32,t:"Era para que se cumprisse a palavra que Jesus dissera, indicando de que morte havia de morrer.",n:"A pena judaica era o apedrejamento; a romana, a cruz. Entregue a Pilatos, Jesus será levantado da terra, como dissera no capítulo 12."},
{v:33,t:"Pilatos entrou de novo no pretório, chamou Jesus e disse-lhe: És tu o rei dos judeus?"},
{v:34,t:"Jesus respondeu: Dizes isso por ti mesmo, ou outros te disseram isso de mim?"},
{v:35,t:"Respondeu Pilatos: Porventura sou eu judeu? A tua nação e os sumos sacerdotes entregaram-te a mim. Que fizeste?"},
{v:36,t:"Jesus respondeu: O meu Reino não é deste mundo. Se o meu Reino fosse deste mundo, os meus servidores teriam lutado para que eu não fosse entregue aos judeus; mas o meu Reino não é daqui.",n:"Não é deste mundo diz a origem do Reino, e não o lugar onde ele se exerce: não nasce da força, e por isso ninguém lutou para o defender. Não diz que não tenha que ver com o mundo."},
{v:37,t:"Disse-lhe então Pilatos: Logo, tu és rei? Jesus respondeu: Tu dizes que eu sou rei. Para isso nasci e para isso vim ao mundo: para dar testemunho da verdade. Todo o que é da verdade ouve a minha voz."},
{v:38,t:"Disse-lhe Pilatos: Que é a verdade? E, tendo dito isso, saiu de novo ao encontro dos judeus e disse-lhes: Não encontro nele culpa alguma.",n:"Pilatos faz a pergunta diante daquele que dissera eu sou a verdade, e não espera pela resposta: sai. A pergunta mais célebre do quarto evangelho fica sem resposta porque quem a faz não a quer ouvir."}
];

EV[190] = [
{p:"Lucas 23:8-12"},
{v:8,t:"Herodes, ao ver Jesus, ficou muito contente; porque havia muito tempo desejava vê-lo, por ter ouvido falar dele, e esperava vê-lo fazer algum sinal.",n:"É Herodes Antipas, o que mandou degolar João Batista e a quem Jesus chamara raposa. São Lucas anotara, no capítulo 9, que ele procurava vê-lo. Agora vê-o — e quer um espetáculo."},
{v:9,t:"Fez-lhe muitas perguntas; mas Jesus nada lhe respondeu.",n:"É a única pessoa, em toda a Paixão, a quem Jesus não diz uma única palavra. Respondeu ao sumo sacerdote e a Pilatos; ao homem que matou o profeta e só quer ver prodígios, não."},
{v:10,t:"Os sumos sacerdotes e os escribas estavam ali, acusando-o com veemência."},
{v:11,t:"Herodes, com os seus soldados, tratou-o com desprezo e escarneceu dele; e, vestindo-o com uma veste esplêndida, mandou-o de volta a Pilatos."},
{v:12,t:"Naquele dia, Herodes e Pilatos tornaram-se amigos, pois antes eram inimigos um do outro.",n:"Os dois poderes que se detestavam fazem as pazes por causa dele. Os Atos dos Apóstolos hão de citar, a propósito deste dia, o Salmo 2: os reis da terra levantaram-se e os príncipes aliaram-se contra o Senhor e contra o seu Cristo."}
];

EV[191] = [
{p:"Mateus 27:15-30"},
{v:15,t:"Por ocasião da festa, o governador costumava soltar ao povo um preso, aquele que quisessem."},
{v:16,t:"Tinham então um preso famoso, chamado Barrabás.",n:"Barrabás é o aramaico bar Abbá, filho do pai. Alguns manuscritos de São Mateus o chamam Jesus Barrabás, e a Nova Vulgata não segue essa leitura; se for original, a pergunta de Pilatos opunha dois homens chamados Jesus — o filho do pai e aquele que chamava Deus de Pai."},
{v:17,t:"Estando, pois, reunidos, Pilatos perguntou-lhes: Qual quereis que vos solte: Barrabás, ou Jesus, chamado Cristo?"},
{v:18,t:"Pois sabia que por inveja o tinham entregado."},
{v:19,t:"Enquanto estava sentado no tribunal, a sua mulher mandou dizer-lhe: Não te envolvas com esse justo, porque hoje sofri muito em sonho por causa dele.",n:"Só São Mateus conta a mensagem da mulher de Pilatos. É uma pagã, e é avisada em sonho, como os magos do princípio do mesmo evangelho: nos dois extremos da vida de Jesus, os estrangeiros veem o que os de casa não veem."},
{v:20,t:"Mas os sumos sacerdotes e os anciãos persuadiram as multidões a que pedissem Barrabás e fizessem morrer Jesus."},
{v:21,t:"O governador, tomando a palavra, disse-lhes: Qual dos dois quereis que vos solte? Eles responderam: Barrabás."},
{v:22,t:"Disse-lhes Pilatos: Que farei, então, de Jesus, chamado Cristo? Responderam todos: Seja crucificado!"},
{v:23,t:"Ele disse: Mas que mal fez ele? Eles, porém, gritavam ainda mais: Seja crucificado!"},
{v:24,t:"Vendo Pilatos que nada conseguia, mas que, pelo contrário, o tumulto aumentava, tomou água e lavou as mãos diante da multidão, dizendo: Sou inocente do sangue deste justo; isso é convosco.",n:"Lavar as mãos era o rito que o Deuteronômio prescrevia aos anciãos de uma cidade, para se declararem inocentes de um sangue derramado sem culpado conhecido. Pilatos usa o gesto judaico para declarar-se inocente do que ele mesmo vai ordenar."},
{v:25,t:"E todo o povo respondeu: O seu sangue caia sobre nós e sobre os nossos filhos!",n:"Nota do tradutor: nenhum versículo da Escritura foi mais usado contra o povo judeu do que este, e durante mais tempo. Traduz-se como está, e registra-se o que a Igreja declarou no Concílio Vaticano II: a morte de Cristo não pode ser imputada indistintamente a todos os judeus que então viviam, nem aos judeus de hoje. E acrescenta-se o que o próprio São Mateus escreveu dois capítulos antes: o sangue de Jesus é o sangue da aliança, derramado por muitos para remissão dos pecados. No evangelho que conta esta frase, o sangue que cai sobre alguém cai como perdão."},
{v:26,t:"Então soltou-lhes Barrabás; e, depois de mandar açoitar Jesus, entregou-o para ser crucificado.",n:"O açoite romano fazia-se com o flagrum, correias com pedaços de osso e de metal, e precedia a crucifixão. Não havia limite de golpes, ao contrário da lei judaica, que os limitava a quarenta, e muitos morriam dele."},
{v:27,t:"Então os soldados do governador levaram Jesus ao pretório e reuniram em torno dele toda a coorte."},
{v:28,t:"Despojaram-no das vestes e cobriram-no com um manto escarlate;"},
{v:29,t:"e, tecendo uma coroa de espinhos, puseram-na na sua cabeça, e uma cana na mão direita; e, ajoelhando-se diante dele, zombavam dele, dizendo: Salve, rei dos judeus!",n:"A cena é a paródia de uma investidura: o manto vermelho dos oficiais em lugar da púrpura imperial, a coroa de espinhos em lugar da de louros, a cana em lugar do cetro; e a saudação imita a que se dirigia ao imperador: ave, Caesar. Zombam do rei, e é rei o que dizem."},
{v:30,t:"E, cuspindo nele, tomavam a cana e batiam-lhe na cabeça."},
{p:"Marcos 15:6-19"},
{v:6,t:"Por ocasião da festa, costumava soltar-lhes um preso, aquele que pedissem."},
{v:7,t:"Havia um, chamado Barrabás, preso com os sediciosos que, numa revolta, tinham cometido um homicídio."},
{v:8,t:"A multidão, tendo subido, começou a pedir que fizesse como sempre lhes fazia."},
{v:9,t:"Pilatos respondeu-lhes: Quereis que vos solte o rei dos judeus?"},
{v:10,t:"Pois sabia que os sumos sacerdotes o tinham entregado por inveja."},
{v:11,t:"Mas os sumos sacerdotes incitaram a multidão a que lhes soltasse antes Barrabás."},
{v:12,t:"Pilatos, tomando de novo a palavra, disse-lhes: Que quereis, então, que eu faça daquele a quem chamais rei dos judeus?"},
{v:13,t:"Eles gritaram de novo: Crucifica-o!"},
{v:14,t:"Pilatos disse-lhes: Mas que mal fez ele? Eles, porém, gritavam ainda mais: Crucifica-o!"},
{v:15,t:"Pilatos, querendo satisfazer a multidão, soltou-lhes Barrabás; e, depois de mandar açoitar Jesus, entregou-o para ser crucificado."},
{v:16,t:"Os soldados levaram-no para dentro do pátio, isto é, do pretório, e convocaram toda a coorte."},
{v:17,t:"Vestiram-no de púrpura e, tecendo uma coroa de espinhos, puseram-na na sua cabeça."},
{v:18,t:"E começaram a saudá-lo: Salve, rei dos judeus!"},
{v:19,t:"E batiam-lhe na cabeça com uma cana, cuspiam nele e, pondo-se de joelhos, prostravam-se diante dele."},
{p:"Lucas 23:13-25"},
{v:13,t:"Pilatos, tendo convocado os sumos sacerdotes, os chefes e o povo,"},
{v:14,t:"disse-lhes: Apresentastes-me este homem como quem desencaminha o povo; e eis que, tendo-o interrogado diante de vós, não encontrei neste homem nenhuma culpa das de que o acusais;"},
{v:15,t:"nem tampouco Herodes, pois o mandou de volta para nós. Eis que nada fez que mereça a morte."},
{v:16,t:"Portanto, depois de o castigar, vou soltá-lo.",n:"Castigar é aqui o açoite, que Pilatos propõe como pena menor, em troca da vida. Alguns manuscritos acrescentam um versículo 17, sobre o costume de soltar um preso na festa, tirado de Mateus e Marcos; falta nos mais antigos, e a Nova Vulgata omite-o."},
{v:18,t:"Mas eles gritaram todos juntos: Tira-o daqui e solta-nos Barrabás!"},
{v:19,t:"Este fora lançado na prisão por uma sedição acontecida na cidade e por um homicídio."},
{v:20,t:"Pilatos falou-lhes de novo, querendo soltar Jesus."},
{v:21,t:"Mas eles gritavam: Crucifica-o, crucifica-o!"},
{v:22,t:"E ele disse-lhes pela terceira vez: Mas que mal fez este? Não encontrei nele nenhuma culpa que mereça a morte. Portanto, depois de o castigar, vou soltá-lo."},
{v:23,t:"Mas eles insistiam em altos brados, pedindo que fosse crucificado; e os seus gritos prevaleciam."},
{v:24,t:"Então Pilatos decidiu que se fizesse o que pediam."},
{v:25,t:"Soltou o que fora lançado na prisão por sedição e homicídio, a quem eles pediam; e entregou Jesus à vontade deles.",n:"São Lucas insiste no contraste: solta-se o culpado de sedição, que era a acusação feita a Jesus, e condena-se o inocente. É a primeira pessoa que a morte de Jesus salva, e é um assassino."},
{p:"João 18:39-40"},
{v:39,t:"Mas é costume entre vós que eu vos solte alguém pela Páscoa. Quereis, pois, que vos solte o rei dos judeus?"},
{v:40,t:"Então gritaram de novo, dizendo: Este não, mas Barrabás! Ora, Barrabás era um salteador.",n:"Salteador traduz lestes, a palavra com que o historiador Josefo designa os guerrilheiros que lutavam contra Roma. O povo prefere o rebelde de armas na mão ao rei que dissera que o seu Reino não é deste mundo."},
{p:"João 19:1-16"},
{v:1,t:"Então Pilatos tomou Jesus e mandou açoitá-lo."},
{v:2,t:"E os soldados, tecendo uma coroa de espinhos, puseram-na na sua cabeça e vestiram-no com um manto de púrpura;"},
{v:3,t:"e aproximavam-se dele e diziam: Salve, rei dos judeus! E davam-lhe bofetadas."},
{v:4,t:"Pilatos saiu de novo e disse-lhes: Eis que o trago para fora, para que saibais que não encontro nele culpa alguma."},
{v:5,t:"Saiu, pois, Jesus, trazendo a coroa de espinhos e o manto de púrpura. E Pilatos disse-lhes: Eis o homem!",n:"Ecce homo. Pilatos diz a frase para inspirar pena, mostrando um homem desfeito; o evangelista lê nela muito mais. Eis o homem: o homem como Deus o fez, e como os homens o deixaram."},
{v:6,t:"Quando os sumos sacerdotes e os guardas o viram, gritaram: Crucifica-o, crucifica-o! Disse-lhes Pilatos: Tomai-o vós e crucificai-o, porque eu não encontro nele culpa."},
{v:7,t:"Responderam-lhe os judeus: Nós temos uma lei, e segundo essa lei ele deve morrer, porque se fez Filho de Deus."},
{v:8,t:"Quando Pilatos ouviu estas palavras, teve ainda mais medo."},
{v:9,t:"E, entrando outra vez no pretório, disse a Jesus: Donde és tu? Mas Jesus não lhe deu resposta.",n:"Donde és tu é a pergunta que atravessa todo o quarto evangelho, e que as multidões e os fariseus fizeram de muitas maneiras. Pilatos faz, sem o saber, a pergunta certa, e Jesus não lhe responde."},
{v:10,t:"Disse-lhe, então, Pilatos: Não me falas? Não sabes que tenho poder para te soltar e poder para te crucificar?"},
{v:11,t:"Respondeu Jesus: Não terias nenhum poder sobre mim, se não te fosse dado do alto; por isso, quem me entregou a ti tem maior pecado."},
{v:12,t:"Desde então Pilatos procurava soltá-lo; mas os judeus gritavam: Se soltas este, não és amigo de César; todo aquele que se faz rei se opõe a César.",n:"Amigo de César era título oficial, dado aos que gozavam da confiança do imperador. A ameaça é concreta: uma denúncia em Roma. É ela, e não a convicção, que decide Pilatos."},
{v:13,t:"Ouvindo estas palavras, Pilatos trouxe Jesus para fora e sentou-se no tribunal, no lugar chamado Litóstroto, em hebraico Gábata.",n:"O grego pode ler-se também fez sentar: Pilatos teria sentado Jesus no tribunal, como rei de zombaria. Alguns autores antigos leram assim, e a ambiguidade é talvez intencional: é Jesus quem está julgando. Litóstroto quer dizer pavimento de pedra."},
{v:14,t:"Era a preparação da Páscoa, cerca da hora sexta. E disse aos judeus: Eis o vosso rei!",n:"A hora sexta é o meio-dia da véspera da Páscoa: pouco depois, no templo, começava a imolação dos cordeiros. Pelo calendário de São João, a sentença e a morte coincidem com o sacrifício pascal."},
{v:15,t:"Mas eles gritaram: Fora! Fora! Crucifica-o! Disse-lhes Pilatos: Hei de crucificar o vosso rei? Responderam os sumos sacerdotes: Não temos rei senão César.",n:"Israel confessava na sua oração que não tinha outro rei senão Deus. Na véspera da festa, os sumos sacerdotes declaram, diante de um pagão, que não têm rei senão César."},
{v:16,t:"Então entregou-o a eles para ser crucificado. E eles tomaram Jesus."}
];

EV[192] = [
{p:"Mateus 27:31-56"},
{v:31,t:"Depois de o terem escarnecido, tiraram-lhe o manto, vestiram-no com as suas vestes e levaram-no para ser crucificado."},
{v:32,t:"Ao saírem, encontraram um homem de Cirene, chamado Simão, e obrigaram-no a carregar a cruz de Jesus.",n:"Cirene ficava na costa da atual Líbia e tinha uma grande comunidade judaica. O condenado carregava a trave horizontal da cruz, o patibulum; o poste ficava fincado no lugar da execução."},
{v:33,t:"E, chegando ao lugar chamado Gólgota, que quer dizer Lugar da Caveira,"},
{v:34,t:"deram-lhe a beber vinho misturado com fel; ele o provou, mas não quis beber.",n:"É o versículo 22 do Salmo 69, já traduzido aqui: puseram fel na minha comida. São Mateus conta a cena com as palavras do salmo."},
{v:35,t:"Depois de o crucificarem, repartiram entre si as suas vestes, tirando a sorte.",n:"A roupa do condenado pertencia aos executores. O evangelista não descreve a crucifixão: diz o fato numa oração subordinada, como quem não consegue dizer mais."},
{v:36,t:"E, sentados, montavam guarda ali."},
{v:37,t:"Puseram acima da sua cabeça a causa da sua condenação, escrita: Este é Jesus, o rei dos judeus."},
{v:38,t:"Foram crucificados com ele dois salteadores, um à direita e outro à esquerda."},
{v:39,t:"Os que passavam blasfemavam contra ele, meneando a cabeça",n:"Menear a cabeça é o gesto do Salmo 22, versículo 8: todos os que me veem zombam de mim, meneiam a cabeça. Todo o relato da cruz em São Mateus e São Marcos é tecido com este salmo."},
{v:40,t:"e dizendo: Tu, que destróis o santuário e em três dias o reedificas, salva-te a ti mesmo! Se és Filho de Deus, desce da cruz!",n:"Se és Filho de Deus é, palavra por palavra, a tentação do deserto. A última tentação é a mesma que a primeira."},
{v:41,t:"Do mesmo modo, também os sumos sacerdotes, com os escribas e os anciãos, zombando, diziam:"},
{v:42,t:"Salvou os outros, e a si mesmo não pode salvar! É rei de Israel: desça agora da cruz, e creremos nele!"},
{v:43,t:"Confiou em Deus: que o livre agora, se o quer bem; pois disse: Sou Filho de Deus.",n:"Os sumos sacerdotes citam, sem o perceber, o versículo 9 do Salmo 22: confiou no Senhor; que ele o livre. Zombam com as palavras do salmo que Jesus vai rezar."},
{v:44,t:"E também os salteadores que foram crucificados com ele o insultavam da mesma maneira."},
{v:45,t:"Desde a hora sexta até à hora nona, houve trevas sobre toda a terra.",n:"Do meio-dia às três da tarde. O profeta Amós anunciara o dia do Senhor assim: farei pôr-se o sol ao meio-dia e escurecerei a terra em pleno dia."},
{v:46,t:"Por volta da hora nona, Jesus clamou em alta voz: Eli, Eli, lemá sabactâni?, isto é: Meu Deus, meu Deus, por que me abandonaste?",n:"Nota do tradutor: são as palavras com que começa o Salmo 22, ditas em aramaico, a língua de Jesus. Não se atenua o grito: é real o abandono que ele diz. Mas quem reza as primeiras palavras de um salmo reza o salmo inteiro — era o costume judaico citar um texto pelo começo —, e o Salmo 22, já traduzido aqui, termina em ação de graças e no anúncio de que todos os confins da terra hão de voltar ao Senhor. O grito é de quem se sente abandonado, e é dirigido a Deus: meu Deus."},
{v:47,t:"Alguns dos que ali estavam, ouvindo isso, diziam: Ele chama Elias.",n:"Eli soa como Elias. Corria a crença de que Elias viria socorrer os justos na hora da aflição."},
{v:48,t:"E logo um deles correu, tomou uma esponja, embebeu-a em vinagre e, pondo-a numa cana, dava-lhe de beber.",n:"O vinagre, posca em latim, era o vinho azedo misturado com água que os soldados bebiam. O gesto pode ter sido de compaixão; o evangelista lê nele o Salmo 69: na minha sede, deram-me vinagre a beber."},
{v:49,t:"Os outros, porém, diziam: Deixa; vejamos se Elias vem salvá-lo."},
{v:50,t:"E Jesus, clamando de novo em alta voz, entregou o espírito.",n:"No momento da morte, nenhum evangelista usa o verbo morrer: dizem entregou o espírito, expirou. Os crucificados morriam de esgotamento, geralmente sem forças para gritar: o grande brado final impressionou quem o ouviu."},
{v:51,t:"E eis que o véu do santuário se rasgou em duas partes, de alto a baixo; a terra tremeu, e as rochas fenderam-se;",n:"O véu separava o Santo dos Santos, onde só o sumo sacerdote entrava, uma vez por ano. Rasga-se de alto a baixo — de cima, portanto, da parte de Deus. A Carta aos Hebreus lê o sinal: está aberto o caminho para o santuário."},
{v:52,t:"os sepulcros abriram-se, e muitos corpos de santos que tinham adormecido ressuscitaram;",n:"Os versículos 52 e 53 só existem em São Mateus e são dos mais enigmáticos dos evangelhos. Usam as imagens de Ezequiel 37 — abrirei os vossos sepulcros — e dizem, em forma de relato, que a morte de Jesus é o princípio da ressurreição dos mortos."},
{v:53,t:"e, saindo dos sepulcros depois da ressurreição dele, entraram na cidade santa e apareceram a muitos."},
{v:54,t:"O centurião e os que com ele guardavam Jesus, vendo o terremoto e o que acontecia, ficaram com muito medo e disseram: Verdadeiramente este era Filho de Deus!"},
{v:55,t:"Estavam ali, olhando de longe, muitas mulheres que tinham seguido Jesus desde a Galileia, servindo-o;",n:"Os discípulos fugiram; as mulheres ficaram. São elas as testemunhas da morte, da sepultura e do sepulcro vazio — num tempo em que o testemunho de uma mulher não valia em tribunal."},
{v:56,t:"entre elas estavam Maria Madalena, Maria, mãe de Tiago e de José, e a mãe dos filhos de Zebedeu."},
{p:"Marcos 15:20-41"},
{v:20,t:"Depois de o terem escarnecido, tiraram-lhe a púrpura e vestiram-no com as suas vestes. E levaram-no para fora, para o crucificarem."},
{v:21,t:"Obrigaram um que passava, Simão de Cirene, que vinha do campo, pai de Alexandre e de Rufo, a carregar a cruz dele.",n:"São Marcos dá os nomes dos filhos de Simão porque os seus leitores os conheciam. Na Carta aos Romanos, São Paulo saúda um Rufo — talvez o mesmo."},
{v:22,t:"E levaram-no ao lugar do Gólgota, que quer dizer Lugar da Caveira."},
{v:23,t:"E deram-lhe vinho misturado com mirra; mas ele não o tomou.",n:"O vinho com mirra devia servir de narcótico. O Talmude conta que as mulheres piedosas de Jerusalém ofereciam aos condenados uma bebida assim, lembrando o livro dos Provérbios: dai bebida forte a quem vai morrer. Jesus recusa-o: bebe o cálice acordado."},
{v:24,t:"E crucificaram-no, e repartiram as suas vestes, tirando a sorte sobre elas, para ver o que cada um levaria."},
{v:25,t:"Era a hora terceira quando o crucificaram.",n:"A hora terceira são nove da manhã. São João põe a sentença ao meio-dia; a diferença é conhecida desde a antiguidade e tem recebido explicações diversas, nenhuma inteiramente pacífica."},
{v:26,t:"E a inscrição da sua culpa dizia: O rei dos judeus."},
{v:27,t:"Com ele crucificaram dois salteadores, um à sua direita e outro à esquerda.",n:"Alguns manuscritos acrescentam um versículo 28: e cumpriu-se a Escritura que diz: foi contado entre os malfeitores — trazido de São Lucas. Falta nos mais antigos, e a Nova Vulgata omite-o; a numeração salta do 27 ao 29."},
{v:29,t:"Os que passavam blasfemavam contra ele, meneando a cabeça e dizendo: Ah! Tu, que destróis o santuário e o reedificas em três dias,"},
{v:30,t:"salva-te a ti mesmo, descendo da cruz!"},
{v:31,t:"Do mesmo modo, também os sumos sacerdotes, com os escribas, zombando entre si, diziam: Salvou os outros, e a si mesmo não pode salvar!"},
{v:32,t:"O Cristo, o rei de Israel, desça agora da cruz, para que vejamos e creiamos! E também os que foram crucificados com ele o injuriavam."},
{v:33,t:"Chegada a hora sexta, houve trevas sobre toda a terra até à hora nona."},
{v:34,t:"E, à hora nona, Jesus clamou em alta voz: Eloí, Eloí, lemá sabactâni?, que quer dizer: Meu Deus, meu Deus, por que me abandonaste?",n:"Eloí é a forma aramaica; São Mateus escreve Eli, mais próxima do hebraico do salmo. São Marcos conserva a língua em que a frase foi gritada, e traduz."},
{v:35,t:"Alguns dos que ali estavam, ouvindo isso, diziam: Eis que chama Elias."},
{v:36,t:"E um deles correu, embebeu uma esponja em vinagre e, pondo-a numa cana, dava-lhe de beber, dizendo: Deixai; vejamos se Elias vem tirá-lo daí."},
{v:37,t:"Mas Jesus, dando um grande brado, expirou."},
{v:38,t:"E o véu do santuário rasgou-se em dois, de alto a baixo.",n:"Rasgou-se traduz eschisthe, o mesmo verbo que São Marcos usou no batismo, quando os céus se rasgaram e se ouviu a voz: tu és o meu Filho. O evangelho abre e fecha com um rasgão e com a mesma confissão."},
{v:39,t:"O centurião, que estava diante dele, vendo que assim tinha expirado, disse: Verdadeiramente este homem era Filho de Deus!",n:"É o ponto de chegada de todo o evangelho de São Marcos, que começara: princípio do Evangelho de Jesus Cristo, Filho de Deus. O primeiro ser humano do livro a confessá-lo é um pagão, oficial do exército que o executou, e o faz ao vê-lo morrer."},
{v:40,t:"Estavam também ali algumas mulheres, olhando de longe; entre elas, Maria Madalena, Maria, mãe de Tiago, o Menor, e de José, e Salomé,"},
{v:41,t:"as quais, quando ele estava na Galileia, o seguiam e o serviam; e muitas outras, que tinham subido com ele a Jerusalém."},
{p:"Lucas 23:26-49"},
{v:26,t:"Quando o levavam, tomaram um certo Simão de Cirene, que vinha do campo, e puseram-lhe a cruz às costas, para que a levasse atrás de Jesus.",n:"Atrás de Jesus: São Lucas faz de Simão, sem o dizer, a figura do discípulo — o que toma a cruz e segue."},
{v:27,t:"Seguia-o uma grande multidão do povo e de mulheres, que batiam no peito e se lamentavam por ele."},
{v:28,t:"Mas Jesus, voltando-se para elas, disse: Filhas de Jerusalém, não choreis por mim; chorai antes por vós mesmas e por vossos filhos."},
{v:29,t:"Porque eis que virão dias em que se dirá: Felizes as estéreis, os ventres que não geraram e os peitos que não amamentaram!"},
{v:30,t:"Então começarão a dizer aos montes: Caí sobre nós!, e às colinas: Cobri-nos!"},
{v:31,t:"Porque, se fazem isto ao lenho verde, que acontecerá ao seco?",n:"Provérbio: se o fogo consome a madeira verde, que é difícil de queimar, que não fará com a seca? Se isto se faz ao inocente, o que virá sobre a cidade culpada."},
{v:32,t:"Eram levados também dois malfeitores, para serem executados com ele."},
{v:33,t:"Quando chegaram ao lugar chamado Caveira, ali o crucificaram, e aos malfeitores, um à direita e outro à esquerda."},
{v:34,t:"E Jesus dizia: Pai, perdoa-lhes, porque não sabem o que fazem. E, repartindo as suas vestes, tiraram a sorte.",n:"A primeira frase falta em alguns manuscritos antigos importantes, mas está em outros igualmente antigos, e os Padres a conhecem desde o século II. A Nova Vulgata conserva-a. Santo Estêvão, nos Atos, morrerá com a mesma oração."},
{v:35,t:"O povo estava ali, olhando; e os chefes escarneciam dele, dizendo: Salvou os outros; salve-se a si mesmo, se é o Cristo de Deus, o eleito!"},
{v:36,t:"Também os soldados zombavam dele, aproximando-se para lhe oferecer vinagre"},
{v:37,t:"e dizendo: Se és o rei dos judeus, salva-te a ti mesmo!"},
{v:38,t:"Havia também acima dele uma inscrição: Este é o rei dos judeus."},
{v:39,t:"Um dos malfeitores que estavam suspensos insultava-o, dizendo: Não és tu o Cristo? Salva-te a ti mesmo e a nós!"},
{v:40,t:"Mas o outro, repreendendo-o, dizia: Nem sequer temes a Deus, estando na mesma condenação?"},
{v:41,t:"Nós, na verdade, com justiça, pois recebemos o que merecem os nossos atos; mas este nada fez de mal."},
{v:42,t:"E dizia: Jesus, lembra-te de mim, quando entrares no teu Reino.",n:"É a única pessoa, em todos os evangelhos, que o chama simplesmente pelo nome, sem título nenhum. E é também o único que, na cruz, vê nele um rei."},
{v:43,t:"E ele lhe disse: Em verdade te digo: hoje estarás comigo no paraíso.",n:"Paraíso é palavra de origem persa, que queria dizer jardim murado, e que a versão grega usou para o jardim do Éden. Hoje é a palavra de São Lucas, que já se notou em Zaqueu. O primeiro a entrar no Reino é um condenado."},
{v:44,t:"Era já cerca da hora sexta, e houve trevas sobre toda a terra até à hora nona,"},
{v:45,t:"tendo o sol escurecido; e o véu do santuário rasgou-se ao meio."},
{v:46,t:"E Jesus, clamando em alta voz, disse: Pai, nas tuas mãos entrego o meu espírito. E, dito isso, expirou.",n:"É o versículo 6 do Salmo 31, já traduzido aqui, que a tradição judaica reza antes de dormir. Jesus acrescenta-lhe uma palavra: Pai. Em São Lucas, as últimas palavras não são o grito do abandono, mas a oração da noite."},
{v:47,t:"O centurião, vendo o que acontecera, deu glória a Deus, dizendo: Verdadeiramente este homem era justo."},
{v:48,t:"E todas as multidões que tinham acorrido a este espetáculo, vendo o que acontecera, voltavam batendo no peito."},
{v:49,t:"Todos os seus conhecidos, e as mulheres que o tinham seguido desde a Galileia, estavam de longe, olhando estas coisas."},
{p:"João 19:17-37"},
{v:17,t:"E ele, carregando a sua cruz, saiu para o lugar chamado da Caveira, que em hebraico se diz Gólgota,",n:"São João não fala de Simão de Cirene: carregando a sua cruz. No quarto evangelho, Jesus vai à morte como quem cumpre uma obra, sem que ninguém o ajude a levá-la."},
{v:18,t:"onde o crucificaram, e com ele outros dois, um de cada lado, e Jesus no meio."},
{v:19,t:"Pilatos escreveu também uma inscrição e colocou-a sobre a cruz. Estava escrito: Jesus, o Nazareno, o rei dos judeus.",n:"Em latim, Iesus Nazarenus Rex Iudaeorum: as iniciais INRI, que a arte cristã pôs no alto de todas as cruzes."},
{v:20,t:"Muitos dos judeus leram esta inscrição, porque o lugar onde Jesus foi crucificado ficava perto da cidade; e estava escrita em hebraico, em latim e em grego.",n:"As três línguas do mundo de então: a da religião, a do poder e a da cultura. Sem querer, Pilatos proclama o rei a todo o mundo conhecido."},
{v:21,t:"Diziam, pois, a Pilatos os sumos sacerdotes dos judeus: Não escrevas: O rei dos judeus; mas que ele disse: Eu sou o rei dos judeus."},
{v:22,t:"Respondeu Pilatos: O que escrevi, escrevi."},
{v:23,t:"Os soldados, depois de crucificarem Jesus, tomaram as suas vestes e fizeram quatro partes, uma para cada soldado; e também a túnica. A túnica era sem costura, tecida de alto a baixo numa só peça.",n:"Uma túnica tecida de uma só peça era, segundo Josefo, a veste do sumo sacerdote. Os Padres viram nela a unidade da Igreja, que nem os soldados quiseram rasgar."},
{v:24,t:"Disseram, pois, entre si: Não a rasguemos, mas tiremos a sorte para ver de quem será. Era para que se cumprisse a Escritura: Repartiram entre si as minhas vestes e sobre a minha túnica lançaram sorte. E assim fizeram os soldados.",n:"É o versículo 19 do Salmo 22, já traduzido aqui."},
{v:25,t:"Junto à cruz de Jesus estavam de pé sua mãe, a irmã de sua mãe, Maria, mulher de Clopas, e Maria Madalena."},
{v:26,t:"Vendo Jesus sua mãe e, junto dela, o discípulo que amava, disse à sua mãe: Mulher, eis o teu filho.",n:"Mulher é como Jesus a chamara em Caná, quando lhe disse que a sua hora ainda não tinha chegado. A hora chegou, e ele volta a chamá-la assim. A tradição viu no discípulo amado todos os discípulos, confiados a ela."},
{v:27,t:"Depois disse ao discípulo: Eis a tua mãe. E, desde aquela hora, o discípulo recebeu-a em sua casa."},
{v:28,t:"Depois disso, sabendo Jesus que tudo estava consumado, para que se cumprisse a Escritura, disse: Tenho sede.",n:"Aquele que prometera à samaritana a água que mata a sede para sempre tem sede. A Escritura que se cumpre é o Salmo 69, e talvez também o 22: a minha força secou como um caco, e a língua se colou ao paladar."},
{v:29,t:"Estava ali um vaso cheio de vinagre. Puseram, pois, numa vara de hissopo uma esponja embebida em vinagre e levaram-na à sua boca.",n:"O hissopo é a planta com que, no Êxodo, os israelitas marcaram com o sangue do cordeiro pascal os batentes das portas. O detalhe, improvável como vara, é escolhido pelo que significa."},
{v:30,t:"Quando Jesus tomou o vinagre, disse: Está consumado. E, inclinando a cabeça, entregou o espírito.",n:"Está consumado é tetelestai, da mesma raiz que o até ao fim com que começou a ceia: amou-os até ao fim. Não é o grito de quem acaba, mas de quem conclui. E entregou o espírito pode ler-se também transmitiu o Espírito: São João gosta dos dois sentidos."},
{v:31,t:"Como era a preparação, para que os corpos não ficassem na cruz durante o sábado — pois aquele sábado era um dia solene —, os judeus pediram a Pilatos que lhes quebrassem as pernas e fossem retirados.",n:"O Deuteronômio mandava que o corpo de um executado não ficasse suspenso durante a noite. Quebravam-se as pernas dos crucificados para apressar a morte: sem apoio nos pés, não conseguiam erguer-se para respirar."},
{v:32,t:"Vieram, pois, os soldados e quebraram as pernas do primeiro e do outro que tinham sido crucificados com ele."},
{v:33,t:"Chegando, porém, a Jesus, e vendo que já estava morto, não lhe quebraram as pernas;"},
{v:34,t:"mas um dos soldados abriu-lhe o lado com uma lança, e logo saiu sangue e água.",n:"Os Padres viram no sangue e na água os sacramentos da Eucaristia e do batismo, e no lado aberto o nascimento da Igreja, como Eva nasceu do lado de Adão adormecido. O evangelista, no versículo seguinte, sublinha que viu."},
{v:35,t:"Aquele que viu dá testemunho, e o seu testemunho é verdadeiro; e ele sabe que diz a verdade, para que também vós creiais."},
{v:36,t:"Porque estas coisas aconteceram para que se cumprisse a Escritura: Nenhum dos seus ossos será quebrado.",n:"É a regra do Êxodo para o cordeiro pascal, do qual não se devia quebrar nenhum osso; e é também o versículo 21 do Salmo 34, já traduzido aqui. No quarto evangelho, Jesus morre como o cordeiro da Páscoa."},
{v:37,t:"E outra Escritura diz ainda: Hão de olhar para aquele que traspassaram.",n:"É Zacarias 12, versículo 10, que continua: e chorarão por ele como se chora por um filho único. O Apocalipse retoma a frase no seu primeiro capítulo."}
];

EV[193] = [
{p:"Mateus 27:57-61"},
{v:57,t:"Ao cair da tarde, veio um homem rico de Arimateia, chamado José, que também era discípulo de Jesus.",n:"Arimateia é provavelmente Ramataim, a terra de Samuel, a noroeste de Jerusalém. Só os ricos tinham sepulcros escavados na rocha; e o profeta Isaías dissera do servo sofredor que teria a sepultura com os ímpios e, na sua morte, estaria com o rico."},
{v:58,t:"Este foi ter com Pilatos e pediu o corpo de Jesus. Então Pilatos mandou que o entregassem."},
{v:59,t:"José tomou o corpo, envolveu-o num lençol de linho limpo"},
{v:60,t:"e colocou-o no seu sepulcro novo, que tinha escavado na rocha; e, depois de rolar uma grande pedra para a entrada do sepulcro, retirou-se."},
{v:61,t:"Estavam ali Maria Madalena e a outra Maria, sentadas diante do sepulcro."},
{p:"Marcos 15:42-47"},
{v:42,t:"Chegada já a tarde, como era a preparação, isto é, a véspera do sábado,",n:"Preparação, parasceve, era o nome da sexta-feira, o dia em que se preparava tudo para o sábado, em que não se podia trabalhar. O sábado começava ao pôr do sol: havia pouco tempo para sepultar."},
{v:43,t:"veio José de Arimateia, membro respeitado do Conselho, que também esperava o Reino de Deus, e teve a ousadia de ir ter com Pilatos e pedir o corpo de Jesus.",n:"Pedir o corpo de um executado por crime contra Roma era declarar-se do lado dele. Os corpos dos crucificados ficavam muitas vezes na cruz, ou iam para a vala comum."},
{v:44,t:"Pilatos admirou-se de que já tivesse morrido; e, chamando o centurião, perguntou-lhe se já estava morto.",n:"Um crucificado podia agonizar durante dias. A pergunta de Pilatos e a resposta do centurião, homem que sabia reconhecer um morto, são também um testemunho: Jesus morreu de fato."},
{v:45,t:"E, informado pelo centurião, cedeu o corpo a José."},
{v:46,t:"Este, tendo comprado um lençol de linho, desceu-o da cruz, envolveu-o no lençol e colocou-o num sepulcro escavado na rocha; e rolou uma pedra para a entrada do sepulcro."},
{v:47,t:"Maria Madalena e Maria, mãe de José, observavam onde ele era posto."},
{p:"Lucas 23:50-56"},
{v:50,t:"Havia um homem chamado José, membro do Conselho, homem bom e justo,"},
{v:51,t:"que não tinha concordado com a decisão nem com os atos dos outros; era de Arimateia, cidade dos judeus, e esperava o Reino de Deus."},
{v:52,t:"Este foi ter com Pilatos e pediu o corpo de Jesus."},
{v:53,t:"E, descendo-o da cruz, envolveu-o num lençol de linho e colocou-o num sepulcro escavado na rocha, onde ninguém ainda tinha sido posto."},
{v:54,t:"Era o dia da preparação, e o sábado já despontava.",n:"Despontava é o verbo do nascer do dia. O sábado começava ao anoitecer da sexta-feira; talvez o evangelista pense nas lâmpadas que se acendiam para a sua entrada, ou na primeira estrela."},
{v:55,t:"As mulheres que tinham vindo com Jesus da Galileia seguiram José, e viram o sepulcro e como o corpo tinha sido posto."},
{v:56,t:"E, voltando, prepararam aromas e perfumes. E, no sábado, descansaram, conforme o preceito.",n:"São Lucas registra o descanso das mulheres: são fiéis à Lei até na dor. É o único sábado em que o corpo de Jesus descansa no sepulcro."},
{p:"João 19:38-42"},
{v:38,t:"Depois disso, José de Arimateia, que era discípulo de Jesus, mas às ocultas, por medo dos judeus, pediu a Pilatos que o deixasse levar o corpo de Jesus; e Pilatos permitiu. Veio, pois, e levou o corpo dele."},
{v:39,t:"Veio também Nicodemos, aquele que antes tinha ido ter com Jesus de noite, trazendo uma mistura de mirra e aloés, cerca de cem libras.",n:"Cem libras romanas são mais de trinta quilos: uma quantidade digna de uma sepultura real. Nicodemos, que viera de noite, aparece agora em plena luz, e José, que era discípulo às ocultas, pede o corpo ao governador. A cruz fez sair da sombra os discípulos tímidos."},
{v:40,t:"Tomaram, então, o corpo de Jesus e envolveram-no em faixas de linho com os aromas, como os judeus costumam sepultar."},
{v:41,t:"No lugar onde fora crucificado, havia um jardim, e no jardim um sepulcro novo, onde ninguém ainda tinha sido posto.",n:"Só São João fala do jardim. A Paixão começou num jardim, do outro lado do Cedron, e acaba em outro; e será neste que Maria Madalena confundirá o ressuscitado com o jardineiro."},
{v:42,t:"Ali, pois, por causa da preparação dos judeus, e porque o sepulcro estava perto, puseram Jesus."}
];

EV[194] = [
{p:"Mateus 27:62-66"},
{v:62,t:"No dia seguinte, o que vem depois da preparação, os sumos sacerdotes e os fariseus reuniram-se junto de Pilatos",n:"São Mateus evita dizer que era sábado; mas era. Os que tinham acusado Jesus de violar o sábado vão, nesse dia, tratar com o governador pagão da guarda de um sepulcro."},
{v:63,t:"e disseram: Senhor, lembramo-nos de que aquele impostor, quando ainda vivia, disse: Depois de três dias ressuscitarei."},
{v:64,t:"Manda, pois, que o sepulcro seja guardado até ao terceiro dia, para que os seus discípulos não venham roubá-lo e digam ao povo: Ressuscitou dos mortos. E a última impostura seria pior do que a primeira."},
{v:65,t:"Disse-lhes Pilatos: Tendes uma guarda; ide e guardai-o como entenderdes.",n:"Tendes uma guarda pode querer dizer levai soldados, ou tendes a vossa, a guarda do templo. O capítulo seguinte, em que os guardas temem o governador, faz pensar em soldados romanos."},
{v:66,t:"Eles foram e puseram o sepulcro em segurança, selando a pedra e deixando a guarda.",n:"Selava-se a pedra com um cordão preso por cera ou argila, que se rompia se ela fosse movida. Os adversários tomam todas as precauções; sem o saber, preparam as testemunhas do sepulcro vazio."}
];

EV[195] = [
{p:"Mateus 28:1-15"},
{v:1,t:"Passado o sábado, ao raiar do primeiro dia da semana, Maria Madalena e a outra Maria foram ver o sepulcro.",n:"Primeiro dia da semana traduz uma expressão hebraica: o primeiro depois do sábado. Os cristãos passaram a chamá-lo dia do Senhor, dominicus dies — o domingo."},
{v:2,t:"E eis que houve um grande terremoto: um anjo do Senhor desceu do céu, aproximou-se, rolou a pedra e sentou-se sobre ela.",n:"O anjo não afasta a pedra para que Jesus saia, mas para que as mulheres entrem e vejam: o sepulcro já está vazio. E senta-se sobre ela, como sobre um trono."},
{v:3,t:"O seu aspecto era como o relâmpago, e a sua veste, branca como a neve."},
{v:4,t:"De medo dele, os guardas tremeram e ficaram como mortos.",n:"Os guardas do morto ficam como mortos; o morto está vivo."},
{v:5,t:"Mas o anjo, tomando a palavra, disse às mulheres: Vós não temais! Sei que procurais Jesus, o crucificado."},
{v:6,t:"Não está aqui: ressuscitou, como tinha dito. Vinde ver o lugar onde jazia."},
{v:7,t:"E ide depressa dizer aos seus discípulos: Ressuscitou dos mortos, e eis que vai à vossa frente para a Galileia; lá o vereis. Eis que eu vos disse."},
{v:8,t:"Elas partiram depressa do sepulcro, com temor e grande alegria, e correram a dar a notícia aos discípulos."},
{v:9,t:"E eis que Jesus veio ao encontro delas e disse: Salve! Elas aproximaram-se, abraçaram-lhe os pés e o adoraram.",n:"Salve traduz chairete, a saudação corrente, que à letra quer dizer alegrai-vos: a palavra do anjo a Maria em Nazaré, alegra-te, e a dos soldados que zombavam do rei dos judeus. Abraçaram-lhe os pés: não é um fantasma, tem pés que se podem tocar."},
{v:10,t:"Então Jesus disse-lhes: Não temais; ide anunciar a meus irmãos que vão para a Galileia, e lá me verão.",n:"Meus irmãos: chama assim os que o abandonaram na noite da prisão. A primeira palavra sobre eles, depois da ressurreição, não é uma censura."},
{v:11,t:"Enquanto elas iam, alguns da guarda foram à cidade e contaram aos sumos sacerdotes tudo o que tinha acontecido."},
{v:12,t:"Estes reuniram-se com os anciãos e, depois de deliberarem, deram muito dinheiro aos soldados,"},
{v:13,t:"dizendo: Dizei: Os seus discípulos vieram de noite e roubaram-no, enquanto dormíamos.",n:"Santo Agostinho resumiu a objeção numa frase: apresentas testemunhas que dormiam? Se dormiam, como viram quem levou o corpo?"},
{v:14,t:"E, se isto chegar aos ouvidos do governador, nós o convenceremos e vos poremos a salvo."},
{v:15,t:"Eles aceitaram o dinheiro e fizeram como lhes tinham ensinado. E esta versão divulgou-se entre os judeus até ao dia de hoje.",n:"Até ao dia de hoje: o dia em que o evangelista escrevia. São Mateus responde a uma acusação que ainda corria; e a acusação supõe o que ela mesma tenta explicar — que o sepulcro estava vazio."},
{p:"Marcos 16:1-11"},
{v:1,t:"Passado o sábado, Maria Madalena, Maria, mãe de Tiago, e Salomé compraram aromas para irem ungi-lo."},
{v:2,t:"E, muito cedo, no primeiro dia da semana, foram ao sepulcro, ao nascer do sol."},
{v:3,t:"E diziam umas às outras: Quem nos rolará a pedra da entrada do sepulcro?"},
{v:4,t:"Mas, levantando os olhos, viram que a pedra já tinha sido rolada; e era muito grande."},
{v:5,t:"E, entrando no sepulcro, viram um jovem sentado do lado direito, vestido com uma túnica branca, e ficaram assustadas."},
{v:6,t:"Ele disse-lhes: Não vos assusteis! Procurais Jesus de Nazaré, o crucificado. Ressuscitou, não está aqui; eis o lugar onde o puseram."},
{v:7,t:"Mas ide dizer aos seus discípulos e a Pedro: Ele vai à vossa frente para a Galileia; lá o vereis, como vos disse.",n:"E a Pedro: o que o negou três vezes é nomeado à parte. Segundo uma tradição antiga, São Marcos escreveu o que ouvia Pedro pregar; se assim foi, era Pedro quem contava esta frase."},
{v:8,t:"Elas saíram e fugiram do sepulcro, porque estavam tomadas de tremor e espanto; e não disseram nada a ninguém, porque tinham medo.",n:"Nota do tradutor: os manuscritos gregos mais antigos, entre eles os códices Sinaítico e Vaticano, terminam aqui o evangelho de São Marcos, suspenso numa frase: tinham medo. Os versículos 9 a 20, chamados final longo, têm vocabulário e estilo diferentes do resto do livro e resumem aparições que os outros evangelistas contam; mas estão na grande maioria dos manuscritos, Santo Ireneu cita-os no século II, e a Igreja recebe-os como Escritura inspirada e canônica. A Nova Vulgata os conserva, e esta tradução também. Se o livro terminava no versículo 8 — por vontade do autor ou por perda da última folha, discute-se —, o silêncio das mulheres não foi a última palavra: o leitor sabe que elas acabaram falando, porque está lendo o que disseram."},
{v:9,t:"Tendo ressuscitado de manhã, no primeiro dia da semana, apareceu primeiro a Maria Madalena, da qual tinha expulsado sete demônios."},
{v:10,t:"Ela foi anunciá-lo aos que tinham estado com ele, os quais estavam de luto e chorando."},
{v:11,t:"Eles, ouvindo que vivia e que tinha sido visto por ela, não acreditaram."},
{p:"Lucas 24:1-12"},
{v:1,t:"No primeiro dia da semana, muito cedo, foram ao sepulcro, levando os aromas que tinham preparado."},
{v:2,t:"Encontraram a pedra removida do sepulcro"},
{v:3,t:"e, entrando, não encontraram o corpo do Senhor Jesus.",n:"Senhor Jesus: fora do final de Marcos, é a única vez nos evangelhos que os dois nomes aparecem assim juntos — o nome humano e o nome de Deus —, como a Igreja dos Atos vai invocá-lo."},
{v:4,t:"E aconteceu que, estando elas perplexas com isso, eis que dois homens se apresentaram junto delas, com vestes resplandecentes."},
{v:5,t:"Como estivessem cheias de medo e inclinassem o rosto para o chão, eles lhes disseram: Por que procurais entre os mortos aquele que vive?"},
{v:6,t:"Não está aqui, mas ressuscitou. Lembrai-vos de como vos falou, quando ainda estava na Galileia,"},
{v:7,t:"dizendo: É necessário que o Filho do Homem seja entregue nas mãos de homens pecadores, seja crucificado e ressuscite ao terceiro dia."},
{v:8,t:"E elas lembraram-se das suas palavras"},
{v:9,t:"e, voltando do sepulcro, anunciaram todas estas coisas aos Onze e a todos os outros."},
{v:10,t:"Eram Maria Madalena, Joana e Maria, mãe de Tiago; e também as outras que estavam com elas contavam estas coisas aos apóstolos."},
{v:11,t:"Mas estas palavras lhes pareceram um delírio, e não acreditavam nelas.",n:"Delírio traduz leros, palavra que os médicos gregos usavam para o desvario dos febris. Ninguém esperava a ressurreição, e os primeiros a duvidar dela foram os apóstolos."},
{v:12,t:"Pedro, porém, levantou-se e correu ao sepulcro; e, inclinando-se, viu só os panos de linho; e voltou para casa, admirado com o que tinha acontecido.",n:"O versículo 12 falta num manuscrito grego antigo e em algumas versões latinas antigas, mas está no papiro 75, do princípio do século III, e em quase todos os outros. São João conta a mesma corrida, com mais detalhes."},
{p:"João 20:1-18"},
{v:1,t:"No primeiro dia da semana, Maria Madalena foi ao sepulcro de madrugada, quando ainda estava escuro, e viu que a pedra tinha sido retirada do sepulcro."},
{v:2,t:"Correu, então, e foi ter com Simão Pedro e com o outro discípulo, aquele que Jesus amava, e disse-lhes: Tiraram o Senhor do sepulcro, e não sabemos onde o puseram!"},
{v:3,t:"Saíram, pois, Pedro e o outro discípulo, e foram ao sepulcro."},
{v:4,t:"Corriam os dois juntos, mas o outro discípulo correu mais depressa do que Pedro e chegou primeiro ao sepulcro;"},
{v:5,t:"e, inclinando-se, viu os panos de linho postos no chão, mas não entrou.",n:"O outro discípulo chega primeiro e espera: deixa Pedro entrar. Os antigos viram no gesto o respeito pelo primeiro dos Doze."},
{v:6,t:"Chegou também Simão Pedro, que o seguia, e entrou no sepulcro; e viu os panos de linho postos no chão"},
{v:7,t:"e o sudário que tinha estado sobre a cabeça dele, não posto com os panos de linho, mas enrolado num lugar à parte.",n:"Quem rouba um corpo não o despe nem arruma os panos. A ordem do sepulcro é o primeiro sinal."},
{v:8,t:"Então entrou também o outro discípulo, que tinha chegado primeiro ao sepulcro; e viu, e creu.",n:"O grego usa três verbos diferentes de ver: o discípulo olha de fora, Pedro examina, e por fim o discípulo vê — e crê. Ainda não viu Jesus; viu um sepulcro vazio e uns panos arrumados. É o primeiro a crer na ressurreição, e crê sem ter visto o ressuscitado."},
{v:9,t:"Pois ainda não tinham compreendido a Escritura, segundo a qual ele devia ressuscitar dos mortos."},
{v:10,t:"E os discípulos voltaram para casa."},
{v:11,t:"Maria, porém, estava junto ao sepulcro, do lado de fora, chorando. Enquanto chorava, inclinou-se para o sepulcro"},
{v:12,t:"e viu dois anjos vestidos de branco, sentados onde tinha sido posto o corpo de Jesus, um à cabeceira e outro aos pés.",n:"Um à cabeceira e outro aos pés: os antigos lembraram os dois querubins nas duas pontas da arca da aliança, entre os quais Deus se fazia presente."},
{v:13,t:"Eles disseram-lhe: Mulher, por que choras? Ela respondeu: Tiraram o meu Senhor, e não sei onde o puseram."},
{v:14,t:"Dito isso, voltou-se para trás e viu Jesus de pé, mas não sabia que era Jesus."},
{v:15,t:"Disse-lhe Jesus: Mulher, por que choras? A quem procuras? Ela, julgando que era o jardineiro, disse-lhe: Senhor, se foste tu que o levaste, dize-me onde o puseste, e eu o irei buscar.",n:"A quem procuras: as primeiras palavras de Jesus neste evangelho foram que procurais?, ditas aos dois primeiros discípulos; e no jardim da prisão perguntou aos soldados: a quem procurais? O livro inteiro é a história de uma busca."},
{v:16,t:"Disse-lhe Jesus: Maria! Ela, voltando-se, disse-lhe em hebraico: Rabbuni! — que quer dizer Mestre.",n:"Reconhece-o quando ele a chama pelo nome, como o bom pastor que chama as ovelhas pelo nome, e elas conhecem a sua voz. Rabbuni é forma respeitosa do aramaico: meu mestre."},
{v:17,t:"Disse-lhe Jesus: Não me retenhas, pois ainda não subi para o Pai; mas vai ter com os meus irmãos e dize-lhes: Subo para meu Pai e vosso Pai, para meu Deus e vosso Deus.",n:"Nota do tradutor: a Vulgata antiga dizia noli me tangere, não me toques, e a frase ficou célebre com essa forma. Mas o grego, no presente, quer dizer antes não continues a segurar-me, não me detenhas; e a Nova Vulgata corrigiu para noli me tenere. Maria não é afastada: é enviada. Não pode reter Jesus como antes, porque a relação com ele passou a ser outra; e é ela a primeira a levar o anúncio aos apóstolos. Por isso a tradição a chamou apóstola dos apóstolos. Note-se ainda meu Pai e vosso Pai: Jesus nunca diz nosso Pai incluindo-se com os discípulos; é Filho de outro modo, mas é agora, pela primeira vez, que os chama irmãos."},
{v:18,t:"Maria Madalena foi anunciar aos discípulos: Vi o Senhor! E contou o que ele lhe tinha dito."}
];

EV[196] = [
{p:"Marcos 16:12-13"},
{v:12,t:"Depois disso, apareceu com outra aparência a dois deles, que iam a caminho do campo."},
{v:13,t:"E estes foram anunciá-lo aos outros; mas também nestes não acreditaram."},
{p:"Lucas 24:13-35"},
{v:13,t:"E eis que, nesse mesmo dia, dois deles iam a caminho de uma aldeia chamada Emaús, distante de Jerusalém sessenta estádios;",n:"Sessenta estádios são cerca de onze quilômetros. A localização de Emaús é discutida desde a antiguidade; alguns manuscritos dizem cento e sessenta estádios, o que levaria a Emaús Nicópolis."},
{v:14,t:"e conversavam entre si sobre tudo o que tinha acontecido."},
{v:15,t:"E aconteceu que, enquanto conversavam e discutiam, o próprio Jesus se aproximou e pôs-se a caminhar com eles;"},
{v:16,t:"mas os seus olhos estavam impedidos de reconhecê-lo."},
{v:17,t:"Ele perguntou-lhes: Que conversa é essa que tendes pelo caminho? E eles pararam, com o rosto triste."},
{v:18,t:"Um deles, chamado Cléofas, respondeu-lhe: És tu o único forasteiro em Jerusalém que não sabe o que nela aconteceu nestes dias?",n:"O companheiro de Cléofas fica sem nome. Muitos leitores viram nesse vazio um lugar deixado para quem lê."},
{v:19,t:"Ele perguntou-lhes: O quê? Responderam-lhe: O que aconteceu a Jesus de Nazaré, que foi um profeta poderoso em obras e palavras, diante de Deus e de todo o povo;"},
{v:20,t:"e como os sumos sacerdotes e os nossos chefes o entregaram para ser condenado à morte, e o crucificaram."},
{v:21,t:"Nós esperávamos que fosse ele quem havia de libertar Israel; mas, com tudo isso, já é o terceiro dia desde que estas coisas aconteceram.",n:"Esperávamos: a esperança dos dois está no passado. Libertar traduz o verbo do resgate de um cativo; esperavam de Jesus a libertação de Israel, e ela lhes parece desmentida pela cruz."},
{v:22,t:"É verdade que algumas mulheres do nosso grupo nos assustaram: foram ao sepulcro antes do amanhecer"},
{v:23,t:"e, não tendo encontrado o corpo dele, vieram dizer que tinham tido uma visão de anjos, os quais afirmam que ele vive."},
{v:24,t:"Alguns dos nossos foram ao sepulcro e encontraram tudo como as mulheres tinham dito; mas a ele não o viram."},
{v:25,t:"Então ele lhes disse: Ó homens sem entendimento e lentos de coração para crer em tudo o que os profetas disseram!"},
{v:26,t:"Não era necessário que o Cristo sofresse essas coisas para entrar na sua glória?"},
{v:27,t:"E, começando por Moisés e por todos os Profetas, explicou-lhes, em todas as Escrituras, o que a ele dizia respeito.",n:"Moisés e os Profetas é um dos nomes da Bíblia hebraica. A leitura cristã do Antigo Testamento começa aqui, e quem a ensina é o próprio Jesus: toda a Escritura fala dele."},
{v:28,t:"Aproximaram-se da aldeia para onde iam, e ele fez menção de ir mais adiante."},
{v:29,t:"Mas eles insistiram com ele, dizendo: Fica conosco, porque é tarde e o dia já está declinando. E ele entrou para ficar com eles."},
{v:30,t:"E aconteceu que, estando à mesa com eles, tomou o pão, pronunciou a bênção, partiu-o e deu-lhes.",n:"São os quatro gestos da multiplicação dos pães e da última ceia: tomou, abençoou, partiu, deu."},
{v:31,t:"Então os seus olhos se abriram, e eles o reconheceram; mas ele desapareceu da vista deles.",n:"Os olhos que estavam impedidos abrem-se ao partir do pão. E, no instante em que o reconhecem, deixam de vê-lo: dali em diante, é no pão partido que ele se deixa encontrar."},
{v:32,t:"E disseram um ao outro: Não ardia o nosso coração dentro de nós, quando ele nos falava pelo caminho e nos explicava as Escrituras?"},
{v:33,t:"E, levantando-se naquela mesma hora, voltaram para Jerusalém, e encontraram reunidos os Onze e os que estavam com eles,"},
{v:34,t:"que diziam: O Senhor ressuscitou verdadeiramente e apareceu a Simão!",n:"Nenhum evangelista conta a aparição a Simão Pedro; mas São Paulo, na Primeira Carta aos Coríntios, põe-na em primeiro lugar entre as testemunhas: apareceu a Cefas e, depois, aos Doze."},
{v:35,t:"E eles contaram o que lhes acontecera pelo caminho, e como o tinham reconhecido ao partir do pão.",n:"O partir do pão é o nome que os Atos dos Apóstolos dão à Eucaristia: perseveravam no ensino dos apóstolos, na comunhão, no partir do pão e nas orações."}
];

EV[197] = [
{p:"Lucas 24:36-43"},
{v:36,t:"Enquanto falavam destas coisas, ele mesmo apareceu no meio deles e disse-lhes: A paz esteja convosco!"},
{v:37,t:"Espantados e cheios de medo, julgavam ver um espírito."},
{v:38,t:"Mas ele lhes disse: Por que estais perturbados, e por que surgem dúvidas nos vossos corações?"},
{v:39,t:"Vede as minhas mãos e os meus pés: sou eu mesmo! Tocai-me e vede: um espírito não tem carne nem ossos, como vedes que eu tenho.",n:"São Lucas insiste no corpo: o ressuscitado não é uma alma sem corpo nem uma visão. É o mesmo — sou eu mesmo —, e não é como antes: aparece e desaparece, e não é logo reconhecido. A fé da Igreja chama a isso corpo glorioso."},
{v:40,t:"E, dizendo isso, mostrou-lhes as mãos e os pés."},
{v:41,t:"E, como eles, de tanta alegria, ainda não acreditassem e estivessem admirados, disse-lhes: Tendes aqui alguma coisa de comer?",n:"Não acreditavam de alegria: a notícia parece boa demais para ser verdade."},
{v:42,t:"Eles ofereceram-lhe um pedaço de peixe assado."},
{v:43,t:"Ele o tomou e comeu diante deles.",n:"Nos Atos, São Pedro dirá que os apóstolos comeram e beberam com ele depois da ressurreição. Comer diante deles é a prova mais simples de que não é um fantasma."},
{p:"João 20:19-23"},
{v:19,t:"Ao entardecer daquele dia, o primeiro da semana, estando fechadas as portas do lugar onde os discípulos se encontravam, por medo dos judeus, Jesus veio, pôs-se no meio deles e disse-lhes: A paz esteja convosco!",n:"A paz, shalom, era a saudação de todos os dias. Mas é a paz que ele prometera na ceia — deixo-vos a paz, a minha paz vos dou —, e é dita a homens que o tinham abandonado, fechados por medo."},
{v:20,t:"Dito isso, mostrou-lhes as mãos e o lado. E os discípulos alegraram-se, vendo o Senhor."},
{v:21,t:"Jesus disse-lhes de novo: A paz esteja convosco! Assim como o Pai me enviou, também eu vos envio."},
{v:22,t:"Dito isso, soprou sobre eles e disse-lhes: Recebei o Espírito Santo.",n:"Soprou é o verbo da versão grega do Gênesis, quando Deus soprou nas narinas do homem o sopro da vida, e de Ezequiel, quando o espírito soprou sobre os ossos secos. Na tarde da Páscoa começa uma nova criação."},
{v:23,t:"Àqueles a quem perdoardes os pecados, serão perdoados; àqueles a quem os retiverdes, serão retidos.",n:"Nota do tradutor: o Concílio de Trento ensinou que nestas palavras o Senhor deu aos apóstolos e aos seus sucessores o poder de perdoar os pecados, que a Igreja exerce no sacramento da penitência. O dom do Espírito e a missão de perdoar vêm juntos, e o primeiro encargo que o ressuscitado confia aos que o abandonaram é o perdão."}
];

EV[198] = [
{p:"Marcos 16:14"},
{v:14,t:"Por fim, apareceu aos Onze, quando estavam à mesa, e censurou-lhes a incredulidade e a dureza de coração, porque não tinham acreditado nos que o tinham visto ressuscitado."},
{p:"João 20:24-29"},
{v:24,t:"Tomé, um dos Doze, chamado Dídimo, não estava com eles quando Jesus veio."},
{v:25,t:"Os outros discípulos disseram-lhe: Vimos o Senhor! Mas ele lhes disse: Se eu não vir nas suas mãos o sinal dos cravos, e não puser o dedo no lugar dos cravos, e não puser a mão no seu lado, não crerei."},
{v:26,t:"Oito dias depois, os discípulos estavam outra vez dentro de casa, e Tomé com eles. Jesus veio, estando as portas fechadas, pôs-se no meio deles e disse: A paz esteja convosco!",n:"Oito dias depois: de domingo a domingo, contando os dois dias, à maneira antiga. A comunidade já se reúne no primeiro dia da semana, e é aí que o ressuscitado vem."},
{v:27,t:"Depois disse a Tomé: Põe aqui o teu dedo e vê as minhas mãos; estende a tua mão e põe-na no meu lado; e não sejas incrédulo, mas fiel.",n:"Incrédulo e fiel são, em grego, a mesma palavra com e sem negação: apistos e pistos, sem fé e com fé. Jesus oferece a Tomé exatamente a prova que ele pedira. O texto não diz que Tomé chegou a tocá-lo."},
{v:28,t:"Tomé respondeu-lhe: Meu Senhor e meu Deus!",n:"É a confissão mais alta de todo o evangelho, que tinha começado dizendo: e o Verbo era Deus. O livro fecha-se como abriu, e quem a pronuncia é o que mais duvidou. Os Salmos invocavam assim o Deus de Israel: meu Deus e meu Senhor."},
{v:29,t:"Disse-lhe Jesus: Porque me viste, creste. Felizes os que não viram e creram!",n:"É a última bem-aventurança dos evangelhos, e é para os que vierem depois: os que creem pelo testemunho, sem ter visto — os leitores deste livro."}
];

EV[199] = [
{p:"João 21:1-23"},
{v:1,t:"Depois disso, Jesus manifestou-se outra vez aos discípulos, junto ao mar de Tiberíades; e manifestou-se deste modo.",n:"O capítulo 21 vem depois de uma conclusão, a do capítulo 20, e parece um epílogo acrescentado, talvez pelos discípulos do evangelista. Mas não há manuscrito do evangelho que não o tenha."},
{v:2,t:"Estavam juntos Simão Pedro, Tomé, chamado Dídimo, Natanael, que era de Caná da Galileia, os filhos de Zebedeu e outros dois dos seus discípulos."},
{v:3,t:"Simão Pedro disse-lhes: Vou pescar. Eles disseram-lhe: Nós também vamos contigo. Saíram e subiram ao barco; mas naquela noite nada apanharam."},
{v:4,t:"Quando já amanhecia, Jesus estava de pé na praia; mas os discípulos não sabiam que era Jesus."},
{v:5,t:"Jesus disse-lhes: Filhos, tendes alguma coisa para comer? Responderam-lhe: Não."},
{v:6,t:"Ele disse-lhes: Lançai a rede do lado direito do barco, e achareis. Lançaram-na, e já não conseguiam puxá-la, por causa da quantidade de peixes."},
{v:7,t:"Então o discípulo que Jesus amava disse a Pedro: É o Senhor! Simão Pedro, ouvindo que era o Senhor, cingiu-se com a túnica, pois estava nu, e lançou-se ao mar.",n:"Nu quer dizer aqui com pouca roupa, como trabalhavam os pescadores. O discípulo amado é o primeiro a reconhecê-lo, como foi o primeiro a crer diante do sepulcro; Pedro é o primeiro a lançar-se."},
{v:8,t:"Os outros discípulos vieram no barco, arrastando a rede com os peixes, pois não estavam longe da terra, apenas uns duzentos côvados.",n:"Cerca de noventa metros."},
{v:9,t:"Ao descerem para terra, viram um fogo de brasas, com peixe em cima, e pão.",n:"Fogo de brasas é a mesma palavra, anthrakia, da fogueira no pátio do sumo sacerdote, junto da qual Pedro negou três vezes conhecer Jesus. É junto de outro fogo de brasas que ele vai ser interrogado três vezes."},
{v:10,t:"Jesus disse-lhes: Trazei alguns dos peixes que apanhastes agora."},
{v:11,t:"Simão Pedro subiu ao barco e puxou para terra a rede, cheia de cento e cinquenta e três grandes peixes; e, apesar de serem tantos, a rede não se rompeu.",n:"O número intrigou os leitores desde os primeiros séculos. São Jerônimo afirma que os naturalistas gregos contavam cento e cinquenta e três espécies de peixes: a rede da Igreja recolhe gente de todos os povos, e não se rompe. Santo Agostinho notou que é a soma dos números de um a dezessete. Talvez seja apenas a lembrança exata de quem os contou."},
{v:12,t:"Jesus disse-lhes: Vinde comer. E nenhum dos discípulos se atrevia a perguntar-lhe: Quem és tu?, porque sabiam que era o Senhor."},
{v:13,t:"Jesus aproximou-se, tomou o pão e deu-lhes; e fez o mesmo com o peixe."},
{v:14,t:"Esta foi a terceira vez que Jesus se manifestou aos discípulos, depois de ressuscitar dos mortos."},
{v:15,t:"Depois de comerem, Jesus disse a Simão Pedro: Simão, filho de João, tu me amas mais do que estes? Ele respondeu: Sim, Senhor, tu sabes que te quero bem. Jesus disse-lhe: Apascenta os meus cordeiros.",n:"Nota do tradutor: o grego alterna aqui dois verbos de amar, agapao e phileo. Nas duas primeiras perguntas Jesus usa agapao, e Pedro responde com phileo, o verbo da amizade; na terceira, Jesus desce ao verbo de Pedro. A Nova Vulgata guarda a diferença — diligis, amo, amas —, e esta tradução também: amar e querer bem. Muitos leram na troca uma lição: Jesus pede o amor maior e acolhe o que Pedro, depois da queda, ousa prometer. Outros observam que São João gosta de variar sinônimos. A nota fica para quem quiser pesar a diferença."},
{v:16,t:"Disse-lhe de novo, pela segunda vez: Simão, filho de João, tu me amas? Ele respondeu: Sim, Senhor, tu sabes que te quero bem. Jesus disse-lhe: Apascenta as minhas ovelhas."},
{v:17,t:"Disse-lhe pela terceira vez: Simão, filho de João, tu me queres bem? Pedro entristeceu-se por lhe ter perguntado pela terceira vez: Tu me queres bem?, e respondeu-lhe: Senhor, tu sabes tudo; tu sabes que te quero bem. Jesus disse-lhe: Apascenta as minhas ovelhas.",n:"Três negações, três confissões de amor; e, a cada uma, a mesma missão: apascentar. A Igreja leu nestes versículos, junto com as palavras de Mateus 16, a missão de Pedro como pastor de todo o rebanho."},
{v:18,t:"Em verdade, em verdade te digo: quando eras mais novo, tu mesmo te cingias e andavas por onde querias; mas, quando fores velho, estenderás as mãos, e outro te cingirá e te levará para onde não queres.",n:"Estender as mãos era expressão antiga para a crucifixão. Segundo a tradição, Pedro foi crucificado em Roma, sob Nero, por volta do ano 64."},
{v:19,t:"Disse isso para indicar com que morte ele havia de glorificar a Deus. E, depois de dizer isso, acrescentou: Segue-me.",n:"É o chamado do princípio, junto a este mesmo mar, feito de novo depois da queda."},
{v:20,t:"Pedro, voltando-se, viu que os seguia o discípulo que Jesus amava, aquele que, na ceia, se tinha reclinado sobre o peito dele e perguntara: Senhor, quem é que te vai entregar?"},
{v:21,t:"Vendo-o, Pedro disse a Jesus: Senhor, e este?"},
{v:22,t:"Jesus disse-lhe: Se eu quiser que ele fique até que eu venha, que te importa? Tu, segue-me."},
{v:23,t:"Espalhou-se então entre os irmãos o boato de que aquele discípulo não morreria. Mas Jesus não lhe tinha dito que não morreria, e sim: Se eu quiser que ele fique até que eu venha, que te importa?",n:"O versículo parece escrito depois da morte do discípulo amado, para desfazer a perturbação que ela causou: Jesus nunca prometera que ele não morreria."}
];

EV[200] = [
{p:"Mateus 28:16-20"},
{v:16,t:"Os onze discípulos foram para a Galileia, ao monte que Jesus lhes tinha indicado."},
{v:17,t:"E, quando o viram, adoraram-no; mas alguns duvidaram.",n:"Alguns duvidaram: São Mateus não esconde a dúvida, nem no último encontro. A missão é confiada a uma comunidade em que a fé e a hesitação convivem."},
{v:18,t:"Jesus aproximou-se e falou-lhes, dizendo: Foi-me dado todo o poder no céu e na terra.",n:"É a linguagem de Daniel 7: ao Filho do Homem foi dado poder, glória e reino, e todos os povos o servirão. O que o livro de Daniel via numa visão é dito agora por Jesus de si mesmo."},
{v:19,t:"Ide, pois, e fazei discípulos todos os povos, batizando-os em nome do Pai e do Filho e do Espírito Santo,",n:"Fazei discípulos traduz matheteusate; a Vulgata diz docete, ensinai. Em nome, no singular: um só nome para o Pai, o Filho e o Espírito Santo. É a fórmula do batismo da Igreja desde o princípio, e a mais clara confissão da Trindade nos evangelhos."},
{v:20,t:"ensinando-os a observar tudo o que vos mandei. E eis que eu estou convosco todos os dias, até o fim do mundo.",n:"O evangelho de São Mateus começou com o nome Emanuel, que significa Deus conosco, e acaba com a mesma promessa: eu estou convosco. O livro inteiro cabe entre essas duas frases."},
{p:"Marcos 16:15-18"},
{v:15,t:"E disse-lhes: Ide pelo mundo inteiro e anunciai o Evangelho a toda a criatura."},
{v:16,t:"Quem crer e for batizado será salvo; quem não crer será condenado."},
{v:17,t:"Estes são os sinais que acompanharão os que crerem: em meu nome expulsarão demônios, falarão línguas novas,"},
{v:18,t:"pegarão serpentes com as mãos e, se beberem algum veneno mortal, não lhes fará mal; imporão as mãos sobre os doentes, e eles ficarão curados.",n:"Nota do tradutor: os Atos contam que São Paulo, em Malta, foi mordido por uma víbora e nada sofreu. A promessa fala da proteção de Deus sobre os enviados; não é um convite a pô-la à prova. O próprio Jesus respondeu ao tentador, no deserto: não tentarás o Senhor teu Deus. Houve e há quem tome o versículo como mandamento e manipule serpentes no culto; nenhuma tradição antiga da Igreja o leu assim."},
{p:"Lucas 24:44-49"},
{v:44,t:"Depois disse-lhes: Eram estas as palavras que eu vos dizia quando ainda estava convosco: é necessário que se cumpra tudo o que está escrito a meu respeito na Lei de Moisés, nos Profetas e nos Salmos.",n:"Lei, Profetas e Salmos: as três partes da Bíblia hebraica, a Lei, os Profetas e os Escritos, dos quais os Salmos são o primeiro livro. Quer dizer: toda a Escritura."},
{v:45,t:"Então abriu-lhes o entendimento para compreenderem as Escrituras."},
{v:46,t:"E disse-lhes: Assim está escrito: o Cristo havia de sofrer e ressuscitar dos mortos ao terceiro dia,"},
{v:47,t:"e em seu nome seria pregada a conversão, para o perdão dos pecados, a todas as nações, começando por Jerusalém."},
{v:48,t:"Vós sois testemunhas destas coisas."},
{v:49,t:"E eis que eu vou enviar sobre vós o que meu Pai prometeu; ficai, pois, na cidade, até que sejais revestidos da força do alto.",n:"O que o Pai prometeu é o Espírito Santo, que virá no Pentecostes. O segundo livro de São Lucas, os Atos dos Apóstolos, começa exatamente neste ponto."}
];

EV[201] = [
{p:"Marcos 16:19-20"},
{v:19,t:"E o Senhor Jesus, depois de lhes ter falado, foi elevado ao céu e sentou-se à direita de Deus.",n:"Sentar-se à direita de Deus é a linguagem do Salmo 110, já traduzido aqui: disse o Senhor ao meu senhor: senta-te à minha direita. Não indica um lugar, mas a participação no poder e na glória de Deus."},
{v:20,t:"E eles partiram e pregaram por toda a parte, e o Senhor agia com eles e confirmava a palavra com os sinais que a acompanhavam.",n:"O evangelho de São Marcos termina com o começo de outra história: a da pregação, que os Atos dos Apóstolos vão contar."},
{p:"Lucas 24:50-53"},
{v:50,t:"Depois levou-os para fora, até perto de Betânia, e, erguendo as mãos, abençoou-os.",n:"Erguer as mãos para abençoar era o gesto do sumo sacerdote no fim do culto, como Aarão no Levítico e o sumo sacerdote Simão no livro de Ben Sirá. O evangelho de São Lucas começou no templo, com um sacerdote, Zacarias, que saiu do santuário mudo e não pôde abençoar o povo; termina com a bênção que faltava."},
{v:51,t:"E aconteceu que, enquanto os abençoava, separou-se deles e foi elevado ao céu.",n:"Nos Atos, a ascensão acontece quarenta dias depois da Páscoa; aqui, São Lucas parece contá-la na tarde do mesmo dia. É o mesmo autor: no fim do evangelho, junta os acontecimentos numa só cena; no começo dos Atos, dá-lhes a duração."},
{v:52,t:"Eles o adoraram e voltaram para Jerusalém com grande alegria;"},
{v:53,t:"e estavam continuamente no templo, bendizendo a Deus.",n:"O evangelho acaba onde começou, no templo, e na alegria que o anjo anunciara aos pastores: uma grande alegria, que será para todo o povo."}
];

EV[202] = [
{p:"João 20:30-31"},
{v:30,t:"Jesus fez ainda, diante dos seus discípulos, muitos outros sinais que não estão escritos neste livro."},
{v:31,t:"Estes, porém, foram escritos para que creiais que Jesus é o Cristo, o Filho de Deus, e para que, crendo, tenhais a vida em seu nome.",n:"É a primeira conclusão do quarto evangelho, e diz para que foi escrito. Os manuscritos hesitam entre para que creiais e para que continueis a crer: o livro pode ter sido escrito para trazer à fé, ou para firmar nela os que já creem."},
{p:"João 21:24-25"},
{v:24,t:"Este é o discípulo que dá testemunho destas coisas e que as escreveu; e sabemos que o seu testemunho é verdadeiro.",n:"Sabemos: quem fala aqui é a comunidade do discípulo amado, que garante o seu testemunho."},
{v:25,t:"Há ainda muitas outras coisas que Jesus fez; se fossem escritas uma por uma, creio que nem o mundo inteiro poderia conter os livros que seriam escritos.",n:"Com esta frase termina a harmonia dos quatro evangelhos. Lidos juntos, não esgotam o que Jesus fez e disse, e não pretendem esgotar: o último evangelista o diz com as suas próprias palavras."}
];
